        set_accessible_label(&sidebar_toggle, &gettext("Show or hide sidebar"));
        self.imp()
            .calendar_sidebar_toggle
            .replace(Some(sidebar_toggle.clone()));

        let sidebar_for_toggle = sidebar_outer_box.clone();
