    fn refresh_task_sidebar(&self) {
        let Some(task_list) = self.imp().task_list.borrow().as_ref().cloned() else {
            return;
        };
        let Some(records) = self.imp().task_records.borrow().as_ref().cloned() else {
            return;
        };

        while let Some(child) = task_list.first_child() {
            task_list.remove(&child);
        }

        match self.calendar_data_state() {
            CalendarDataState::Loading => {
                task_list.set_visible(false);
                if let Some(state) = self.imp().task_state.borrow().as_ref() {
                    state.set_visible(true);
                    state.set_label(&gettext("Tasks are being loaded together with the calendar snapshot…"));
                }
                return;
            }
            CalendarDataState::Error => {
                task_list.set_visible(false);
                if let Some(state) = self.imp().task_state.borrow().as_ref() {
                    state.set_visible(true);
                    let default_err = gettext("Tasks could not be loaded");
                    state.set_label(
                        self.imp()
                            .calendar_load_error
                            .borrow()
                            .as_deref()
                            .unwrap_or(&default_err),
                    );
                }
                return;
            }
            CalendarDataState::Ready => {}
        }

        let all_count = records.borrow().len();
        let mut tasks = records
            .borrow()
            .iter()
            .filter(|task| self.calendar_source_is_visible(&task.source_uid))
            .cloned()
            .collect::<Vec<_>>();
        tasks.sort_by(|left, right| {
            left.completed
                .cmp(&right.completed)
                .then_with(|| compare_task_due(&left.due, &right.due))
                .then_with(|| {
                    left.summary
                        .to_lowercase()
                        .cmp(&right.summary.to_lowercase())
                })
        });

        for task in tasks.iter().cloned() {
            append_calendar_task_row(self, &task_list, task);
        }

        let visible_count = tasks.len();
        task_list.set_visible(visible_count > 0);
        if let Some(state) = self.imp().task_state.borrow().as_ref() {
            state.set_visible(visible_count == 0);
            let label = if all_count == 0 {
                gettext("No tasks loaded")
            } else if visible_count == 0 {
                gettext("No visible tasks")
            } else {
                ngettext(
                    "1 task loaded from synchronized/local data",
                    "{n} tasks loaded from synchronized/local data",
                    visible_count as u32,
                )
                .replace("{n}", &visible_count.to_string())
            };
            state.set_label(&label);
        }
    }

    pub(crate) fn refresh_taskpad(&self) {
        let Some(taskpad_canvas) = self.imp().taskpad_canvas.borrow().as_ref().cloned() else {
            return;
        };
        let Some(records) = self.imp().task_records.borrow().as_ref().cloned() else {
            return;
        };

        let taskpad_expanded = self
            .imp()
            .taskpad_scroll
            .borrow()
            .as_ref()
            .map(|s| s.is_visible())
            .unwrap_or(true);

        match self.calendar_data_state() {
            CalendarDataState::Loading => {
                taskpad_canvas.set_visible(false);
                if let Some(state) = self.imp().taskpad_state.borrow().as_ref() {
                    state.set_visible(taskpad_expanded);
                    state.set_label(&gettext("Loading tasks…"));
                }
                if let Some(count) = self.imp().taskpad_count.borrow().as_ref() {
                    count.set_label("");
                }
                return;
            }
            CalendarDataState::Error => {
                taskpad_canvas.set_visible(false);
                if let Some(state) = self.imp().taskpad_state.borrow().as_ref() {
                    state.set_visible(taskpad_expanded);
                    let default_err = gettext("Tasks could not be loaded");
                    state.set_label(
                        self.imp()
                            .calendar_load_error
                            .borrow()
                            .as_deref()
                            .unwrap_or(&default_err),
                    );
                }
                if let Some(count) = self.imp().taskpad_count.borrow().as_ref() {
                    count.set_label("");
                }
                return;
            }
            CalendarDataState::Ready => {}
        }

        let query = self.imp().calendar_search_query.borrow().clone();
        let category = self.imp().calendar_category_filter.borrow().clone();
        let hidden_sources = self.imp().hidden_calendar_sources.borrow().clone();

        let mut tasks = records
            .borrow()
            .iter()
            .filter(|task| {
                task_matches_calendar_filter(task, &query, category.as_deref(), &hidden_sources)
            })
            .cloned()
            .collect::<Vec<_>>();
        tasks.sort_by(|left, right| {
            left.completed
                .cmp(&right.completed)
                .then_with(|| compare_task_due(&left.due, &right.due))
                .then_with(|| {
                    left.summary
                        .to_lowercase()
                        .cmp(&right.summary.to_lowercase())
                })
        });

        let today = chrono::Local::now().date_naive();
        let layout = prepare_taskpad_layout(&tasks, today);
        let total_h = (layout.total_height as i32).max(1);
        self.imp().taskpad_layout.replace(Some(layout));
        taskpad_canvas.set_content_height(total_h);

        let visible_count = tasks.len();
        taskpad_canvas.set_visible(visible_count > 0);
        taskpad_canvas.queue_draw();

        if let Some(count) = self.imp().taskpad_count.borrow().as_ref() {
            count.set_label(&format!("({visible_count})"));
        }
        if let Some(state) = self.imp().taskpad_state.borrow().as_ref() {
            state.set_visible(taskpad_expanded && visible_count == 0);
            let empty_label = if records.borrow().is_empty() {
                gettext("No tasks loaded")
            } else {
                gettext("No tasks match the filter")
            };
            state.set_label(&empty_label);
        }
        if !self.imp().sidebar_vpane_dragging.get()
            && !self.imp().sidebar_inner_vpane_dragging.get()
        {
            self.sync_sidebar_vpane_layout();
        }
    }

    pub(crate) fn refresh_memopad(&self) {
        let Some(memopad_canvas) = self.imp().memopad_canvas.borrow().as_ref().cloned() else {
            return;
        };
        let Some(records) = self.imp().memo_records.borrow().as_ref().cloned() else {
            return;
        };

        let memopad_expanded = self
            .imp()
            .memopad_scroll
            .borrow()
            .as_ref()
            .map(|s| s.is_visible())
            .unwrap_or(true);

        match self.calendar_data_state() {
            CalendarDataState::Loading => {
                memopad_canvas.set_visible(false);
                if let Some(state) = self.imp().memopad_state.borrow().as_ref() {
                    state.set_visible(memopad_expanded);
                    state.set_label(&gettext("Loading memos…"));
                }
                if let Some(count) = self.imp().memopad_count.borrow().as_ref() {
                    count.set_label("");
                }
                return;
            }
            CalendarDataState::Error => {
                memopad_canvas.set_visible(false);
                if let Some(state) = self.imp().memopad_state.borrow().as_ref() {
                    state.set_visible(memopad_expanded);
                    let default_err = gettext("Memos could not be loaded");
                    state.set_label(
                        self.imp()
                            .calendar_load_error
                            .borrow()
                            .as_deref()
                            .unwrap_or(&default_err),
                    );
                }
                if let Some(count) = self.imp().memopad_count.borrow().as_ref() {
                    count.set_label("");
                }
                return;
            }
            CalendarDataState::Ready => {}
        }

        let query = self.imp().calendar_search_query.borrow().clone();
        let category = self.imp().calendar_category_filter.borrow().clone();
        let hidden_sources = self.imp().hidden_calendar_sources.borrow().clone();

        let mut memos = records
            .borrow()
            .iter()
            .filter(|memo| {
                memo_matches_calendar_filter(memo, &query, category.as_deref(), &hidden_sources)
            })
            .cloned()
            .collect::<Vec<_>>();
        memos.sort_by(|left, right| {
            left.summary
                .to_lowercase()
                .cmp(&right.summary.to_lowercase())
                .then_with(|| left.updated.cmp(&right.updated))
        });

        let layout = prepare_memopad_layout(&memos);
        let total_h = (layout.total_height as i32).max(1);
        self.imp().memopad_layout.replace(Some(layout));
        memopad_canvas.set_content_height(total_h);

        let visible_count = memos.len();
        memopad_canvas.set_visible(visible_count > 0);
        memopad_canvas.queue_draw();

        if let Some(count) = self.imp().memopad_count.borrow().as_ref() {
            count.set_label(&format!("({visible_count})"));
        }
        if let Some(state) = self.imp().memopad_state.borrow().as_ref() {
            state.set_visible(memopad_expanded && visible_count == 0);
            let empty_label = if records.borrow().is_empty() {
                gettext("No memos loaded")
            } else {
                gettext("No memos match the filter")
            };
            state.set_label(&empty_label);
        }
        if !self.imp().sidebar_vpane_dragging.get()
            && !self.imp().sidebar_inner_vpane_dragging.get()
        {
            self.sync_sidebar_vpane_layout();
        }
    }

    pub(crate) fn refresh_task_and_memo_panes(&self) {
        self.refresh_taskpad();
        self.refresh_memopad();
    }

    fn shift_period(&self, direction: i32) {
        if *self.imp().current_view.borrow() == CalendarView::List {
            return;
        }
        if *self.imp().current_view.borrow() == CalendarView::Month && configured_month_scroll_by_week() {
            self.shift_month_week(direction);
            return;
        }
        let custom_opt = self.imp().custom_selected_range.borrow().clone();
        if let Some(custom) = custom_opt {
            let span = (custom.last_inclusive() - custom.start).num_days() + 1;
            if span > 0 {
                let delta = direction as i64 * span;
                let new_start = custom.start + Duration::days(delta);
                let new_range = CalendarDateRange::from_days(new_start, span);
                *self.imp().custom_selected_range.borrow_mut() = Some(new_range);
                *self.imp().current_date.borrow_mut() = new_start;
                self.imp().mini_calendar_last_key.replace(None);
                self.refresh_period_label();
                self.refresh_calendar_views();
                self.sync_mini_calendar();
                return;
            }
        }
        self.imp().agenda_needs_initial_scroll.set(true);
        self.imp().agenda_selected_row.set(None);
        if *self.imp().current_view.borrow() == CalendarView::Year
            && self.imp().year_view_style.get() == YearViewStyle::MultiYear
        {
            let cur = self.imp().view_state.borrow().anchor_date;
            let step_years = Self::multi_year_visible_count() as i32;
            let next_d = step_date_by_year(cur, direction.signum() * step_years);
            self.imp()
                .view_state
                .borrow_mut()
                .set_anchor(next_d, configured_first_weekday());
            self.imp().view_state.borrow_mut().select_civil_day(next_d);
            *self.imp().current_date.borrow_mut() = next_d;
            self.imp().year_planner_scroll_y.set(0.0);
            self.refresh_period_label();
            self.refresh_calendar_views();
            self.sync_mini_calendar();
            return;
        }
        self.imp().view_state.borrow_mut().navigate_step(
            direction,
            configured_first_weekday(),
            configured_month_scroll_by_week(),
        );
        *self.imp().current_date.borrow_mut() = self.imp().view_state.borrow().anchor_date;
        self.sync_mini_calendar();
    }

    pub(crate) fn finish_month_scroll_animation(&self) {
        if self.imp().month_scroll_anim.borrow().is_some() {
            self.imp().month_scroll_anim.replace(None);
            self.imp().month_scroll_anim_active.set(false);
            if let Some(canvas) = self.imp().month_canvas.borrow().as_ref() {
                canvas.queue_draw();
            }
            self.sync_mini_calendar();
        }
    }

    pub(crate) fn shift_month_week(&self, steps: i32) {
        if *self.imp().current_view.borrow() != CalendarView::Month {
            return;
        }

        let anim_enabled = configured_month_scroll_animation()
            && crate::views::accessibility::are_animations_enabled()
            && steps != 0
            && steps.abs() <= 3;

        if anim_enabled {
            let old_layout = self.imp().month_layout.borrow().as_ref().cloned();
            let canvas = self.imp().month_canvas.borrow().as_ref().cloned();

            if let (Some(old_layout), Some(canvas)) = (old_layout, canvas) {
                if canvas.height() > 50 {
                    let num_rows = (old_layout.visible_dates.len() / 7).max(1) as f64;
                    let grid_h = (canvas.height() as f64 - 28.0).max(1.0);
                    let row_h = grid_h / num_rows;
                    let is_forward = steps > 0;

                    let prev_anim = self.imp().month_scroll_anim.borrow().clone();
                    let (start_offset, duration_ms) = if let Some(prev) = prev_anim {
                        if prev.is_forward == is_forward {
                            // Smooth continuous glide: carry over remaining offset and use shorter duration (100ms)
                            let remaining = prev.current_offset;
                            let step_offset = steps as f64 * row_h;
                            let combined = (remaining + step_offset).clamp(-2.5 * row_h, 2.5 * row_h);
                            (combined, 100.0)
                        } else {
                            ((steps as f64 * row_h).clamp(-2.0 * row_h, 2.0 * row_h), 120.0)
                        }
                    } else {
                        ((steps as f64 * row_h).clamp(-2.0 * row_h, 2.0 * row_h), 130.0)
                    };

                    self.imp().month_scroll_anim.replace(Some(MonthScrollAnimState {
                        outgoing_layout: old_layout,
                        start_offset,
                        current_offset: start_offset,
                        start_time: None,
                        duration_ms,
                        is_forward,
                    }));

                    if !self.imp().month_scroll_anim_active.get() {
                        self.imp().month_scroll_anim_active.set(true);
                        let page_weak = self.downgrade();
                        canvas.add_tick_callback(move |_, _| {
                            let Some(page) = page_weak.upgrade() else {
                                return glib::ControlFlow::Break;
                            };
                            let mut anim_guard = page.imp().month_scroll_anim.borrow_mut();
                            let Some(anim) = anim_guard.as_mut() else {
                                page.imp().month_scroll_anim_active.set(false);
                                return glib::ControlFlow::Break;
                            };
                            let start_time = *anim.start_time.get_or_insert_with(std::time::Instant::now);
                            let elapsed = start_time.elapsed().as_secs_f64() * 1000.0;
                            let progress = (elapsed / anim.duration_ms).clamp(0.0, 1.0);
                            let eased = 1.0 - (1.0 - progress).powi(3);
                            anim.current_offset = anim.start_offset * (1.0 - eased);

                            if progress >= 1.0 {
                                drop(anim_guard);
                                page.imp().month_scroll_anim.replace(None);
                                page.imp().month_scroll_anim_active.set(false);
                                if let Some(c) = page.imp().month_canvas.borrow().as_ref() {
                                    c.queue_draw();
                                }
                                let page_weak_sync = page.downgrade();
                                glib::idle_add_local_once(move || {
                                    if let Some(p) = page_weak_sync.upgrade() {
                                        p.sync_mini_calendar();
                                    }
                                });
                                return glib::ControlFlow::Break;
                            }

                            drop(anim_guard);
                            if let Some(c) = page.imp().month_canvas.borrow().as_ref() {
                                c.queue_draw();
                            }
                            glib::ControlFlow::Continue
                        });
                    }
                }
            }
        } else {
            self.finish_month_scroll_animation();
        }

        let first_weekday = configured_first_weekday();
        self.imp().view_state.borrow_mut().navigate_step(
            steps,
            first_weekday,
            true,
        );
        *self.imp().current_date.borrow_mut() = self.imp().view_state.borrow().anchor_date;

        self.refresh_month_grid();
        self.update_calendar_navigation_controls();
        self.refresh_period_label();
        self.sync_mini_calendar();
    }

    pub(crate) fn ensure_mini_calendar_count(&self, target_count: usize) {
        let current_len = self.imp().mini_calendars.borrow().len();
        if target_count > current_len {
            let mut calendars = self.imp().mini_calendars.borrow_mut();
            for _ in current_len..target_count {
                let cal = gtk::Calendar::new();
                calendars.push(cal);
            }
            drop(calendars);
            self.imp().mini_calendar_last_key.replace(None);
            self.sync_mini_calendar();
        }
    }

    fn sync_mini_calendar(&self) {
        if self.imp().month_scroll_anim_active.get() {
            return;
        }
        let date = *self.imp().current_date.borrow();
        let current_view = *self.imp().current_view.borrow();
        let viewport = self.current_calendar_viewport();

        let custom_range = self.imp().custom_selected_range.borrow().clone();
        let key = (current_view, date, viewport.visible_range, custom_range);
        if self.imp().mini_calendar_last_key.borrow().as_ref() == Some(&key) {
            return;
        }

        self.imp().syncing_mini_calendar.set(true);

        let choosers = self.imp().sidebar_date_choosers.borrow().clone();
        for (idx, chooser) in choosers.iter().enumerate() {
            let target_date = if idx == 0 {
                date
            } else {
                step_date_by_month(date, idx as i32)
            };
            chooser.browse_date.set(target_date);
            if chooser.container.is_visible() || idx == 0 {
                self.refresh_date_chooser_grid(chooser);
            }
        }
        let popover_chooser = self.imp().popover_date_chooser.borrow().clone();
        if let Some(chooser) = popover_chooser {
            chooser.browse_date.set(date);
            self.refresh_date_chooser_grid(&chooser);
        }

        let is_month_view = current_view == CalendarView::Month;
        let calendars = self.imp().mini_calendars.borrow().clone();
        for (i, cal) in calendars.iter().enumerate() {
            let (y, m) = add_months(date.year(), date.month(), i);
            let has_selected_date = date.year() == y && date.month() == m;
            let day_to_select = if has_selected_date {
                date.day() as i32
            } else {
                1
            };
            if let Ok(dt) = glib::DateTime::new(
                &glib::TimeZone::local(),
                y,
                m as i32,
                day_to_select,
                0,
                0,
                0.0,
            ) {
                cal.select_day(&dt);
            }
            cal.clear_marks();
            let days_count = days_in_month(y, m);
            for day in 1..=days_count {
                if let Some(d) = NaiveDate::from_ymd_opt(y, m, day) {
                    let visible = if let Some(custom) = custom_range {
                        custom.contains(d)
                    } else if is_month_view {
                        has_selected_date && is_day_visible_in_viewport(&viewport, d)
                    } else if matches!(
                        current_view,
                        CalendarView::Year | CalendarView::List | CalendarView::Agenda
                    ) {
                        false
                    } else {
                        is_day_visible_in_viewport(&viewport, d)
                    };
                    if visible {
                        cal.mark_day(day);
                    }
                }
            }
        }

        self.imp().mini_calendar_last_key.replace(Some(key));
        self.imp().syncing_mini_calendar.set(false);
    }

    fn set_calendar_anchor(&self, date: NaiveDate) {
        *self.imp().current_date.borrow_mut() = date;
        self.imp().agenda_needs_initial_scroll.set(true);
        self.imp().agenda_selected_row.set(None);
        self.imp()
            .view_state
            .borrow_mut()
            .set_anchor(date, configured_first_weekday());
        if *self.imp().current_view.borrow() == CalendarView::Year {
            self.imp().view_state.borrow_mut().select_civil_day(date);
        }
        self.sync_mini_calendar();
    }

    pub fn navigate_to_date(&self, date: NaiveDate) {
        self.imp().custom_selected_range.borrow_mut().take();
        self.set_calendar_anchor(date);
        self.refresh_calendar_views();
    }

    pub fn navigate_to_custom_date_range(&self, start: NaiveDate, end: NaiveDate) {
        let (min_d, max_d) = if start <= end { (start, end) } else { (end, start) };
        let span = (max_d - min_d).num_days() + 1;
        if span <= 1 {
            self.imp().custom_selected_range.borrow_mut().take();
            self.navigate_to_date(min_d);
            return;
        }
        let range = CalendarDateRange::from_days(min_d, span);
        *self.imp().custom_selected_range.borrow_mut() = Some(range);
        *self.imp().current_date.borrow_mut() = min_d;

        *self.imp().current_view.borrow_mut() = CalendarView::Week;
        self.imp()
            .view_state
            .borrow_mut()
            .set_view(CalendarView::Week, configured_first_weekday());
        if let Some(stack) = self.imp().calendar_stack.borrow().as_ref() {
            stack.set_visible_child_name(calendar_view_name(CalendarView::Week));
        }
        self.imp().syncing_calendar_view.set(true);
        if let Some(buttons) = self.imp().calendar_view_buttons.borrow().as_ref() {
            for (button, candidate) in buttons.iter().zip([
                CalendarView::Day,
                CalendarView::WorkWeek,
                CalendarView::Week,
                CalendarView::Month,
                CalendarView::Agenda,
                CalendarView::Year,
            ]) {
                button.set_active(candidate == CalendarView::Week);
            }
        }
        self.imp().syncing_calendar_view.set(false);

        self.set_calendar_anchor(min_d);
        self.imp().mini_calendar_last_key.replace(None);
        self.refresh_period_label();
        self.refresh_calendar_views();
        self.sync_mini_calendar();
    }

    pub fn preview_custom_date_range(&self, start: NaiveDate, end: NaiveDate) {
        let (min_d, max_d) = if start <= end { (start, end) } else { (end, start) };
        let span = (max_d - min_d).num_days() + 1;
        let range = CalendarDateRange::from_days(min_d, span);
        *self.imp().custom_selected_range.borrow_mut() = Some(range);
        self.imp().mini_calendar_last_key.replace(None);
        self.sync_mini_calendar();
    }

    /// Navigate to the week starting at `week_start` (from a mini-calendar week number).
    /// In Month view with week-scrolling enabled, the month grid starts at that week.
    pub fn navigate_to_week(&self, week_start: NaiveDate) {
        let view = *self.imp().current_view.borrow();
        if view == CalendarView::Month && configured_month_scroll_by_week() {
            self.finish_month_scroll_animation();
            // Pick an anchor inside the dominant month of the new window
            let range = CalendarDateRange::from_days(week_start, configured_month_grid_cells());
            let (dom_y, dom_m) = dominant_month_for_range(range, None);
            let anchor = if week_start.year() == dom_y && week_start.month() == dom_m {
                week_start
            } else {
                NaiveDate::from_ymd_opt(dom_y, dom_m, 1).unwrap_or(week_start)
            };
            *self.imp().current_date.borrow_mut() = anchor;
            {
                let mut state = self.imp().view_state.borrow_mut();
                state.anchor_date = anchor;
                state.visible_range = range;
                state.selected_range = None;
            }
            self.refresh_month_grid();
            self.update_calendar_navigation_controls();
            self.refresh_period_label();
            self.imp().mini_calendar_last_key.replace(None);
            self.sync_mini_calendar();
            return;
        }
        self.navigate_to_date(week_start);
    }

    /// Navigate to a specific date for inspecting an appointment.
    /// In accordance with GNOME HIG:
    /// - If the user is already in a time-based view (Day, WorkWeek, Week), that view is preserved.
    /// - If the user is in an overview mode (Month, Year, List), switch to Week view so time slots and neighbouring events are immediately visible.
    pub fn navigate_to_date_contextual(&self, date: NaiveDate) {
        self.dismiss_zoom_toast();
        let current = *self.imp().current_view.borrow();
        if matches!(current, CalendarView::Month | CalendarView::Year | CalendarView::List) {
            self.select_calendar_view(CalendarView::Week);
        }
        self.navigate_to_date(date);
    }

    fn current_calendar_viewport(&self) -> CalendarViewport {
        self.imp().view_state.borrow().viewport()
    }

    fn rebuild_calendar_index_from_records(&self) {
        let Some(event_records) = self.imp().event_records.borrow().as_ref().cloned() else {
            return;
        };
        let events = event_records.borrow().clone();
        let tasks = self
            .imp()
            .task_records
            .borrow()
            .as_ref()
            .map(|records| records.borrow().clone())
            .unwrap_or_default();
        let snapshot = Arc::new(CalendarSnapshot {
            events,
            tasks,
            memos: Vec::new(),
        });
        self.imp()
            .calendar_snapshot_index
            .replace(Some(Arc::new(CalendarSnapshotIndex::new(snapshot))));
    }

    fn refresh_calendar_views(&self) {
        let current_date = *self.imp().current_date.borrow();
        let current_view = *self.imp().current_view.borrow();
        self.imp().view_state.borrow_mut().view = current_view;
        self.imp()
            .view_state
            .borrow_mut()
            .set_anchor(current_date, configured_first_weekday());
        if !matches!(
            current_view,
            CalendarView::Year | CalendarView::List | CalendarView::Month | CalendarView::Agenda
        ) {
            let list_events = self.filtered_sorted_events();
            self.imp()
                .view_state
                .borrow_mut()
                .reconcile_event_selection(&list_events);
        } else if !matches!(current_view, CalendarView::List | CalendarView::Agenda) {
            self.cancel_calendar_projection();
        }
        match current_view {
            CalendarView::Month => self.refresh_month_grid(),
            CalendarView::Day => self.refresh_day_view(),
            CalendarView::Week => self.refresh_week_view(),
            CalendarView::WorkWeek => self.refresh_workweek_view(),
            CalendarView::Agenda => self.refresh_agenda_view(),
            CalendarView::Year => self.refresh_year_view(),
            CalendarView::List => self.refresh_list_view(),
        }
        self.update_calendar_navigation_controls();
        self.refresh_period_label();
        self.imp().mini_calendar_last_key.replace(None);
        self.sync_mini_calendar();
        self.sync_sidebar_lower_section_visibility();

        let inspected = self.imp().current_inspected_event.borrow().clone();
        if let Some((current_ev, date)) = inspected {
            if let Some(id) = CalendarEventIdentity::from_event(&current_ev) {
                if let Some(updated_ev) = self.unique_loaded_calendar_event(&id) {
                    *self.imp().current_inspected_event.borrow_mut() = Some((updated_ev, date));
                    self.refresh_event_inspector();
                } else {
                    self.clear_inspected_event();
                }
            }
        } else {
            self.refresh_event_inspector();
        }
    }

    fn refresh_calendar_time_display(&self) {
        if let Some(records) = self.imp().event_records.borrow().as_ref().cloned() {
            for event in records.borrow_mut().iter_mut() {
                if let Some(start) =
                    property_local_display(&event.component, "DTSTART", event.all_day)
                {
                    event.start = start;
                }
                if let Some(end) = property_local_display(&event.component, "DTEND", event.all_day)
                {
                    event.end = end;
                }
            }

            self.rebuild_calendar_index_from_records();
            self.bump_calendar_revision();
        }
        self.refresh_calendar_views();
        self.refresh_event_list_visibility();
    }

    fn refresh_calendar_category_model(&self) {
        let Some(model) = self
            .imp()
            .calendar_category_model
            .borrow()
            .as_ref()
            .cloned()
        else {
            return;
        };
        let Some(selector) = self
            .imp()
            .calendar_category_selector
            .borrow()
            .as_ref()
            .cloned()
        else {
            return;
        };

        let mut categories = CalendarCategoryStore::default()
            .load()
            .into_iter()
            .map(|category| category.name)
            .collect::<Vec<_>>();
        if let Some(records) = self.imp().event_records.borrow().as_ref() {
            categories.extend(
                records
                    .borrow()
                    .iter()
                    .flat_map(|event| category_names_from_ical_component(&event.component)),
            );
        }
        categories.retain(|category| !category.trim().is_empty());
        categories.sort_by_cached_key(|category| category.to_lowercase());
        categories.dedup_by(|left, right| left.eq_ignore_ascii_case(right));

        let current_filter = self.imp().calendar_category_filter.borrow().clone();
        let selected = current_filter
            .as_deref()
            .and_then(|filter| {
                categories
                    .iter()
                    .position(|category| category.eq_ignore_ascii_case(filter))
            })
            .map(|index| index as u32 + 1)
            .unwrap_or(0);
        if current_filter.is_some() && selected == 0 {
            self.imp().calendar_category_filter.replace(None);
        }

        let mut names = vec![crate::i18n::gettext("All Categories")];
        names.extend(categories);
        let name_refs = names.iter().map(String::as_str).collect::<Vec<_>>();
        model.splice(0, model.n_items(), &name_refs);
        if selector.selected() != selected {
            selector.set_selected(selected);
        }
    }

    fn refresh_event_list_visibility(&self) {
        let Some(event_list) = self.imp().event_list.borrow().as_ref().cloned() else {
            return;
        };
        if self.calendar_data_state() != CalendarDataState::Ready {
            event_list.set_visible(false);
            if let Some(label) = self.imp().calendar_data_state.borrow().as_ref() {
                match self.calendar_data_state() {
                    CalendarDataState::Loading => {
                        label.set_label(&crate::i18n::gettext("Loading calendars…"));
                    }
                    CalendarDataState::Error => {
                        let default_err = crate::i18n::gettext("Failed to load calendars");
                        label.set_label(
                            self.imp()
                                .calendar_load_error
                                .borrow()
                                .as_deref()
                                .unwrap_or(&default_err),
                        );
                    }
                    CalendarDataState::Ready => {}
                }
            }
            return;
        }
        let mut visible_count = 0usize;
        let mut child = event_list.first_child();
        while let Some(widget) = child {
            child = widget.next_sibling();
            let Ok(row) = widget.downcast::<gtk::ListBoxRow>() else {
                continue;
            };
            let Some(event_row) = row
                .child()
                .and_then(|child| child.downcast::<adw::ActionRow>().ok())
            else {
                continue;
            };
            let source_uid = unsafe {
                event_row
                    .data::<String>("event-source-uid")
                    .map(|value| value.as_ref().clone())
                    .unwrap_or_default()
            };
            let category_matches = unsafe {
                event_row
                    .data::<String>("event-categories")
                    .is_none_or(|value| self.calendar_category_matches(value.as_ref()))
            };
            let search_matches = unsafe {
                event_row
                    .data::<String>("event-search")
                    .is_none_or(|value| self.calendar_search_matches(value.as_ref()))
            };
            let visible =
                self.calendar_source_is_visible(&source_uid) && category_matches && search_matches;
            row.set_visible(visible);
            if visible {
                visible_count += 1;
            }
        }
        event_list.set_visible(visible_count > 0);
    }

    fn refresh_period_label(&self) {
        let text = self.period_label_text();
        if let Some(label) = self.imp().month_date_label.borrow().as_ref().cloned() {
            label.set_label(&text);
        }
        if let Some(label) = self.imp().toolbar_title_label.borrow().as_ref() {
            label.set_label(&text);
        }
        if let Some(btn) = self.imp().toolbar_title_button.borrow().as_ref() {
            btn.set_label(&text);
        }
        if self.imp().is_mobile.get() {
            if let Some(win) = crate::window::find_meridian_window(self) {
                win.sync_back_button();
            }
        }
    }

    fn refresh_day_view(&self) {
        let Some(view) = self.imp().day_view.borrow().as_ref().cloned() else {
            return;
        };
        let date = self.current_calendar_viewport().visible_range.start;
        self.render_continuous_time_grid(&view, &[date]);
    }

    fn refresh_week_view(&self) {
        let Some(view) = self.imp().week_view.borrow().as_ref().cloned() else {
            return;
        };
        let days: Vec<NaiveDate> = if let Some(custom) = self.imp().custom_selected_range.borrow().as_ref() {
            custom.dates().collect()
        } else {
            let week_start = self.current_calendar_viewport().visible_range.start;
            (0..7)
                .map(|i| week_start + chrono::Duration::days(i))
                .collect()
        };
        self.render_continuous_time_grid(&view, &days);
    }

    fn refresh_workweek_view(&self) {
        let Some(view) = self.imp().workweek_view.borrow().as_ref().cloned() else {
            return;
        };
        let viewport = self.current_calendar_viewport();
        let workdays = configured_workdays();
        let days = workweek_display_dates(viewport.visible_range, &workdays);
        self.render_continuous_time_grid(&view, &days);
    }

    fn render_continuous_time_grid(&self, view: &gtk::Box, days: &[NaiveDate]) {
        self.imp().continuous_day_canvases.borrow_mut().clear();
        *self.imp().continuous_time_gutter_canvas.borrow_mut() = None;

        if self.calendar_data_state() != CalendarDataState::Ready {
            clear_box(view);
            self.append_calendar_state_to_box(view);
            return;
        }

        let should_reset = self.imp().time_grid_reset_scroll.replace(false);
        let mut target_center_ratio = if should_reset {
            self.imp().time_grid_center_ratio.set(None);
            if let Some(source) = self.imp().time_grid_center_ratio_cleanup_source.borrow_mut().take() {
                let _ = unsafe { glib::ffi::g_source_remove(source.as_raw()) };
            }
            None
        } else {
            self.imp().time_grid_center_ratio.get()
        };

        let prev_page_size = view
            .last_child()
            .and_then(|w| w.downcast::<gtk::ScrolledWindow>().ok())
            .map(|sw| sw.vadjustment().page_size())
            .filter(|p| *p > 50.0);

        if target_center_ratio.is_none() && !should_reset {
            if let Some(sw) = view.last_child().and_then(|w| w.downcast::<gtk::ScrolledWindow>().ok()) {
                let vadj = sw.vadjustment();
                if vadj.upper() > 100.0 && vadj.page_size() > 50.0 && vadj.value() > 1.0 {
                    let center_y = vadj.value() + (vadj.page_size() / 2.0);
                    let ratio = (center_y / vadj.upper()).clamp(0.0, 1.0);
                    target_center_ratio = Some(ratio);
                }
            }
        }

        clear_box(view);

        let now = Local::now().time();
        let now_min = (now.hour() * 60 + now.minute()) as f64 + (now.second() as f64 / 60.0);
        self.imp().current_time_minute.set(now_min);

        let today = Local::now().date_naive();
        let (workday_start, workday_end) = configured_workday_range();
        let workdays = configured_workdays();
        let visible_range = if let (Some(first), Some(last)) = (days.first(), days.last()) {
            let end = last.succ_opt().unwrap_or_else(|| *last + Duration::days(1));
            CalendarDateRange::new(*first, end)
        } else {
            return;
        };
        let events_by_date = self.events_by_date(visible_range);

        let interval_minutes = configured_time_divisions();
        let slots_per_hour = (60 / interval_minutes) as usize;
        let slot_count = 24 * slots_per_hour;
        let base_slot_height = match interval_minutes {
            60 => 36,
            30 => 24,
            15 => 18,
            10 => 14,
            5 => 12,
            _ => 24,
        };
        let chip_scale = configured_chip_scale();
        let is_fit_24h = chip_scale <= 0.751;
        let slot_height = ((base_slot_height as f64) * chip_scale).round().max(8.0) as i32;
        let time_col_width = 62;

        let second_zone_name = configured_second_zone();
        let second_tz = timezone_from_name(&second_zone_name);
        let has_second_zone = second_tz.is_some();
        let day_column_offset = if has_second_zone { 2 } else { 1 };
        let use_12h = AppSettings::try_new().is_some_and(|s| s.time_format() == "12h");

        // SizeGroups to synchronize column widths between sticky header and scrolling grid
        let time_col_group = gtk::SizeGroup::new(gtk::SizeGroupMode::Horizontal);
        let sec_col_group = if has_second_zone {
            Some(gtk::SizeGroup::new(gtk::SizeGroupMode::Horizontal))
        } else {
            None
        };
        let day_groups: Vec<gtk::SizeGroup> = (0..days.len())
            .map(|_| gtk::SizeGroup::new(gtk::SizeGroupMode::Horizontal))
            .collect();

        // ══════════════════════════════════════════════════════════════════════════
        // Sticky Header Grid: Day Names & Dates (Row 0) + All-Day Events (Row 1)
        // ══════════════════════════════════════════════════════════════════════════
        let header_grid = gtk::Grid::builder()
            .column_spacing(0)
            .row_spacing(0)
            .hexpand(true)
            .vexpand(false)
            .valign(gtk::Align::Start)
            .css_classes(vec!["calendar-header-grid"])
            .build();

        // Row 0, Col 0: Primary Timezone label (e.g. "Berlin")
        let tz_name = primary_timezone_header_label();
        let time_header = gtk::Label::builder()
            .label(&tz_name)
            .css_classes(vec!["calendar-grid-header-cell", "calendar-timezone-header"])
            .halign(gtk::Align::Start)
            .valign(gtk::Align::Center)
            .margin_start(4)
            .width_request(time_col_width)
            .build();
        time_col_group.add_widget(&time_header);
        header_grid.attach(&time_header, 0, 0, 1, 1);

        if let Some(ref sec_group) = sec_col_group {
            let sec_header_text = secondary_timezone_header_label(&second_zone_name);
            let sec_header = gtk::Label::builder()
                .label(&sec_header_text)
                .css_classes(vec!["calendar-grid-header-cell", "secondary-tz-header"])
                .halign(gtk::Align::Center)
                .valign(gtk::Align::Center)
                .width_request(time_col_width)
                .build();
            sec_group.add_widget(&sec_header);
            header_grid.attach(&sec_header, 1, 0, 1, 1);
        }

        for (day_index, day) in days.iter().enumerate() {
            let is_today = *day == today;
            let header_cell = gtk::Box::builder()
                .orientation(gtk::Orientation::Vertical)
                .spacing(2)
                .css_classes(if is_today {
                    vec!["calendar-grid-header-cell", "today"]
                } else {
                    vec!["calendar-grid-header-cell"]
                })
                .hexpand(true)
                .build();
            let day_name = gtk::Label::builder()
                .label(&weekday_short_name(day.weekday()).to_uppercase())
                .css_classes(if is_today {
                    vec!["calendar-header-day-name", "accent"]
                } else {
                    vec!["calendar-header-day-name", "dim-label"]
                })
                .halign(gtk::Align::Center)
                .build();
            let day_num = gtk::Label::builder()
                .label(&day.day().to_string())
                .css_classes(if is_today {
                    vec!["calendar-header-day-number", "accent"]
                } else {
                    vec!["calendar-header-day-number"]
                })
                .halign(gtk::Align::Center)
                .build();
            header_cell.append(&day_name);
            header_cell.append(&day_num);
            day_groups[day_index].add_widget(&header_cell);
            header_grid.attach(&header_cell, day_index as i32 + day_column_offset, 0, 1, 1);
        }

        // Collect unique all-day and multi-day events across the displayed days
        let mut unique_allday: Vec<CalendarEventRecord> = Vec::new();
        let mut seen_ids: HashSet<String> = HashSet::new();
        for day in days {
            if let Some(day_events) = events_by_date.get(day) {
                for event in day_events.iter().filter(|e| e.all_day || event_display_range(e).map(|r| r.len_days() > 1).unwrap_or(false)) {
                    let id = format!("{}_{}_{}", event.uid, event.summary, event.start);
                    if seen_ids.insert(id) {
                        unique_allday.push(event.clone());
                    }
                }
            }
        }

        struct AlldaySpan {
            event: CalendarEventRecord,
            start_col: usize,
            span: usize,
        }

        let mut spans: Vec<AlldaySpan> = Vec::new();
        for event in &unique_allday {
            let range = event_display_range(event);
            let mut start_idx = None;
            let mut end_idx = 0;
            for (idx, day) in days.iter().enumerate() {
                let matches = range.map(|r| r.contains(*day)).unwrap_or(false);
                if matches {
                    if start_idx.is_none() {
                        start_idx = Some(idx);
                    }
                    end_idx = idx + 1;
                }
            }
            if let Some(s) = start_idx {
                let span = end_idx - s;
                if span > 0 {
                    spans.push(AlldaySpan {
                        event: event.clone(),
                        start_col: s,
                        span,
                    });
                }
            }
        }

        spans.sort_by(|a, b| {
            a.start_col
                .cmp(&b.start_col)
                .then_with(|| b.span.cmp(&a.span))
                .then_with(|| a.event.summary.cmp(&b.event.summary))
        });

        let mut track_busy: Vec<Vec<bool>> = Vec::new();
        let mut spans_with_tracks: Vec<(AlldaySpan, usize)> = Vec::new();
        for item in spans {
            let mut assigned_track = None;
            for (t_idx, row) in track_busy.iter().enumerate() {
                let conflict = (item.start_col..(item.start_col + item.span))
                    .any(|col| col < row.len() && row[col]);
                if !conflict {
                    assigned_track = Some(t_idx);
                    break;
                }
            }
            let track = match assigned_track {
                Some(t) => t,
                None => {
                    let t = track_busy.len();
                    track_busy.push(vec![false; days.len()]);
                    t
                }
            };
            for col in item.start_col..(item.start_col + item.span) {
                if col < track_busy[track].len() {
                    track_busy[track][col] = true;
                }
            }
            spans_with_tracks.push((item, track));
        }

        let is_collapsed = self.imp().time_grid_allday_collapsed.get();
        let track_count = track_busy.len();
        let allday_h = if is_collapsed {
            if track_count == 0 {
                24
            } else {
                ((track_count * 8 + 2).max(24)) as i32
            }
        } else {
            (track_count * 24 + 4).max(28) as i32
        };

        // Row 1: All-Day Column Header (Expander toggle button + label)
        let all_day_container = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(0)
            .halign(gtk::Align::Center)
            .valign(gtk::Align::Fill)
            .vexpand(false)
            .css_classes(vec!["calendar-allday-label"])
            .width_request(time_col_width)
            .build();

        if !unique_allday.is_empty() {
            if !is_collapsed {
                let all_day_label = gtk::Label::builder()
                    .label(&crate::i18n::gettext("All Day"))
                    .halign(gtk::Align::Center)
                    .valign(gtk::Align::Start)
                    .vexpand(false)
                    .margin_top(4)
                    .build();
                all_day_container.append(&all_day_label);
            }

            let mut css_classes = vec!["circular", "flat", "week-header-expander"];
            if is_collapsed {
                css_classes.push("collapsed");
            } else {
                css_classes.push("expanded");
            }

            let expander_btn = gtk::Button::builder()
                .icon_name(if is_collapsed { "go-down-symbolic" } else { "go-up-symbolic" })
                .css_classes(css_classes)
                .halign(gtk::Align::Center)
                .valign(gtk::Align::End)
                .vexpand(true)
                .margin_bottom(3)
                .tooltip_text(if is_collapsed {
                    crate::i18n::gettext("Expand all-day events")
                } else {
                    crate::i18n::gettext("Collapse all-day events")
                })
                .build();
            let page_weak = self.downgrade();
            expander_btn.connect_clicked(move |_| {
                if let Some(page) = page_weak.upgrade() {
                    let cur = page.imp().time_grid_allday_collapsed.get();
                    let new_val = !cur;
                    page.imp().time_grid_allday_collapsed.set(new_val);
                    if let Some(settings) = AppSettings::try_new() {
                        settings.set_calendar_allday_collapsed(new_val);
                    }
                    page.refresh_calendar_views();
                }
            });
            all_day_container.append(&expander_btn);
        } else {
            let all_day_label = gtk::Label::builder()
                .label(&crate::i18n::gettext("All Day"))
                .halign(gtk::Align::Center)
                .valign(gtk::Align::Center)
                .vexpand(true)
                .build();
            all_day_container.append(&all_day_label);
        }

        time_col_group.add_widget(&all_day_container);
        header_grid.attach(&all_day_container, 0, 1, 1, 1);

        if let Some(ref sec_group) = sec_col_group {
            let sec_allday_box = gtk::Box::builder()
                .orientation(gtk::Orientation::Vertical)
                .css_classes(vec![
                    "calendar-allday-label",
                    "calendar-time-gutter-secondary",
                ])
                .width_request(time_col_width)
                .valign(gtk::Align::Center)
                .vexpand(false)
                .build();
            sec_group.add_widget(&sec_allday_box);
            header_grid.attach(&sec_allday_box, 1, 1, 1, 1);
        }

        let days_overlay = gtk::Overlay::new();
        days_overlay.set_hexpand(true);
        days_overlay.set_vexpand(false);
        days_overlay.set_valign(gtk::Align::Start);

        let base_days_box = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(0)
            .hexpand(true)
            .vexpand(false)
            .valign(gtk::Align::Start)
            .build();

        for (day_index, day) in days.iter().enumerate() {
            let bg_cell = gtk::Box::builder()
                .orientation(gtk::Orientation::Vertical)
                .css_classes(vec!["calendar-allday-cell"])
                .hexpand(true)
                .vexpand(false)
                .height_request(allday_h)
                .valign(gtk::Align::Start)
                .build();
            day_groups[day_index].add_widget(&bg_cell);
            install_day_drop_target(&bg_cell, self, *day);
            base_days_box.append(&bg_cell);
        }
        days_overlay.set_child(Some(&base_days_box));

        let allday_grid = gtk::Grid::builder()
            .column_homogeneous(true)
            .row_spacing(2)
            .column_spacing(2)
            .hexpand(true)
            .vexpand(false)
            .valign(gtk::Align::Start)
            .margin_top(if is_collapsed { 2 } else { 1 })
            .margin_bottom(if is_collapsed { 2 } else { 1 })
            .margin_start(1)
            .margin_end(1)
            .build();

        for (item, track) in spans_with_tracks {
            let range = event_display_range(&item.event);
            let cont_left = range.as_ref().map(|r| r.start < days[0]).unwrap_or(false);
            let cont_right = range.as_ref().map(|r| r.last_inclusive() > days[days.len() - 1]).unwrap_or(false);

            let chip = if is_collapsed {
                calendar_grid_compact_allday_chip(
                    self,
                    &item.event,
                    days[item.start_col],
                    cont_left,
                    cont_right,
                )
            } else {
                calendar_grid_event_chip(
                    self,
                    &item.event,
                    true,
                    days[item.start_col],
                    None,
                    1,
                    cont_left,
                    cont_right,
                )
            };
            allday_grid.attach(
                &chip,
                item.start_col as i32,
                track as i32,
                item.span as i32,
                1,
            );
        }

        days_overlay.add_overlay(&allday_grid);
        days_overlay.set_measure_overlay(&allday_grid, true);
        header_grid.attach(&days_overlay, day_column_offset, 1, days.len() as i32, 1);

        view.append(&header_grid);

        // ══════════════════════════════════════════════════════════════════════════
        // Timed Hours Grid (Scrollable or Full 24h Fit)
        // ══════════════════════════════════════════════════════════════════════════
        let timed_grid = gtk::Grid::builder()
            .column_spacing(0)
            .row_spacing(0)
            .row_homogeneous(is_fit_24h)
            .hexpand(true)
            .vexpand(true)
            .css_classes(vec!["calendar-time-grid"])
            .build();

        let total_hours = 24usize;
        let total_grid_height = (slot_count as i32 * slot_height).max(1);
        let has_any_workday = days.iter().any(|d| workdays.contains(&d.weekday()));

        // Primary time gutter: Cairo canvas for hour/workday/current-time lines + native GTK labels in a Fixed overlay
        let gutter_overlay = gtk::Overlay::builder()
            .width_request(time_col_width)
            .hexpand(false)
            .vexpand(true)
            .can_target(false)
            .css_classes(vec!["calendar-time-gutter", "calendar-hour-cell"])
            .build();
        let gutter_canvas = gtk::DrawingArea::builder()
            .width_request(time_col_width)
            .height_request(if is_fit_24h { -1 } else { total_grid_height })
            .hexpand(true)
            .vexpand(true)
            .can_target(false)
            .build();
        gutter_overlay.set_child(Some(&gutter_canvas));
        *self.imp().continuous_time_gutter_canvas.borrow_mut() = Some(gutter_canvas.clone());

        let gutter_fixed = gtk::Fixed::builder()
            .can_target(false)
            .overflow(gtk::Overflow::Hidden)
            .build();
        let hour_label_scale = if is_fit_24h {
            0.84
        } else {
            chip_scale.clamp(0.84, 1.0)
        };
        let init_eff_slot_h = (total_grid_height as f64 / slot_count as f64).max(1.0);
        let mut gutter_labels = Vec::with_capacity(total_hours);
        for hour in 0..total_hours {
            let minute = (hour * 60) as u32;
            let lbl = gtk::Label::builder()
                .use_markup(true)
                .label(&format_hour_markup_scaled(minute, use_12h, hour_label_scale))
                .css_classes(vec!["calendar-time-gutter-label"])
                .width_request(time_col_width)
                .xalign(1.0)
                .valign(gtk::Align::Start)
                .build();
            let init_y = ((hour * slots_per_hour) as f64 * init_eff_slot_h).round() + 1.0;
            gutter_fixed.put(&lbl, 0.0, init_y);
            gutter_labels.push(lbl);
        }
        gutter_overlay.add_overlay(&gutter_fixed);
        gutter_overlay.set_measure_overlay(&gutter_fixed, false);

        let gutter_fixed_resize = gutter_fixed.clone();
        gutter_canvas.connect_resize(move |_, _w, height_i32| {
            if height_i32 <= 0 {
                return;
            }
            let eff_slot_h = (height_i32 as f64 / slot_count as f64).max(1.0);
            for (hour, lbl) in gutter_labels.iter().enumerate() {
                let y = ((hour * slots_per_hour) as f64 * eff_slot_h).round() + 1.0;
                gutter_fixed_resize.move_(lbl, 0.0, y);
            }
        });

        time_col_group.add_widget(&gutter_overlay);
        timed_grid.attach(&gutter_overlay, 0, 0, 1, slot_count as i32);

        let days_for_gutter = days.to_vec();
        let page_weak_gutter = self.downgrade();
        gutter_canvas.set_draw_func(move |_area, cr, width_i32, height_i32| {
            let width = width_i32 as f64;
            let height = height_i32 as f64;
            let eff_slot_h = (height / slot_count as f64).max(1.0);
            let is_dark = adw::StyleManager::default().is_dark();

            let workday_y1 = (workday_start as f64 / 1440.0) * height;
            let workday_y2 = (workday_end as f64 / 1440.0) * height;
            let line_color = if is_dark { 1.0 } else { 0.0 };
            let hour_line_alpha = if is_dark { 0.10 } else { 0.08 };
            cr.set_source_rgba(line_color, line_color, line_color, hour_line_alpha);
            cr.set_line_width(1.0);
            for slot in (slots_per_hour..slot_count).step_by(slots_per_hour) {
                let y = (slot as f64 * eff_slot_h).round() - 0.5;
                cr.move_to(0.0, y);
                cr.line_to(width, y);
            }
            let _ = cr.stroke();

            if has_any_workday {
                cr.set_source_rgba(
                    line_color,
                    line_color,
                    line_color,
                    if is_dark { 0.16 } else { 0.13 },
                );
                cr.set_line_width(1.0);
                if workday_y1 > 0.0 && workday_y1 < height {
                    let y = workday_y1.round() - 0.5;
                    cr.move_to(0.0, y);
                    cr.line_to(width, y);
                }
                if workday_y2 > 0.0 && workday_y2 < height {
                    let y = workday_y2.round() - 0.5;
                    cr.move_to(0.0, y);
                    cr.line_to(width, y);
                }
                let _ = cr.stroke();
            }

            if let Some(page) = page_weak_gutter.upgrade() {
                let current_today = Local::now().date_naive();
                if days_for_gutter.contains(&current_today) {
                    let now_min = page.imp().current_time_minute.get();
                    draw_current_time_indicator_line(cr, width, height, now_min);
                }
            }
        });

        if let Some(ref sec_tz_obj) = second_tz {
            let ref_day = days.first().copied().unwrap_or(today);
            let sec_overlay = gtk::Overlay::builder()
                .width_request(time_col_width)
                .hexpand(false)
                .vexpand(true)
                .can_target(false)
                .css_classes(vec![
                    "calendar-time-gutter",
                    "calendar-time-gutter-secondary",
                    "calendar-hour-cell",
                ])
                .build();
            let sec_gutter_canvas = gtk::DrawingArea::builder()
                .width_request(time_col_width)
                .height_request(if is_fit_24h { -1 } else { total_grid_height })
                .hexpand(true)
                .vexpand(true)
                .can_target(false)
                .build();
            sec_overlay.set_child(Some(&sec_gutter_canvas));

            let sec_fixed = gtk::Fixed::builder()
                .can_target(false)
                .overflow(gtk::Overflow::Hidden)
                .build();
            let mut sec_label_widgets = Vec::with_capacity(total_hours);
            for hour in 0..total_hours {
                let minute = (hour * 60) as u32;
                let text = secondary_timezone_hour_label(ref_day, minute, sec_tz_obj, use_12h)
                    .unwrap_or_default();
                let lbl = gtk::Label::builder()
                    .label(&text)
                    .css_classes(vec!["secondary-tz-label", "caption", "dim-label"])
                    .width_request(time_col_width - 4)
                    .xalign(1.0)
                    .valign(gtk::Align::Start)
                    .build();
                let init_y = ((hour * slots_per_hour) as f64 * init_eff_slot_h).round() + 1.0;
                sec_fixed.put(&lbl, 0.0, init_y);
                sec_label_widgets.push(lbl);
            }
            sec_overlay.add_overlay(&sec_fixed);
            sec_overlay.set_measure_overlay(&sec_fixed, false);

            let sec_fixed_resize = sec_fixed.clone();
            sec_gutter_canvas.connect_resize(move |_, _w, height_i32| {
                if height_i32 <= 0 {
                    return;
                }
                let eff_slot_h = (height_i32 as f64 / slot_count as f64).max(1.0);
                for (hour, lbl) in sec_label_widgets.iter().enumerate() {
                    let y = ((hour * slots_per_hour) as f64 * eff_slot_h).round() + 1.0;
                    sec_fixed_resize.move_(lbl, 0.0, y);
                }
            });

            if let Some(ref sec_group) = sec_col_group {
                sec_group.add_widget(&sec_overlay);
            }
            let days_for_sec_gutter = days.to_vec();
            let page_weak_sec_gutter = self.downgrade();
            sec_gutter_canvas.set_draw_func(move |_area, cr, width_i32, height_i32| {
                let width = width_i32 as f64;
                let height = height_i32 as f64;
                let eff_slot_h = (height / slot_count as f64).max(1.0);
                let is_dark = adw::StyleManager::default().is_dark();

                let workday_y1 = (workday_start as f64 / 1440.0) * height;
                let workday_y2 = (workday_end as f64 / 1440.0) * height;
                let line_color = if is_dark { 1.0 } else { 0.0 };
                let hour_line_alpha = if is_dark { 0.10 } else { 0.08 };
                cr.set_source_rgba(line_color, line_color, line_color, hour_line_alpha);
                cr.set_line_width(1.0);
                for slot in (slots_per_hour..slot_count).step_by(slots_per_hour) {
                    let y = (slot as f64 * eff_slot_h).round() - 0.5;
                    cr.move_to(0.0, y);
                    cr.line_to(width, y);
                }
                let _ = cr.stroke();

                if has_any_workday {
                    cr.set_source_rgba(
                        line_color,
                        line_color,
                        line_color,
                        if is_dark { 0.16 } else { 0.13 },
                    );
                    cr.set_line_width(1.0);
                    if workday_y1 > 0.0 && workday_y1 < height {
                        let y = workday_y1.round() - 0.5;
                        cr.move_to(0.0, y);
                        cr.line_to(width, y);
                    }
                    if workday_y2 > 0.0 && workday_y2 < height {
                        let y = workday_y2.round() - 0.5;
                        cr.move_to(0.0, y);
                        cr.line_to(width, y);
                    }
                    let _ = cr.stroke();
                }

                if let Some(page) = page_weak_sec_gutter.upgrade() {
                    let current_today = Local::now().date_naive();
                    if days_for_sec_gutter.contains(&current_today) {
                        let now_min = page.imp().current_time_minute.get();
                        draw_current_time_indicator_line(cr, width, height, now_min);
                    }
                }
            });
            timed_grid.attach(&sec_overlay, 1, 0, 1, slot_count as i32);
        }

        let total_grid_height = (slot_count as i32 * slot_height).max(1);
        let days_vec = days.to_vec();
        let mut earliest_event_slot: Option<usize> = None;

        for (day_index, day) in days.iter().enumerate() {
            let target_date = *day;
            let day_events = events_by_date.get(day).cloned().unwrap_or_default();
            let placed_chips = compute_placed_timed_chips(
                &day_events,
                target_date,
                interval_minutes as u32,
                slot_count,
            );
            if let Some(first_slot) = placed_chips.iter().map(|c| c.start_slot).min() {
                earliest_event_slot = Some(earliest_event_slot.map_or(first_slot, |s| s.min(first_slot)));
            }
            let placed_chips_rc = Rc::new(RefCell::new(placed_chips));
            let drag_start_x = Rc::new(Cell::new(0.0f64));
            let drag_start_y = Rc::new(Cell::new(0.0f64));
            let drag_start_slot = Rc::new(Cell::new(0usize));
            let last_click_rc: Rc<Cell<Option<(usize, std::time::Instant)>>> = Rc::new(Cell::new(None));

            let drawing_area = gtk::DrawingArea::builder()
                .height_request(if is_fit_24h { -1 } else { total_grid_height })
                .hexpand(true)
                .vexpand(true)
                .can_focus(true)
                .focusable(true)
                .css_classes(vec!["calendar-day-canvas"])
                .build();
            day_groups[day_index].add_widget(&drawing_area);
            self.imp().continuous_day_canvases.borrow_mut().push(drawing_area.clone());

            // Draw function for this day
            let page_weak_draw = self.downgrade();
            let placed_chips_draw = placed_chips_rc.clone();
            drawing_area.set_draw_func(move |_area, cr, width_i32, height_i32| {
                let width = width_i32 as f64;
                let height = height_i32 as f64;
                let eff_slot_h = (height / slot_count as f64).max(1.0);
                let is_dark = adw::StyleManager::default().is_dark();

                if let Ok(mut font_options) = gtk::cairo::FontOptions::new() {
                    font_options.set_antialias(gtk::cairo::Antialias::Subpixel);
                    font_options.set_hint_style(gtk::cairo::HintStyle::Full);
                    font_options.set_hint_metrics(gtk::cairo::HintMetrics::On);
                    cr.set_font_options(&font_options);
                }

                // 1. Grid lines (delicate and clean, matching GNOME Calendar - no grey background tint)
                let workday_y1 = (workday_start as f64 / 1440.0) * height;
                let workday_y2 = (workday_end as f64 / 1440.0) * height;
                let line_color = if is_dark { 1.0 } else { 0.0 };
                let hour_line_alpha = if is_dark { 0.10 } else { 0.08 };
                let sub_line_alpha = if is_dark { 0.05 } else { 0.035 };

                // Hour lines
                cr.set_source_rgba(line_color, line_color, line_color, hour_line_alpha);
                cr.set_line_width(1.0);
                for slot in (slots_per_hour..slot_count).step_by(slots_per_hour) {
                    let y = (slot as f64 * eff_slot_h).round() - 0.5;
                    cr.move_to(0.0, y);
                    cr.line_to(width, y);
                }
                let _ = cr.stroke();

                // Workday boundary lines (continuous across the entire row when workdays are shown)
                if has_any_workday {
                    cr.set_source_rgba(line_color, line_color, line_color, if is_dark { 0.16 } else { 0.13 });
                    cr.set_line_width(1.0);
                    if workday_y1 > 0.0 && workday_y1 < height {
                        let y = workday_y1.round() - 0.5;
                        cr.move_to(0.0, y);
                        cr.line_to(width, y);
                    }
                    if workday_y2 > 0.0 && workday_y2 < height {
                        let y = workday_y2.round() - 0.5;
                        cr.move_to(0.0, y);
                        cr.line_to(width, y);
                    }
                    let _ = cr.stroke();
                }

                // Fine interval lines
                cr.set_source_rgba(line_color, line_color, line_color, sub_line_alpha);
                cr.set_line_width(1.0);
                cr.set_dash(&[2.0, 2.0], 0.0);
                for slot in 1..slot_count {
                    if slot % slots_per_hour != 0 {
                        let y = (slot as f64 * eff_slot_h).round() - 0.5;
                        cr.move_to(0.0, y);
                        cr.line_to(width, y);
                    }
                }
                let _ = cr.stroke();
                cr.set_dash(&[], 0.0);

                // Vertical column separator line on the right
                cr.set_source_rgba(line_color, line_color, line_color, hour_line_alpha);
                cr.set_line_width(1.0);
                cr.move_to(width - 0.5, 0.0);
                cr.line_to(width - 0.5, height);
                let _ = cr.stroke();

                // 3. Selection highlight
                let mut sel_range = None;
                if let Some(page) = page_weak_draw.upgrade() {
                    if let Some(sel) = *page.imp().selected_time_slot.borrow() {
                            let (d_start, d_end, t_start, t_end) = if sel.date <= sel.end_date {
                                (sel.date, sel.end_date, sel.start_minute, sel.end_minute)
                            } else {
                                (sel.end_date, sel.date, sel.end_minute, sel.start_minute)
                            };

                            if target_date >= d_start && target_date <= d_end {
                                if d_start == d_end {
                                    let s1 = (t_start / interval_minutes as u32) as usize;
                                    let s2 = ((t_end.saturating_sub(1)) / interval_minutes as u32) as usize;
                                    sel_range = Some((s1, s2));
                                } else if target_date == d_start {
                                    let s1 = (t_start / interval_minutes as u32) as usize;
                                    let s2 = slot_count.saturating_sub(1);
                                    sel_range = Some((s1, s2));
                                } else if target_date == d_end {
                                    let s1 = 0;
                                    let s2 = ((t_end.saturating_sub(1)) / interval_minutes as u32) as usize;
                                    sel_range = Some((s1, s2));
                                } else {
                                    let s1 = 0;
                                    let s2 = slot_count.saturating_sub(1);
                                    sel_range = Some((s1, s2));
                                }
                            }
                        }
                    }

                if let Some((min_s, max_s)) = sel_range {
                    let sy1 = min_s as f64 * eff_slot_h;
                    let sy2 = (max_s + 1) as f64 * eff_slot_h;
                    let sh = (sy2 - sy1).max(2.0);
                    draw_cairo_rounded_rect(cr, 2.0, sy1 + 1.0, (width - 5.0).max(10.0), sh - 2.0, 6.0);
                    cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 0.25);
                    let _ = cr.fill();
                }

                // 4. Event chips
                let current_today = Local::now().date_naive();
                let now_min = if let Some(page) = page_weak_draw.upgrade() {
                    page.imp().current_time_minute.get()
                } else {
                    let now = Local::now().time();
                    (now.hour() * 60 + now.minute()) as f64 + (now.second() as f64 / 60.0)
                };
                let dim_past = configured_dim_past_events();

                let active_move = page_weak_draw.upgrade().and_then(|p| p.imp().time_grid_drag_move_state.borrow().clone());

                // 4. Event chip background cards ("div")
                for chip in placed_chips_draw.borrow().iter() {
                    let is_being_moved = if let Some(ref ms) = active_move {
                        ms.is_active && ms.origin_date == target_date && chip.event.uid == ms.event.uid
                    } else {
                        false
                    };
                    let is_past = dim_past && is_time_grid_chip_past(chip, target_date, current_today, now_min, interval_minutes);
                    if is_being_moved {
                        cr.push_group();
                    }
                    draw_time_grid_chip_card(
                        cr,
                        chip,
                        width,
                        eff_slot_h,
                        is_dark,
                        is_past,
                    );
                    if is_being_moved {
                        let _ = cr.pop_group_to_source();
                        let _ = cr.paint_with_alpha(0.30);
                    }
                }

                // 5. Current-time red indicator line
                // Rendered above the event cards ("über deren div"), but below text labels ("unter der beschriftung")
                if target_date == current_today {
                    draw_current_time_indicator_line(cr, width, height, now_min);
                }

                // 6. Event chip text labels
                for chip in placed_chips_draw.borrow().iter() {
                    let is_being_moved = if let Some(ref ms) = active_move {
                        ms.is_active && ms.origin_date == target_date && chip.event.uid == ms.event.uid
                    } else {
                        false
                    };
                    let is_past = dim_past && is_time_grid_chip_past(chip, target_date, current_today, now_min, interval_minutes);
                    if is_being_moved {
                        cr.push_group();
                    }
                    draw_time_grid_chip_content(
                        cr,
                        chip,
                        width,
                        eff_slot_h,
                        is_dark,
                        is_past,
                    );
                    if is_being_moved {
                        let _ = cr.pop_group_to_source();
                        let _ = cr.paint_with_alpha(0.30);
                    }
                }

                // 7. Ghost preview chip when dragging an event onto this day
                if let Some(ref ms) = active_move {
                    if ms.is_active && ms.current_date == target_date {
                        draw_ghost_move_chip(
                            cr,
                            ms,
                            width,
                            eff_slot_h,
                            interval_minutes as u32,
                            is_dark,
                            use_12h,
                        );
                    }
                }
            });

            // Motion controller for cursor change
            let motion = gtk::EventControllerMotion::new();
            let placed_chips_motion = placed_chips_rc.clone();
            let page_weak_motion = self.downgrade();
            let current_grid_cursor: Rc<Cell<Option<&'static str>>> = Rc::new(Cell::new(None));
            let current_grid_cursor_motion = current_grid_cursor.clone();
            motion.connect_motion(move |controller, x, y| {
                let Some(area) = controller.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                let is_moving = page_weak_motion.upgrade().map(|p| {
                    p.imp().time_grid_drag_move_state.borrow().as_ref().map(|s| s.is_active).unwrap_or(false)
                }).unwrap_or(false);

                let desired_cursor = if is_moving {
                    Some("grabbing")
                } else {
                    let w = area.width() as f64;
                    let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);
                    let on_edge = find_chip_bottom_edge_at(&placed_chips_motion.borrow(), x, y, w, eff_slot_h);
                    if on_edge.is_some() {
                        Some("ns-resize")
                    } else if find_chip_at(&placed_chips_motion.borrow(), x, y, w, eff_slot_h).is_some() {
                        Some("pointer")
                    } else {
                        None
                    }
                };

                if current_grid_cursor_motion.get() != desired_cursor {
                    current_grid_cursor_motion.set(desired_cursor);
                    area.set_cursor_from_name(desired_cursor);
                }
            });
            let current_grid_cursor_leave = current_grid_cursor.clone();
            motion.connect_leave(move |controller| {
                if let Some(area) = controller.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) {
                    if current_grid_cursor_leave.get().is_some() {
                        current_grid_cursor_leave.set(None);
                        area.set_cursor_from_name(None);
                    }
                }
            });
            drawing_area.add_controller(motion);

            // Tooltips for event chips
            drawing_area.set_has_tooltip(true);
            let placed_chips_tt = placed_chips_rc.clone();
            drawing_area.connect_query_tooltip(move |area, x, y, _keyboard, tooltip| {
                let w = area.width() as f64;
                let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);
                let found = find_chip_at(&placed_chips_tt.borrow(), x as f64, y as f64, w, eff_slot_h);
                if let Some(idx) = found {
                    let chip = &placed_chips_tt.borrow()[idx];
                    let untitled = gettext("(Untitled)");
                    let title = if chip.event.summary.trim().is_empty() {
                        untitled.as_str()
                    } else {
                        chip.event.summary.as_str()
                    };
                    let cal = if chip.event.source_display_name.is_empty() {
                        ""
                    } else {
                        &chip.event.source_display_name
                    };
                    let text = if cal.is_empty() {
                        format!("{}\n{}", title, chip.time_text)
                    } else {
                        format!("{}\n{} · {}", title, chip.time_text, cal)
                    };
                    tooltip.set_text(Some(&text));
                    true
                } else {
                    false
                }
            });

            let drag_happened = Rc::new(Cell::new(false));
            let drag_happened_click = drag_happened.clone();
            let drag_happened_drag = drag_happened.clone();

            // Click gesture: open event details or select/open event dialog
            let click_gesture = gtk::GestureClick::new();
            click_gesture.set_button(1);
            let page_weak_click = self.downgrade();
            let placed_chips_click = placed_chips_rc.clone();
            let last_click_click = last_click_rc.clone();

            click_gesture.connect_pressed(move |gesture, n_press, click_x, click_y| {
                let Some(page) = page_weak_click.upgrade() else { return };
                let Some(area) = gesture.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                let w = area.width() as f64;
                let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);
                let on_edge = find_chip_bottom_edge_at(&placed_chips_click.borrow(), click_x, click_y, w, eff_slot_h);
                let found = on_edge.or_else(|| find_chip_at(&placed_chips_click.borrow(), click_x, click_y, w, eff_slot_h));

                if let Some(chip_idx) = found {
                    let chip = &placed_chips_click.borrow()[chip_idx];
                    page.clear_selected_time_slot();
                    page.select_and_inspect_event(&chip.event, Some(target_date));
                    if n_press == 2 {
                        gesture.set_state(gtk::EventSequenceState::Claimed);
                        if let Some(id) = CalendarEventIdentity::from_event(&chip.event) {
                            page.open_event_editor_for_identity(&area, &id);
                        }
                    }
                } else {
                    // Clicked on an empty time slot
                    page.clear_inspected_event();
                    let slot = ((click_y / eff_slot_h).floor() as usize).min(slot_count.saturating_sub(1));
                    let start_min = (slot * interval_minutes as usize) as u32;
                    let end_min = ((slot + 1) * interval_minutes as usize) as u32;

                    let direct_create = AppSettings::try_new()
                        .map(|s| s.calendar_click_action() == "create")
                        .unwrap_or(false);

                    let now = std::time::Instant::now();
                    let is_double_click = if let Some((last_slot, last_time)) = last_click_click.get() {
                        last_slot == slot && (now - last_time).as_millis() < 450
                    } else {
                        false
                    };
                    last_click_click.set(Some((slot, now)));

                    let is_shift = gesture.current_event_state().contains(gtk::gdk::ModifierType::SHIFT_MASK);
                    let prev_sel = *page.imp().selected_time_slot.borrow();
                    let is_already_selected = prev_sel == Some(SelectedTimeSlot {
                        date: target_date,
                        end_date: target_date,
                        start_minute: start_min,
                        end_minute: end_min,
                    });

                    let new_slot = if is_shift {
                        if let Some(prev) = prev_sel {
                            let (d_start, d_end, t_start, t_end) = if (prev.date, prev.start_minute) <= (target_date, start_min) {
                                (prev.date, target_date, prev.start_minute, end_min)
                            } else {
                                (target_date, prev.end_date, start_min, prev.end_minute)
                            };
                            SelectedTimeSlot {
                                date: d_start,
                                end_date: d_end,
                                start_minute: t_start,
                                end_minute: t_end,
                            }
                        } else {
                            SelectedTimeSlot {
                                date: target_date,
                                end_date: target_date,
                                start_minute: start_min,
                                end_minute: end_min,
                            }
                        }
                    } else {
                        SelectedTimeSlot {
                            date: target_date,
                            end_date: target_date,
                            start_minute: start_min,
                            end_minute: end_min,
                        }
                    };

                    page.set_selected_time_slot(Some(new_slot));

                    if is_double_click || (direct_create && is_already_selected) {
                        gesture.set_state(gtk::EventSequenceState::Claimed);
                        let slot_for_create = page.imp().selected_time_slot.borrow().unwrap_or(new_slot);
                        let (s_date, e_date, s_min, e_min) = if slot_for_create.date <= slot_for_create.end_date {
                            (slot_for_create.date, slot_for_create.end_date, slot_for_create.start_minute, slot_for_create.end_minute)
                        } else {
                            (slot_for_create.end_date, slot_for_create.date, slot_for_create.end_minute, slot_for_create.start_minute)
                        };
                        let start_time = s_date.and_hms_opt(0, 0, 0).unwrap() + Duration::minutes(s_min as i64);
                        let end_time = e_date.and_hms_opt(0, 0, 0).unwrap() + Duration::minutes(e_min as i64);
                        let rect = {
                            let y = (s_min as f64 / interval_minutes as f64) * eff_slot_h;
                            let dur_min = (e_min.saturating_sub(s_min)).max(interval_minutes as u32);
                            let h = (dur_min as f64 / interval_minutes as f64) * eff_slot_h;
                            let w = area.width() as f64;
                            gdk::Rectangle::new(0, y as i32, w as i32, h as i32)
                        };
                        page.present_quick_add(&area, Some(rect), start_time, end_time, false);
                    }
                }
            });

            let page_weak_release = self.downgrade();
            let placed_chips_release = placed_chips_rc.clone();
            click_gesture.connect_released(move |gesture, n_press, click_x, click_y| {
                if drag_happened_click.get() {
                    drag_happened_click.set(false);
                    return;
                }
                if n_press == 1 {
                    let Some(page) = page_weak_release.upgrade() else { return };
                    let Some(area) = gesture.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                    let w = area.width() as f64;
                    let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);
                    let found = find_chip_at(&placed_chips_release.borrow(), click_x, click_y, w, eff_slot_h);
                    if let Some(chip_idx) = found {
                        let chip = &placed_chips_release.borrow()[chip_idx];
                        page.select_and_inspect_event(&chip.event, Some(target_date));
                        if !page.is_tag_vpane_visible() {
                            let (cx, cy, cw, ch) = chip_rect_coordinates(chip, w, eff_slot_h);
                            let rect = gdk::Rectangle::new(cx as i32, cy as i32, cw as i32, ch as i32);
                            show_calendar_event_details_popover_full(
                                &page,
                                &area,
                                &chip.event,
                                Some(target_date),
                                Some(rect),
                            );
                        }
                    }
                }
            });
            drawing_area.add_controller(click_gesture);

            let resizing_drag_state: Rc<RefCell<Option<ResizeDragState>>> = Rc::new(RefCell::new(None));
            let move_drag_state: Rc<RefCell<Option<MoveDragState>>> = Rc::new(RefCell::new(None));

            // Drag gesture for:
            // 1. Resizing event duration by dragging bottom edge
            // 2. Moving event to another time slot or day (Google Calendar style)
            // 3. Selecting continuous time ranges on empty slots
            let drag_gesture = gtk::GestureDrag::new();
            drag_gesture.set_button(1);
            let page_weak_drag_begin = self.downgrade();
            let placed_chips_for_drag = placed_chips_rc.clone();
            let drag_start_x_begin = drag_start_x.clone();
            let drag_start_y_begin = drag_start_y.clone();
            let drag_start_slot_begin = drag_start_slot.clone();
            let resizing_drag_begin = resizing_drag_state.clone();
            let move_drag_begin = move_drag_state.clone();

            drag_gesture.connect_drag_begin(move |gesture, start_x, start_y| {
                let Some(area) = gesture.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                let w = area.width() as f64;
                let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);
                drag_start_x_begin.set(start_x);
                drag_start_y_begin.set(start_y);

                // 1. Check if user is resizing bottom edge
                let on_edge = find_chip_bottom_edge_at(&placed_chips_for_drag.borrow(), start_x, start_y, w, eff_slot_h);
                if let Some(chip_idx) = on_edge {
                    gesture.set_state(gtk::EventSequenceState::Claimed);
                    if let Some(page) = page_weak_drag_begin.upgrade() {
                        page.clear_selected_time_slot();
                    }
                    let chip = &placed_chips_for_drag.borrow()[chip_idx];
                    let end_slot = chip.start_slot + chip.row_span;
                    resizing_drag_begin.borrow_mut().replace(ResizeDragState {
                        chip_idx,
                        event: chip.event.clone(),
                        start_slot: chip.start_slot,
                        initial_end_slot: end_slot,
                        current_end_slot: end_slot,
                    });
                    return;
                }

                // 2. Check if user clicked an event to move it
                let on_chip = find_chip_at(&placed_chips_for_drag.borrow(), start_x, start_y, w, eff_slot_h);
                if let Some(chip_idx) = on_chip {
                    let chip = &placed_chips_for_drag.borrow()[chip_idx];
                    if event_mutation_error(&chip.event).is_none() {
                        if let Some(page) = page_weak_drag_begin.upgrade() {
                            page.clear_selected_time_slot();
                        }
                        let grab_y = start_y.max(0.0);
                        let chip_top_y = chip.start_slot as f64 * eff_slot_h;
                        let offset_in_chip = ((grab_y - chip_top_y).max(0.0) / eff_slot_h).floor() as usize;
                        let grab_slot_offset = offset_in_chip.min(chip.row_span.saturating_sub(1));

                        move_drag_begin.borrow_mut().replace(MoveDragState {
                            origin_day_index: day_index,
                            origin_date: target_date,
                            event: chip.event.clone(),
                            initial_start_slot: chip.start_slot,
                            row_span: chip.row_span,
                            grab_slot_offset,
                            current_day_index: day_index,
                            current_date: target_date,
                            current_start_slot: chip.start_slot,
                            is_active: false,
                        });
                        return;
                    }
                }

                // 3. Otherwise, empty time slot selection drag
                let s = ((start_y.max(0.0) / eff_slot_h).floor() as usize).min(slot_count.saturating_sub(1));
                drag_start_slot_begin.set(s);
                let start_min = (s * interval_minutes as usize) as u32;
                let end_min = ((s + 1) * interval_minutes as usize) as u32;
                if let Some(page) = page_weak_drag_begin.upgrade() {
                    page.imp().view_state.borrow_mut().select_event(None, None);
                    page.set_selected_time_slot(Some(SelectedTimeSlot {
                        date: target_date,
                        end_date: target_date,
                        start_minute: start_min,
                        end_minute: end_min,
                    }));
                }
            });

            let page_weak_drag_update = self.downgrade();
            let drag_start_x_update = drag_start_x.clone();
            let drag_start_y_update = drag_start_y.clone();
            let drag_start_slot_update = drag_start_slot.clone();
            let days_for_update = days_vec.clone();
            let resizing_drag_update = resizing_drag_state.clone();
            let move_drag_update = move_drag_state.clone();
            let placed_chips_for_resize = placed_chips_rc.clone();
            let drag_happened_update = drag_happened_drag.clone();

            drag_gesture.connect_drag_update(move |gesture, offset_x, offset_y| {
                // A. Handle Resizing
                if let Some(ref mut rs) = *resizing_drag_update.borrow_mut() {
                    gesture.set_state(gtk::EventSequenceState::Claimed);
                    drag_happened_update.set(true);
                    if let Some(page) = page_weak_drag_update.upgrade() {
                        if page.imp().selected_time_slot.borrow().is_some() {
                            page.clear_selected_time_slot();
                        }
                    }
                    let Some(area) = gesture.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                    let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);
                    let cur_y = (drag_start_y_update.get() + offset_y).max(0.0);
                    let cur_slot = ((cur_y / eff_slot_h).round() as usize)
                        .clamp(rs.start_slot + 1, slot_count);
                    if cur_slot != rs.current_end_slot {
                        rs.current_end_slot = cur_slot;
                        let new_span = cur_slot.saturating_sub(rs.start_slot).max(1);
                        if let Some(chip) = placed_chips_for_resize.borrow_mut().get_mut(rs.chip_idx) {
                            chip.row_span = new_span;
                            let start_min = (chip.start_slot as u32 * interval_minutes as u32).min(1439);
                            let end_min = ((chip.start_slot + new_span) as u32 * interval_minutes as u32).min(1440);
                            chip.time_text = format!("{}–{}", format_minute_of_day(start_min, use_12h), format_minute_of_day(end_min, use_12h));
                        }
                        area.queue_draw();
                    }
                    return;
                }

                // B. Handle Move Drag (Google Calendar style)
                if let Some(ref mut ms) = *move_drag_update.borrow_mut() {
                    if offset_x.abs() > 4.0 || offset_y.abs() > 4.0 || ms.is_active {
                        ms.is_active = true;
                        gesture.set_state(gtk::EventSequenceState::Claimed);
                        drag_happened_update.set(true);

                        let Some(page) = page_weak_drag_update.upgrade() else { return };
                        if page.imp().selected_time_slot.borrow().is_some() {
                            page.clear_selected_time_slot();
                        }
                        let Some(area) = gesture.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                        let w = area.width() as f64;
                        if w <= 0.0 { return; }
                        let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);

                        let day_offset = ((drag_start_x_update.get() + offset_x) / w).floor() as i32;
                        let cur_day_idx = (day_index as i32 + day_offset).clamp(0, days_for_update.len() as i32 - 1) as usize;
                        let cur_date = days_for_update[cur_day_idx];

                        let cur_y = (drag_start_y_update.get() + offset_y).max(0.0);
                        let pointer_slot = (cur_y / eff_slot_h).floor() as i64;
                        let max_start_slot = (slot_count.saturating_sub(ms.row_span)) as i64;
                        let target_start = (pointer_slot - ms.grab_slot_offset as i64).clamp(0, max_start_slot) as usize;

                        let mut changed = false;
                        if ms.current_day_index != cur_day_idx || ms.current_date != cur_date || ms.current_start_slot != target_start {
                            ms.current_day_index = cur_day_idx;
                            ms.current_date = cur_date;
                            ms.current_start_slot = target_start;
                            changed = true;
                        }

                        if changed || page.imp().time_grid_drag_move_state.borrow().is_none() {
                            *page.imp().time_grid_drag_move_state.borrow_mut() = Some(ms.clone());
                            page.queue_redraw_all_time_slots();
                        }
                    }
                    return;
                }

                // C. Handle Empty Slot Range Selection
                if offset_x.abs() > 4.0 || offset_y.abs() > 4.0 {
                    gesture.set_state(gtk::EventSequenceState::Claimed);
                    drag_happened_update.set(true);
                    let Some(page) = page_weak_drag_update.upgrade() else { return };
                    let Some(area) = gesture.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                    let w = area.width() as f64;
                    if w <= 0.0 { return; }
                    let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);

                    let day_offset = ((drag_start_x_update.get() + offset_x) / w).floor() as i32;
                    let cur_day_idx = (day_index as i32 + day_offset).clamp(0, days_for_update.len() as i32 - 1) as usize;
                    let cur_date = days_for_update[cur_day_idx];

                    let cur_y = (drag_start_y_update.get() + offset_y).max(0.0);
                    let cur_slot = ((cur_y / eff_slot_h).floor() as usize).min(slot_count.saturating_sub(1));
                    let start_s = drag_start_slot_update.get();

                    let (start_d, end_d, start_m, end_m) = if cur_date == target_date {
                        let min_s = start_s.min(cur_slot);
                        let max_s = start_s.max(cur_slot);
                        let start_min = (min_s * interval_minutes as usize) as u32;
                        let end_min = ((max_s + 1) * interval_minutes as usize) as u32;
                        (target_date, target_date, start_min, end_min)
                    } else if target_date < cur_date {
                        let start_min = (start_s * interval_minutes as usize) as u32;
                        let end_min = ((cur_slot + 1) * interval_minutes as usize) as u32;
                        (target_date, cur_date, start_min, end_min)
                    } else {
                        let start_min = (cur_slot * interval_minutes as usize) as u32;
                        let end_min = ((start_s + 1) * interval_minutes as usize) as u32;
                        (cur_date, target_date, start_min, end_min)
                    };

                    let new_slot = SelectedTimeSlot {
                        date: start_d,
                        end_date: end_d,
                        start_minute: start_m,
                        end_minute: end_m,
                    };
                    if *page.imp().selected_time_slot.borrow() != Some(new_slot) {
                        page.set_selected_time_slot(Some(new_slot));
                    }
                }
            });

            let page_weak_drag_end = self.downgrade();
            let resizing_drag_end = resizing_drag_state.clone();
            let move_drag_end = move_drag_state.clone();
            let drag_happened_end = drag_happened_drag.clone();

            drag_gesture.connect_drag_end(move |gesture, _offset_x, _offset_y| {
                // A. Finish Resize
                if let Some(rs) = resizing_drag_end.borrow_mut().take() {
                    drag_happened_end.set(true);
                    gesture.set_state(gtk::EventSequenceState::Claimed);
                    let Some(page) = page_weak_drag_end.upgrade() else { return };
                    page.clear_selected_time_slot();
                    let Some(area) = gesture.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                    if rs.current_end_slot != rs.initial_end_slot {
                        let delta_slots = rs.current_end_slot as i64 - rs.initial_end_slot as i64;
                        let delta_minutes = delta_slots * interval_minutes as i64;
                        page.resize_event_by_minutes(rs.event, delta_minutes);
                    } else {
                        area.queue_draw();
                    }
                    return;
                }

                // B. Finish Move Drag
                if let Some(ms) = move_drag_end.borrow_mut().take() {
                    let Some(page) = page_weak_drag_end.upgrade() else { return };
                    page.clear_selected_time_slot();
                    page.imp().time_grid_drag_move_state.borrow_mut().take();
                    page.queue_redraw_all_time_slots();

                    if ms.is_active {
                        drag_happened_end.set(true);
                        gesture.set_state(gtk::EventSequenceState::Claimed);
                        let delta_days = (ms.current_date - ms.origin_date).num_days();
                        let delta_slots = ms.current_start_slot as i64 - ms.initial_start_slot as i64;
                        let delta_minutes = delta_slots * interval_minutes as i64;
                        if delta_days != 0 || delta_minutes != 0 {
                            page.move_event_by_delta(ms.event, delta_days, delta_minutes);
                        }
                    }
                    return;
                }

                // C. Finish Empty Slot Selection
                let Some(page) = page_weak_drag_end.upgrade() else { return };
                let Some(area) = gesture.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                if let Some(sel) = *page.imp().selected_time_slot.borrow() {
                    let has_multi_slot = sel.date != sel.end_date
                        || sel.end_minute.saturating_sub(sel.start_minute) > interval_minutes as u32;
                    if has_multi_slot {
                        drag_happened_end.set(true);
                        gesture.set_state(gtk::EventSequenceState::Claimed);
                        let (d_start, d_end, t_start, t_end) = if (sel.date, sel.start_minute) <= (sel.end_date, sel.end_minute) {
                            (sel.date, sel.end_date, sel.start_minute, sel.end_minute)
                        } else {
                            (sel.end_date, sel.date, sel.end_minute, sel.start_minute)
                        };
                        let start_time = d_start.and_hms_opt(0, 0, 0).unwrap() + Duration::minutes(t_start as i64);
                        let end_time = d_end.and_hms_opt(0, 0, 0).unwrap() + Duration::minutes(t_end as i64);
                        let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);
                        let rect = {
                            let y = (t_start as f64 / interval_minutes as f64) * eff_slot_h;
                            let dur_min = (t_end.saturating_sub(t_start)).max(interval_minutes as u32);
                            let h = (dur_min as f64 / interval_minutes as f64) * eff_slot_h;
                            let w = area.width() as f64;
                            gdk::Rectangle::new(0, y as i32, w as i32, h as i32)
                        };
                        page.present_quick_add(&area, Some(rect), start_time, end_time, false);
                    }
                }
                page.queue_redraw_all_time_slots();
            });
            drawing_area.add_controller(drag_gesture);

            let key_ctrl = gtk::EventControllerKey::new();
            let page_weak_key = self.downgrade();
            key_ctrl.connect_key_pressed(move |_, keyval, _, _| {
                if keyval == gdk::Key::Escape {
                    if let Some(page) = page_weak_key.upgrade() {
                        if page.imp().time_grid_drag_move_state.borrow_mut().take().is_some() {
                            page.queue_redraw_all_time_slots();
                            return glib::Propagation::Stop;
                        }
                    }
                }
                glib::Propagation::Proceed
            });
            drawing_area.add_controller(key_ctrl);

            // Secondary / Right click context menu
            let time_grid_right_click = gtk::GestureClick::builder().button(3).build();
            let page_weak_tgrc = self.downgrade();
            let placed_chips_tgrc = placed_chips_rc.clone();
            time_grid_right_click.connect_pressed(move |gesture, _n_press, x, y| {
                gesture.set_state(gtk::EventSequenceState::Claimed);
                let Some(page) = page_weak_tgrc.upgrade() else { return };
                let Some(area) = gesture.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                let w = area.width() as f64;
                let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);
                let found = find_chip_at(&placed_chips_tgrc.borrow(), x, y, w, eff_slot_h);
                let rect = gdk::Rectangle::new(x as i32, y as i32, 1, 1);

                if let Some(chip_idx) = found {
                    let chip = &placed_chips_tgrc.borrow()[chip_idx];
                    page.clear_selected_time_slot();
                    show_calendar_event_context_menu(&page, &area, &chip.event, rect);
                } else {
                    let slot = ((y / eff_slot_h).floor() as usize).min(slot_count.saturating_sub(1));
                    let start_min = (slot * interval_minutes as usize) as u32;
                    let end_min = ((slot + 1) * interval_minutes as usize) as u32;

                    page.imp().view_state.borrow_mut().select_event(None, None);
                    page.set_selected_time_slot(Some(SelectedTimeSlot {
                        date: target_date,
                        end_date: target_date,
                        start_minute: start_min,
                        end_minute: end_min,
                    }));
                    show_calendar_day_context_menu(&page, &area, target_date, Some((start_min, end_min)), rect);
                }
            });
            drawing_area.add_controller(time_grid_right_click);

            // Long press context menu (touch / mobile)
            let time_grid_long_press = gtk::GestureLongPress::new();
            let page_weak_tglp = self.downgrade();
            let placed_chips_tglp = placed_chips_rc.clone();
            time_grid_long_press.connect_pressed(move |gesture, x, y| {
                gesture.set_state(gtk::EventSequenceState::Claimed);
                let Some(page) = page_weak_tglp.upgrade() else { return };
                let Some(area) = gesture.widget().and_then(|w| w.downcast::<gtk::DrawingArea>().ok()) else { return };
                let w = area.width() as f64;
                let eff_slot_h = (area.height() as f64 / slot_count as f64).max(1.0);
                let found = find_chip_at(&placed_chips_tglp.borrow(), x, y, w, eff_slot_h);
                let rect = gdk::Rectangle::new(x as i32, y as i32, 1, 1);

                if let Some(chip_idx) = found {
                    let chip = &placed_chips_tglp.borrow()[chip_idx];
                    page.clear_selected_time_slot();
                    show_calendar_event_context_menu(&page, &area, &chip.event, rect);
                } else {
                    let slot = ((y / eff_slot_h).floor() as usize).min(slot_count.saturating_sub(1));
                    let start_min = (slot * interval_minutes as usize) as u32;
                    let end_min = ((slot + 1) * interval_minutes as usize) as u32;

                    page.imp().view_state.borrow_mut().select_event(None, None);
                    page.set_selected_time_slot(Some(SelectedTimeSlot {
                        date: target_date,
                        end_date: target_date,
                        start_minute: start_min,
                        end_minute: end_min,
                    }));
                    show_calendar_day_context_menu(&page, &area, target_date, Some((start_min, end_min)), rect);
                }
            });
            drawing_area.add_controller(time_grid_long_press);

            // Touch / Trackpad swipe gesture (Day / Week switching)
            let time_grid_swipe = gtk::GestureSwipe::new();
            let page_weak_tgswipe = self.downgrade();
            time_grid_swipe.connect_swipe(move |gesture, velocity_x, velocity_y| {
                if velocity_x.abs() > 200.0 && velocity_x.abs() > velocity_y.abs() * 1.5 {
                    let Some(page) = page_weak_tgswipe.upgrade() else { return; };
                    if velocity_x < -200.0 {
                        // Swipe left: Next day / week
                        page.shift_period(1);
                        gesture.set_state(gtk::EventSequenceState::Claimed);
                    } else if velocity_x > 200.0 {
                        // Swipe right: Previous day / week
                        page.shift_period(-1);
                        gesture.set_state(gtk::EventSequenceState::Claimed);
                    }
                }
            });
            drawing_area.add_controller(time_grid_swipe);

            // Drop target: Rescheduling or duplicating a dropped event onto this day / time
            let drop_target = gtk::DropTarget::new(glib::Type::STRING, gdk::DragAction::MOVE | gdk::DragAction::COPY);
            let page_weak_drop = self.downgrade();
            let interval_min_val = interval_minutes as u32;
            let total_h_f64 = total_grid_height as f64;

            drop_target.connect_drop(move |target, value, _x, y| {
                let Ok(payload) = value.get::<String>() else { return false; };
                let is_copy = target.current_drop().map(|d| d.actions().contains(gdk::DragAction::COPY)).unwrap_or(false);
                let mut parts = payload.splitn(4, '\n');
                let Some(source_uid) = parts.next() else { return false; };
                let Some(uid) = parts.next() else { return false; };
                let recurrence_id = parts.next().map(str::trim).filter(|s| !s.is_empty());
                let occurrence_date = parts.next().and_then(|s| NaiveDate::parse_from_str(s, "%Y-%m-%d").ok());
                let Some(page) = page_weak_drop.upgrade() else { return false; };
                let records = page.imp().event_records.borrow().as_ref().cloned();
                let Some(event) = records.and_then(|records| {
                    let target_identity = calendar_event_identity_from_parts(source_uid, uid, recurrence_id);
                    unique_event_for_identity(&records.borrow(), &target_identity)
                }) else {
                    show_toast_for_widget(&page, &gettext("The dragged appointment is no longer loaded"));
                    return false;
                };
                let Some(start_date) = occurrence_date.or_else(|| event_start_date(&event)) else {
                    show_toast_for_widget(&page, &gettext("The appointment has no valid start date"));
                    return false;
                };
                let delta_days = (target_date - start_date).num_days();
                let delta_minutes = if event.all_day {
                    0
                } else {
                    let drop_h = target
                        .widget()
                        .map(|w| w.height() as f64)
                        .filter(|&h| h > 1.0)
                        .unwrap_or(total_h_f64);
                    let target_min = ((y / drop_h) * 1440.0) as u32;
                    let snapped_min = (target_min / interval_min_val) * interval_min_val;
                    let start_dt = event_start_datetime(&event);
                    let current_minute = start_dt.map(|dt| dt.time().hour() * 60 + dt.time().minute()).unwrap_or(0);
                    snapped_min as i64 - current_minute as i64
                };
                if is_copy {
                    page.duplicate_event_by_delta(event, delta_days, delta_minutes);
                } else {
                    page.move_event_by_delta(event, delta_days, delta_minutes);
                }
                true
            });
            drawing_area.add_controller(drop_target);

            timed_grid.attach(
                &drawing_area,
                day_index as i32 + day_column_offset,
                0,
                1,
                slot_count as i32,
            );
        }

        let timed_scroll = gtk::ScrolledWindow::builder()
            .hscrollbar_policy(gtk::PolicyType::Never)
            .vscrollbar_policy(if is_fit_24h {
                gtk::PolicyType::Never
            } else {
                gtk::PolicyType::Automatic
            })
            .vexpand(true)
            .hexpand(true)
            .child(&timed_grid)
            .build();

        if let Some(viewport) = timed_scroll.child().and_downcast::<gtk::Viewport>() {
            viewport.set_scroll_to_focus(false);
        }

        let (workday_start, _) = configured_workday_range();
        // Start ~2h before the configured workday so the working day is visible without scrolling
        let base_start_min = workday_start.saturating_sub(120);
        // Pull earlier only for real early-morning events (after 05:00), never into the night
        let earliest_event_min = earliest_event_slot
            .map(|slot| (slot as u32) * (interval_minutes as u32))
            .filter(|min| *min >= 300 && *min < base_start_min)
            .map(|min| min.saturating_sub(30).max(300))
            .unwrap_or(base_start_min);
        let target_start_min = earliest_event_min;

        let center_ratio_captured = target_center_ratio;
        let initial_applied = Rc::new(Cell::new(is_fit_24h));
        let apply_scheduled = Rc::new(Cell::new(false));

        let compute_target_y = move |adj: &gtk::Adjustment| -> f64 {
            if is_fit_24h {
                return 0.0;
            }
            let max_scroll = (adj.upper() - adj.page_size()).max(0.0);
            if let Some(center_ratio) = center_ratio_captured {
                let center_y = center_ratio * adj.upper();
                let page_size = if adj.page_size() > 50.0 {
                    adj.page_size()
                } else {
                    (adj.upper() * 0.45).clamp(300.0, 700.0)
                };
                let top_y = center_y - (page_size / 2.0);
                return top_y.clamp(0.0, max_scroll);
            }

            // Initial placement: align top to ~2h before configured workday start
            let start_slot = (target_start_min / interval_minutes as u32) as usize;
            let slot_y = (start_slot * slot_height as usize) as f64;
            slot_y.clamp(0.0, max_scroll)
        };

        // Flicker-free re-render (e.g. Ctrl+scroll zoom): if we know the viewport height from the
        // previous grid, hand the new ScrolledWindow an adjustment that already holds the target
        // value. GtkViewport keeps that value on its first allocation, so the very first frame is
        // already at the correct position instead of jumping from 0 afterwards.
        if !is_fit_24h {
            if let Some(page) = prev_page_size {
                let upper = (total_grid_height as f64).max(page);
                let preset = gtk::Adjustment::new(
                    0.0,
                    0.0,
                    upper,
                    slot_height as f64,
                    page * 0.9,
                    page,
                );
                let target = compute_target_y(&preset);
                preset.set_value(target);
                timed_scroll.set_vadjustment(Some(&preset));
                initial_applied.set(true);
            }
        }
        let vadj = timed_scroll.vadjustment();

        // Applies the scroll target. Must never run inside GtkViewport::size_allocate,
        // otherwise the adjustment value changes but the child allocation is not updated.
        let apply_target_scroll = {
            let compute_y = compute_target_y.clone();
            let applied = initial_applied.clone();
            let scroll_weak = timed_scroll.downgrade();
            move |adj: &gtk::Adjustment| {
                if applied.get() {
                    return;
                }
                if adj.upper() > 100.0 && adj.page_size() > 50.0 {
                    let target = compute_y(adj);
                    adj.set_value(target);
                    applied.set(true);
                    if let Some(sw) = scroll_weak.upgrade() {
                        if let Some(child) = sw.child() {
                            child.queue_allocate();
                        }
                        sw.queue_allocate();
                    }
                }
            }
        };

        // Defers application to the next main-loop iteration (outside size_allocate)
        let schedule_apply = {
            let apply = apply_target_scroll.clone();
            let scheduled = apply_scheduled.clone();
            let applied = initial_applied.clone();
            move |adj: &gtk::Adjustment| {
                if applied.get() || scheduled.get() {
                    return;
                }
                scheduled.set(true);
                let apply = apply.clone();
                let scheduled = scheduled.clone();
                let adj = adj.clone();
                glib::idle_add_local_once(move || {
                    scheduled.set(false);
                    apply(&adj);
                });
            }
        };

        let schedule_notify = schedule_apply.clone();
        vadj.connect_upper_notify(move |adj| {
            schedule_notify(adj);
        });

        let schedule_page = schedule_apply.clone();
        vadj.connect_page_size_notify(move |adj| {
            if adj.page_size() > 50.0 {
                schedule_page(adj);
            }
        });

        let schedule_map = schedule_apply.clone();
        let vadj_map = vadj.clone();
        timed_scroll.connect_map(move |_| {
            schedule_map(&vadj_map);
        });

        let schedule_idle = schedule_apply;
        let vadj_idle = vadj.clone();
        schedule_idle(&vadj_idle);

        view.append(&timed_scroll);
    }

    fn refresh_agenda_view(&self) {
        if self.calendar_data_state() != CalendarDataState::Ready {
            self.imp().agenda_items.borrow_mut().clear();
            self.imp().agenda_selected_row.set(None);
            self.imp().agenda_rendered_key.replace(None);
            if let Some(empty_box) = self
                .imp()
                .agenda_empty_box
                .borrow()
                .as_ref()
                .and_then(|w| w.downcast_ref::<gtk::Box>())
            {
                clear_box(empty_box);
                empty_box.append(&self.calendar_state_row());
                empty_box.set_visible(true);
            }
            if let Some(scroll) = self.imp().agenda_scroll.borrow().as_ref() {
                scroll.set_visible(false);
            }
            return;
        }

        let visible_range = self.current_calendar_viewport().visible_range;
        let start_date = visible_range.start;
        let end_date = visible_range.last_inclusive();
        let workday_text = configured_workday_text();

        if let Some(title_lbl) = self.imp().agenda_title_label.borrow().as_ref() {
            title_lbl.set_label(
                &gettext("Upcoming appointments · {start} to {end} · Working hours: {hours}")
                    .replace("{start}", &format_date(start_date))
                    .replace("{end}", &format_date(end_date))
                    .replace("{hours}", &workday_text),
            );
        }

        let query = self.imp().calendar_search_query.borrow().clone();
        let category = self.imp().calendar_category_filter.borrow().clone();
        let hidden_count = self.imp().hidden_calendar_sources.borrow().len();
        let revision = self.imp().calendar_revision.get();
        let key = (visible_range, revision, query.clone(), category.clone(), hidden_count);

        if self.imp().agenda_rendered_key.borrow().as_ref() == Some(&key) {
            let is_empty = self.imp().agenda_items.borrow().is_empty();
            if let Some(scroll) = self.imp().agenda_scroll.borrow().as_ref() {
                scroll.set_visible(!is_empty);
            }
            if let Some(empty_box) = self
                .imp()
                .agenda_empty_box
                .borrow()
                .as_ref()
                .and_then(|w| w.downcast_ref::<gtk::Box>())
            {
                empty_box.set_visible(is_empty);
            }

            let items = self.imp().agenda_items.borrow();
            let reconciled_idx = self.resolve_agenda_selection_index(&items);
            self.imp().agenda_selected_row.set(reconciled_idx);
            if let Some(idx) = reconciled_idx {
                if let Some(id) = items[idx].identity() {
                    self.imp()
                        .view_state
                        .borrow_mut()
                        .select_event(Some(id.clone()), Some(idx));
                }
            }

            if let Some(vadj) = self.imp().agenda_vadjustment.borrow().as_ref() {
                if self.imp().agenda_needs_initial_scroll.get() {
                    self.imp().agenda_needs_initial_scroll.set(false);
                    let anchor_date = self.current_calendar_viewport().anchor_date;
                    let target_y = items
                        .iter()
                        .find(|it| !it.is_event_row() && it.date() >= anchor_date)
                        .map(|it| it.y())
                        .unwrap_or(0.0);
                    let page_size = vadj.page_size();
                    let upper = vadj.upper();
                    let max_val = (upper - page_size).max(0.0);
                    vadj.set_value(target_y.min(max_val));
                }
            }
            drop(items);

            if let Some(canvas) = self.imp().agenda_canvas.borrow().as_ref() {
                canvas.queue_draw();
            }
            self.refresh_period_label();
            self.refresh_agenda_detail_pane();
            return;
        }

        // Cache miss: If index is in memory, build and apply plan immediately & synchronously (0ms delay)
        let snapshot_index = self.imp().calendar_snapshot_index.borrow().clone();
        if let Some(index) = snapshot_index {
            self.cancel_calendar_projection();
            let today = Local::now().date_naive();
            let plan = build_agenda_projection_plan(
                &index,
                visible_range,
                &query,
                category.as_deref(),
                &self.imp().hidden_calendar_sources.borrow(),
                today,
            );
            self.apply_agenda_plan(plan, revision);
            return;
        }

        self.start_calendar_projection(CalendarView::Agenda);
    }

    pub(crate) fn resolve_agenda_selection_index(&self, items: &[PreparedAgendaItem]) -> Option<usize> {
        let follow = self.imp().agenda_follow_current.get();
        let selected_identity = self.imp().view_state.borrow().selected_event.clone();
        if !follow && selected_identity.is_some() {
            let target_id = selected_identity.as_ref().unwrap();
            let pos = items.iter().position(|it| it.identity() == Some(target_id));
            if pos.is_some() {
                return pos;
            }
        }
        if !follow {
            if let Some(saved) = self.imp().agenda_selected_row.get() {
                if saved < items.len() && items[saved].is_event_row() {
                    return Some(saved);
                }
            }
        }
        let running_pos = items.iter().position(|it| {
            if let PreparedAgendaItem::EventRow { record, date, .. } = it {
                is_event_running_now(record, *date)
            } else {
                false
            }
        });
        running_pos.or_else(|| {
            let today = chrono::Local::now().date_naive();
            let anchor = self.current_calendar_viewport().anchor_date;
            let target_date = anchor.max(today);
            items.iter().position(|it| it.is_event_row() && it.date() >= target_date)
        }).or_else(|| {
            let today = chrono::Local::now().date_naive();
            items.iter().position(|it| it.is_event_row() && it.date() >= today)
        }).or_else(|| {
            items.iter().position(|it| it.is_event_row())
        })
    }

    fn apply_agenda_plan(&self, plan: AgendaProjectionPlan, revision: u64) {
        let is_empty = plan.is_empty;
        if let Some(empty_box) = self
            .imp()
            .agenda_empty_box
            .borrow()
            .as_ref()
            .and_then(|w| w.downcast_ref::<gtk::Box>())
        {
            if is_empty {
                clear_box(empty_box);
                let empty_row = empty_period_row(
                    &gettext("No upcoming appointments"),
                    &gettext("No VEVENTs loaded for the next 90 days."),
                );
                empty_box.append(&empty_row);
                empty_box.set_visible(true);
            } else {
                empty_box.set_visible(false);
            }
        }

        if let Some(scroll) = self.imp().agenda_scroll.borrow().as_ref() {
            scroll.set_visible(!is_empty);
        }

        let reconciled_idx = self.resolve_agenda_selection_index(&plan.items);
        self.imp().agenda_selected_row.set(reconciled_idx);
        if let Some(idx) = reconciled_idx {
            if let Some(id) = plan.items[idx].identity() {
                self.imp()
                    .view_state
                    .borrow_mut()
                    .select_event(Some(id.clone()), Some(idx));
            }
        }

        let total_height = plan.total_height;
        let visible_range = plan.visible_range;
        self.imp().agenda_items.replace(plan.items);
        let key = (
            visible_range,
            revision,
            self.imp().calendar_search_query.borrow().clone(),
            self.imp().calendar_category_filter.borrow().clone(),
            self.imp().hidden_calendar_sources.borrow().len(),
        );
        self.imp().agenda_rendered_key.replace(Some(key));
        self.refresh_agenda_detail_pane();

        if let Some(vadj) = self.imp().agenda_vadjustment.borrow().as_ref() {
            vadj.set_upper(total_height.max(1) as f64);
            if self.imp().agenda_needs_initial_scroll.get() {
                self.imp().agenda_needs_initial_scroll.set(false);
                let anchor_date = self.current_calendar_viewport().anchor_date;
                let items_ref = self.imp().agenda_items.borrow();
                let target_y = items_ref
                    .iter()
                    .find(|it| !it.is_event_row() && it.date() >= anchor_date)
                    .map(|it| it.y())
                    .unwrap_or(0.0);
                drop(items_ref);
                let page_size = vadj.page_size();
                let upper = vadj.upper();
                let max_val = (upper - page_size).max(0.0);
                vadj.set_value(target_y.min(max_val));
            }
        }
        if let Some(canvas) = self.imp().agenda_canvas.borrow().as_ref() {
            canvas.queue_draw();
        }
    }

    fn apply_agenda_projection_plan(
        &self,
        load: CalendarProjectionLoad,
        plan: AgendaProjectionPlan,
    ) {
        if !self.calendar_projection_is_current(&load) {
            return;
        }
        self.apply_agenda_plan(plan, load.revision);
        self.finish_calendar_projection(&load);
    }

    fn set_current_year(&self, target_year: i32) {
        let current = self.current_calendar_viewport().anchor_date;
        let month = current.month();
        let day = current.day();
        let new_date = NaiveDate::from_ymd_opt(target_year, month, day)
            .or_else(|| NaiveDate::from_ymd_opt(target_year, month, 28))
            .unwrap_or_else(|| NaiveDate::from_ymd_opt(target_year, 1, 1).unwrap());
        *self.imp().current_date.borrow_mut() = new_date;
        self.imp()
            .view_state
            .borrow_mut()
            .set_anchor(new_date, configured_first_weekday());
        self.imp().view_state.borrow_mut().select_civil_day(new_date);
        self.refresh_calendar_views();
    }

    fn create_year_navigation_strip(&self, current_year: i32) -> gtk::Box {
        let strip = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(8)
            .halign(gtk::Align::Center)
            .css_classes(vec!["calendar-year-nav-strip"])
            .build();

        let prev_btn = gtk::Button::builder()
            .icon_name("go-previous-symbolic")
            .css_classes(vec!["flat", "calendar-year-nav-arrow"])
            .tooltip_text(&gettext("Previous year"))
            .build();
        let page_prev = self.downgrade();
        prev_btn.connect_clicked(move |_| {
            if let Some(page) = page_prev.upgrade() {
                page.set_current_year(current_year - 1);
            }
        });
        strip.append(&prev_btn);

        for y in (current_year - 2)..=(current_year + 2) {
            let year_btn = gtk::Button::builder()
                .label(&y.to_string())
                .css_classes(if y == current_year {
                    vec!["flat", "calendar-year-nav-current"]
                } else {
                    vec!["flat", "calendar-year-nav-btn"]
                })
                .tooltip_text(&gettext("Show year {y}").replace("{y}", &y.to_string()))
                .build();
            let page_y = self.downgrade();
            year_btn.connect_clicked(move |_| {
                if let Some(page) = page_y.upgrade() {
                    page.set_current_year(y);
                }
            });
            strip.append(&year_btn);
        }

        let next_btn = gtk::Button::builder()
            .icon_name("go-next-symbolic")
            .css_classes(vec!["flat", "calendar-year-nav-arrow"])
            .tooltip_text(&gettext("Next year"))
            .build();
        let page_next = self.downgrade();
        next_btn.connect_clicked(move |_| {
            if let Some(page) = page_next.upgrade() {
                page.set_current_year(current_year + 1);
            }
        });
        strip.append(&next_btn);

        let today_year = Local::now().date_naive().year();
        if current_year != today_year {
            let today_btn = gtk::Button::builder()
                .label(&crate::i18n::gettext("Today"))
                .css_classes(vec!["flat", "pill"])
                .margin_start(12)
                .tooltip_text(&crate::i18n::gettext("Return to current year"))
                .build();
            let page_today = self.downgrade();
            today_btn.connect_clicked(move |_| {
                if let Some(page) = page_today.upgrade() {
                    page.set_current_year(today_year);
                }
            });
            strip.append(&today_btn);
        }

        strip
    }

    fn render_year_day_schedule(&self, date: NaiveDate, events: &[CalendarEventRecord], panel_width: i32) -> gtk::Widget {
        const HOUR_HEIGHT: f64 = 28.0;
        let today = Local::now().date_naive();
        let is_today = date == today;

        let content_box = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(4)
            .vexpand(true)
            .hexpand(true)
            .build();

        // 1. All-day and multi-day events
        let all_day_events: Vec<&CalendarEventRecord> = events
            .iter()
            .filter(|e| e.all_day || event_display_range(e).map(|r| r.len_days() > 1).unwrap_or(false))
            .collect();
        if !all_day_events.is_empty() {
            let allday_box = gtk::Box::builder()
                .orientation(gtk::Orientation::Vertical)
                .spacing(2)
                .margin_bottom(4)
                .build();
            for ev in all_day_events {
                let range = event_display_range(ev);
                let cont_left = range.as_ref().map(|r| r.start < date).unwrap_or(false);
                let cont_right = range.as_ref().map(|r| r.last_inclusive() > date).unwrap_or(false);
                let chip = calendar_grid_event_chip(self, ev, true, date, None, 1, cont_left, cont_right);
                allday_box.append(&chip);
            }
            content_box.append(&allday_box);
        }

        // 2. Timed events
        let timed_events: Vec<&CalendarEventRecord> = events
            .iter()
            .filter(|e| !e.all_day && event_display_range(e).map(|r| r.len_days() <= 1).unwrap_or(true))
            .collect();

        struct TimedItem<'a> {
            event: &'a CalendarEventRecord,
            start_min: u32,
            end_min: u32,
            time_text: String,
        }

        let mut items: Vec<TimedItem> = Vec::new();
        for ev in timed_events {
            let (start_min, end_min, time_text) = event_occurrence_times_for_date(ev, date, 30);
            items.push(TimedItem {
                event: ev,
                start_min,
                end_min: end_min.max(start_min + 15),
                time_text,
            });
        }

        items.sort_by_key(|it| (it.start_min, it.end_min));

        // Overlapping clusters
        let mut clusters: Vec<Vec<TimedItem>> = Vec::new();
        let mut current_cluster: Vec<TimedItem> = Vec::new();
        let mut cluster_end = 0;

        for item in items {
            if current_cluster.is_empty() || item.start_min < cluster_end {
                cluster_end = cluster_end.max(item.end_min);
                current_cluster.push(item);
            } else {
                clusters.push(std::mem::take(&mut current_cluster));
                cluster_end = item.end_min;
                current_cluster.push(item);
            }
        }
        if !current_cluster.is_empty() {
            clusters.push(current_cluster);
        }

        let timeline_overlay = gtk::Overlay::new();

        let hours_box = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .height_request((24.0 * HOUR_HEIGHT) as i32)
            .hexpand(true)
            .build();

        for h in 0..24 {
            let row = gtk::Box::builder()
                .orientation(gtk::Orientation::Horizontal)
                .height_request(HOUR_HEIGHT as i32)
                .hexpand(true)
                .css_classes(vec!["appointment-timeline-hour-row"])
                .build();
            let lbl = gtk::Label::builder()
                .label(&format!("{h}⁰⁰"))
                .width_request(34)
                .halign(gtk::Align::End)
                .valign(gtk::Align::Start)
                .css_classes(vec!["appointment-timeline-hour-label"])
                .build();
            let sep = gtk::Separator::builder()
                .orientation(gtk::Orientation::Horizontal)
                .hexpand(true)
                .valign(gtk::Align::Start)
                .build();
            row.append(&lbl);
            row.append(&sep);
            hours_box.append(&row);
        }
        timeline_overlay.set_child(Some(&hours_box));

        let timeline_fixed = gtk::Fixed::builder()
            .height_request((24.0 * HOUR_HEIGHT) as i32)
            .hexpand(true)
            .build();

        let is_dark = adw::StyleManager::default().is_dark();

        let events_x = 38.0;
        let available_width = (panel_width as f64 - 68.0).clamp(100.0, 900.0);

        for cluster in clusters {
            let mut col_ends: Vec<u32> = Vec::new();
            let mut placed: Vec<(TimedItem, usize)> = Vec::new();

            for item in cluster {
                let mut col_idx = None;
                for (idx, end) in col_ends.iter_mut().enumerate() {
                    if *end <= item.start_min {
                        *end = item.end_min;
                        col_idx = Some(idx);
                        break;
                    }
                }
                let c = col_idx.unwrap_or_else(|| {
                    let idx = col_ends.len();
                    col_ends.push(item.end_min);
                    idx
                });
                placed.push((item, c));
            }

            let total_cols = col_ends.len().max(1);
            let col_gap = 2.0;
            let col_width = if total_cols > 1 {
                ((available_width - (total_cols as f64 - 1.0) * col_gap) / total_cols as f64).max(30.0)
            } else {
                available_width
            };

            for (item, col_idx) in placed {
                let x = events_x + col_idx as f64 * (col_width + col_gap);
                let y = (item.start_min as f64 / 60.0) * HOUR_HEIGHT;
                let duration = item.end_min.saturating_sub(item.start_min);
                let h = ((duration.max(15) as f64) / 60.0) * HOUR_HEIGHT - 2.0;

                let color = event_color_for_record(item.event);
                let (bg, hover, active, fg) = pastel_colors_for_hex(&color, is_dark);
                let chip_class = ensure_event_chip_css_class(&color, &bg, &hover, &active, &fg);

                let untitled = gettext("(Untitled)");
                let title = if item.event.summary.trim().is_empty() {
                    untitled.as_str()
                } else {
                    item.event.summary.as_str()
                };

                let time_prefix = format_clock_minutes(item.start_min);
                let chip_btn = gtk::Button::builder()
                    .label(&format!("{} {}", time_prefix, title))
                    .halign(gtk::Align::Fill)
                    .valign(gtk::Align::Fill)
                    .width_request(col_width as i32)
                    .height_request(h.max(22.0) as i32)
                    .css_classes(vec!["flat", "calendar-grid-event", chip_class.as_str()])
                    .tooltip_text(&format!("{}\n{} · {}", title, item.time_text, item.event.source_display_name))
                    .build();

                let page_weak = self.downgrade();
                let ev_record = item.event.clone();
                let identity = CalendarEventIdentity::from_event(item.event);
                let gesture = gtk::GestureClick::new();
                gesture.connect_pressed(move |gesture, n_press, _x, _y| {
                    gesture.set_state(gtk::EventSequenceState::Claimed);
                    let (Some(page), Some(widget)) = (page_weak.upgrade(), gesture.widget()) else { return };
                    page.select_and_inspect_event(&ev_record, Some(date));
                    if n_press == 2 {
                        if let Some(id) = identity.as_ref() {
                            page.open_event_editor_for_identity(&widget, id);
                        }
                    } else if n_press == 1 {
                        if !page.is_tag_vpane_visible() {
                            show_calendar_event_details_popover(&page, &widget, &ev_record, Some(date));
                        }
                    }
                });
                chip_btn.add_controller(gesture);

                timeline_fixed.put(&chip_btn, x, y);
            }
        }

        // Current-time red indicator line
        if is_today {
            let now = Local::now().time();
            let now_min = (now.hour() * 60 + now.minute()) as f64;
            let now_y = (now_min / 60.0) * HOUR_HEIGHT;
            let time_line = gtk::Box::builder()
                .css_classes(vec!["calendar-current-time-line"])
                .height_request(2)
                .width_request((available_width + 4.0) as i32)
                .can_target(false)
                .build();
            timeline_fixed.put(&time_line, events_x, now_y);
        }

        timeline_overlay.add_overlay(&timeline_fixed);

        let scrolled = gtk::ScrolledWindow::builder()
            .hscrollbar_policy(gtk::PolicyType::Never)
            .vscrollbar_policy(gtk::PolicyType::Automatic)
            .vexpand(true)
            .hexpand(true)
            .child(&timeline_overlay)
            .build();

        let workday_start_hour = AppSettings::try_new()
            .map(|s| s.calendar_workday_start_minutes() as f64 / 60.0)
            .unwrap_or(8.0);
        let target_hour = if is_today {
            (Local::now().hour() as f64 - 1.0).max(workday_start_hour)
        } else if let Some(first_ev) = events.iter().filter(|e| !e.all_day).next() {
            let (start_min, _, _) = event_occurrence_times_for_date(first_ev, date, 30);
            ((start_min / 60) as f64 - 1.0).clamp(workday_start_hour, 23.0)
        } else {
            workday_start_hour
        };
        let target_y = target_hour * HOUR_HEIGHT;
        let vadj = scrolled.vadjustment();
        let scrolled_flag = Rc::new(Cell::new(false));
        let scrolled_notify = scrolled_flag.clone();
        vadj.connect_upper_notify(move |adj| {
            if !scrolled_notify.get() && adj.upper() > 100.0 {
                scrolled_notify.set(true);
                adj.set_value(target_y);
            }
        });
        let vadj_idle = vadj.clone();
        let scrolled_idle = scrolled_flag.clone();
        glib::idle_add_local_once(move || {
            if !scrolled_idle.get() && vadj_idle.upper() > 0.0 {
                scrolled_idle.set(true);
                vadj_idle.set_value(target_y);
            }
        });

        content_box.append(&scrolled);
        content_box.upcast::<gtk::Widget>()
    }

    fn render_year_day_details(&self, container: &gtk::Box, date: NaiveDate) {
        clear_box(container);

        let selected_events = self
            .events_by_date(CalendarDateRange::single(date))
            .remove(&date)
            .unwrap_or_default();

        self.imp()
            .view_state
            .borrow_mut()
            .reconcile_event_selection(&selected_events);

        // Header
        let header_box = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(4)
            .css_classes(vec!["calendar-year-details-header"])
            .build();

        let title_lbl = gtk::Label::builder()
            .label(&format_date(date))
            .css_classes(vec!["calendar-year-details-title"])
            .halign(gtk::Align::Start)
            .ellipsize(pango::EllipsizeMode::End)
            .build();
        let title_btn = gtk::Button::builder()
            .child(&title_lbl)
            .tooltip_text(&gettext("Open in Day View"))
            .css_classes(vec!["flat", "calendar-year-details-title-btn"])
            .halign(gtk::Align::Start)
            .hexpand(true)
            .build();
        title_btn.set_cursor_from_name(Some("pointer"));
        let page_for_open = self.downgrade();
        title_btn.connect_clicked(move |_| {
            if let Some(page) = page_for_open.upgrade() {
                *page.imp().current_date.borrow_mut() = date;
                page.imp()
                    .view_state
                    .borrow_mut()
                    .set_anchor(date, configured_first_weekday());
                page.imp().view_state.borrow_mut().select_civil_day(date);
                page.select_calendar_view(CalendarView::Day);
            }
        });
        header_box.append(&title_btn);

        // Mode switcher: [ Liste | Tagesplan ]
        let current_mode = self.imp().year_preview_mode.get();
        let switcher_box = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .css_classes(vec!["linked"])
            .build();

        let list_btn = gtk::Button::builder()
            .icon_name("view-list-symbolic")
            .tooltip_text(&gettext("Show as list"))
            .css_classes(if current_mode == YearPreviewMode::List {
                vec!["suggested-action"]
            } else {
                vec!["flat"]
            })
            .build();
        let page_for_list = self.downgrade();
        let container_weak = container.downgrade();
        list_btn.connect_clicked(move |_| {
            if let Some(page) = page_for_list.upgrade() {
                page.imp().year_preview_mode.set(YearPreviewMode::List);
                if let Some(c) = container_weak.upgrade() {
                    page.render_year_day_details(&c, date);
                }
            }
        });
        switcher_box.append(&list_btn);

        let sched_btn = gtk::Button::builder()
            .icon_name("x-office-calendar-symbolic")
            .tooltip_text(&gettext("Show as schedule"))
            .css_classes(if current_mode == YearPreviewMode::Schedule {
                vec!["suggested-action"]
            } else {
                vec!["flat"]
            })
            .build();
        let page_for_sched = self.downgrade();
        let container_weak2 = container.downgrade();
        sched_btn.connect_clicked(move |_| {
            if let Some(page) = page_for_sched.upgrade() {
                page.imp().year_preview_mode.set(YearPreviewMode::Schedule);
                if let Some(c) = container_weak2.upgrade() {
                    page.render_year_day_details(&c, date);
                }
            }
        });
        switcher_box.append(&sched_btn);
        header_box.append(&switcher_box);

        container.append(&header_box);

        // Content
        match current_mode {
            YearPreviewMode::Schedule => {
                let panel_w = match self.imp().year_preview_orientation.get() {
                    YearPreviewOrientation::Side => {
                        let cw = container.width();
                        if cw > 100 {
                            cw
                        } else {
                            self.imp().year_details_side_width.get()
                        }
                    }
                    YearPreviewOrientation::Bottom => {
                        let cw = container.width();
                        if cw > 100 {
                            cw
                        } else {
                            500
                        }
                    }
                };
                let schedule_widget = self.render_year_day_schedule(date, &selected_events, panel_w);
                container.append(&schedule_widget);
            }
            YearPreviewMode::List => {
                let event_list = gtk::ListBox::builder()
                    .selection_mode(gtk::SelectionMode::Single)
                    .css_classes(vec!["calendar-year-details-list"])
                    .vexpand(true)
                    .build();
                self.connect_calendar_event_selection(&event_list);

                let page_weak = self.downgrade();
                event_list.connect_row_activated(move |_, row| {
                    let Some(page) = page_weak.upgrade() else { return };
                    if let Some(identity) = calendar_event_identity_from_list_row(row) {
                        page.open_event_editor_for_identity(row, &identity);
                    }
                });

                if selected_events.is_empty() {
                    let empty_box = gtk::Box::builder()
                        .orientation(gtk::Orientation::Vertical)
                        .spacing(8)
                        .valign(gtk::Align::Center)
                        .halign(gtk::Align::Center)
                        .margin_top(40)
                        .margin_bottom(40)
                        .margin_start(16)
                        .margin_end(16)
                        .build();
                    let empty_icon = gtk::Image::builder()
                        .icon_name("x-office-calendar-symbolic")
                        .pixel_size(32)
                        .css_classes(vec!["dim-label"])
                        .build();
                    let empty_lbl = gtk::Label::builder()
                        .label(&gettext("No appointments"))
                        .css_classes(vec!["dim-label", "heading"])
                        .build();
                    let empty_sub = gtk::Label::builder()
                        .label(
                            &gettext("No appointments scheduled for {date}.")
                                .replace("{date}", &format_date(date)),
                        )
                        .wrap(true)
                        .wrap_mode(pango::WrapMode::WordChar)
                        .justify(gtk::Justification::Center)
                        .css_classes(vec!["dim-label", "caption"])
                        .build();
                    empty_box.append(&empty_icon);
                    empty_box.append(&empty_lbl);
                    empty_box.append(&empty_sub);
                    let empty_row = gtk::ListBoxRow::builder()
                        .activatable(false)
                        .selectable(false)
                        .child(&empty_box)
                        .build();
                    event_list.append(&empty_row);
                } else {
                    for event in &selected_events {
                        self.append_year_day_event_row(&event_list, event, date);
                    }
                    self.restore_calendar_event_selection(&event_list, &selected_events);
                }

                let scroll = gtk::ScrolledWindow::builder()
                    .hscrollbar_policy(gtk::PolicyType::Never)
                    .vscrollbar_policy(gtk::PolicyType::Automatic)
                    .vexpand(true)
                    .child(&event_list)
                    .build();
                container.append(&scroll);
            }
        }
    }

    fn append_year_day_event_row(
        &self,
        event_list: &gtk::ListBox,
        event: &CalendarEventRecord,
        date: NaiveDate,
    ) {
        let row = gtk::ListBoxRow::builder()
            .activatable(true)
            .selectable(true)
            .css_classes(vec!["calendar-year-event-row"])
            .build();

        let hbox = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(10)
            .margin_start(12)
            .margin_end(12)
            .margin_top(8)
            .margin_bottom(8)
            .hexpand(true)
            .build();

        // 4px vertical color bar in event / calendar color
        let color = event_color_for_record(event);
        let bar_class = ensure_year_event_bar_css_class(&color);
        let color_bar = gtk::Box::builder()
            .width_request(4)
            .valign(gtk::Align::Fill)
            .css_classes(vec!["calendar-year-event-bar", bar_class.as_str()])
            .build();
        hbox.append(&color_bar);

        let text_col = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(2)
            .hexpand(true)
            .build();

        let title = if event.summary.trim().is_empty() {
            gettext("(Untitled)")
        } else {
            event.summary.clone()
        };

        let title_lbl = gtk::Label::builder()
            .label(&title)
            .halign(gtk::Align::Start)
            .wrap(true)
            .wrap_mode(pango::WrapMode::WordChar)
            .css_classes(vec!["calendar-year-event-title"])
            .build();
        text_col.append(&title_lbl);

        // Time and details
        let time_str = if event.all_day {
            crate::i18n::gettext("All Day")
        } else {
            let (_, _, text) = event_occurrence_times_for_date(event, date, 30);
            if !text.is_empty() {
                text
            } else if !event.start.is_empty() {
                if !event.end.is_empty() && event.start != event.end {
                    format!("{}–{}", event.start, event.end)
                } else {
                    event.start.clone()
                }
            } else {
                String::new()
            }
        };

        let mut sub_parts = Vec::new();
        if !time_str.is_empty() {
            sub_parts.push(time_str);
        }
        if !event.location.trim().is_empty() {
            sub_parts.push(event.location.trim().to_string());
        }
        if !event.source_display_name.trim().is_empty() {
            sub_parts.push(event.source_display_name.trim().to_string());
        }

        if !sub_parts.is_empty() {
            let sub_lbl = gtk::Label::builder()
                .label(&sub_parts.join(" · "))
                .halign(gtk::Align::Start)
                .ellipsize(pango::EllipsizeMode::End)
                .css_classes(vec!["caption", "dim-label"])
                .build();
            text_col.append(&sub_lbl);
        }

        hbox.append(&text_col);
        row.set_child(Some(&hbox));

        if let Some(identity) = CalendarEventIdentity::from_event(event) {
            unsafe {
                row.set_data("event-id", identity.uid.clone());
                row.set_data("event-source-uid", identity.source_uid.clone());
                row.set_data("event-source-object-key", identity.source_object_key.clone());
                row.set_data("event-recurrence-id", identity.recurrence_id.clone().unwrap_or_default());
            }

            let page_weak = self.downgrade();
            let identity_for_click = identity.clone();
            row.connect_activate(move |r| {
                if let Some(page) = page_weak.upgrade() {
                    page.open_event_editor_for_identity(r, &identity_for_click);
                }
            });
        }

        row.set_tooltip_text(Some(&format!("{}\n{}", title, crate::i18n::gettext("(Click to edit)"))));
        event_list.append(&row);
    }

    fn calendar_month_name(month: u32) -> String {
        Self::month_name(month)
    }

    fn prepare_year_canvas_layout(
        year: i32,
        width: f64,
        show_week_numbers: bool,
        first_weekday: Weekday,
    ) -> PreparedYearCanvasLayout {
        Self::prepare_year_canvas_layout_for_viewport(
            year,
            width,
            0.0,
            show_week_numbers,
            first_weekday,
        )
    }

    fn prepare_year_canvas_layout_for_viewport(
        year: i32,
        width: f64,
        avail_height: f64,
        show_week_numbers: bool,
        first_weekday: Weekday,
    ) -> PreparedYearCanvasLayout {
        let scale = configured_chip_scale().clamp(0.75, 1.50);
        let eff_w = width / scale;
        let num_cols = if eff_w >= 860.0 || (avail_height > 200.0 && scale <= 1.001 && width >= 660.0) {
            4
        } else if eff_w >= 620.0 || (avail_height > 200.0 && scale <= 1.001 && width >= 480.0) {
            3
        } else {
            2
        };
        let num_rows: u32 = (12 + num_cols - 1) / num_cols;

        let margin_x = 16.0f64;
        let col_spacing = 16.0f64;

        let avail_w = (width - 2.0 * margin_x - (num_cols - 1) as f64 * col_spacing).max(200.0);
        let card_w = (avail_w / num_cols as f64).floor();
        let total_cards_w = num_cols as f64 * card_w + (num_cols - 1) as f64 * col_spacing;
        let actual_margin_x = ((width - total_cards_w) / 2.0).max(margin_x);

        let card_pad_x = 6.0f64;
        let card_pad_top = 4.0f64;
        let card_pad_bottom = 4.0f64;
        let total_rows = 6usize;

        let (margin_top, margin_bottom, row_spacing, header_h, weekday_h, cell_h, header_gap, weekday_gap) =
            if avail_height > 200.0 {
                let zoom_factor = if scale > 1.0 { scale } else { 1.0 };
                let target_h = avail_height * zoom_factor;
                let m_top = (target_h * 0.016).round().clamp(6.0, 16.0);
                let m_bot = (target_h * 0.016).round().clamp(6.0, 20.0);
                let r_space = (target_h * 0.020).round().clamp(6.0, 24.0);
                let fit_card_h = ((target_h - m_top - m_bot - (num_rows - 1) as f64 * r_space)
                    / num_rows as f64)
                    .floor()
                    .max(92.0);
                let h_gap = 2.0f64;
                let w_gap = 2.0f64;
                let hdr_h = (fit_card_h * 0.14).round().clamp(15.0, (28.0 * zoom_factor).round());
                let wk_h = (fit_card_h * 0.095).round().clamp(11.0, (18.0 * zoom_factor).round());
                let c_h = ((fit_card_h - card_pad_top - card_pad_bottom - h_gap - w_gap - hdr_h - wk_h)
                    / total_rows as f64)
                    .floor()
                    .clamp(11.0, (26.0 * zoom_factor).round());
                (m_top, m_bot, r_space, hdr_h, wk_h, c_h, h_gap, w_gap)
            } else {
                let m_top = 16.0f64;
                let m_bot = 24.0f64;
                let r_space = (24.0f64 * scale).round().max(12.0);
                let hdr_h = (28.0f64 * scale).round();
                let wk_h = (18.0f64 * scale).round();
                let c_h = (24.0f64 * scale).round();
                (m_top, m_bot, r_space, hdr_h, wk_h, c_h, 4.0f64, 4.0f64)
            };

        let col_offset = if show_week_numbers { 1 } else { 0 };
        let num_grid_cols = 7 + col_offset;
        let cell_w = ((card_w - 2.0 * card_pad_x) / num_grid_cols as f64).floor();
        let card_h = card_pad_top
            + header_h
            + header_gap
            + weekday_h
            + weekday_gap
            + (total_rows as f64 * cell_h)
            + card_pad_bottom;

        let cards_block_h = num_rows as f64 * card_h + (num_rows.saturating_sub(1)) as f64 * row_spacing;
        let actual_margin_top = if avail_height > 200.0 && scale <= 1.001 && avail_height > cards_block_h {
            ((avail_height - cards_block_h) / 2.0).floor().max(margin_top)
        } else {
            margin_top
        };

        let mut months = Vec::with_capacity(12);

        for month in 1..=12 {
            let m_idx = month - 1;
            let c = m_idx % num_cols;
            let r = m_idx / num_cols;

            let card_x = actual_margin_x + c as f64 * (card_w + col_spacing);
            let card_y = actual_margin_top + r as f64 * (card_h + row_spacing);

            let first_of_month = NaiveDate::from_ymd_opt(year, month, 1)
                .unwrap_or_else(|| NaiveDate::from_ymd_opt(2026, 1, 1).unwrap());
            let last_of_month = match month {
                12 => NaiveDate::from_ymd_opt(year, 12, 31),
                m => NaiveDate::from_ymd_opt(year, m + 1, 1).map(|d| d - Duration::days(1)),
            }
            .unwrap_or(first_of_month);

            let grid_start = week_start_for(first_of_month, first_weekday);

            let weekday_y = card_y + card_pad_top + header_h + header_gap;
            let days_y = weekday_y + weekday_h + weekday_gap;

            months.push(PreparedYearMonthLayout {
                month,
                card_x,
                card_y,
                card_w,
                card_h,
                header_h,
                weekday_y,
                weekday_h,
                days_y,
                cell_w,
                cell_h,
                col_offset,
                first_of_month,
                last_of_month,
                grid_start,
                total_rows,
            });
        }

        let raw_total_h = actual_margin_top + cards_block_h + margin_bottom;
        let total_h = if avail_height > 200.0 && scale <= 1.001 {
            raw_total_h.min(avail_height)
        } else {
            raw_total_h
        };

        PreparedYearCanvasLayout {
            year,
            width,
            height: total_h,
            months,
            show_week_numbers,
            first_weekday,
        }
    }

    fn hit_test_year_canvas(
        layout: &PreparedYearCanvasLayout,
        x: f64,
        y: f64,
    ) -> Option<YearCanvasHitTarget> {
        for m in &layout.months {
            if x < m.card_x || x > m.card_x + m.card_w || y < m.card_y || y > m.card_y + m.card_h {
                continue;
            }

            // Check header click (Month title)
            if y >= m.card_y && y < m.weekday_y {
                return Some(YearCanvasHitTarget::MonthHeader(m.month));
            }

            // Check day cell click
            if y >= m.days_y && y <= m.card_y + m.card_h {
                let row_idx = ((y - m.days_y) / m.cell_h).floor() as usize;
                let col_idx = ((x - (m.card_x + 6.0)) / m.cell_w).floor() as usize;

                if row_idx < m.total_rows && col_idx >= m.col_offset && col_idx < m.col_offset + 7 {
                    let day_col = col_idx - m.col_offset;
                    let cell_date = m.grid_start + Duration::days((row_idx * 7 + day_col) as i64);
                    if cell_date.month() == m.month && cell_date.year() == layout.year {
                        return Some(YearCanvasHitTarget::Day(cell_date));
                    }
                }
            }
        }
        None
    }

    pub(crate) fn year_grid_day_rect(
        layout: &PreparedYearCanvasLayout,
        date: NaiveDate,
        scroll_y: f64,
    ) -> gdk::Rectangle {
        for m in &layout.months {
            if m.month == date.month() {
                let offset_days = (date - m.grid_start).num_days().max(0) as usize;
                let row = offset_days / 7;
                let col = offset_days % 7;
                let cell_x = m.card_x + 6.0 + (col + m.col_offset) as f64 * m.cell_w;
                let cell_y = m.days_y + row as f64 * m.cell_h - scroll_y;
                return gdk::Rectangle::new(
                    cell_x.round() as i32,
                    cell_y.round() as i32,
                    m.cell_w.round().max(16.0) as i32,
                    m.cell_h.round().max(16.0) as i32,
                );
            }
        }
        gdk::Rectangle::new(24, 24, 24, 24)
    }

    fn draw_year_canvas(
        cr: &gtk::cairo::Context,
        layout: &PreparedYearCanvasLayout,
        markers: &BTreeMap<NaiveDate, usize>,
        selected_day: Option<NaiveDate>,
        today: NaiveDate,
        hovered_target: Option<&YearCanvasHitTarget>,
        is_dark: bool,
    ) {
        Self::draw_year_canvas_with_style(
            cr,
            layout,
            markers,
            &HashMap::new(),
            YearGridIndicatorStyle::SingleDot,
            selected_day.map(|d| (d, d)),
            today,
            hovered_target,
            is_dark,
        );
    }

    fn draw_year_canvas_with_style(
        cr: &gtk::cairo::Context,
        layout: &PreparedYearCanvasLayout,
        markers: &BTreeMap<NaiveDate, usize>,
        day_previews: &HashMap<NaiveDate, Vec<YearPlannerDayPreviewItem>>,
        indicator_style: YearGridIndicatorStyle,
        selected_range: Option<(NaiveDate, NaiveDate)>,
        today: NaiveDate,
        hovered_target: Option<&YearCanvasHitTarget>,
        is_dark: bool,
    ) {
        let fg = if is_dark { 1.0 } else { 0.0 };
        let primary_alpha = if is_dark { 0.95 } else { 0.88 };
        let secondary_alpha = if is_dark { 0.55 } else { 0.45 };

        let weekday_names: Vec<&'static str> = match layout.first_weekday {
            Weekday::Sun => vec!["So", "Mo", "Di", "Mi", "Do", "Fr", "Sa"],
            _ => vec!["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"],
        };

        let (clip_y1, clip_y2) = match cr.clip_extents() {
            Ok((_, y1, _, y2)) => (y1, y2),
            Err(_) => (0.0, f64::MAX),
        };

        for m in &layout.months {
            if m.card_y + m.card_h < clip_y1 || m.card_y > clip_y2 {
                continue;
            }
            // Month Header (Title) - clean GNOME typography without card border
            let is_header_hovered = hovered_target == Some(&YearCanvasHitTarget::MonthHeader(m.month));
            let m_name = Self::calendar_month_name(m.month);

            if is_header_hovered {
                let pill_w = (m.card_w * 0.75).clamp(80.0, 140.0);
                let pill_x = m.card_x + (m.card_w - pill_w) / 2.0;
                let pill_y = m.card_y + 2.0;
                cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.20 } else { 0.12 });
                draw_cairo_rounded_rect(cr, pill_x, pill_y, pill_w, m.header_h - 2.0, 6.0);
                let _ = cr.fill();
            }

            cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
            cr.set_font_size((m.header_h * 0.56).clamp(12.5, 15.5));
            if is_header_hovered {
                cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
            } else {
                cr.set_source_rgba(fg, fg, fg, primary_alpha);
            }
            if let Ok(ext) = cr.text_extents(&m_name) {
                let tx = m.card_x + (m.card_w - ext.width()) / 2.0 - ext.x_bearing();
                let ty = m.card_y + 2.0 + m.header_h / 2.0 - ext.height() / 2.0 - ext.y_bearing();
                cr.move_to(tx, ty);
                let _ = cr.show_text(&m_name);
            }

            // Weekday headers
            cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
            cr.set_font_size((m.weekday_h * 0.62).clamp(9.5, 11.0));
            cr.set_source_rgba(fg, fg, fg, secondary_alpha);

            if layout.show_week_numbers {
                let kw_x = m.card_x + 6.0;
                if let Ok(ext) = cr.text_extents("KW") {
                    let tx = kw_x + (m.cell_w - ext.width()) / 2.0 - ext.x_bearing();
                    let ty = m.weekday_y + m.weekday_h / 2.0 - ext.height() / 2.0 - ext.y_bearing();
                    cr.move_to(tx, ty);
                    let _ = cr.show_text("KW");
                }
            }

            for (col_i, &w_name) in weekday_names.iter().enumerate() {
                let col_x = m.card_x + 6.0 + (col_i + m.col_offset) as f64 * m.cell_w;
                if let Ok(ext) = cr.text_extents(w_name) {
                    let tx = col_x + (m.cell_w - ext.width()) / 2.0 - ext.x_bearing();
                    let ty = m.weekday_y + m.weekday_h / 2.0 - ext.height() / 2.0 - ext.y_bearing();
                    cr.move_to(tx, ty);
                    let _ = cr.show_text(w_name);
                }
            }

            // Days
            let mut curr_week = m.grid_start;
            for row in 0..m.total_rows {
                if curr_week > m.last_of_month && row > 0 {
                    let first_day_in_row = curr_week;
                    if first_day_in_row.month() != m.month {
                        break;
                    }
                }

                // KW column
                if layout.show_week_numbers {
                    let kw = (curr_week + Duration::days(3)).iso_week().week();
                    let kw_str = kw.to_string();
                    let kw_x = m.card_x + 6.0;
                    let cell_y = m.days_y + row as f64 * m.cell_h;
                    cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
                    cr.set_font_size((m.cell_h * 0.45).clamp(8.5, 10.0));
                    cr.set_source_rgba(fg, fg, fg, secondary_alpha * 0.7);
                    if let Ok(ext) = cr.text_extents(&kw_str) {
                        let tx = kw_x + (m.cell_w - ext.width()) / 2.0 - ext.x_bearing();
                        let ty = cell_y + m.cell_h / 2.0 - ext.height() / 2.0 - ext.y_bearing();
                        cr.move_to(tx, ty);
                        let _ = cr.show_text(&kw_str);
                    }
                }

                // Soft, borderless connecting pill for multi-day range selection in this week row
                if let Some((s, e)) = selected_range.filter(|(s, e)| s < e) {
                    let mut first_sel_col: Option<usize> = None;
                    let mut last_sel_col: Option<usize> = None;
                    for col in 0..7 {
                        let cell_date = curr_week + Duration::days(col as i64);
                        if cell_date.month() == m.month && cell_date >= s && cell_date <= e {
                            if first_sel_col.is_none() {
                                first_sel_col = Some(col);
                            }
                            last_sel_col = Some(col);
                        }
                    }
                    if let (Some(fc), Some(lc)) = (first_sel_col, last_sel_col) {
                        let cell_y = m.days_y + row as f64 * m.cell_h;
                        let cy = cell_y + m.cell_h / 2.0;
                        let band_r = (m.cell_w.min(m.cell_h) / 2.0 - 1.5).clamp(7.0, 11.5);
                        let start_cx = m.card_x + 6.0 + (fc + m.col_offset) as f64 * m.cell_w + m.cell_w / 2.0;
                        let end_cx = m.card_x + 6.0 + (lc + m.col_offset) as f64 * m.cell_w + m.cell_w / 2.0;
                        let pill_x = start_cx - band_r;
                        let pill_w = (end_cx + band_r) - pill_x;
                        draw_cairo_rounded_rect(cr, pill_x, cy - band_r, pill_w, band_r * 2.0, band_r);
                        cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.22 } else { 0.14 });
                        let _ = cr.fill();
                    }
                }

                for col in 0..7 {
                    let cell_date = curr_week + Duration::days(col as i64);
                    if cell_date.month() != m.month {
                        continue;
                    }

                    let cell_x = m.card_x + 6.0 + (col + m.col_offset) as f64 * m.cell_w;
                    let cell_y = m.days_y + row as f64 * m.cell_h;
                    let cx = cell_x + m.cell_w / 2.0;
                    let cy = cell_y + m.cell_h / 2.0;
                    let radius = (m.cell_w.min(m.cell_h) / 2.0 - 1.5).clamp(7.0, 11.5);

                    let is_selected = selected_range
                        .map(|(s, e)| cell_date >= s && cell_date <= e)
                        .unwrap_or(false);
                    let is_multi_range = selected_range.map(|(s, e)| s < e).unwrap_or(false);
                    let is_range_endpoint = selected_range
                        .map(|(s, e)| s < e && (cell_date == s || cell_date == e))
                        .unwrap_or(false);
                    let is_today = cell_date == today;
                    let is_hovered = hovered_target == Some(&YearCanvasHitTarget::Day(cell_date));
                    let event_count = markers.get(&cell_date).copied().unwrap_or(0);

                    let heatmap_rgba = |count: usize, dark: bool| -> (f64, f64, f64, f64) {
                        if count == 1 {
                            // 1 event: soft emerald/mint green (calm/light load)
                            if dark {
                                (46.0 / 255.0, 194.0 / 255.0, 126.0 / 255.0, 0.28)
                            } else {
                                (38.0 / 255.0, 162.0 / 255.0, 105.0 / 255.0, 0.22)
                            }
                        } else if count == 2 {
                            // 2 events: warm amber/gold (moderate load)
                            if dark {
                                (245.0 / 255.0, 194.0 / 255.0, 17.0 / 255.0, 0.34)
                            } else {
                                (229.0 / 255.0, 165.0 / 255.0, 10.0 / 255.0, 0.26)
                            }
                        } else if count == 3 {
                            // 3 events: vibrant orange (busy day)
                            if dark {
                                (255.0 / 255.0, 120.0 / 255.0, 0.0 / 255.0, 0.40)
                            } else {
                                (230.0 / 255.0, 97.0 / 255.0, 0.0 / 255.0, 0.30)
                            }
                        } else {
                            // 4+ events: coral/crimson (high density / hot)
                            if dark {
                                (246.0 / 255.0, 97.0 / 255.0, 81.0 / 255.0, 0.46)
                            } else {
                                (224.0 / 255.0, 27.0 / 255.0, 36.0 / 255.0, 0.34)
                            }
                        }
                    };

                    // Day shape: circle indicator on today, single selected day, or start/end caps of a multi-day range
                    if is_today {
                        cr.arc(cx, cy, radius, 0.0, 2.0 * std::f64::consts::PI);
                        cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
                        let _ = cr.fill();
                    } else if is_range_endpoint {
                        cr.arc(cx, cy, radius, 0.0, 2.0 * std::f64::consts::PI);
                        cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.88 } else { 0.85 });
                        let _ = cr.fill();
                    } else if is_selected && !is_multi_range {
                        cr.arc(cx, cy, radius, 0.0, 2.0 * std::f64::consts::PI);
                        if indicator_style == YearGridIndicatorStyle::Heatmap && event_count > 0 {
                            let (hr, hg, hb, ha) = heatmap_rgba(event_count, is_dark);
                            cr.set_source_rgba(hr, hg, hb, ha);
                        } else {
                            cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.30 } else { 0.22 });
                        }
                        let _ = cr.fill();
                        if indicator_style == YearGridIndicatorStyle::Heatmap {
                            cr.arc(cx, cy, radius, 0.0, 2.0 * std::f64::consts::PI);
                            cr.set_line_width(1.5);
                            cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 0.92);
                            let _ = cr.stroke();
                        }
                    } else if !is_selected && indicator_style == YearGridIndicatorStyle::Heatmap && event_count > 0 {
                        let (hr, hg, hb, ha) = heatmap_rgba(event_count, is_dark);
                        cr.arc(cx, cy, radius, 0.0, 2.0 * std::f64::consts::PI);
                        cr.set_source_rgba(hr, hg, hb, ha);
                        let _ = cr.fill();
                    } else if is_hovered {
                        cr.arc(cx, cy, radius, 0.0, 2.0 * std::f64::consts::PI);
                        cr.set_source_rgba(fg, fg, fg, if is_dark { 0.08 } else { 0.05 });
                        let _ = cr.fill();
                    }

                    // Day number text
                    let day_str = cell_date.day().to_string();
                    cr.select_font_face(
                        "sans-serif",
                        gtk::cairo::FontSlant::Normal,
                        if is_selected || is_today || (indicator_style == YearGridIndicatorStyle::Heatmap && event_count >= 4) {
                            gtk::cairo::FontWeight::Bold
                        } else {
                            gtk::cairo::FontWeight::Normal
                        },
                    );
                    cr.set_font_size((m.cell_h * 0.52).clamp(9.5, 12.0));

                    if is_today || is_range_endpoint {
                        cr.set_source_rgb(1.0, 1.0, 1.0);
                    } else if is_selected {
                        cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
                    } else {
                        cr.set_source_rgba(fg, fg, fg, primary_alpha);
                    }

                    let show_bottom_dots = event_count > 0 && indicator_style != YearGridIndicatorStyle::Heatmap;
                    if let Ok(ext) = cr.text_extents(&day_str) {
                        let text_cy = if show_bottom_dots { cy - 1.5 } else { cy };
                        let tx = cx - ext.width() / 2.0 - ext.x_bearing();
                        let ty = text_cy - ext.height() / 2.0 - ext.y_bearing();
                        cr.move_to(tx, ty);
                        let _ = cr.show_text(&day_str);
                    }

                    // Event indicator dot(s)
                    if show_bottom_dots {
                        let dot_y = cy + (radius * 0.65).clamp(5.0, 7.5);
                        match indicator_style {
                            YearGridIndicatorStyle::ColoredDots => {
                                let mut colors: Vec<(u8, u8, u8)> = day_previews
                                    .get(&cell_date)
                                    .map(|items| items.iter().take(3).map(|it| it.color_rgb).collect())
                                    .unwrap_or_default();
                                if colors.is_empty() {
                                    colors.push((53, 132, 228));
                                }
                                let n = colors.len().min(3);
                                let dot_r = 1.55;
                                let gap = 4.0;
                                let total_w = (n as f64 - 1.0) * gap;
                                let start_x = cx - total_w * 0.5;
                                for (i, &(r, g, b)) in colors.iter().take(3).enumerate() {
                                    let dx = start_x + i as f64 * gap;
                                    cr.arc(dx, dot_y, dot_r, 0.0, 2.0 * std::f64::consts::PI);
                                    if is_today {
                                        cr.set_source_rgba(1.0, 1.0, 1.0, 0.92);
                                    } else {
                                        cr.set_source_rgba(r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0, 0.92);
                                    }
                                    let _ = cr.fill();
                                }
                            }
                            YearGridIndicatorStyle::SingleDot | YearGridIndicatorStyle::Heatmap => {
                                cr.arc(cx, dot_y, 1.6, 0.0, 2.0 * std::f64::consts::PI);
                                if is_today {
                                    cr.set_source_rgba(1.0, 1.0, 1.0, 0.90);
                                } else if is_selected {
                                    cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
                                } else {
                                    cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 0.85);
                                }
                                let _ = cr.fill();
                            }
                        }
                    }
                }

                curr_week = curr_week + Duration::days(7);
            }
        }
    }

    fn build_multi_year_summaries_from_index(
        index: &CalendarSnapshotIndex,
        years: &[i32],
        query: &str,
        category: Option<&str>,
        hidden_sources: &HashSet<String>,
    ) -> BTreeMap<(i32, u32), MultiYearMonthSummary> {
        let Some(&min_year) = years.iter().min() else {
            return BTreeMap::new();
        };
        let Some(&max_year) = years.iter().max() else {
            return BTreeMap::new();
        };
        let Some(range_start) = NaiveDate::from_ymd_opt(min_year, 1, 1) else {
            return BTreeMap::new();
        };
        let Some(range_end) = NaiveDate::from_ymd_opt(max_year + 1, 1, 1) else {
            return BTreeMap::new();
        };
        let full_range = CalendarDateRange::new(range_start, range_end);
        let years_set: HashSet<i32> = years.iter().copied().collect();

        let hide_cancelled = configured_hide_cancelled_events();
        let normalized_query = query.trim().to_lowercase();
        let normalized_category = category
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_lowercase);

        let mut filter_cache: Vec<Option<bool>> = vec![None; index.metas.len()];
        let mut check_match = |ev_idx: usize| -> bool {
            if let Some(res) = filter_cache[ev_idx] {
                return res;
            }
            let matched = index_event_matches_filter(
                index,
                ev_idx,
                &normalized_query,
                normalized_category.as_deref(),
                hidden_sources,
                hide_cancelled,
            );
            filter_cache[ev_idx] = Some(matched);
            matched
        };

        let mut occurrences: Vec<(usize, CalendarDateRange)> = Vec::with_capacity(512);
        for (date, bucket) in index.date_buckets.range(full_range.start..full_range.end) {
            for &ev_idx in bucket {
                if check_match(ev_idx) {
                    occurrences.push((ev_idx, CalendarDateRange::single(*date)));
                }
            }
        }

        for &(ev_idx, range) in &index.long_events {
            if range.intersects(full_range) && check_match(ev_idx) {
                occurrences.push((ev_idx, range));
            }
        }

        for &ev_idx in &index.recurring_events {
            if !check_match(ev_idx) {
                continue;
            }
            let meta = &index.metas[ev_idx];
            let Some(initial_range) = meta.display_range else { continue };
            let initial_start = initial_range.start;
            let span_days = initial_range.len_days().saturating_sub(1);
            let mut occ_starts = BTreeSet::new();

            if !meta.excluded_dates.contains(&initial_start) {
                let initial_occ_end = initial_start
                    .checked_add_signed(Duration::days(span_days + 1))
                    .unwrap_or(initial_range.end);
                let occ_r = CalendarDateRange::new(initial_start, initial_occ_end);
                if occ_r.intersects(full_range) {
                    occ_starts.insert(initial_start);
                }
            }
            for &rdate in &meta.rdate_values {
                if !meta.excluded_dates.contains(&rdate) {
                    let r_end = rdate
                        .checked_add_signed(Duration::days(span_days + 1))
                        .unwrap_or(rdate);
                    if CalendarDateRange::new(rdate, r_end).intersects(full_range) {
                        occ_starts.insert(rdate);
                    }
                }
            }
            if let Some(ref rule) = meta.recurrence_rule {
                let from = full_range
                    .start
                    .checked_sub_signed(Duration::days(span_days))
                    .unwrap_or(full_range.start);
                if initial_start < full_range.end {
                    let starts = recurrence_occurrences_in_range(
                        rule,
                        initial_start,
                        from,
                        full_range.end,
                        &meta.excluded_dates,
                    );
                    occ_starts.extend(starts);
                }
            }
            for occ_start in occ_starts {
                let Some(occ_end) = occ_start.checked_add_signed(Duration::days(span_days + 1)) else {
                    continue;
                };
                let occ_range = CalendarDateRange::new(occ_start, occ_end);
                if occ_range.intersects(full_range) {
                    occurrences.push((ev_idx, occ_range));
                }
            }
        }

        let mut month_identities: BTreeMap<(i32, u32), (BTreeSet<CalendarEventIdentity>, usize)> =
            BTreeMap::new();
        let mut month_busy_days: BTreeMap<(i32, u32), [bool; 32]> = BTreeMap::new();
        let mut month_previews: BTreeMap<(i32, u32), Vec<(u32, u32, String, (u8, u8, u8))>> =
            BTreeMap::new();
        let mut month_day_counts: BTreeMap<(i32, u32), [u8; 32]> = BTreeMap::new();
        let mut month_day_colors: BTreeMap<(i32, u32), [Option<(u8, u8, u8)>; 32]> = BTreeMap::new();
        let untitled = gettext("(Untitled)");

        for &(ev_idx, occ_range) in &occurrences {
            let event = &index.snapshot.events[ev_idx];
            let meta = &index.metas[ev_idx];
            let title = if event.summary.trim().is_empty() {
                untitled.clone()
            } else {
                event.summary.trim().to_string()
            };
            let cs = occ_range.start.max(full_range.start);
            let ce = occ_range.last_inclusive().min(full_range.last_inclusive());
            let mut cur = cs;
            let mut visited_months_for_occ: Vec<(i32, u32, u32, u32)> = Vec::new();
            while cur <= ce {
                let y = cur.year();
                if years_set.contains(&y) {
                    let m = cur.month();
                    let d = cur.day();
                    let ym = (y, m);
                    let d_idx = (d as usize).min(31);
                    let counts = month_day_counts.entry(ym).or_insert([0; 32]);
                    counts[d_idx] = counts[d_idx].saturating_add(1);
                    let colors = month_day_colors.entry(ym).or_insert([None; 32]);
                    if colors[d_idx].is_none() {
                        colors[d_idx] = Some(meta.color_rgb);
                    }
                    let busy = month_busy_days.entry(ym).or_insert([false; 32]);
                    busy[d_idx] = true;
                    if let Some(last) = visited_months_for_occ.last_mut().filter(|x| x.0 == y && x.1 == m) {
                        last.3 = d;
                    } else {
                        visited_months_for_occ.push((y, m, d, d));
                    }
                }
                let Some(next) = cur.succ_opt() else { break };
                cur = next;
            }

            for (y, m, d_start, d_end) in visited_months_for_occ {
                let ym = (y, m);
                let (seen_ids, anon_count) = month_identities.entry(ym).or_default();
                let is_new_in_month = if let Some(ref id) = meta.identity {
                    seen_ids.insert(id.clone())
                } else {
                    *anon_count += 1;
                    true
                };
                if is_new_in_month {
                    let previews = month_previews.entry(ym).or_default();
                    if previews.len() < 32 {
                        let date_prefix = if d_start == d_end {
                            format!("{:02}.", d_start)
                        } else {
                            format!("{:02}.–{:02}.", d_start, d_end)
                        };
                        previews.push((
                            d_start,
                            d_end,
                            format!("{date_prefix} {title}"),
                            meta.color_rgb,
                        ));
                    }
                }
            }
        }

        let mut summaries: BTreeMap<(i32, u32), MultiYearMonthSummary> = BTreeMap::new();
        for &y in years {
            for m in 1..=12 {
                let ym = (y, m);
                let event_count = month_identities
                    .get(&ym)
                    .map(|(ids, anon)| ids.len() + *anon)
                    .unwrap_or(0);
                let busy_days = month_busy_days
                    .get(&ym)
                    .map(|arr| arr.iter().filter(|&&b| b).count() as u32)
                    .unwrap_or(0);
                let mut raw_previews = month_previews.remove(&ym).unwrap_or_default();
                raw_previews.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)).then_with(|| a.2.cmp(&b.2)));
                let previews: Vec<(String, (u8, u8, u8))> = raw_previews
                    .into_iter()
                    .take(24)
                    .map(|(_, _, text, c)| (text, c))
                    .collect();
                let day_counts = month_day_counts.remove(&ym).unwrap_or([0; 32]);
                let day_colors = month_day_colors.remove(&ym).unwrap_or([None; 32]);
                if event_count > 0 || busy_days > 0 {
                    summaries.insert(
                        ym,
                        MultiYearMonthSummary {
                            event_count,
                            busy_days,
                            previews,
                            day_counts,
                            day_colors,
                        },
                    );
                }
            }
        }
        summaries
    }

    pub(crate) fn ensure_multi_year_summaries_for_anchor(&self, anchor_year: i32) {
        let query = self.imp().calendar_search_query.borrow().clone();
        let category = self.imp().calendar_category_filter.borrow().clone();
        let hidden_sources = self.imp().hidden_calendar_sources.borrow().clone();
        let hidden_count = hidden_sources.len();
        let revision = self.imp().calendar_revision.get();
        let filter_key = (revision, query.clone(), category.clone(), hidden_count);

        if self.imp().multi_year_rendered_key.borrow().as_ref() != Some(&filter_key) {
            self.imp().multi_year_summaries.borrow_mut().clear();
            self.imp().multi_year_loaded_years.borrow_mut().clear();
            self.imp().multi_year_loading_years.borrow_mut().clear();
            self.imp().multi_year_rendered_key.replace(Some(filter_key.clone()));
        }

        let start_year = anchor_year - 8;
        let end_year = anchor_year + 23;
        let missing_years: Vec<i32> = {
            let loaded = self.imp().multi_year_loaded_years.borrow();
            let loading = self.imp().multi_year_loading_years.borrow();
            (start_year..=end_year)
                .filter(|y| !loaded.contains(y) && !loading.contains(y))
                .collect()
        };
        if missing_years.is_empty() {
            return;
        }

        let Some(index) = self
            .imp()
            .calendar_snapshot_index
            .borrow()
            .as_ref()
            .cloned()
        else {
            return;
        };

        {
            let mut loading = self.imp().multi_year_loading_years.borrow_mut();
            for &y in &missing_years {
                loading.insert(y);
            }
        }

        let page_weak = self.downgrade();
        glib::MainContext::default().spawn_local(async move {
            let years_for_worker = missing_years.clone();
            let q_worker = query.clone();
            let cat_worker = category.clone();
            let hidden_worker = hidden_sources.clone();
            let Ok(built) = gio::spawn_blocking(move || {
                Self::build_multi_year_summaries_from_index(
                    &index,
                    &years_for_worker,
                    &q_worker,
                    cat_worker.as_deref(),
                    &hidden_worker,
                )
            })
            .await
            else {
                return;
            };

            let Some(page) = page_weak.upgrade() else { return };
            if page.imp().multi_year_rendered_key.borrow().as_ref() != Some(&filter_key) {
                return;
            }
            {
                let mut loading = page.imp().multi_year_loading_years.borrow_mut();
                let mut loaded = page.imp().multi_year_loaded_years.borrow_mut();
                for &y in &missing_years {
                    loading.remove(&y);
                    loaded.insert(y);
                }
            }
            page.imp().multi_year_summaries.borrow_mut().extend(built);
            if let Some(canvas) = page.imp().year_canvas.borrow().as_ref() {
                canvas.queue_draw();
            }
        });
    }

    pub(crate) fn multi_year_grid_dimensions(scale: f64, width: f64) -> (usize, usize) {
        let (base_cols, vis_rows) = if scale >= 1.35 {
            (2, 1)
        } else if scale >= 1.15 {
            (2, 2)
        } else if scale >= 0.96 {
            (3, 2)
        } else if scale >= 0.86 {
            (3, 3)
        } else if scale >= 0.78 {
            (4, 3)
        } else {
            (4, 4)
        };
        let max_cols = if width < 480.0 {
            1
        } else if width < 720.0 {
            2
        } else if width < 960.0 {
            3
        } else {
            4
        };
        (base_cols.min(max_cols).max(1), vis_rows)
    }

    pub(crate) fn multi_year_visible_count() -> usize {
        let scale = configured_chip_scale().clamp(0.75, 1.50);
        let (cols, rows) = Self::multi_year_grid_dimensions(scale, 1200.0);
        cols * rows
    }

    fn prepare_multi_year_canvas_layout(
        anchor_year: i32,
        width: f64,
        avail_height: f64,
        first_weekday: Weekday,
    ) -> PreparedMultiYearCanvasLayout {
        let scale = configured_chip_scale().clamp(0.75, 1.50);
        let (num_cols, vis_rows) = Self::multi_year_grid_dimensions(scale, width);
        let visible_years = num_cols * vis_rows;
        let margin_x = if num_cols >= 4 { 14.0 } else { 20.0 };
        let margin_y = if vis_rows >= 3 { 12.0 } else { 16.0 };
        let spacing_x = if num_cols >= 4 { 12.0 } else { 18.0 };
        let spacing_y = if vis_rows >= 3 { 12.0 } else { 18.0 };

        let usable_w = (width - 2.0 * margin_x - (num_cols - 1) as f64 * spacing_x).max(220.0);
        let card_w = (usable_w / num_cols as f64).floor();
        let total_cards_w = num_cols as f64 * card_w + (num_cols - 1) as f64 * spacing_x;
        let actual_margin_x = ((width - total_cards_w) * 0.5).max(margin_x);

        let usable_h =
            (avail_height - 2.0 * margin_y - (vis_rows.saturating_sub(1)) as f64 * spacing_y)
                .max(360.0);
        let card_h = (usable_h / vis_rows as f64).floor().clamp(156.0, 620.0);
        let row_step = card_h + spacing_y;
        let header_h = (card_h * 0.11).round().clamp(26.0, 38.0);
        let pad_x = (card_w * 0.035).round().clamp(8.0, 14.0);
        let pad_bottom = (card_h * 0.035).round().clamp(6.0, 12.0);
        let tile_gap_x = (card_w * 0.025).round().clamp(6.0, 12.0);
        let tile_gap_y = (card_h * 0.024).round().clamp(4.0, 10.0);

        let prev_rows = vis_rows as i32;
        let next_rows = (vis_rows * 2) as i32;
        let total_rows_span = (next_rows - (-prev_rows)) as usize;
        let mut cards = Vec::with_capacity(total_rows_span * num_cols);

        for r in -prev_rows..next_rows {
            for c in 0..num_cols {
                let y = anchor_year + r * (num_cols as i32) + c as i32;
                let card_x = actual_margin_x + c as f64 * (card_w + spacing_x);
                let card_y = margin_y + r as f64 * row_step;

                let grid_x = card_x + pad_x;
                let grid_y = card_y + header_h;
                let grid_w = (card_w - 2.0 * pad_x).max(80.0);
                let grid_h = (card_h - header_h - pad_bottom).max(72.0);
                let tile_w = ((grid_w - 3.0 * tile_gap_x) / 4.0).max(16.0);
                let tile_h = ((grid_h - 2.0 * tile_gap_y) / 3.0).max(18.0);

                let month_tiles = std::array::from_fn(|m_idx| {
                    let m = (m_idx + 1) as u32;
                    let mc = m_idx % 4;
                    let mr = m_idx / 4;
                    let tx = grid_x + mc as f64 * (tile_w + tile_gap_x);
                    let ty = grid_y + mr as f64 * (tile_h + tile_gap_y);
                    PreparedMultiYearMonthTile {
                        month: m,
                        x: tx,
                        y: ty,
                        w: tile_w,
                        h: tile_h,
                    }
                });

                cards.push(PreparedMultiYearCardLayout {
                    year: y,
                    card_x,
                    card_y,
                    card_w,
                    card_h,
                    header_h,
                    month_tiles,
                });
            }
        }

        let total_h =
            margin_y * 2.0 + vis_rows as f64 * card_h + (vis_rows.saturating_sub(1)) as f64 * spacing_y;
        PreparedMultiYearCanvasLayout {
            anchor_year,
            start_year: anchor_year,
            end_year: anchor_year + (visible_years as i32 - 1),
            num_cols,
            vis_rows,
            row_step,
            width,
            height: total_h.max(avail_height),
            first_weekday,
            cards,
        }
    }

    fn hit_test_multi_year_canvas(
        layout: &PreparedMultiYearCanvasLayout,
        x: f64,
        y: f64,
    ) -> Option<YearCanvasHitTarget> {
        for card in &layout.cards {
            if x >= card.card_x
                && x <= card.card_x + card.card_w
                && y >= card.card_y
                && y <= card.card_y + card.card_h
            {
                for tile in &card.month_tiles {
                    if x >= tile.x
                        && x <= tile.x + tile.w
                        && y >= tile.y
                        && y <= tile.y + tile.h
                    {
                        return Some(YearCanvasHitTarget::YearMonth(card.year, tile.month));
                    }
                }
                return Some(YearCanvasHitTarget::YearCard(card.year));
            }
        }
        None
    }

    fn draw_multi_year_canvas(
        cr: &gtk::cairo::Context,
        layout: &PreparedMultiYearCanvasLayout,
        summaries: &BTreeMap<(i32, u32), MultiYearMonthSummary>,
        selected_year: i32,
        today: NaiveDate,
        hovered_target: Option<&YearCanvasHitTarget>,
        scroll_y: f64,
        viewport_height: f64,
        is_dark: bool,
    ) {
        let fg = if is_dark { 1.0 } else { 0.0 };
        let primary_alpha = if is_dark { 0.92 } else { 0.86 };
        let secondary_alpha = if is_dark { 0.46 } else { 0.42 };
        let current_year = today.year();
        let vis_top = scroll_y - 24.0;
        let vis_bottom = scroll_y + viewport_height + 24.0;

        for card in &layout.cards {
            if card.card_y + card.card_h < vis_top || card.card_y > vis_bottom {
                continue;
            }
            let is_card_hovered = hovered_target == Some(&YearCanvasHitTarget::YearCard(card.year));
            let is_current = card.year == current_year;
            let _is_selected = card.year == selected_year;

            let year_total_events: usize = (1..=12)
                .filter_map(|m| summaries.get(&(card.year, m)))
                .map(|s| s.event_count)
                .sum();

            // Clean GNOME Libadwaita flat card surface (.card style)
            draw_cairo_rounded_rect(cr, card.card_x, card.card_y, card.card_w, card.card_h, 12.0);
            if is_dark {
                cr.set_source_rgba(1.0, 1.0, 1.0, if is_card_hovered { 0.06 } else { 0.04 });
            } else {
                cr.set_source_rgba(0.0, 0.0, 0.0, if is_card_hovered { 0.035 } else { 0.02 });
            }
            let _ = cr.fill();

            // Subtle Libadwaita hairline border
            draw_cairo_rounded_rect(
                cr,
                card.card_x + 0.5,
                card.card_y + 0.5,
                card.card_w - 1.0,
                card.card_h - 1.0,
                12.0,
            );
            cr.set_line_width(1.0);
            if is_current {
                cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.45 } else { 0.35 });
            } else {
                cr.set_source_rgba(fg, fg, fg, if is_dark { 0.08 } else { 0.07 });
            }
            let _ = cr.stroke();

            // Year number title on top-left (GNOME typography)
            let year_str = card.year.to_string();
            let title_font_sz = (card.header_h * 0.46).clamp(13.0, 18.0);
            let title_baseline = card.card_y + (card.header_h * 0.68).clamp(18.0, 26.0);
            cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
            cr.set_font_size(title_font_sz);
            if is_current || is_card_hovered {
                cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
            } else {
                cr.set_source_rgba(fg, fg, fg, primary_alpha);
            }
            cr.move_to(card.card_x + 12.0, title_baseline);
            let _ = cr.show_text(&year_str);

            // Subtle dim-label event count on top-right (only when > 0, no pill box)
            if year_total_events > 0 {
                let count_str = if year_total_events == 1 {
                    format!("1 {}", gettext("event"))
                } else {
                    format!("{} {}", year_total_events, gettext("events"))
                };
                cr.select_font_face(
                    "sans-serif",
                    gtk::cairo::FontSlant::Normal,
                    gtk::cairo::FontWeight::Normal,
                );
                cr.set_font_size((card.header_h * 0.30).clamp(9.5, 11.5));
                cr.set_source_rgba(fg, fg, fg, secondary_alpha);
                if let Ok(ext) = cr.text_extents(&count_str) {
                    let tx = card.card_x + card.card_w - 12.0 - ext.width() - ext.x_bearing();
                    cr.move_to(tx, title_baseline - 1.0);
                    let _ = cr.show_text(&count_str);
                }
            }

            // 12 borderless miniature 7-column month calendars (4x3) inside the year card
            for tile in &card.month_tiles {
                let m = tile.month;
                let is_curr_month = is_current && today.month() == m;
                let is_tile_hovered =
                    hovered_target == Some(&YearCanvasHitTarget::YearMonth(card.year, m));
                let summary_opt = summaries.get(&(card.year, m));

                // Soft flat Libadwaita hover highlight only when hovered (no tile borders!)
                if is_tile_hovered {
                    draw_cairo_rounded_rect(
                        cr,
                        tile.x - 3.0,
                        tile.y - 2.0,
                        tile.w + 6.0,
                        tile.h + 4.0,
                        6.0,
                    );
                    cr.set_source_rgba(fg, fg, fg, if is_dark { 0.07 } else { 0.045 });
                    let _ = cr.fill();
                }

                // Month short name at top-left
                let short_m = Self::calendar_month_short_name(m);
                let month_hdr_h = (tile.h * 0.22).clamp(10.0, 15.0);
                cr.select_font_face(
                    "sans-serif",
                    gtk::cairo::FontSlant::Normal,
                    gtk::cairo::FontWeight::Bold,
                );
                cr.set_font_size((month_hdr_h * 0.72).clamp(8.5, 11.0));
                if is_curr_month || is_tile_hovered {
                    cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
                } else {
                    cr.set_source_rgba(fg, fg, fg, primary_alpha * 0.92);
                }
                cr.move_to(tile.x + 2.0, tile.y + month_hdr_h * 0.78);
                let _ = cr.show_text(&short_m);

                // Miniature 7-column × 6-row day grid for this month
                let Some(first_of_month) = NaiveDate::from_ymd_opt(card.year, m, 1) else {
                    continue;
                };
                let last_of_month = match m {
                    12 => NaiveDate::from_ymd_opt(card.year, 12, 31),
                    _ => NaiveDate::from_ymd_opt(card.year, m + 1, 1).map(|d| d - Duration::days(1)),
                }
                .unwrap_or(first_of_month);
                let grid_start = week_start_for(first_of_month, layout.first_weekday);

                let days_top = tile.y + month_hdr_h;
                let days_h = (tile.h - month_hdr_h).max(18.0);
                let cell_w = tile.w / 7.0;
                let cell_h = days_h / 6.0;
                let radius = (cell_w.min(cell_h) * 0.46).clamp(2.4, 6.4);
                let font_sz = (cell_w.min(cell_h) * 0.62).clamp(5.8, 9.2);

                for d in 1..=last_of_month.day() {
                    let Some(cell_date) = NaiveDate::from_ymd_opt(card.year, m, d) else {
                        continue;
                    };
                    let offset_days = (cell_date - grid_start).num_days().max(0) as usize;
                    let row = offset_days / 7;
                    let col = offset_days % 7;
                    if row >= 6 {
                        continue;
                    }

                    let cx = tile.x + (col as f64 + 0.5) * cell_w;
                    let cy = days_top + (row as f64 + 0.5) * cell_h;
                    let is_today = cell_date == today;
                    let d_idx = (d as usize).min(31);
                    let day_ev_count = summary_opt.map(|s| s.day_counts[d_idx]).unwrap_or(0);
                    let day_color = summary_opt
                        .and_then(|s| s.day_colors[d_idx])
                        .unwrap_or((53, 132, 228));

                    if is_today {
                        cr.arc(cx, cy, radius, 0.0, std::f64::consts::TAU);
                        cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
                        let _ = cr.fill();
                    } else if day_ev_count > 0 {
                        let heat_alpha = if day_ev_count == 1 {
                            if is_dark { 0.22 } else { 0.16 }
                        } else if day_ev_count <= 2 {
                            if is_dark { 0.34 } else { 0.25 }
                        } else {
                            if is_dark { 0.48 } else { 0.36 }
                        };
                        cr.arc(cx, cy, radius, 0.0, std::f64::consts::TAU);
                        cr.set_source_rgba(
                            day_color.0 as f64 / 255.0,
                            day_color.1 as f64 / 255.0,
                            day_color.2 as f64 / 255.0,
                            heat_alpha,
                        );
                        let _ = cr.fill();
                    }

                    let day_str = d.to_string();
                    cr.select_font_face(
                        "sans-serif",
                        gtk::cairo::FontSlant::Normal,
                        if is_today || day_ev_count > 0 {
                            gtk::cairo::FontWeight::Bold
                        } else {
                            gtk::cairo::FontWeight::Normal
                        },
                    );
                    cr.set_font_size(font_sz);
                    if is_today {
                        cr.set_source_rgb(1.0, 1.0, 1.0);
                    } else if day_ev_count > 0 {
                        cr.set_source_rgba(fg, fg, fg, primary_alpha);
                    } else {
                        cr.set_source_rgba(fg, fg, fg, secondary_alpha);
                    }
                    if let Ok(ext) = cr.text_extents(&day_str) {
                        let tx = cx - ext.width() * 0.5 - ext.x_bearing();
                        let ty = cy - ext.height() * 0.5 - ext.y_bearing();
                        cr.move_to(tx, ty);
                        let _ = cr.show_text(&day_str);
                    }
                }
            }
        }
    }

    pub(crate) fn calendar_month_short_name(month: u32) -> String {
        match month {
            1 => gettext("Jan"),
            2 => gettext("Feb"),
            3 => gettext("Mar"),
            4 => gettext("Apr"),
            5 => gettext("May"),
            6 => gettext("Jun"),
            7 => gettext("Jul"),
            8 => gettext("Aug"),
            9 => gettext("Sep"),
            10 => gettext("Oct"),
            11 => gettext("Nov"),
            12 => gettext("Dec"),
            _ => String::new(),
        }
    }

    pub(crate) fn calendar_weekday_two_letter(wd: Weekday) -> &'static str {
        match wd {
            Weekday::Mon => "Mo",
            Weekday::Tue => "Di",
            Weekday::Wed => "Mi",
            Weekday::Thu => "Do",
            Weekday::Fri => "Fr",
            Weekday::Sat => "Sa",
            Weekday::Sun => "So",
        }
    }

    pub(crate) fn effective_year_scroll_y(&self) -> f64 {
        let style = self.imp().year_view_style.get();
        if style == YearViewStyle::Planner || style == YearViewStyle::MultiYear {
            self.imp().year_planner_scroll_y.get().round()
        } else {
            self.imp()
                .year_vadjustment
                .borrow()
                .as_ref()
                .map(|v| v.value())
                .unwrap_or(0.0)
        }
    }

    pub(crate) fn prepare_year_planner_layout(
        year: i32,
        avail_width: f64,
        avail_height: f64,
    ) -> YearPlannerCanvasLayout {
        let month_header_w = 32.0;
        let usable_w = (avail_width - month_header_w).max(31.0 * 26.0);
        let col_w = usable_w / 31.0;
        let scale = configured_chip_scale().clamp(0.75, 1.50);
        let zoom_factor = if scale > 1.0 {
            1.0 + (scale - 1.0) * 1.8
        } else {
            scale
        };
        let base_row_h = if scale <= 1.001 {
            (avail_height / 12.0).max(16.0)
        } else {
            (avail_height / 12.0).max(28.0)
        };
        let row_h = base_row_h * zoom_factor;
        YearPlannerCanvasLayout {
            year,
            width: month_header_w + 31.0 * col_w,
            height: 12.0 * row_h,
            month_header_w,
            col_w,
            row_h,
        }
    }

    pub(crate) fn hit_test_year_planner_date_for_drag(
        layout: &YearPlannerCanvasLayout,
        x: f64,
        y: f64,
    ) -> Option<NaiveDate> {
        let total_month_idx = (y / layout.row_h).floor().clamp(-12.0, 23.0) as i32;
        let target_year = layout.year + total_month_idx.div_euclid(12);
        let month = (total_month_idx.rem_euclid(12) + 1) as u32;
        let max_d = days_in_month(target_year, month);
        let raw_day = (((x - layout.month_header_w).max(0.0)) / layout.col_w).floor() as u32 + 1;
        let day = raw_day.clamp(1, max_d);
        NaiveDate::from_ymd_opt(target_year, month, day)
    }

    pub(crate) fn hit_test_year_planner_canvas(
        layout: &YearPlannerCanvasLayout,
        x: f64,
        y: f64,
    ) -> Option<YearCanvasHitTarget> {
        if x < 0.0 || x >= layout.width {
            return None;
        }
        let total_month_idx = (y / layout.row_h).floor() as i32;
        if !(-12..24).contains(&total_month_idx) {
            return None;
        }
        let target_year = layout.year + total_month_idx.div_euclid(12);
        let month = (total_month_idx.rem_euclid(12) + 1) as u32;
        if x < layout.month_header_w {
            if target_year == layout.year {
                return Some(YearCanvasHitTarget::MonthHeader(month));
            } else {
                return Some(YearCanvasHitTarget::YearMonth(target_year, month));
            }
        }
        let day = ((x - layout.month_header_w) / layout.col_w).floor() as u32 + 1;
        if !(1..=31).contains(&day) {
            return None;
        }
        NaiveDate::from_ymd_opt(target_year, month, day).map(YearCanvasHitTarget::Day)
    }

    pub(crate) fn year_planner_day_rect(
        layout: &YearPlannerCanvasLayout,
        date: NaiveDate,
        scroll_y: f64,
    ) -> gdk::Rectangle {
        let rx = layout.month_header_w + (date.day().saturating_sub(1)) as f64 * layout.col_w;
        let year_diff = (date.year() - layout.year) as f64;
        let month_idx = year_diff * 12.0 + (date.month().saturating_sub(1)) as f64;
        let ry = month_idx * layout.row_h - scroll_y;
        gdk::Rectangle::new(
            rx.round() as i32,
            ry.round() as i32,
            layout.col_w.round().max(1.0) as i32,
            layout.row_h.round().max(1.0) as i32,
        )
    }

    pub(crate) fn build_year_planner_months(
        year: i32,
        events_by_date: &BTreeMap<NaiveDate, Vec<CalendarEventRecord>>,
    ) -> [YearPlannerMonthData; 12] {
        std::array::from_fn(|m_idx| {
            let month = (m_idx + 1) as u32;
            let max_d = days_in_month(year, month);
            let Some(month_start) = NaiveDate::from_ymd_opt(year, month, 1) else {
                return YearPlannerMonthData::default();
            };
            let Some(month_end) = NaiveDate::from_ymd_opt(year, month, max_d) else {
                return YearPlannerMonthData::default();
            };

            let mut multi_candidates: Vec<(u32, u32, (u8, u8, u8), bool, bool, String)> = Vec::new();
            let mut seen_multi = HashSet::<(String, String, NaiveDate)>::new();

            for d in 1..=max_d {
                let Some(date) = NaiveDate::from_ymd_opt(year, month, d) else { continue };
                let Some(events) = events_by_date.get(&date) else { continue };
                for ev in events {
                    let range = event_occurrence_range_for_date(ev, date)
                        .or_else(|| event_display_range(ev))
                        .unwrap_or_else(|| CalendarDateRange::single(date));
                    if ev.all_day || range.len_days() > 1 {
                        let dedup_key = (ev.source_uid.clone(), ev.uid.clone(), range.start);
                        if seen_multi.insert(dedup_key) {
                            let clamped_start = range.start.max(month_start);
                            let clamped_end = range.last_inclusive().min(month_end);
                            if clamped_start <= clamped_end {
                                let hex = event_color_for_record(ev);
                                let rgb = parse_hex_color(&hex).unwrap_or((53, 132, 228));
                                multi_candidates.push((
                                    clamped_start.day(),
                                    clamped_end.day(),
                                    rgb,
                                    range.start < month_start,
                                    range.last_inclusive() > month_end,
                                    ev.summary.clone(),
                                ));
                            }
                        }
                    }
                }
            }

            multi_candidates.sort_by(|a, b| {
                a.0.cmp(&b.0)
                    .then_with(|| (b.1 - b.0).cmp(&(a.1 - a.0)))
                    .then_with(|| a.5.cmp(&b.5))
            });

            let mut tracks: Vec<[bool; 32]> = Vec::new();
            let mut spans: Vec<YearPlannerEventSpan> = Vec::new();

            for (start_day, end_day, color_rgb, continues_left, continues_right, _) in multi_candidates {
                let mut t = 0;
                loop {
                    if t >= tracks.len() {
                        tracks.push([false; 32]);
                        break;
                    }
                    if (start_day..=end_day).all(|d| !tracks[t][d as usize]) {
                        break;
                    }
                    t += 1;
                }
                for d in start_day..=end_day {
                    tracks[t][d as usize] = true;
                }
                spans.push(YearPlannerEventSpan {
                    start_day,
                    end_day,
                    track: t,
                    color_rgb,
                    continues_left,
                    continues_right,
                    is_timed_single: false,
                    start_min: 0,
                });
            }

            for d in 1..=max_d {
                let Some(date) = NaiveDate::from_ymd_opt(year, month, d) else { continue };
                let Some(events) = events_by_date.get(&date) else { continue };
                for ev in events {
                    let range = event_occurrence_range_for_date(ev, date)
                        .or_else(|| event_display_range(ev))
                        .unwrap_or_else(|| CalendarDateRange::single(date));
                    if ev.all_day || range.len_days() > 1 {
                        continue;
                    }
                    let hex = event_color_for_record(ev);
                    let color_rgb = parse_hex_color(&hex).unwrap_or((53, 132, 228));
                    let (start_min_u32, _, _) = event_occurrence_times_for_date(ev, date, 30);
                    let start_min = start_min_u32.min(1439) as u16;
                    let mut t = 0;
                    loop {
                        if t >= tracks.len() {
                            tracks.push([false; 32]);
                            break;
                        }
                        if !tracks[t][d as usize] {
                            break;
                        }
                        t += 1;
                    }
                    tracks[t][d as usize] = true;
                    spans.push(YearPlannerEventSpan {
                        start_day: d,
                        end_day: d,
                        track: t,
                        color_rgb,
                        continues_left: false,
                        continues_right: false,
                        is_timed_single: true,
                        start_min,
                    });
                }
            }

            YearPlannerMonthData { spans }
        })
    }

    fn build_year_projection_from_index(
        index: &CalendarSnapshotIndex,
        year: i32,
        year_range: CalendarDateRange,
        query: &str,
        category: Option<&str>,
        hidden_sources: &HashSet<String>,
    ) -> (
        BTreeMap<NaiveDate, usize>,
        [YearPlannerMonthData; 12],
        HashMap<NaiveDate, Vec<YearPlannerDayPreviewItem>>,
    ) {
        let hide_cancelled = configured_hide_cancelled_events();
        let normalized_query = query.trim().to_lowercase();
        let normalized_category = category
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_lowercase);

        let mut filter_cache: Vec<Option<bool>> = vec![None; index.metas.len()];
        let mut check_match = |ev_idx: usize| -> bool {
            if let Some(res) = filter_cache[ev_idx] {
                return res;
            }
            let matched = index_event_matches_filter(
                index,
                ev_idx,
                &normalized_query,
                normalized_category.as_deref(),
                hidden_sources,
                hide_cancelled,
            );
            filter_cache[ev_idx] = Some(matched);
            matched
        };

        // Collect all (ev_idx, occurrence_range) intersecting year_range
        let mut occurrences: Vec<(usize, CalendarDateRange)> = Vec::with_capacity(256);

        for (date, bucket) in index.date_buckets.range(year_range.start..year_range.end) {
            for &ev_idx in bucket {
                if check_match(ev_idx) {
                    occurrences.push((ev_idx, CalendarDateRange::single(*date)));
                }
            }
        }

        for &(ev_idx, range) in &index.long_events {
            if range.intersects(year_range) && check_match(ev_idx) {
                occurrences.push((ev_idx, range));
            }
        }

        for &ev_idx in &index.recurring_events {
            if !check_match(ev_idx) {
                continue;
            }
            let meta = &index.metas[ev_idx];
            let Some(initial_range) = meta.display_range else { continue };
            let initial_start = initial_range.start;
            let span_days = initial_range.len_days().saturating_sub(1);
            let mut occ_starts = BTreeSet::new();

            if !meta.excluded_dates.contains(&initial_start) {
                let initial_occ_end = initial_start
                    .checked_add_signed(Duration::days(span_days + 1))
                    .unwrap_or(initial_range.end);
                let occ_r = CalendarDateRange::new(initial_start, initial_occ_end);
                if occ_r.intersects(year_range) {
                    occ_starts.insert(initial_start);
                }
            }
            for &rdate in &meta.rdate_values {
                if !meta.excluded_dates.contains(&rdate) {
                    let occ_end = rdate
                        .checked_add_signed(Duration::days(span_days + 1))
                        .unwrap_or(rdate);
                    let occ_r = CalendarDateRange::new(rdate, occ_end);
                    if occ_r.intersects(year_range) {
                        occ_starts.insert(rdate);
                    }
                }
            }
            if let Some(rule) = meta.recurrence_rule.as_ref() {
                let from = year_range
                    .start
                    .checked_sub_signed(Duration::days(span_days))
                    .unwrap_or(year_range.start)
                    .max(initial_start);
                if from < year_range.end {
                    let starts = recurrence_occurrences_in_range(
                        rule,
                        initial_start,
                        from,
                        year_range.end,
                        &meta.excluded_dates,
                    );
                    occ_starts.extend(starts);
                }
            }
            for occ_start in occ_starts {
                let Some(occ_end) = occ_start.checked_add_signed(Duration::days(span_days + 1)) else {
                    continue;
                };
                let occ_range = CalendarDateRange::new(occ_start, occ_end);
                if occ_range.intersects(year_range) {
                    occurrences.push((ev_idx, occ_range));
                }
            }
        }

        let mut day_identities: BTreeMap<NaiveDate, (BTreeSet<CalendarEventIdentity>, usize)> =
            BTreeMap::new();
        let mut day_previews: HashMap<NaiveDate, Vec<YearPlannerDayPreviewItem>> = HashMap::new();
        let mut month_multi_candidates: [Vec<(u32, u32, (u8, u8, u8), bool, bool, usize)>; 12] =
            std::array::from_fn(|_| Vec::new());
        let mut month_timed_singles: [Vec<(u32, u16, (u8, u8, u8), usize)>; 12] =
            std::array::from_fn(|_| Vec::new());

        let untitled = gettext("(Untitled)");

        for &(ev_idx, occ_range) in &occurrences {
            let event = &index.snapshot.events[ev_idx];
            let meta = &index.metas[ev_idx];
            let is_all_day_or_multi = meta.all_day || occ_range.len_days() > 1;
            let title = if event.summary.trim().is_empty() {
                untitled.clone()
            } else {
                event.summary.clone()
            };
            let time_str = if is_all_day_or_multi {
                None
            } else {
                Some(format_clock_minutes(meta.start_min as u32))
            };

            let clamped_year_start = occ_range.start.max(year_range.start);
            let clamped_year_end = occ_range.last_inclusive().min(year_range.last_inclusive());
            let mut cur = clamped_year_start;
            while cur <= clamped_year_end {
                let (seen, no_id_count) = day_identities.entry(cur).or_default();
                let is_new_on_day = if let Some(ref id) = meta.identity {
                    seen.insert(id.clone())
                } else {
                    *no_id_count += 1;
                    true
                };
                if is_new_on_day {
                    day_previews
                        .entry(cur)
                        .or_default()
                        .push(YearPlannerDayPreviewItem {
                            title: title.clone(),
                            time_str: time_str.clone(),
                            color_rgb: meta.color_rgb,
                            is_all_day_or_multi,
                            start_min: meta.start_min,
                        });
                }
                let Some(next) = cur.succ_opt() else { break };
                cur = next;
            }

            if is_all_day_or_multi {
                let start_m = clamped_year_start.month();
                let end_m = clamped_year_end.month();
                for m in start_m..=end_m {
                    let max_d = days_in_month(year, m);
                    let Some(m_start) = NaiveDate::from_ymd_opt(year, m, 1) else { continue };
                    let Some(m_end) = NaiveDate::from_ymd_opt(year, m, max_d) else { continue };
                    let cs = occ_range.start.max(m_start);
                    let ce = occ_range.last_inclusive().min(m_end);
                    if cs <= ce {
                        month_multi_candidates[(m - 1) as usize].push((
                            cs.day(),
                            ce.day(),
                            meta.color_rgb,
                            occ_range.start < m_start,
                            occ_range.last_inclusive() > m_end,
                            ev_idx,
                        ));
                    }
                }
            } else if clamped_year_start.year() == year {
                let m_idx = (clamped_year_start.month() - 1) as usize;
                month_timed_singles[m_idx].push((
                    clamped_year_start.day(),
                    meta.start_min,
                    meta.color_rgb,
                    ev_idx,
                ));
            }
        }

        for items in day_previews.values_mut() {
            items.sort_by(|a, b| {
                b.is_all_day_or_multi
                    .cmp(&a.is_all_day_or_multi)
                    .then_with(|| a.start_min.cmp(&b.start_min))
                    .then_with(|| a.title.cmp(&b.title))
            });
        }

        let markers: BTreeMap<NaiveDate, usize> = day_identities
            .into_iter()
            .filter_map(|(date, (seen, no_id_count))| {
                let count = seen.len() + no_id_count;
                (count > 0).then_some((date, count))
            })
            .collect();

        let planner_months: [YearPlannerMonthData; 12] = std::array::from_fn(|m_idx| {
            let mut multi = std::mem::take(&mut month_multi_candidates[m_idx]);
            multi.sort_by(|a, b| {
                a.0.cmp(&b.0)
                    .then_with(|| (b.1 - b.0).cmp(&(a.1 - a.0)))
                    .then_with(|| {
                        index.metas[a.5]
                            .summary_lowercase
                            .cmp(&index.metas[b.5].summary_lowercase)
                    })
            });

            let mut tracks: Vec<[bool; 32]> = Vec::new();
            let mut spans: Vec<YearPlannerEventSpan> = Vec::new();

            for (start_day, end_day, color_rgb, continues_left, continues_right, _) in multi {
                let mut t = 0;
                loop {
                    if t >= tracks.len() {
                        tracks.push([false; 32]);
                        break;
                    }
                    if (start_day..=end_day).all(|d| !tracks[t][d as usize]) {
                        break;
                    }
                    t += 1;
                }
                for d in start_day..=end_day {
                    tracks[t][d as usize] = true;
                }
                spans.push(YearPlannerEventSpan {
                    start_day,
                    end_day,
                    track: t,
                    color_rgb,
                    continues_left,
                    continues_right,
                    is_timed_single: false,
                    start_min: 0,
                });
            }

            let mut singles = std::mem::take(&mut month_timed_singles[m_idx]);
            singles.sort_by(|a, b| {
                a.0.cmp(&b.0)
                    .then_with(|| a.1.cmp(&b.1))
                    .then_with(|| {
                        index.metas[a.3]
                            .summary_lowercase
                            .cmp(&index.metas[b.3].summary_lowercase)
                    })
            });

            for (d, start_min, color_rgb, _) in singles {
                let mut t = 0;
                loop {
                    if t >= tracks.len() {
                        tracks.push([false; 32]);
                        break;
                    }
                    if !tracks[t][d as usize] {
                        break;
                    }
                    t += 1;
                }
                tracks[t][d as usize] = true;
                spans.push(YearPlannerEventSpan {
                    start_day: d,
                    end_day: d,
                    track: t,
                    color_rgb,
                    continues_left: false,
                    continues_right: false,
                    is_timed_single: true,
                    start_min,
                });
            }

            YearPlannerMonthData { spans }
        });

        (markers, planner_months, day_previews)
    }

    fn draw_year_planner_canvas(
        cr: &gtk::cairo::Context,
        layout: &YearPlannerCanvasLayout,
        planner_months: &[YearPlannerMonthData; 12],
        day_previews: &HashMap<NaiveDate, Vec<YearPlannerDayPreviewItem>>,
        selected_day: Option<NaiveDate>,
        today: NaiveDate,
        hovered_target: Option<&YearCanvasHitTarget>,
        scroll_y: f64,
        viewport_height: f64,
        is_dark: bool,
    ) {
        Self::draw_year_planner_canvas_multi(
            cr,
            layout,
            &[(layout.year, planner_months, day_previews)],
            selected_day.map(|d| (d, d)),
            today,
            hovered_target,
            scroll_y,
            viewport_height,
            is_dark,
        );
    }

    fn draw_year_planner_canvas_multi(
        cr: &gtk::cairo::Context,
        layout: &YearPlannerCanvasLayout,
        years_slice: &[(
            i32,
            &[YearPlannerMonthData; 12],
            &HashMap<NaiveDate, Vec<YearPlannerDayPreviewItem>>,
        )],
        selected_range: Option<(NaiveDate, NaiveDate)>,
        today: NaiveDate,
        hovered_target: Option<&YearCanvasHitTarget>,
        scroll_y: f64,
        viewport_height: f64,
        is_dark: bool,
    ) {
        // Base background
        if let Ok(mut font_opts) = gtk::cairo::FontOptions::new() {
            font_opts.set_antialias(gtk::cairo::Antialias::Gray);
            font_opts.set_hint_style(gtk::cairo::HintStyle::Full);
            font_opts.set_hint_metrics(gtk::cairo::HintMetrics::On);
            cr.set_font_options(&font_opts);
        }

        let min_year = years_slice.first().map(|x| x.0).unwrap_or(layout.year);
        let max_year = years_slice.last().map(|x| x.0).unwrap_or(layout.year);
        let bg_top = ((min_year - layout.year) as f64) * 12.0 * layout.row_h;
        let bg_bottom = ((max_year - layout.year + 1) as f64) * 12.0 * layout.row_h;

        if is_dark {
            cr.set_source_rgb(0.135, 0.135, 0.15);
        } else {
            cr.set_source_rgb(1.0, 1.0, 1.0);
        }
        cr.rectangle(0.0, bg_top, layout.width, (bg_bottom - bg_top).max(layout.height));
        let _ = cr.fill();

        let fg = if is_dark { 1.0 } else { 0.12 };
        let primary_alpha = if is_dark { 0.96 } else { 0.92 };
        let muted_alpha = if is_dark { 0.70 } else { 0.65 };
        let (wknd_r, wknd_g, wknd_b) = if is_dark {
            (1.0, 0.44, 0.44)
        } else {
            (0.84, 0.16, 0.16)
        };
        let border_alpha = if is_dark { 0.14 } else { 0.11 };
        let vis_top = scroll_y - layout.row_h;
        let vis_bottom = scroll_y + viewport_height + layout.row_h;
        let show_year_on_jan = years_slice.len() > 1 && scroll_y.abs() > 2.0;

        for &(row_year, planner_months, _) in years_slice {
            let year_base_y = ((row_year - layout.year) as f64) * 12.0 * layout.row_h;

            for m in 1..=12u32 {
                let row_idx = (m - 1) as usize;
                let row_y = year_base_y + row_idx as f64 * layout.row_h;
                if row_y + layout.row_h < vis_top || row_y > vis_bottom {
                    continue;
                }

                let row_y0 = row_y.round();
                let row_y1 = (row_y + layout.row_h).round();
                let row_h_snap = (row_y1 - row_y0).max(1.0);

                // 1. Left Month Header cell
                let is_header_hovered = if row_year == layout.year {
                    hovered_target == Some(&YearCanvasHitTarget::MonthHeader(m))
                        || hovered_target == Some(&YearCanvasHitTarget::YearMonth(row_year, m))
                } else {
                    hovered_target == Some(&YearCanvasHitTarget::YearMonth(row_year, m))
                };
                if is_header_hovered {
                    cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.22 } else { 0.12 });
                } else if is_dark {
                    cr.set_source_rgba(1.0, 1.0, 1.0, 0.025);
                } else {
                    cr.set_source_rgba(0.0, 0.0, 0.0, 0.02);
                }
                cr.rectangle(0.0, row_y0, layout.month_header_w, row_h_snap);
                let _ = cr.fill();

                let m_short = if m == 1 && (show_year_on_jan || row_year != layout.year) {
                    format!("{} '{}'", Self::calendar_month_short_name(m), (row_year % 100).abs()).replace("'", "")
                } else {
                    Self::calendar_month_short_name(m)
                };
                let _ = cr.save();
                cr.translate(
                    (layout.month_header_w * 0.5 + 5.0).round(),
                    (row_y0 + row_h_snap * 0.5).round(),
                );
                cr.rotate(-std::f64::consts::FRAC_PI_2);
                cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
                cr.set_font_size(if m == 1 && (show_year_on_jan || row_year != layout.year) { 11.5 } else { 13.0 });
                if is_header_hovered {
                    cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
                } else {
                    cr.set_source_rgba(fg, fg, fg, primary_alpha);
                }
                if let Ok(ext) = cr.text_extents(&m_short) {
                    cr.move_to((-ext.width() * 0.5 - ext.x_bearing()).round(), 0.0);
                    let _ = cr.show_text(&m_short);
                }
                let _ = cr.restore();

                // 2. Day cells (1..=31)
                for day in 1..=31u32 {
                    let col_idx = (day - 1) as usize;
                    let cell_x = layout.month_header_w + col_idx as f64 * layout.col_w;

                    if let Some(date) = NaiveDate::from_ymd_opt(row_year, m, day) {
                        let is_sat_sun = matches!(date.weekday(), Weekday::Sat | Weekday::Sun);
                        let is_today = date == today;
                        let is_selected = selected_range
                            .map(|(s, e)| date >= s && date <= e)
                            .unwrap_or(false);
                        let is_hovered = hovered_target == Some(&YearCanvasHitTarget::Day(date));

                        if is_sat_sun {
                            if is_dark {
                                cr.set_source_rgba(1.0, 1.0, 1.0, 0.042);
                            } else {
                                cr.set_source_rgba(0.0, 0.0, 0.0, 0.044);
                            }
                            cr.rectangle(cell_x, row_y0, layout.col_w, row_h_snap);
                            let _ = cr.fill();
                        }
                        if is_selected {
                            cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.22 } else { 0.15 });
                            cr.rectangle(cell_x, row_y0, layout.col_w, row_h_snap);
                            let _ = cr.fill();
                        } else if is_today {
                            cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.16 } else { 0.10 });
                            cr.rectangle(cell_x, row_y0, layout.col_w, row_h_snap);
                            let _ = cr.fill();
                        } else if is_hovered {
                            cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.12 } else { 0.07 });
                            cr.rectangle(cell_x, row_y0, layout.col_w, row_h_snap);
                            let _ = cr.fill();
                        }

                        // Top-left day number + 2-letter weekday header ("1 Do" / "3 Sa") snapped to integer pixels
                        let day_str = day.to_string();
                        cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
                        cr.set_font_size(12.0);
                        if is_sat_sun {
                            cr.set_source_rgba(wknd_r, wknd_g, wknd_b, 0.96);
                        } else {
                            cr.set_source_rgba(fg, fg, fg, primary_alpha);
                        }
                        let day_tx = (cell_x + 3.0).round();
                        let day_ty = (row_y0 + 13.0).round();
                        cr.move_to(day_tx, day_ty);
                        let _ = cr.show_text(&day_str);

                        if layout.col_w >= 26.0 {
                            let day_adv = cr.text_extents(&day_str).map(|e| e.x_advance()).unwrap_or(13.0);
                            let wd_str = Self::calendar_weekday_two_letter(date.weekday());
                            cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
                            cr.set_font_size(11.0);
                            cr.set_source_rgba(fg, fg, fg, muted_alpha);
                            let wd_tx = (day_tx + day_adv + 2.0).round();
                            if wd_tx + 12.0 <= cell_x + layout.col_w {
                                cr.move_to(wd_tx, day_ty);
                                let _ = cr.show_text(wd_str);
                            }
                        }
                    } else {
                        // Invalid trailing day of month (e.g. Feb 29-31, Apr 31)
                        if is_dark {
                            cr.set_source_rgba(0.0, 0.0, 0.0, 0.18);
                        } else {
                            cr.set_source_rgba(0.0, 0.0, 0.0, 0.018);
                        }
                        cr.rectangle(cell_x, row_y0, layout.col_w, row_h_snap);
                        let _ = cr.fill();
                    }
                }

                // 3. Pixel-sharp 1px horizontal row divider (stronger neutral black/dark line at year boundary)
                cr.set_line_width(1.0);
                let line_c = if is_dark { 1.0 } else { 0.0 };
                let line_alpha = if m == 12 && (show_year_on_jan || row_year != max_year) {
                    if is_dark { 0.50 } else { 0.55 }
                } else {
                    border_alpha
                };
                cr.set_source_rgba(line_c, line_c, line_c, line_alpha);
                cr.move_to(0.0, row_y1 - 0.5);
                cr.line_to(layout.width, row_y1 - 0.5);
                let _ = cr.stroke();

                // 4. Event bars inside this month row
                let events_top_y = (row_y + 18.0).round();
                let avail_event_h = (layout.row_h - 19.0).max(4.0);
                let bar_h = (layout.row_h * 0.075).clamp(4.0, 5.0).round();
                let track_gap = 2.0;
                let track_step = bar_h + track_gap;
                let max_tracks = ((avail_event_h / track_step).floor() as usize).max(1);

                for span in &planner_months[row_idx].spans {
                    if span.track >= max_tracks {
                        continue;
                    }
                    let bar_y = (events_top_y + span.track as f64 * track_step).round();
                    let (start_x, bar_w) = if span.is_timed_single {
                        let cell_left = layout.month_header_w + (span.start_day - 1) as f64 * layout.col_w + 2.0;
                        let usable_cell_w = (layout.col_w - 4.0).max(6.0);
                        let short_w = (usable_cell_w * 0.44).clamp(7.0, 18.0).min(usable_cell_w).round();
                        let time_ratio = ((span.start_min as f64 - 420.0) / (1200.0 - 420.0)).clamp(0.0, 1.0);
                        let max_offset = (usable_cell_w - short_w).max(0.0);
                        ((cell_left + max_offset * time_ratio).round(), short_w)
                    } else {
                        let left_pad = if span.continues_left { 0.0 } else { 1.5 };
                        let right_pad = if span.continues_right { 0.0 } else { 1.5 };
                        let sx = (layout.month_header_w + (span.start_day - 1) as f64 * layout.col_w + left_pad).round();
                        let ex = (layout.month_header_w + span.end_day as f64 * layout.col_w - right_pad).round();
                        (sx, (ex - sx).max(2.0))
                    };
                    let (r, g, b) = span.color_rgb;
                    cr.set_source_rgba(
                        r as f64 / 255.0,
                        g as f64 / 255.0,
                        b as f64 / 255.0,
                        if span.is_timed_single { 0.90 } else { 0.98 },
                    );
                    draw_cairo_rounded_rect(cr, start_x, bar_y, bar_w, bar_h, bar_h * 0.48);
                    let _ = cr.fill();
                }
            }
        }

        // Vertical column grid lines
        cr.set_line_width(1.0);
        cr.set_source_rgba(if is_dark { 1.0 } else { 0.0 }, if is_dark { 1.0 } else { 0.0 }, if is_dark { 1.0 } else { 0.0 }, border_alpha);
        for col in 0..=31usize {
            let x = (layout.month_header_w + col as f64 * layout.col_w).floor() + 0.5;
            cr.move_to(x, bg_top);
            cr.line_to(x, bg_bottom.max(layout.height));
        }
        let _ = cr.stroke();

        // Today, Selected Range & Hovered Day outlines (drawn on top of grid lines)
        let today_in_selected = selected_range
            .map(|(s, e)| today >= s && today <= e)
            .unwrap_or(false);
        if !today_in_selected && (min_year..=max_year).contains(&today.year()) {
            let tx = layout.month_header_w + (today.day() - 1) as f64 * layout.col_w;
            let ty = ((today.year() - layout.year) as f64 * 12.0 + (today.month() - 1) as f64) * layout.row_h;
            cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 0.70);
            cr.set_line_width(1.5);
            cr.rectangle(tx + 0.75, ty + 0.75, layout.col_w - 1.5, layout.row_h - 1.5);
            let _ = cr.stroke();
        }

        if let Some((sel_start, sel_end)) = selected_range {
            cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
            cr.set_line_width(2.0);
            for &(row_year, _, _) in years_slice {
                for m in 1..=12u32 {
                    let Some(month_first) = NaiveDate::from_ymd_opt(row_year, m, 1) else {
                        continue;
                    };
                    let Some(month_last) = NaiveDate::from_ymd_opt(row_year, m, days_in_month(row_year, m)) else {
                        continue;
                    };
                    if sel_end < month_first || sel_start > month_last {
                        continue;
                    }
                    let cs = sel_start.max(month_first);
                    let ce = sel_end.min(month_last);
                    let sx = layout.month_header_w + (cs.day() - 1) as f64 * layout.col_w;
                    let ex = layout.month_header_w + ce.day() as f64 * layout.col_w;
                    let sy = ((row_year - layout.year) as f64 * 12.0 + (m - 1) as f64) * layout.row_h;
                    cr.rectangle(
                        sx + 1.0,
                        sy + 1.0,
                        (ex - sx - 2.0).max(1.0),
                        (layout.row_h - 2.0).max(1.0),
                    );
                    let _ = cr.stroke();
                }
            }
        }

        if let Some(YearCanvasHitTarget::Day(hover_date)) = hovered_target {
            if let Some(&(_, _, previews_map)) = years_slice.iter().find(|&&(y, _, _)| y == hover_date.year()) {
                let hx = layout.month_header_w + (hover_date.day() - 1) as f64 * layout.col_w;
                let hy = ((hover_date.year() - layout.year) as f64 * 12.0 + (hover_date.month() - 1) as f64) * layout.row_h;
                cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 0.95);
                cr.set_line_width(2.0);
                cr.rectangle(hx + 1.0, hy + 1.0, (layout.col_w - 2.0).max(1.0), (layout.row_h - 2.0).max(1.0));
                let _ = cr.stroke();

                Self::draw_year_planner_hover_card(
                    cr,
                    layout,
                    *hover_date,
                    previews_map.get(hover_date).map(Vec::as_slice).unwrap_or(&[]),
                    today,
                    scroll_y,
                    viewport_height,
                    is_dark,
                );
            }
        }
    }

    fn draw_year_planner_hover_card(
        cr: &gtk::cairo::Context,
        layout: &YearPlannerCanvasLayout,
        date: NaiveDate,
        items: &[YearPlannerDayPreviewItem],
        today: NaiveDate,
        scroll_y: f64,
        viewport_height: f64,
        is_dark: bool,
    ) {
        let max_items = 8usize;
        let shown_items = &items[..items.len().min(max_items)];
        let extra_count = items.len().saturating_sub(max_items);

        let card_w: f64 = 308.0;
        let header_h: f64 = 56.0;
        let mut content_h: f64 = 0.0;
        if shown_items.is_empty() {
            content_h += 30.0;
        } else {
            content_h += 6.0;
            for item in shown_items {
                content_h += if item.is_all_day_or_multi { 26.0 } else { 23.0 };
            }
            if extra_count > 0 {
                content_h += 22.0;
            }
        }
        let card_h: f64 = (header_h + content_h + 12.0).round();

        let cell_x = layout.month_header_w + (date.day() - 1) as f64 * layout.col_w;
        let cell_y = ((date.year() - layout.year) as f64 * 12.0 + (date.month() - 1) as f64) * layout.row_h;

        // Place card right next to the hovered cell (or to the left if near right edge), snapped to integer pixels
        let card_x = if cell_x + layout.col_w + 8.0 + card_w <= layout.width - 6.0 {
            (cell_x + layout.col_w + 7.0).round()
        } else {
            (cell_x - card_w - 7.0).max(6.0).round()
        };
        let min_y = (scroll_y + 6.0).round();
        let max_y = (scroll_y + viewport_height - card_h - 6.0).max(min_y).round();
        let card_y = (cell_y + layout.row_h * 0.5 - card_h * 0.35).clamp(min_y, max_y).round();

        let _ = cr.save();

        // Soft drop shadow
        for (i, alpha) in [
            (4.0, if is_dark { 0.26 } else { 0.09 }),
            (2.0, if is_dark { 0.36 } else { 0.14 }),
        ] {
            cr.set_source_rgba(0.0, 0.0, 0.0, alpha);
            draw_cairo_rounded_rect(cr, card_x - i * 0.5, card_y + i, card_w + i, card_h + i, 11.0 + i * 0.5);
            let _ = cr.fill();
        }

        // Card background (integer pixel bounds)
        if is_dark {
            cr.set_source_rgba(0.19, 0.19, 0.21, 0.99);
        } else {
            cr.set_source_rgba(1.0, 1.0, 1.0, 0.99);
        }
        draw_cairo_rounded_rect(cr, card_x, card_y, card_w, card_h, 10.0);
        let _ = cr.fill();

        // Crisp 1px card border aligned on +0.5 pixel grid
        if is_dark {
            cr.set_source_rgba(1.0, 1.0, 1.0, 0.18);
        } else {
            cr.set_source_rgba(0.0, 0.0, 0.0, 0.16);
        }
        cr.set_line_width(1.0);
        draw_cairo_rounded_rect(cr, card_x + 0.5, card_y + 0.5, card_w - 1.0, card_h - 1.0, 10.0);
        let _ = cr.stroke();

        // Header: Big Day Number ("13") on left + Weekday & Month/KW on right
        let day_str = date.day().to_string();
        cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
        cr.set_font_size(29.0);
        if is_dark {
            cr.set_source_rgba(98.0 / 255.0, 160.0 / 255.0, 234.0 / 255.0, 1.0);
        } else {
            cr.set_source_rgba(28.0 / 255.0, 113.0 / 255.0, 216.0 / 255.0, 1.0);
        }
        let num_x = (card_x + 14.0).round();
        let num_y = (card_y + 37.0).round();
        cr.move_to(num_x, num_y);
        let _ = cr.show_text(&day_str);
        let num_adv = cr.text_extents(&day_str).map(|e| e.x_advance()).unwrap_or(32.0);

        let info_x = (num_x + num_adv + 10.0).round();
        let wd_name = match date.weekday() {
            Weekday::Mon => gettext("Monday"),
            Weekday::Tue => gettext("Tuesday"),
            Weekday::Wed => gettext("Wednesday"),
            Weekday::Thu => gettext("Thursday"),
            Weekday::Fri => gettext("Friday"),
            Weekday::Sat => gettext("Saturday"),
            Weekday::Sun => gettext("Sunday"),
        };
        let rel_header = if date == today {
            format!("{}, {}", gettext("Today").to_uppercase(), wd_name.to_uppercase())
        } else if Some(date) == today.succ_opt() {
            format!("{}, {}", gettext("Tomorrow").to_uppercase(), wd_name.to_uppercase())
        } else if Some(date) == today.pred_opt() {
            format!("{}, {}", gettext("Yesterday").to_uppercase(), wd_name.to_uppercase())
        } else {
            wd_name.to_uppercase()
        };

        let fg = if is_dark { 1.0 } else { 0.12 };
        cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
        cr.set_font_size(11.0);
        cr.set_source_rgba(fg, fg, fg, if is_dark { 0.90 } else { 0.86 });
        let max_hdr_w = (card_x + card_w - info_x - 12.0).max(40.0);
        let rel_trunc = truncate_cairo_text(cr, &rel_header, max_hdr_w);
        cr.move_to(info_x, (card_y + 21.0).round());
        let _ = cr.show_text(&rel_trunc);

        let month_name = Self::calendar_month_name(date.month());
        let kw_str = format!("{} {}", gettext("CW"), date.iso_week().week());
        cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
        cr.set_font_size(12.0);
        cr.set_source_rgba(fg, fg, fg, if is_dark { 0.68 } else { 0.62 });
        let sub_hdr_y = (card_y + 38.0).round();
        cr.move_to(info_x, sub_hdr_y);
        let _ = cr.show_text(&month_name);

        if let Ok(ext) = cr.text_extents(&kw_str) {
            cr.move_to((card_x + card_w - 14.0 - ext.width()).round(), sub_hdr_y);
            let _ = cr.show_text(&kw_str);
        }

        // Crisp 1px divider line under header
        cr.set_source_rgba(fg, fg, fg, if is_dark { 0.14 } else { 0.10 });
        cr.set_line_width(1.0);
        let div_y = (card_y + 48.0).floor() + 0.5;
        cr.move_to(card_x + 12.0, div_y);
        cr.line_to(card_x + card_w - 12.0, div_y);
        let _ = cr.stroke();

        let mut cur_y = (card_y + 56.0).round();
        if shown_items.is_empty() {
            cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
            cr.set_font_size(12.0);
            cr.set_source_rgba(fg, fg, fg, if is_dark { 0.56 } else { 0.52 });
            cr.move_to((card_x + 14.0).round(), (cur_y + 18.0).round());
            let _ = cr.show_text(&gettext("No appointments"));
        } else {
            for item in shown_items {
                let (r, g, b) = item.color_rgb;
                if item.is_all_day_or_multi {
                    let pill_x = (card_x + 12.0).round();
                    let pill_w = (card_w - 24.0).round();
                    let pill_h = 22.0;
                    cr.set_source_rgba(
                        r as f64 / 255.0,
                        g as f64 / 255.0,
                        b as f64 / 255.0,
                        if is_dark { 0.34 } else { 0.22 },
                    );
                    draw_cairo_rounded_rect(cr, pill_x, cur_y, pill_w, pill_h, 5.0);
                    let _ = cr.fill();

                    // Left accent stripe inside pill
                    cr.set_source_rgba(r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0, 0.96);
                    draw_cairo_rounded_rect(cr, pill_x, cur_y, 4.0, pill_h, 2.0);
                    let _ = cr.fill();

                    cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
                    cr.set_font_size(12.0);
                    if is_dark {
                        cr.set_source_rgba(0.97, 0.97, 0.99, 0.98);
                    } else {
                        cr.set_source_rgba(
                            (r as f64 * 0.42) / 255.0,
                            (g as f64 * 0.42) / 255.0,
                            (b as f64 * 0.42) / 255.0,
                            0.98,
                        );
                    }
                    let text_trunc = truncate_cairo_text(cr, &item.title, pill_w - 16.0);
                    cr.move_to((pill_x + 9.0).round(), (cur_y + 15.0).round());
                    let _ = cr.show_text(&text_trunc);
                    cur_y += 26.0;
                } else {
                    let row_x = (card_x + 14.0).round();
                    let text_y = (cur_y + 15.0).round();
                    let time_s = item.time_str.as_deref().unwrap_or("");
                    cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
                    cr.set_font_size(11.5);
                    cr.set_source_rgba(fg, fg, fg, if is_dark { 0.70 } else { 0.64 });
                    cr.move_to(row_x, text_y);
                    let _ = cr.show_text(time_s);

                    let dot_x = (row_x + 42.0).round();
                    let dot_y = (cur_y + 11.0).round();
                    cr.arc(dot_x, dot_y, 3.8, 0.0, 2.0 * std::f64::consts::PI);
                    cr.set_source_rgba(r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0, 0.96);
                    let _ = cr.fill();

                    cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
                    cr.set_font_size(12.0);
                    cr.set_source_rgba(fg, fg, fg, if is_dark { 0.96 } else { 0.92 });
                    let title_x = (dot_x + 9.0).round();
                    let avail_w = (card_x + card_w - 12.0 - title_x).max(30.0);
                    let title_trunc = truncate_cairo_text(cr, &item.title, avail_w);
                    cr.move_to(title_x, text_y);
                    let _ = cr.show_text(&title_trunc);
                    cur_y += 23.0;
                }
            }
            if extra_count > 0 {
                cr.select_font_face("sans-serif", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
                cr.set_font_size(11.0);
                cr.set_source_rgba(fg, fg, fg, if is_dark { 0.64 } else { 0.60 });
                let more_txt = format!("+{} {}", extra_count, gettext("more"));
                cr.move_to((card_x + 14.0).round(), (cur_y + 15.0).round());
                let _ = cr.show_text(&more_txt);
            }
        }

        let _ = cr.restore();
    }

    fn show_year_planner_day_popover(
        &self,
        area: &gtk::DrawingArea,
        date: NaiveDate,
        cell_rect: gdk::Rectangle,
    ) {
        self.dismiss_year_planner_popover();

        let popover = gtk::Popover::builder()
            .autohide(true)
            .has_arrow(true)
            .pointing_to(&cell_rect)
            .css_classes(vec!["year-planner-day-popover"])
            .build();
        popover.set_parent(area);

        let page_weak_close = self.downgrade();
        let pop_weak = popover.downgrade();
        popover.connect_closed(move |p| {
            if let Some(page) = page_weak_close.upgrade() {
                let matches_curr = page
                    .imp()
                    .year_planner_popover
                    .borrow()
                    .as_ref()
                    .is_some_and(|curr| curr == p);
                if matches_curr {
                    page.imp().year_planner_popover.replace(None);
                }
            }
            if let Some(pop) = pop_weak.upgrade() {
                pop.unparent();
            }
        });

        let root_box = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(8)
            .margin_top(10)
            .margin_bottom(10)
            .margin_start(12)
            .margin_end(12)
            .width_request(268)
            .build();

        // Top BusyCal-style header: [ Big Day Number "12" | Uppercase Weekday + Month & W42 | + ]
        let header_row = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(10)
            .valign(gtk::Align::Center)
            .build();

        let day_num_lbl = gtk::Label::builder()
            .label(&date.day().to_string())
            .css_classes(vec!["year-planner-popover-day-number"])
            .valign(gtk::Align::Center)
            .build();
        header_row.append(&day_num_lbl);

        let meta_col = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(1)
            .hexpand(true)
            .valign(gtk::Align::Center)
            .build();

        let today = Local::now().date_naive();
        let weekday_full = match date.weekday() {
            Weekday::Mon => gettext("Monday"),
            Weekday::Tue => gettext("Tuesday"),
            Weekday::Wed => gettext("Wednesday"),
            Weekday::Thu => gettext("Thursday"),
            Weekday::Fri => gettext("Friday"),
            Weekday::Sat => gettext("Saturday"),
            Weekday::Sun => gettext("Sunday"),
        };
        let top_line_str = if date == today {
            format!("{}, {}", gettext("Today"), weekday_full).to_uppercase()
        } else if Some(date) == today.succ_opt() {
            format!("{}, {}", gettext("Tomorrow"), weekday_full).to_uppercase()
        } else if Some(date) == today.pred_opt() {
            format!("{}, {}", gettext("Yesterday"), weekday_full).to_uppercase()
        } else {
            weekday_full.to_uppercase()
        };

        let weekday_lbl = gtk::Label::builder()
            .label(&top_line_str)
            .xalign(0.0)
            .ellipsize(pango::EllipsizeMode::End)
            .css_classes(vec!["year-planner-popover-weekday"])
            .build();
        meta_col.append(&weekday_lbl);

        let sub_row = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(8)
            .hexpand(true)
            .build();
        let month_lbl = gtk::Label::builder()
            .label(&Self::calendar_month_name(date.month()))
            .xalign(0.0)
            .hexpand(true)
            .css_classes(vec!["caption", "dim-label"])
            .build();
        let kw_lbl = gtk::Label::builder()
            .label(&format!("{} {}", gettext("W"), date.iso_week().week()))
            .xalign(1.0)
            .css_classes(vec!["caption", "dim-label"])
            .build();
        sub_row.append(&month_lbl);
        sub_row.append(&kw_lbl);
        meta_col.append(&sub_row);
        header_row.append(&meta_col);

        let add_btn = gtk::Button::builder()
            .icon_name("list-add-symbolic")
            .tooltip_text(&gettext("New Appointment"))
            .css_classes(vec!["flat", "circular"])
            .valign(gtk::Align::Center)
            .build();
        {
            let page_weak = self.downgrade();
            let pop_weak = popover.downgrade();
            add_btn.connect_clicked(move |_| {
                if let Some(pop) = pop_weak.upgrade() {
                    pop.popdown();
                }
                if let Some(page) = page_weak.upgrade() {
                    let dialog = crate::dialogs::EventDialog::new_for_date(date);
                    let page_for_refresh = page.downgrade();
                    dialog.connect_closed(move |_| {
                        if let Some(page) = page_for_refresh.upgrade() {
                            page.reload_calendar_data();
                        }
                    });
                    dialog.present_adaptive(&page);
                }
            });
        }
        header_row.append(&add_btn);
        root_box.append(&header_row);

        // Events on this day
        let day_events = self
            .events_by_date(CalendarDateRange::single(date))
            .remove(&date)
            .unwrap_or_default();

        if day_events.is_empty() {
            let empty_lbl = gtk::Label::builder()
                .label(&gettext("No appointments"))
                .xalign(0.0)
                .margin_top(2)
                .margin_bottom(2)
                .css_classes(vec!["caption", "dim-label"])
                .build();
            root_box.append(&empty_lbl);
        } else {
            let events_box = gtk::Box::builder()
                .orientation(gtk::Orientation::Vertical)
                .spacing(4)
                .margin_top(2)
                .build();
            let is_dark = adw::StyleManager::default().is_dark();

            // 1. All-day & Multi-day pills first (matching BusyCal)
            for ev in day_events.iter() {
                let range = event_occurrence_range_for_date(ev, date)
                    .or_else(|| event_display_range(ev))
                    .unwrap_or_else(|| CalendarDateRange::single(date));
                if !(ev.all_day || range.len_days() > 1) {
                    continue;
                }
                let color = event_color_for_record(ev);
                let (bg, hover, active, fg) = pastel_colors_for_hex(&color, is_dark);
                let chip_class = ensure_event_chip_css_class(&color, &bg, &hover, &active, &fg);
                let title = if ev.summary.trim().is_empty() {
                    gettext("(Untitled)")
                } else {
                    ev.summary.clone()
                };
                let pill_btn = gtk::Button::builder()
                    .label(&title)
                    .halign(gtk::Align::Fill)
                    .css_classes(vec!["flat", "calendar-grid-event", chip_class.as_str()])
                    .build();
                let identity = CalendarEventIdentity::from_event(ev);
                let page_weak = self.downgrade();
                let pop_weak = popover.downgrade();
                let area_clone = area.clone();
                pill_btn.connect_clicked(move |_| {
                    if let Some(pop) = pop_weak.upgrade() {
                        pop.popdown();
                    }
                    if let (Some(page), Some(id)) = (page_weak.upgrade(), identity.as_ref()) {
                        page.open_event_editor_for_identity(&area_clone, id);
                    }
                });
                events_box.append(&pill_btn);
            }

            // 2. Timed single-day rows: "07:30  •  Summary"
            for ev in day_events.iter() {
                let range = event_occurrence_range_for_date(ev, date)
                    .or_else(|| event_display_range(ev))
                    .unwrap_or_else(|| CalendarDateRange::single(date));
                if ev.all_day || range.len_days() > 1 {
                    continue;
                }
                let (start_min, _, _) = event_occurrence_times_for_date(ev, date, 30);
                let time_str = format_clock_minutes(start_min);
                let color = event_color_for_record(ev);
                let (r, g, b) = parse_hex_color(&color).unwrap_or((53, 132, 228));

                let row_btn = gtk::Button::builder()
                    .css_classes(vec!["flat", "year-planner-popover-event-row"])
                    .halign(gtk::Align::Fill)
                    .build();
                let row_box = gtk::Box::builder()
                    .orientation(gtk::Orientation::Horizontal)
                    .spacing(8)
                    .valign(gtk::Align::Center)
                    .build();

                let time_lbl = gtk::Label::builder()
                    .label(&time_str)
                    .xalign(0.0)
                    .width_chars(5)
                    .css_classes(vec!["caption", "dim-label", "numeric"])
                    .build();
                row_box.append(&time_lbl);

                let dot = gtk::DrawingArea::builder()
                    .content_width(8)
                    .content_height(8)
                    .valign(gtk::Align::Center)
                    .build();
                dot.set_draw_func(move |_, cr, w, h| {
                    cr.arc(w as f64 * 0.5, h as f64 * 0.5, 3.5, 0.0, 2.0 * std::f64::consts::PI);
                    cr.set_source_rgb(r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0);
                    let _ = cr.fill();
                });
                row_box.append(&dot);

                let title = if ev.summary.trim().is_empty() {
                    gettext("(Untitled)")
                } else {
                    ev.summary.clone()
                };
                let title_lbl = gtk::Label::builder()
                    .label(&title)
                    .xalign(0.0)
                    .hexpand(true)
                    .ellipsize(pango::EllipsizeMode::End)
                    .css_classes(vec!["caption"])
                    .build();
                row_box.append(&title_lbl);

                row_btn.set_child(Some(&row_box));

                let identity = CalendarEventIdentity::from_event(ev);
                let page_weak = self.downgrade();
                let pop_weak = popover.downgrade();
                let area_clone = area.clone();
                row_btn.connect_clicked(move |_| {
                    if let Some(pop) = pop_weak.upgrade() {
                        pop.popdown();
                    }
                    if let (Some(page), Some(id)) = (page_weak.upgrade(), identity.as_ref()) {
                        page.open_event_editor_for_identity(&area_clone, id);
                    }
                });
                events_box.append(&row_btn);
            }

            let scroll = gtk::ScrolledWindow::builder()
                .hscrollbar_policy(gtk::PolicyType::Never)
                .vscrollbar_policy(gtk::PolicyType::Automatic)
                .propagate_natural_height(true)
                .max_content_height(260)
                .child(&events_box)
                .build();
            root_box.append(&scroll);
        }

        popover.set_child(Some(&root_box));
        self.imp().year_planner_popover.replace(Some(popover.clone()));
        popover.popup();
    }

    fn update_year_paned_layout(&self) {
        if let (Some(paned), Some(details_container)) = (
            self.imp().year_paned.borrow().as_ref(),
            self.imp().year_details_container.borrow().as_ref(),
        ) {
            if self.imp().year_view_style.get() != YearViewStyle::Grid {
                details_container.set_visible(false);
                return;
            }
            details_container.set_visible(true);
            details_container.remove_css_class("side-mode");
            details_container.remove_css_class("bottom-mode");
            details_container.add_css_class("calendar-year-details-panel");
            match self.imp().year_preview_orientation.get() {
                YearPreviewOrientation::Side => {
                    details_container.add_css_class("side-mode");
                    let side_w = self.imp().year_details_side_width.get();
                    details_container.set_width_request(side_w.clamp(160, 600));
                    details_container.set_height_request(-1);
                    paned.set_orientation(gtk::Orientation::Horizontal);
                }
                YearPreviewOrientation::Bottom => {
                    details_container.add_css_class("bottom-mode");
                    let bottom_h = self.imp().year_details_bottom_height.get();
                    details_container.set_height_request(bottom_h.clamp(120, 500));
                    details_container.set_width_request(-1);
                    paned.set_orientation(gtk::Orientation::Vertical);
                }
            }
        }
    }

    pub(crate) fn get_or_build_year_projection(
        &self,
        target_year: i32,
    ) -> (
        BTreeMap<NaiveDate, usize>,
        [YearPlannerMonthData; 12],
        HashMap<NaiveDate, Vec<YearPlannerDayPreviewItem>>,
    ) {
        let Some(year_range) = calendar_year_range_option(target_year) else {
            return (
                BTreeMap::new(),
                std::array::from_fn(|_| YearPlannerMonthData::default()),
                HashMap::new(),
            );
        };
        let query = self.imp().calendar_search_query.borrow().clone();
        let category = self.imp().calendar_category_filter.borrow().clone();
        let hidden_sources = self.imp().hidden_calendar_sources.borrow().clone();
        let hidden_count = hidden_sources.len();
        let revision = self.imp().calendar_revision.get();
        let key = (
            target_year,
            revision,
            query.clone(),
            category.clone(),
            hidden_count,
        );
        if let Some(hit) = self.imp().year_projection_cache.borrow().get(&key).cloned() {
            return hit;
        }
        let built = if let Some(index) = self
            .imp()
            .calendar_snapshot_index
            .borrow()
            .as_ref()
        {
            Self::build_year_projection_from_index(
                index,
                target_year,
                year_range,
                &query,
                category.as_deref(),
                &hidden_sources,
            )
        } else {
            let mut day_identities: BTreeMap<NaiveDate, (BTreeSet<CalendarEventIdentity>, usize)> =
                BTreeMap::new();
            if let Some(records) = self.imp().event_records.borrow().as_ref() {
                for event in records.borrow().iter() {
                    if !event_matches_calendar_filter(
                        event,
                        &query,
                        category.as_deref(),
                        &hidden_sources,
                    ) {
                        continue;
                    }
                    let identity = CalendarEventIdentity::from_event(event);
                    for date in event_occurrence_dates_in_range(event, year_range) {
                        let (seen, no_id_count) = day_identities.entry(date).or_default();
                        if let Some(ref id) = identity {
                            seen.insert(id.clone());
                        } else {
                            *no_id_count += 1;
                        }
                    }
                }
            }
            let markers: BTreeMap<NaiveDate, usize> = day_identities
                .into_iter()
                .filter_map(|(date, (seen, no_id_count))| {
                    let count = seen.len() + no_id_count;
                    (count > 0).then_some((date, count))
                })
                .collect();
            let year_events_by_date = self.events_by_date(year_range);
            let planner_months = Self::build_year_planner_months(target_year, &year_events_by_date);
            let mut day_previews: HashMap<NaiveDate, Vec<YearPlannerDayPreviewItem>> =
                HashMap::new();
            for (&date, evs) in &year_events_by_date {
                let mut items = Vec::with_capacity(evs.len());
                for ev in evs {
                    let range = event_occurrence_range_for_date(ev, date)
                        .or_else(|| event_display_range(ev))
                        .unwrap_or_else(|| CalendarDateRange::single(date));
                    let is_all_day_or_multi = ev.all_day || range.len_days() > 1;
                    let (s_min, _, _) = event_occurrence_times_for_date(ev, date, 30);
                    let hex = event_color_for_record(ev);
                    let color_rgb = parse_hex_color(&hex).unwrap_or((53, 132, 228));
                    items.push(YearPlannerDayPreviewItem {
                        title: if ev.summary.trim().is_empty() {
                            gettext("(Untitled)")
                        } else {
                            ev.summary.clone()
                        },
                        time_str: (!is_all_day_or_multi).then(|| format_clock_minutes(s_min)),
                        color_rgb,
                        is_all_day_or_multi,
                        start_min: s_min.min(1439) as u16,
                    });
                }
                items.sort_by(|a, b| {
                    b.is_all_day_or_multi
                        .cmp(&a.is_all_day_or_multi)
                        .then_with(|| a.start_min.cmp(&b.start_min))
                        .then_with(|| a.title.cmp(&b.title))
                });
                day_previews.insert(date, items);
            }
            (markers, planner_months, day_previews)
        };
        let mut cache = self.imp().year_projection_cache.borrow_mut();
        if cache.len() >= 16 {
            cache.clear();
        }
        cache.insert(key, built.clone());
        built
    }

    fn refresh_year_view(&self) {
        let state_box = self.imp().year_state_box.borrow().as_ref().cloned();
        let paned = self.imp().year_paned.borrow().as_ref().cloned();

        if self.calendar_data_state() != CalendarDataState::Ready {
            if let Some(paned) = paned {
                paned.set_visible(false);
            }
            if let Some(state_box) = state_box {
                clear_box(&state_box);
                state_box.append(&self.calendar_state_row());
                state_box.set_visible(true);
            }
            return;
        }

        let year = self.current_calendar_viewport().anchor_date.year();
        let Some(year_range) = calendar_year_range_option(year) else {
            if let Some(state_box) = state_box.as_ref() {
                clear_box(state_box);
                state_box.append(&empty_period_row(
                    &gettext("Year view not available"),
                    &gettext("The selected calendar year is outside the supported date range."),
                ));
                state_box.set_visible(true);
            }
            if let Some(paned) = paned {
                paned.set_visible(false);
            }
            return;
        };

        if let Some(state_box) = state_box {
            state_box.set_visible(false);
        }
        if let Some(paned) = paned.as_ref() {
            paned.set_visible(true);
        }

        let selected_day = self
            .imp()
            .view_state
            .borrow()
            .selected_range
            .filter(|range| range.start.year() == year)
            .map(|range| range.start)
            .unwrap_or_else(|| {
                self.current_calendar_viewport()
                    .anchor_date
                    .max(year_range.start)
                    .min(year_range.last_inclusive())
            });

        let query = self.imp().calendar_search_query.borrow().clone();
        let category = self.imp().calendar_category_filter.borrow().clone();
        let hidden_sources = self.imp().hidden_calendar_sources.borrow().clone();
        let hidden_count = hidden_sources.len();
        let revision = self.imp().calendar_revision.get();
        let key = (year, revision, query.clone(), category.clone(), hidden_count);

        if self.imp().year_view_style.get() == YearViewStyle::MultiYear {
            self.ensure_multi_year_summaries_for_anchor(year);
        } else if self.imp().year_rendered_key.borrow().as_ref() != Some(&key) {
            let (markers, planner_months, day_previews) = self.get_or_build_year_projection(year);

            *self.imp().year_planner_months.borrow_mut() = planner_months;
            *self.imp().year_day_previews.borrow_mut() = day_previews;
            *self.imp().year_markers.borrow_mut() = markers;
            self.imp().year_rendered_key.replace(Some(key));

            // Pre-warm adjacent years (year - 1, year + 1) on idle so clicking `<` or `>` is a 0.00ms cache hit
            let page_weak = self.downgrade();
            glib::idle_add_local_once(move || {
                let Some(page) = page_weak.upgrade() else { return };
                let Some(index) = page.imp().calendar_snapshot_index.borrow().as_ref().cloned() else { return };
                let q = page.imp().calendar_search_query.borrow().clone();
                let cat = page.imp().calendar_category_filter.borrow().clone();
                let hidden = page.imp().hidden_calendar_sources.borrow().clone();
                let h_cnt = hidden.len();
                let rev = page.imp().calendar_revision.get();
                for adj_year in [year - 1, year + 1] {
                    let adj_key = (adj_year, rev, q.clone(), cat.clone(), h_cnt);
                    if !page.imp().year_projection_cache.borrow().contains_key(&adj_key) {
                        if let Some(adj_range) = calendar_year_range_option(adj_year) {
                            let built = Self::build_year_projection_from_index(
                                &index,
                                adj_year,
                                adj_range,
                                &q,
                                cat.as_deref(),
                                &hidden,
                            );
                            page.imp().year_projection_cache.borrow_mut().insert(adj_key, built);
                        }
                    }
                }
            });
        }

        // Reset scroll position if year changed
        if self.imp().year_rendered_year.get() != Some(year) {
            self.imp().year_rendered_year.set(Some(year));
            self.imp().year_planner_scroll_y.set(0.0);
            if let Some(vadj) = self.imp().year_vadjustment.borrow().as_ref() {
                vadj.set_value(0.0);
            }
        }

        self.update_year_paned_layout();

        if let Some(canvas) = self.imp().year_canvas.borrow().as_ref() {
            canvas.queue_draw();
        }
        if self.imp().year_view_style.get() == YearViewStyle::Grid {
            if let Some(details) = self.imp().year_details_container.borrow().as_ref() {
                self.render_year_day_details(details, selected_day);
            }
        }
    }

    fn populate_list_view(
        &self,
        _view: &gtk::Box,
        events: Vec<CalendarEventRecord>,
        prepared: Vec<PreparedCalendarListRow>,
    ) {
        self.imp()
            .view_state
            .borrow_mut()
            .reconcile_event_selection(&events);
        self.imp()
            .calendar_list_projection_count
            .set(Some(events.len()));

        let count_str = if events.is_empty() {
            gettext("No matching appointments")
        } else {
            ngettext(
                "1 filtered appointment",
                "{n} filtered appointments",
                events.len() as u32,
            )
            .replace("{n}", &events.len().to_string())
        };

        if let Some(count_lbl) = self.imp().calendar_list_count_label.borrow().as_ref() {
            count_lbl.set_label(&count_str);
        }

        let is_empty = events.is_empty();
        if let Some(empty_box) = self.imp().calendar_list_empty_box.borrow().as_ref().and_then(|w| w.downcast_ref::<gtk::Box>()) {
            clear_box(empty_box);
            if is_empty {
                let all_count = self
                    .imp()
                    .calendar_snapshot_index
                    .borrow()
                    .as_ref()
                    .map(|index| index.snapshot.events.len())
                    .unwrap_or(0);
                let title = if all_count == 0 {
                    gettext("No appointments loaded")
                } else {
                    gettext("No appointments match the filter")
                };
                let empty_row = empty_period_row(
                    &title,
                    &gettext("The list view is independent of the current date anchor."),
                );
                empty_box.append(&empty_row);
                empty_box.set_visible(true);
            } else {
                empty_box.set_visible(false);
            }
        }

        let total_h = (prepared.len() as f64 * 46.0).ceil() as i32;
        self.imp().calendar_list_events.replace(prepared);

        if let Some(scroll) = self.imp().calendar_list_scroll.borrow().as_ref() {
            scroll.set_visible(!is_empty);
        }

        if let Some(canvas) = self.imp().calendar_list_canvas.borrow().as_ref() {
            canvas.set_content_height(total_h.max(1));
            canvas.queue_draw();
        }
    }

    fn refresh_list_view(&self) {
        let Some(_view) = self.imp().list_view.borrow().as_ref().cloned() else {
            return;
        };
        self.imp().calendar_list_projection_count.set(None);
        if self.calendar_data_state() != CalendarDataState::Ready {
            self.imp().calendar_list_rendered_key.replace(None);
            if let Some(empty_box) = self.imp().calendar_list_empty_box.borrow().as_ref().and_then(|w| w.downcast_ref::<gtk::Box>()) {
                clear_box(empty_box);
                empty_box.append(&self.calendar_state_row());
                empty_box.set_visible(true);
            }
            if let Some(scroll) = self.imp().calendar_list_scroll.borrow().as_ref() {
                scroll.set_visible(false);
            }
            return;
        }
        let Some(_index) = self.imp().calendar_snapshot_index.borrow().as_ref().cloned() else {
            self.imp().calendar_list_rendered_key.replace(None);
            self.populate_list_view(&_view, Vec::new(), Vec::new());
            return;
        };

        let search_query = self.imp().calendar_search_query.borrow().clone();
        let category_filter = self.imp().calendar_category_filter.borrow().clone();
        let hidden_sources = self.imp().hidden_calendar_sources.borrow().clone();
        let revision = self.imp().calendar_revision.get();
        let key = (revision, search_query, category_filter, hidden_sources.len());

        if self.imp().calendar_list_rendered_key.borrow().as_ref() == Some(&key) {
            let is_empty = self.imp().calendar_list_events.borrow().is_empty();
            if let Some(scroll) = self.imp().calendar_list_scroll.borrow().as_ref() {
                scroll.set_visible(!is_empty);
            }
            if let Some(empty_box) = self.imp().calendar_list_empty_box.borrow().as_ref() {
                empty_box.set_visible(is_empty);
            }
            if let Some(canvas) = self.imp().calendar_list_canvas.borrow().as_ref() {
                canvas.queue_draw();
            }
            self.refresh_period_label();
            return;
        }

        self.start_calendar_projection(CalendarView::List);
        self.refresh_period_label();
    }

    fn apply_list_projection_plan(&self, load: CalendarProjectionLoad, plan: ListProjectionPlan) {
        let Some(view) = self.imp().list_view.borrow().as_ref().cloned() else {
            return;
        };
        if !self.calendar_projection_is_current(&load) {
            return;
        }
        let key = (
            load.revision,
            self.imp().calendar_search_query.borrow().clone(),
            self.imp().calendar_category_filter.borrow().clone(),
            self.imp().hidden_calendar_sources.borrow().len(),
        );
        self.imp().calendar_list_rendered_key.replace(Some(key));
        self.populate_list_view(&view, plan.events, plan.prepared);
        if self.finish_calendar_projection(&load) {
            self.refresh_period_label();
        }
    }

    fn append_calendar_event_action_row(
        &self,
        event_list: &gtk::ListBox,
        event: &CalendarEventRecord,
    ) {
        if let Some(records) = self.imp().event_records.borrow().as_ref().cloned() {
            append_event_row(self, event_list, records, event.clone());
        } else {
            event_list.append(&calendar_event_row(self, event));
        }
    }

    fn select_calendar_day(&self, date: NaiveDate) {
        if *self.imp().current_view.borrow() != CalendarView::Year {
            return;
        }
        *self.imp().current_date.borrow_mut() = date;
        self.imp()
            .view_state
            .borrow_mut()
            .set_anchor(date, configured_first_weekday());
        self.imp().view_state.borrow_mut().select_civil_day(date);
        *self.imp().selected_time_slot.borrow_mut() = Some(SelectedTimeSlot {
            date,
            end_date: date,
            start_minute: 540,
            end_minute: 600,
        });

        if let Some(canvas) = self.imp().year_canvas.borrow().as_ref() {
            canvas.queue_draw();
        }
        if self.imp().year_view_style.get() == YearViewStyle::Grid {
            if let Some(details) = self.imp().year_details_container.borrow().as_ref() {
                self.render_year_day_details(details, date);
            }
        }
        if self.imp().year_rendered_year.get() == Some(date.year())
            || self.imp().year_view_style.get() == YearViewStyle::Planner
        {
            self.refresh_period_label();
            return;
        }

        self.refresh_calendar_views();
    }

    fn select_calendar_day_range(&self, start_date: NaiveDate, end_date: NaiveDate) {
        if *self.imp().current_view.borrow() != CalendarView::Year {
            return;
        }
        let (s, e) = if start_date <= end_date {
            (start_date, end_date)
        } else {
            (end_date, start_date)
        };
        *self.imp().current_date.borrow_mut() = e;
        {
            let mut state = self.imp().view_state.borrow_mut();
            state.set_anchor(e, configured_first_weekday());
            state.select_civil_day(e);
        }
        *self.imp().selected_time_slot.borrow_mut() = Some(SelectedTimeSlot {
            date: s,
            end_date: e,
            start_minute: 540,
            end_minute: 600,
        });

        if let Some(canvas) = self.imp().year_canvas.borrow().as_ref() {
            canvas.queue_draw();
        }
        if self.imp().year_view_style.get() == YearViewStyle::Grid {
            if let Some(details) = self.imp().year_details_container.borrow().as_ref() {
                self.render_year_day_details(details, s);
            }
        }
        self.refresh_period_label();
    }

    fn connect_calendar_event_selection(&self, event_list: &gtk::ListBox) {
        let page_weak = self.downgrade();
        event_list.connect_row_selected(move |_, row| {
            let Some(page) = page_weak.upgrade() else {
                return;
            };
            let identity = row.and_then(calendar_event_identity_from_list_row);
            page.select_calendar_event_identity(identity);
        });
    }

    fn select_calendar_event_identity(&self, identity: Option<CalendarEventIdentity>) {
        let events = self.filtered_sorted_events();
        let Some(identity) = identity else {
            self.imp().view_state.borrow_mut().select_event(None, None);
            return;
        };
        let Some(index) = unique_event_index_for_identity(&events, &identity) else {
            self.imp().view_state.borrow_mut().select_event(None, None);
            return;
        };
        self.imp()
            .view_state
            .borrow_mut()
            .select_event(Some(identity), Some(index));
    }

    fn restore_calendar_event_selection(
        &self,
        event_list: &gtk::ListBox,
        events: &[CalendarEventRecord],
    ) {
        let selected = self.imp().view_state.borrow().selected_event.clone();
        let Some(selected) = selected else {
            return;
        };
        let Some(index) = unique_event_index_for_identity(events, &selected) else {
            return;
        };
        if let Some(row) = event_list.row_at_index(index as i32) {
            event_list.select_row(Some(&row));
        }
    }

    fn filtered_sorted_events(&self) -> Vec<CalendarEventRecord> {
        let query = self.imp().calendar_search_query.borrow().clone();
        let category = self.imp().calendar_category_filter.borrow().clone();
        let hidden_sources = self.imp().hidden_calendar_sources.borrow().clone();
        if let Some(index) = self
            .imp()
            .calendar_snapshot_index
            .borrow()
            .as_ref()
            .cloned()
        {
            return filtered_sorted_event_indices(
                &index,
                &query,
                category.as_deref(),
                &hidden_sources,
            )
            .into_iter()
            .filter_map(|event_index| index.snapshot.events.get(event_index).cloned())
            .collect();
        }

        let mut events = self
            .imp()
            .event_records
            .borrow()
            .as_ref()
            .map(|records| records.borrow().clone())
            .unwrap_or_default();
        events.retain(|event| {
            event_matches_calendar_filter(event, &query, category.as_deref(), &hidden_sources)
        });
        events.sort_by(compare_event_list_order);
        events
    }

    fn events_by_date(
        &self,
        range: CalendarDateRange,
    ) -> BTreeMap<NaiveDate, Vec<CalendarEventRecord>> {
        let query = self.imp().calendar_search_query.borrow().clone();
        let category = self.imp().calendar_category_filter.borrow().clone();
        let hidden_sources = self.imp().hidden_calendar_sources.borrow().clone();
        if let Some(index) = self
            .imp()
            .calendar_snapshot_index
            .borrow()
            .as_ref()
            .cloned()
        {
            return indexed_events_by_date(
                &index,
                range,
                &query,
                category.as_deref(),
                &hidden_sources,
            );
        }

        let mut grouped = BTreeMap::<NaiveDate, Vec<CalendarEventRecord>>::new();
        if let Some(records) = self.imp().event_records.borrow().as_ref().cloned() {
            for date in range.dates() {
                for event in records.borrow().iter() {
                    if event_matches_calendar_filter(
                        event,
                        &query,
                        category.as_deref(),
                        &hidden_sources,
                    ) && event_occurs_on(event, date)
                    {
                        grouped.entry(date).or_default().push(event.clone());
                    }
                }
            }
        }

        for (date, events) in grouped.iter_mut() {
            events.sort_by(|a, b| compare_day_events_order(a, b, *date));
            let mut seen = BTreeSet::new();
            events.retain(|event| {
                CalendarEventIdentity::from_event(event)
                    .map(|identity| seen.insert(identity))
                    .unwrap_or(true)
            });
        }
        grouped
    }

    fn calendar_source_is_visible(&self, source_uid: &str) -> bool {
        !self
            .imp()
            .hidden_calendar_sources
            .borrow()
            .contains(source_uid)
    }

    fn calendar_category_matches(&self, categories: &str) -> bool {
        self.imp()
            .calendar_category_filter
            .borrow()
            .as_deref()
            .is_none_or(|filter| {
                categories
                    .split('\u{1f}')
                    .any(|category| category.eq_ignore_ascii_case(filter))
            })
    }

    fn calendar_search_matches(&self, search_text: &str) -> bool {
        let query = self.imp().calendar_search_query.borrow();
        query.is_empty() || search_text.contains(query.as_str())
    }

    fn update_month_header_labels(&self, is_compact: bool) {
        self.imp().month_header_is_compact.set(is_compact);
        let names = if is_compact {
            configured_weekday_names_short()
        } else {
            configured_weekday_names_full()
        };
        let labels = self.imp().month_header_labels.borrow();
        for (label, name) in labels.iter().zip(names.iter()) {
            label.set_text(name.as_str());
        }
    }

    fn refresh_month_grid(&self) {
        let anchor = *self.imp().current_date.borrow();
        let first_weekday = configured_first_weekday();
        let viewport = {
            let state_vp = self.imp().view_state.borrow().viewport();
            if state_vp.view == CalendarView::Month && state_vp.visible_range.len_days() >= 28 {
                state_vp
            } else {
                CalendarViewport::for_view(CalendarView::Month, anchor, first_weekday)
            }
        };
        let query = self.imp().calendar_search_query.borrow().clone();
        let category = self.imp().calendar_category_filter.borrow().clone();
        let hidden_count = self.imp().hidden_calendar_sources.borrow().len();
        let revision = self.imp().calendar_revision.get();
        let is_dark = adw::StyleManager::default().is_dark();
        let scale_pct = (configured_chip_scale() * 100.0).round() as i32;
        let key = (viewport.anchor_date, viewport.visible_range, revision, query, category, hidden_count, is_dark, scale_pct);

        let reusable_prev_layout = {
            let prev_key_guard = self.imp().month_rendered_key.borrow();
            let prev_layout_guard = self.imp().month_layout.borrow();
            if prev_key_guard.as_ref() == Some(&key) && prev_layout_guard.is_some() {
                drop(prev_key_guard);
                drop(prev_layout_guard);
                if let Some(canvas) = self.imp().month_canvas.borrow().as_ref() {
                    canvas.queue_draw();
                }
                return;
            }
            match (prev_key_guard.as_ref(), prev_layout_guard.as_ref()) {
                (Some(pk), Some(pl))
                    if pk.2 == key.2
                        && pk.3 == key.3
                        && pk.4 == key.4
                        && pk.5 == key.5
                        && pk.6 == key.6
                        && pk.7 == key.7 =>
                {
                    Some(pl.clone())
                }
                _ => None,
            }
        };

        let events_by_date = self.events_by_date(viewport.visible_range);
        let today = Local::now().date_naive();
        let show_week_numbers = AppSettings::try_new()
            .map(|settings| settings.calendar_show_week_numbers())
            .unwrap_or(false);
        let compress_weekend = configured_compress_weekend();
        let workdays: HashSet<Weekday> = configured_workdays().into_iter().collect();

        let weekday_names_full = configured_weekday_names_full();
        let weekday_names_short = configured_weekday_names_short();
        let full_refs: Vec<&str> = weekday_names_full.iter().map(|s| s.as_str()).collect();
        let short_refs: Vec<&str> = weekday_names_short.iter().map(|s| s.as_str()).collect();

        let prev_weeks = reusable_prev_layout
            .as_ref()
            .filter(|pl| pl.today == today)
            .map(|pl| pl.weeks.as_slice());

        let layout = prepare_month_layout_with_cache(
            &viewport,
            &events_by_date,
            today,
            show_week_numbers,
            &workdays,
            compress_weekend,
            &full_refs,
            &short_refs,
            is_dark,
            16,
            prev_weeks,
        );

        self.imp().month_layout.replace(Some(Rc::new(layout)));
        self.imp().month_rendered_key.replace(Some(key));
        if let Some(canvas) = self.imp().month_canvas.borrow().as_ref() {
            canvas.queue_draw();
        }
    }

    fn move_event_by_days(&self, event: CalendarEventRecord, delta_days: i64) {
        self.move_event_by_delta(event, delta_days, 0);
    }

    fn move_event_by_delta(
        &self,
        event: CalendarEventRecord,
        delta_days: i64,
        delta_minutes: i64,
    ) {
        if delta_days == 0 && delta_minutes == 0 {
            return;
        }
        if let Some(error) = event_mutation_error(&event) {
            show_toast_for_widget(self, &error);
            return;
        }
        let updated_component =
            match shift_event_component_full(&event.component, delta_days, delta_minutes) {
                Ok(component) => component,
                Err(error) => {
                    show_toast_for_widget(self, &error);
                    return;
                }
            };
        let mutation_token =
            self.begin_calendar_mutation(CalendarEventIdentity::from_event(&event));
        let source_uid = event.source_uid.clone();
        let uid = event.uid.clone();
        let (sender, receiver) = async_channel::bounded(1);
        std::thread::spawn(move || {
            let result = ECalService::new().modify_component(
                &source_uid,
                ECalComponentType::Event,
                &uid,
                &updated_component,
            );
            if let Err(error) = sender.send_blocking(result) {
                tracing::debug!(%error, "Event move result was dropped");
            }
        });

        let page_weak = self.downgrade();
        glib::spawn_future_local(async move {
            let result = receiver.recv().await;
            let Some(page) = page_weak.upgrade() else {
                return;
            };
            if !page.calendar_event_mutation_is_current(&mutation_token) {
                show_toast_for_widget(
                    &page,
                    &gettext("The calendar state has changed; the event move was discarded"),
                );
                page.reload_calendar_data();
                return;
            }
            let result = match result {
                Ok(result) => result,
                Err(error) => {
                    page.finish_calendar_mutation(&mutation_token);
                    show_toast_for_widget(
                        &page,
                        &format!("{}: {error}", crate::i18n::gettext("Failed to confirm event move")),
                    );
                    page.reload_calendar_data();
                    return;
                }
            };
            match result {
                Ok(result) => {
                    let component = match validated_event_mutation_component(&event, &result) {
                        Ok(component) => component,
                        Err(error) => {
                            page.finish_calendar_mutation(&mutation_token);
                            show_toast_for_widget(&page, &error);
                            page.reload_calendar_data();
                            return;
                        }
                    };
                    let mut updated_event = event.clone();
                    updated_event.component = component.clone();
                    updated_event.start =
                        property_local_display(&component, "DTSTART", updated_event.all_day)
                            .unwrap_or_default();
                    updated_event.end =
                        property_local_display(&component, "DTEND", updated_event.all_day)
                            .unwrap_or_default();
                    let records = page.imp().event_records.borrow().as_ref().cloned();
                    if let Some(records) = records {
                        let mut records = records.borrow_mut();
                        if let Some(existing) = records
                            .iter_mut()
                            .find(|existing| same_calendar_event_identity(existing, &updated_event))
                        {
                            *existing = updated_event;
                        }
                    }
                    if !page.finish_calendar_mutation(&mutation_token) {
                        page.reload_calendar_data();
                        return;
                    }
                    page.bump_calendar_revision();
                    page.rebuild_calendar_index_from_records();
                    page.refresh_calendar_views();
                    show_toast_for_widget(&page, &format!("{} ({})", crate::i18n::gettext("Event moved"), result.uid));
                }
                Err(error) => {
                    page.finish_calendar_mutation(&mutation_token);
                    show_toast_for_widget(
                        &page,
                        &format!("{}: {error}", crate::i18n::gettext("Could not move event")),
                    );
                    page.reload_calendar_data();
                }
            }
        });
    }

    fn duplicate_event_by_delta(
        &self,
        event: CalendarEventRecord,
        delta_days: i64,
        delta_minutes: i64,
    ) {
        if let Some(error) = event_mutation_error(&event) {
            show_toast_for_widget(self, &error);
            return;
        }
        let updated_component =
            match shift_event_component_full(&event.component, delta_days, delta_minutes) {
                Ok(component) => component,
                Err(error) => {
                    show_toast_for_widget(self, &error);
                    return;
                }
            };
        let new_uid = uuid::Uuid::new_v4().to_string();
        let mut duplicated = update_ical_property(&updated_component, "UID", Some(&new_uid));
        duplicated = update_ical_property(&duplicated, "RECURRENCE-ID", None);

        let mutation_token = self.begin_calendar_mutation(None);
        let source_uid = event.source_uid.clone();
        let (sender, receiver) = async_channel::bounded(1);
        std::thread::spawn(move || {
            let result = ECalService::new().create_component(
                &source_uid,
                ECalComponentType::Event,
                &duplicated,
            );
            if let Err(error) = sender.send_blocking(result) {
                tracing::debug!(%error, "Event duplicate result was dropped");
            }
        });

        let page_weak = self.downgrade();
        glib::spawn_future_local(async move {
            let result = receiver.recv().await;
            let Some(page) = page_weak.upgrade() else {
                return;
            };
            page.finish_calendar_mutation(&mutation_token);
            match result {
                Ok(Ok(_)) => {
                    page.reload_calendar_data();
                    show_toast_for_widget(&page, &gettext("Appointment duplicated"));
                }
                Ok(Err(error)) => {
                    show_toast_for_widget(
                        &page,
                        &format!("{}: {error}", gettext("Failed to duplicate appointment")),
                    );
                }
                Err(error) => {
                    show_toast_for_widget(
                        &page,
                        &format!("{}: {error}", gettext("Failed to confirm event duplication")),
                    );
                }
            }
        });
    }

