pub(crate) enum MonthCanvasHit {
    Header { col: usize },
    KwHeader,
    KwRow { row: usize },
    Event {
        event: CalendarEventRecord,
        date: NaiveDate,
        occurrence_date: NaiveDate,
    },
    Overflow { date: NaiveDate },
    DayCell { date: NaiveDate },
}

pub(crate) fn prepare_month_layout(
    viewport: &CalendarViewport,
    events_by_date: &BTreeMap<NaiveDate, Vec<CalendarEventRecord>>,
    today: NaiveDate,
    show_week_numbers: bool,
    workdays: &HashSet<Weekday>,
    compress_weekend: bool,
    weekday_names_full: &[&str],
    weekday_names_short: &[&str],
    is_dark: bool,
    max_events_per_cell: usize,
) -> PreparedMonthLayout {
    prepare_month_layout_with_cache(
        viewport,
        events_by_date,
        today,
        show_week_numbers,
        workdays,
        compress_weekend,
        weekday_names_full,
        weekday_names_short,
        is_dark,
        max_events_per_cell,
        None,
    )
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn prepare_month_layout_with_cache(
    viewport: &CalendarViewport,
    events_by_date: &BTreeMap<NaiveDate, Vec<CalendarEventRecord>>,
    today: NaiveDate,
    show_week_numbers: bool,
    workdays: &HashSet<Weekday>,
    compress_weekend: bool,
    weekday_names_full: &[&str],
    weekday_names_short: &[&str],
    is_dark: bool,
    max_events_per_cell: usize,
    prev_weeks: Option<&[PreparedMonthWeek]>,
) -> PreparedMonthLayout {
    let anchor_date = viewport.anchor_date;
    let year = anchor_date.year();
    let month = anchor_date.month();
    let visible_dates: Vec<NaiveDate> = viewport.visible_range.dates().collect();

    let num_weeks = (visible_dates.len() / 7).max(1);
    let mut weeks = Vec::with_capacity(num_weeks);

    for week_idx in 0..num_weeks {
        if (week_idx + 1) * 7 > visible_dates.len() {
            break;
        }
        let week_slice = &visible_dates[week_idx * 7..(week_idx + 1) * 7];
        let mut week_dates = [anchor_date; 7];
        week_dates.copy_from_slice(week_slice);

        if let Some(cached) = prev_weeks.and_then(|pw| pw.iter().find(|w| w.week_dates == week_dates)) {
            weeks.push(cached.clone());
            continue;
        }

        let week_number = week_dates[0].iso_week().week();

        let layouts = compute_week_cell_layouts(&week_dates, events_by_date, max_events_per_cell);

        let mut event_bars = Vec::new();
        // Extract continuous event bars across track matrix
        for t in 0..max_events_per_cell {
            let mut col = 0;
            while col < 7 {
                if let Some(MonthCellTrackItem::Event { event, span, occurrence_date, .. }) = layouts[col].visible_items.get(t) {
                    let ev_uid = event.uid.clone();
                    let ev_start = event.start.clone();
                    let occ_date = *occurrence_date;
                    let mut end_col = col;
                    while end_col + 1 < 7 {
                        if let Some(MonthCellTrackItem::Event { event: next_ev, occurrence_date: next_occ, .. }) = layouts[end_col + 1].visible_items.get(t) {
                            if next_ev.uid == ev_uid && next_ev.start == ev_start && *next_occ == occ_date {
                                end_col += 1;
                                continue;
                            }
                        }
                        break;
                    }

                    let is_multi_day_display = event_display_range(event).is_some_and(|r| r.len_days() > 1);
                    let event_range = if is_multi_day_display {
                        event_occurrence_range_for_date(event, week_dates[col])
                    } else {
                        None
                    };
                    let cont_left = col == 0
                        && (*span == MonthBarSpan::Middle
                            || *span == MonthBarSpan::End
                            || event_range.as_ref().map(|r| r.start < week_dates[0]).unwrap_or(false));
                    let cont_right = end_col == 6
                        && event_range
                            .as_ref()
                            .map(|r| r.last_inclusive() > week_dates[6])
                            .unwrap_or(false);

                    let color_hex = event_color_for_record(event);
                    let (bg_hex, hov_hex, _, fg_hex) = pastel_colors_for_hex(&color_hex, is_dark);

                    let time_str = if !event.all_day {
                        if let Some(s) = quick_time_str(&event.start) {
                            Some(s)
                        } else {
                            let (start_min, _, _) = event_occurrence_times_for_date(event, week_dates[col], 30);
                            Some(format_clock_minutes(start_min))
                        }
                    } else {
                        None
                    };

                    event_bars.push(PreparedMonthEventBar {
                        event: event.clone(),
                        track: t,
                        start_col: col,
                        end_col,
                        continues_left: cont_left,
                        continues_right: cont_right,
                        all_day: event.all_day || is_multi_day_display,
                        time_str,
                        bg_hex,
                        hov_hex,
                        fg_hex,
                        color_hex,
                        occurrence_date: occ_date,
                    });

                    col = end_col + 1;
                } else {
                    col += 1;
                }
            }
        }

        let mut overflow_by_col: [Vec<CalendarEventRecord>; 7] = Default::default();
        for (c, l) in layouts.iter().enumerate().take(7) {
            overflow_by_col[c] = l.overflow_events.clone();
        }

        weeks.push(PreparedMonthWeek {
            week_dates,
            week_number,
            event_bars,
            overflow_by_col,
        });
    }

    PreparedMonthLayout {
        anchor_date,
        year,
        month,
        visible_dates,
        today,
        show_week_numbers,
        workdays: workdays.clone(),
        compress_weekend,
        dim_past_events: configured_dim_past_events(),
        weeks,
        weekday_names_full: weekday_names_full.iter().map(|s| s.to_string()).collect(),
        weekday_names_short: weekday_names_short.iter().map(|s| s.to_string()).collect(),
    }
}

pub(crate) fn month_layout_metrics(row_h: f64, chip_scale: f64) -> (f64, f64, f64, usize) {
    let scale = chip_scale.clamp(0.75, 1.50);
    let target_chip_h = (22.0 * scale).round();
    let chip_gap = (2.0 * scale).round().max(1.0);
    let target_step = target_chip_h + chip_gap;
    let pad_base = 3.0;

    let usable = (row_h - 2.0 * pad_base).max(20.0);
    let total_lines = (((usable + chip_gap) / target_step).floor() as usize).max(2);
    let max_tracks = total_lines.saturating_sub(1);

    let total_gaps = max_tracks as f64 * chip_gap;
    let avail = (row_h - 2.0 * pad_base - total_gaps).max(total_lines as f64 * 12.0);
    let line_h = (avail / total_lines as f64).floor();
    let chip_h = line_h;
    let chip_step = chip_h + chip_gap;
    let day_header_h = pad_base + line_h + chip_gap;

    (day_header_h, chip_h, chip_step, max_tracks)
}

pub(crate) fn month_canvas_date_and_rect_at_point(
    x: f64,
    y: f64,
    width: f64,
    height: f64,
    layout: &PreparedMonthLayout,
) -> Option<(NaiveDate, gdk::Rectangle)> {
    let header_h = 28.0;
    let kw_w = if layout.show_week_numbers { 36.0 } else { 0.0 };
    let grid_w = (width - kw_w).max(1.0);
    let grid_h = (height - header_h).max(1.0);
    let num_rows = (layout.visible_dates.len() / 7).max(1);
    let max_row = num_rows.saturating_sub(1);
    let col_w = grid_w / 7.0;
    let row_h = grid_h / (num_rows as f64);

    let row = (((y - header_h).max(0.0) / row_h).floor() as usize).min(max_row);
    let col = (((x - kw_w).max(0.0) / col_w).floor() as usize).min(6);
    let date_idx = row * 7 + col;
    let date = *layout.visible_dates.get(date_idx)?;
    let rect = gdk::Rectangle::new(
        (kw_w + col as f64 * col_w).round() as i32,
        (header_h + row as f64 * row_h).round() as i32,
        col_w.round().max(16.0) as i32,
        row_h.round().max(16.0) as i32,
    );
    Some((date, rect))
}

pub(crate) fn month_canvas_rect_for_date(
    date: NaiveDate,
    width: f64,
    height: f64,
    layout: &PreparedMonthLayout,
) -> Option<gdk::Rectangle> {
    let date_idx = layout.visible_dates.iter().position(|&d| d == date)?;
    let header_h = 28.0;
    let kw_w = if layout.show_week_numbers { 36.0 } else { 0.0 };
    let grid_w = (width - kw_w).max(1.0);
    let grid_h = (height - header_h).max(1.0);
    let num_rows = (layout.visible_dates.len() / 7).max(1);
    let col_w = grid_w / 7.0;
    let row_h = grid_h / (num_rows as f64);
    let row = date_idx / 7;
    let col = date_idx % 7;
    Some(gdk::Rectangle::new(
        (kw_w + col as f64 * col_w).round() as i32,
        (header_h + row as f64 * row_h).round() as i32,
        col_w.round().max(16.0) as i32,
        row_h.round().max(16.0) as i32,
    ))
}

pub(crate) fn hit_test_month_canvas(
    x: f64,
    y: f64,
    width: f64,
    height: f64,
    layout: &PreparedMonthLayout,
) -> Option<MonthCanvasHit> {
    let header_h = 28.0;
    let kw_w = if layout.show_week_numbers { 36.0 } else { 0.0 };
    let grid_w = (width - kw_w).max(1.0);
    let grid_h = (height - header_h).max(1.0);
    let num_rows = (layout.visible_dates.len() / 7).max(1) as f64;
    let max_row = (num_rows as usize).saturating_sub(1);
    let col_w = grid_w / 7.0;
    let row_h = grid_h / num_rows;
    let chip_scale = configured_chip_scale();
    let (day_header_h, chip_h, chip_step, max_tracks) = month_layout_metrics(row_h, chip_scale);

    if y < header_h {
        if layout.show_week_numbers && x < kw_w {
            return Some(MonthCanvasHit::KwHeader);
        }
        let col = (((x - kw_w).max(0.0) / col_w).floor() as usize).min(6);
        return Some(MonthCanvasHit::Header { col });
    }

    if layout.show_week_numbers && x < kw_w {
        let row = (((y - header_h).max(0.0) / row_h).floor() as usize).min(max_row);
        return Some(MonthCanvasHit::KwRow { row });
    }

    let row = (((y - header_h).max(0.0) / row_h).floor() as usize).min(max_row);
    let col = (((x - kw_w).max(0.0) / col_w).floor() as usize).min(6);
    let date_idx = row * 7 + col;
    if date_idx >= layout.visible_dates.len() {
        return None;
    }
    let date = layout.visible_dates[date_idx];
    let cell_y = header_h + row as f64 * row_h;

    if row < layout.weeks.len() {
        let week = &layout.weeks[row];

        let mut col_event_counts = [0usize; 7];
        for b in &week.event_bars {
            for c in b.start_col..=b.end_col {
                col_event_counts[c] += 1;
            }
        }
        for (c, of) in week.overflow_by_col.iter().enumerate() {
            col_event_counts[c] += of.len();
        }

        // Overflow hit test (only when events in this column exceed available tracks)
        if col_event_counts[col] > max_tracks {
            let of_x = kw_w + col as f64 * col_w + 3.0;
            let of_w = col_w - 6.0;
            let of_y = cell_y + day_header_h + (max_tracks.saturating_sub(1)) as f64 * chip_step;
            if x >= of_x && x <= of_x + of_w && y >= of_y && y <= of_y + chip_h {
                return Some(MonthCanvasHit::Overflow { date });
            }
        }

        // Event bar hit test
        for bar in &week.event_bars {
            let all_cols_have_overflow =
                (bar.start_col..=bar.end_col).all(|c| col_event_counts[c] > max_tracks);
            if all_cols_have_overflow && bar.track >= max_tracks.saturating_sub(1) {
                continue;
            }
            if bar.track >= max_tracks {
                continue;
            }
            let left_margin = if bar.continues_left { 0.0 } else { 3.0 };
            let right_margin = if bar.continues_right { 0.0 } else { 3.0 };
            let bar_x = kw_w + bar.start_col as f64 * col_w + left_margin;
            let bar_w = (bar.end_col - bar.start_col + 1) as f64 * col_w - left_margin - right_margin;
            let bar_y = cell_y + day_header_h + bar.track as f64 * chip_step;
            if x >= bar_x && x <= bar_x + bar_w && y >= bar_y && y <= bar_y + chip_h {
                return Some(MonthCanvasHit::Event {
                    event: bar.event.clone(),
                    date,
                    occurrence_date: bar.occurrence_date,
                });
            }
        }
    }

    Some(MonthCanvasHit::DayCell { date })
}

pub(crate) fn draw_month_event_bar(
    cr: &gtk::cairo::Context,
    x: f64,
    y: f64,
    w: f64,
    h: f64,
    radius: f64,
    continues_left: bool,
    continues_right: bool,
) {
    let r_left = if continues_left { 0.0 } else { radius.min(h / 2.0).min(w / 2.0) };
    let r_right = if continues_right { 0.0 } else { radius.min(h / 2.0).min(w / 2.0) };
    let degrees = std::f64::consts::PI / 180.0;
    cr.new_sub_path();

    cr.move_to(x + r_left, y);
    cr.line_to(x + w - r_right, y);
    if r_right > 0.0 {
        cr.arc(x + w - r_right, y + r_right, r_right, -90.0 * degrees, 0.0 * degrees);
        cr.arc(x + w - r_right, y + h - r_right, r_right, 0.0 * degrees, 90.0 * degrees);
    } else {
        cr.line_to(x + w, y);
        cr.line_to(x + w, y + h);
    }

    cr.line_to(x + r_left, y + h);
    if r_left > 0.0 {
        cr.arc(x + r_left, y + h - r_left, r_left, 90.0 * degrees, 180.0 * degrees);
        cr.arc(x + r_left, y + r_left, r_left, 180.0 * degrees, 270.0 * degrees);
    } else {
        cr.line_to(x, y + h);
        cr.line_to(x, y);
    }

    cr.close_path();
}

#[allow(clippy::too_many_arguments)]
fn draw_month_canvas_rows(
    cr: &gtk::cairo::Context,
    width: f64,
    height: f64,
    header_h: f64,
    chip_scale: f64,
    layout: &PreparedMonthLayout,
    selected_time_slot: Option<SelectedTimeSlot>,
    drag_selection: Option<MonthDragSelection>,
    hovered_target: Option<&MonthHoverTarget>,
    is_dark: bool,
    high_contrast: bool,
    font_scale: f64,
    row_range: std::ops::Range<usize>,
    offset_y: f64,
) {
    let kw_w = if layout.show_week_numbers { 36.0 } else { 0.0 };
    let grid_w = (width - kw_w).max(1.0);
    let grid_h = (height - header_h).max(1.0);
    let num_rows = (layout.visible_dates.len() / 7).max(1);
    let col_w = grid_w / 7.0;
    let row_h = grid_h / (num_rows as f64);
    let (day_header_h, chip_h, chip_step, max_tracks) = month_layout_metrics(row_h, chip_scale);
    let now_dt = Local::now().naive_local();

    let _ = cr.save();
    if offset_y != 0.0 {
        cr.translate(0.0, offset_y);
    }

    // 1. Cell backgrounds (connected selection fill across each week row)
    let active_sel: Option<(NaiveDate, NaiveDate, bool)> = if let Some(d) = drag_selection {
        let (s, e) = if d.start_date <= d.current_date {
            (d.start_date, d.current_date)
        } else {
            (d.current_date, d.start_date)
        };
        Some((s, e, true))
    } else if let Some(s) = selected_time_slot {
        let (s_d, e_d) = if s.date <= s.end_date {
            (s.date, s.end_date)
        } else {
            (s.end_date, s.date)
        };
        Some((s_d, e_d, false))
    } else {
        None
    };

    if let Some((sel_start, sel_end, is_drag)) = active_sel {
        let is_multi = sel_start < sel_end;
        if is_drag || is_multi {
            let fill_alpha = if is_drag { 0.20 } else { 0.14 };
            cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, fill_alpha);
            for row in row_range.clone() {
                if row >= num_rows {
                    continue;
                }
                let cell_y = header_h + row as f64 * row_h;
                let mut first_col: Option<usize> = None;
                let mut last_col: Option<usize> = None;
                for col in 0..7 {
                    let date_idx = row * 7 + col;
                    if let Some(&date) = layout.visible_dates.get(date_idx) {
                        if date >= sel_start && date <= sel_end {
                            if first_col.is_none() {
                                first_col = Some(col);
                            }
                            last_col = Some(col);
                        }
                    }
                }
                if let (Some(fc), Some(lc)) = (first_col, last_col) {
                    let sx = kw_w + fc as f64 * col_w;
                    let sw = (lc - fc + 1) as f64 * col_w;
                    cr.rectangle(sx, cell_y, sw, row_h);
                    let _ = cr.fill();
                }
            }
        }
    }

    // 2. Crisp Grid Lines for rows in row_range
    cr.set_line_width(if high_contrast { 1.5 } else { 1.0 });
    if high_contrast {
        if is_dark {
            cr.set_source_rgba(1.0, 1.0, 1.0, 0.65);
        } else {
            cr.set_source_rgba(0.0, 0.0, 0.0, 0.65);
        }
    } else if is_dark {
        cr.set_source_rgba(1.0, 1.0, 1.0, 0.14);
    } else {
        cr.set_source_rgba(0.0, 0.0, 0.0, 0.14);
    }

    for row in row_range.clone() {
        if row >= num_rows {
            continue;
        }
        let y_top = (header_h + row as f64 * row_h).round() + 0.5;
        let y_bot = (header_h + (row + 1) as f64 * row_h).round() + 0.5;

        // Bottom horizontal line of row
        cr.move_to(0.0, y_bot);
        cr.line_to(width, y_bot);
        let _ = cr.stroke();

        // Vertical lines for this row:
        if layout.show_week_numbers {
            let x_kw = kw_w.round() + 0.5;
            cr.move_to(x_kw, y_top);
            cr.line_to(x_kw, y_bot);
            let _ = cr.stroke();
        }

        for col in 1..7 {
            let x = (kw_w + col as f64 * col_w).round() + 0.5;
            cr.move_to(x, y_top);
            cr.line_to(x, y_bot);
            let _ = cr.stroke();
        }
    }

    // 2b. Month Separation Boundary Lines (crisp bold dark grey line on month transition)
    cr.set_line_width(2.0);
    if high_contrast {
        if is_dark {
            cr.set_source_rgba(1.0, 1.0, 1.0, 1.0);
        } else {
            cr.set_source_rgba(0.0, 0.0, 0.0, 1.0);
        }
    } else if is_dark {
        cr.set_source_rgba(1.0, 1.0, 1.0, 0.50);
    } else {
        cr.set_source_rgb(150.0 / 255.0, 150.0 / 255.0, 155.0 / 255.0);
    }

    for (date_idx, date) in layout.visible_dates.iter().enumerate() {
        if date.day() == 1 {
            let row = date_idx / 7;
            let col = date_idx % 7;
            if row_range.contains(&row) && row < num_rows {
                let y_top = (header_h + row as f64 * row_h).round();
                let x_left = (kw_w + col as f64 * col_w).round();
                let y_bot = (header_h + (row + 1) as f64 * row_h).round();

                cr.set_line_join(gtk::cairo::LineJoin::Miter);
                if col > 0 {
                    // Contiguous path: width at y_top -> (x_left, y_top) -> (x_left, y_bot) -> kw_w at y_bot
                    // Miter join cleanly connects the corner without missing pixels
                    cr.move_to(width, y_top);
                    cr.line_to(x_left, y_top);
                    cr.line_to(x_left, y_bot);
                    if (row + 1) < num_rows {
                        cr.line_to(kw_w, y_bot);
                    }
                    let _ = cr.stroke();
                } else {
                    cr.move_to(kw_w, y_top);
                    cr.line_to(width, y_top);
                    let _ = cr.stroke();
                }
            }
        }
    }

    // 2c. Connected outer selection frame per week row (no inner blue borders between selected days)
    if let Some((sel_start, sel_end, _)) = active_sel {
        cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 0.90);
        cr.set_line_width(1.75);
        for row in row_range.clone() {
            if row >= num_rows {
                continue;
            }
            let cell_y = header_h + row as f64 * row_h;
            let mut first_col: Option<usize> = None;
            let mut last_col: Option<usize> = None;
            for col in 0..7 {
                let date_idx = row * 7 + col;
                if let Some(&date) = layout.visible_dates.get(date_idx) {
                    if date >= sel_start && date <= sel_end {
                        if first_col.is_none() {
                            first_col = Some(col);
                        }
                        last_col = Some(col);
                    }
                }
            }
            if let (Some(fc), Some(lc)) = (first_col, last_col) {
                let sx = kw_w + fc as f64 * col_w;
                let sw = (lc - fc + 1) as f64 * col_w;
                cr.rectangle(sx + 1.0, cell_y + 1.0, (sw - 2.0).max(1.0), (row_h - 2.0).max(1.0));
                let _ = cr.stroke();
            }
        }
    }

    // 4. KW Column Numbers
    if layout.show_week_numbers {
        cr.set_font_size((11.0 * font_scale).round());
        cr.select_font_face(
            "sans-serif",
            gtk::cairo::FontSlant::Normal,
            gtk::cairo::FontWeight::Normal,
        );
        if is_dark {
            cr.set_source_rgba(1.0, 1.0, 1.0, 0.45);
        } else {
            cr.set_source_rgba(0.0, 0.0, 0.0, 0.45);
        }
        for row in row_range.clone() {
            if let Some(week) = layout.weeks.get(row) {
                let week_num_str = format!("{:02}", week.week_number);
                let cy = header_h + row as f64 * row_h;
                if let Ok(ext) = cr.text_extents(&week_num_str) {
                    let tx = ((kw_w - ext.width()) / 2.0 - ext.x_bearing()).round();
                    let ty = (cy + 16.0 - ext.y_bearing()).round();
                    cr.move_to(tx, ty);
                    let _ = cr.show_text(&week_num_str);
                }
            }
        }
    }

    // 5. Day Numbers & Month Badges (GNOME Calendar parity)
    for row in row_range.clone() {
        if row >= num_rows {
            continue;
        }
        let cell_y = header_h + row as f64 * row_h;
        for col in 0..7 {
            let date_idx = row * 7 + col;
            if date_idx >= layout.visible_dates.len() {
                continue;
            }
            let cell_x = kw_w + col as f64 * col_w;
            let date = layout.visible_dates[date_idx];
            let outside_month = date.year() != layout.year || date.month() != layout.month;
            let is_today = date == layout.today;
            let day_str = date.day().to_string();

            let pad_top = (day_header_h - chip_step).max(0.0);
            let header_top = cell_y + pad_top;
            let row_header_h = chip_h;

            if date.day() == 1 {
                let month_name = CalendarPage::month_name(date.month());
                let num_font_size = (chip_h * 0.52 * font_scale).round().clamp(10.0, 22.0);
                cr.set_font_size(num_font_size);
                cr.select_font_face(
                    "sans-serif",
                    gtk::cairo::FontSlant::Normal,
                    gtk::cairo::FontWeight::Bold,
                );
                if let Ok(ext) = cr.text_extents(&month_name) {
                    let badge_h = (chip_h * 0.82).round().clamp(14.0, (row_header_h - 2.0).max(14.0));
                    let badge_w = ext.width() + (12.0 * font_scale).round();
                    let badge_x = cell_x + 6.0;
                    let badge_y = (header_top + (row_header_h - badge_h) / 2.0).round();
                    let radius = 5.0 * font_scale;
                    draw_cairo_rounded_rect(cr, badge_x, badge_y, badge_w, badge_h, radius);

                    if is_today {
                        cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
                    } else if high_contrast {
                        if is_dark {
                            cr.set_source_rgba(1.0, 1.0, 1.0, 0.90);
                        } else {
                            cr.set_source_rgba(0.0, 0.0, 0.0, 0.90);
                        }
                    } else if is_dark {
                        cr.set_source_rgba(224.0 / 255.0, 224.0 / 255.0, 224.0 / 255.0, 1.0);
                    } else {
                        cr.set_source_rgba(80.0 / 255.0, 78.0 / 255.0, 85.0 / 255.0, 1.0);
                    }
                    let _ = cr.fill();

                    if is_today {
                        cr.set_source_rgba(1.0, 1.0, 1.0, 1.0);
                    } else if high_contrast {
                        if is_dark {
                            cr.set_source_rgba(0.0, 0.0, 0.0, 1.0);
                        } else {
                            cr.set_source_rgba(1.0, 1.0, 1.0, 1.0);
                        }
                    } else if is_dark {
                        cr.set_source_rgba(30.0 / 255.0, 30.0 / 255.0, 30.0 / 255.0, 1.0);
                    } else {
                        cr.set_source_rgba(1.0, 1.0, 1.0, 1.0);
                    }

                    let tx = (badge_x + (badge_w - ext.width()) / 2.0 - ext.x_bearing()).round();
                    let ty = (badge_y + (badge_h - ext.height()) / 2.0 - ext.y_bearing()).round();
                    cr.move_to(tx, ty);
                    let _ = cr.show_text(&month_name);
                }
            } else if is_today {
                let num_font_size = (chip_h * 0.55 * font_scale).round().clamp(11.0, 22.0);
                cr.set_font_size(num_font_size);
                cr.select_font_face(
                    "sans-serif",
                    gtk::cairo::FontSlant::Normal,
                    gtk::cairo::FontWeight::Bold,
                );
                if let Ok(ext) = cr.text_extents(&day_str) {
                    let badge_h = (chip_h * 0.82).round().clamp(14.0, (row_header_h - 2.0).max(14.0));
                    let badge_w = (ext.width() + 8.0 * font_scale).round().max(badge_h);
                    let badge_x = cell_x + 5.0;
                    let badge_y = (header_top + (row_header_h - badge_h) / 2.0).round();
                    let radius = badge_h / 2.0;
                    draw_cairo_rounded_rect(cr, badge_x, badge_y, badge_w, badge_h, radius);
                    cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
                    let _ = cr.fill();

                    cr.set_source_rgba(1.0, 1.0, 1.0, 1.0);
                    let tx = (badge_x + (badge_w - ext.width()) / 2.0 - ext.x_bearing()).round();
                    let ty = (badge_y + (badge_h - ext.height()) / 2.0 - ext.y_bearing()).round();
                    cr.move_to(tx, ty);
                    let _ = cr.show_text(&day_str);
                }
            } else {
                let num_font_size = (chip_h * if outside_month { 0.55 } else { 0.60 } * font_scale).round().clamp(11.0, 22.0);
                cr.set_font_size(num_font_size);
                if outside_month {
                    if is_dark {
                        cr.set_source_rgba(1.0, 1.0, 1.0, 0.38);
                    } else {
                        cr.set_source_rgba(46.0 / 255.0, 52.0 / 255.0, 54.0 / 255.0, 0.38);
                    }
                    cr.select_font_face(
                        "sans-serif",
                        gtk::cairo::FontSlant::Normal,
                        gtk::cairo::FontWeight::Normal,
                    );
                } else {
                    if is_dark {
                        cr.set_source_rgba(1.0, 1.0, 1.0, 0.92);
                    } else {
                        cr.set_source_rgba(46.0 / 255.0, 52.0 / 255.0, 54.0 / 255.0, 0.92);
                    }
                    cr.select_font_face(
                        "sans-serif",
                        gtk::cairo::FontSlant::Normal,
                        gtk::cairo::FontWeight::Bold,
                    );
                }
                if let Ok(ext) = cr.text_extents(&day_str) {
                    let tx = (cell_x + 16.0 * font_scale - ext.width() / 2.0 - ext.x_bearing()).round();
                    let ty = (header_top + (row_header_h - ext.height()) / 2.0 - ext.y_bearing()).round();
                    cr.move_to(tx, ty);
                    let _ = cr.show_text(&day_str);
                }
            }
        }
    }

    // 6. Event Bars & Chips (GNOME Calendar parity)
    for row in row_range.clone() {
        let Some(week) = layout.weeks.get(row) else { continue };
        let cell_y = header_h + row as f64 * row_h;

        let mut col_event_counts = [0usize; 7];
        for b in &week.event_bars {
            for c in b.start_col..=b.end_col {
                col_event_counts[c] += 1;
            }
        }
        for (c, of) in week.overflow_by_col.iter().enumerate() {
            col_event_counts[c] += of.len();
        }

        for bar in &week.event_bars {
            let all_cols_have_overflow =
                (bar.start_col..=bar.end_col).all(|c| col_event_counts[c] > max_tracks);
            if all_cols_have_overflow && bar.track >= max_tracks.saturating_sub(1) {
                continue;
            }
            if bar.track >= max_tracks {
                continue;
            }

            let left_margin = if bar.continues_left { 0.0 } else { 3.0 };
            let right_margin = if bar.continues_right { 0.0 } else { 3.0 };
            let bar_x = kw_w + bar.start_col as f64 * col_w + left_margin;
            let bar_w = (bar.end_col - bar.start_col + 1) as f64 * col_w - left_margin - right_margin;
            let bar_y = cell_y + day_header_h + bar.track as f64 * chip_step;

            let (col_r, col_g, col_b) =
                parse_hex_color(&bar.color_hex).unwrap_or((53, 132, 228));
            let (bg_r, bg_g, bg_b) =
                parse_hex_color(&bar.bg_hex).unwrap_or(if is_dark { (40, 60, 84) } else { (205, 224, 248) });

            let is_past = layout.dim_past_events && !bar.all_day && is_month_bar_past(bar, layout.today, now_dt);
            let alpha = if is_past { 0.55 } else { 1.0 };

            if bar.all_day {
                // Multi-day / all-day event chip with optional continuation
                draw_month_event_bar(
                    cr,
                    bar_x,
                    bar_y,
                    bar_w,
                    chip_h,
                    6.0,
                    bar.continues_left,
                    bar.continues_right,
                );
                cr.set_source_rgba(
                    bg_r as f64 / 255.0,
                    bg_g as f64 / 255.0,
                    bg_b as f64 / 255.0,
                    alpha,
                );
                let _ = cr.fill();

                let stripe_w = (6.0 * chip_scale).max(4.0).round();

                // Solid left accent stripe (if not continuing from previous week)
                if !bar.continues_left {
                    let _ = cr.save();
                    draw_month_event_bar(
                        cr,
                        bar_x,
                        bar_y,
                        bar_w,
                        chip_h,
                        6.0,
                        bar.continues_left,
                        bar.continues_right,
                    );
                    let _ = cr.clip();
                    cr.rectangle(bar_x, bar_y, stripe_w, chip_h);
                    cr.set_source_rgba(
                        col_r as f64 / 255.0,
                        col_g as f64 / 255.0,
                        col_b as f64 / 255.0,
                        alpha,
                    );
                    let _ = cr.fill();
                    let _ = cr.restore();
                }

                let (txt_r, txt_g, txt_b) =
                    parse_hex_color(&bar.fg_hex).unwrap_or(if is_dark { (255, 255, 255) } else { (46, 52, 54) });

                let text_pad_left = if bar.continues_left { (6.0 * chip_scale).round() } else { (stripe_w + (5.0 * chip_scale).round()).round() };
                let text_pad_right = (6.0 * chip_scale).round();
                let text_x = (bar_x + text_pad_left).round();
                let max_text_w = (bar_w - text_pad_left - text_pad_right).max(0.0);

                let _ = cr.save();
                cr.rectangle(text_x, bar_y, max_text_w, chip_h);
                let _ = cr.clip();

                cr.set_source_rgba(
                    txt_r as f64 / 255.0,
                    txt_g as f64 / 255.0,
                    txt_b as f64 / 255.0,
                    alpha,
                );
                cr.set_font_size((12.0 * font_scale * chip_scale).round());
                cr.select_font_face(
                    "Sans",
                    gtk::cairo::FontSlant::Normal,
                    gtk::cairo::FontWeight::Normal,
                );
                let trunc = truncate_cairo_text(cr, &bar.event.summary, max_text_w);
                if let Ok(ext) = cr.text_extents(&trunc) {
                    let ty = (bar_y + (chip_h - ext.height()) / 2.0 - ext.y_bearing()).round();
                    cr.move_to(text_x, ty);
                    let _ = cr.show_text(&trunc);
                }
                let _ = cr.restore();
            } else {
                // Timed / Single-day event chip (GNOME Calendar parity: chip with left stripe, title on left, time on right)
                draw_cairo_rounded_rect(cr, bar_x, bar_y, bar_w, chip_h, 6.0);
                cr.set_source_rgba(
                    bg_r as f64 / 255.0,
                    bg_g as f64 / 255.0,
                    bg_b as f64 / 255.0,
                    alpha,
                );
                let _ = cr.fill();

                let stripe_w = (6.0 * chip_scale).max(4.0).round();

                // Solid left accent stripe
                let _ = cr.save();
                draw_cairo_rounded_rect(cr, bar_x, bar_y, bar_w, chip_h, 6.0);
                let _ = cr.clip();
                cr.rectangle(bar_x, bar_y, stripe_w, chip_h);
                cr.set_source_rgba(
                    col_r as f64 / 255.0,
                    col_g as f64 / 255.0,
                    col_b as f64 / 255.0,
                    alpha,
                );
                let _ = cr.fill();
                let _ = cr.restore();

                let (txt_r, txt_g, txt_b) =
                    parse_hex_color(&bar.fg_hex).unwrap_or(if is_dark { (255, 255, 255) } else { (36, 41, 46) });

                // Right-aligned time string (if present)
                let mut time_width = 0.0;
                if let Some(ref t) = bar.time_str {
                    cr.set_font_size((10.5 * font_scale * chip_scale).round());
                    cr.select_font_face(
                        "Sans",
                        gtk::cairo::FontSlant::Normal,
                        gtk::cairo::FontWeight::Normal,
                    );
                    if let Ok(ext) = cr.text_extents(t) {
                        time_width = ext.width() + (6.0 * chip_scale).round();
                        let tx = (bar_x + bar_w - ext.width() - (5.0 * chip_scale).round() - ext.x_bearing()).round();
                        let ty = (bar_y + (chip_h - ext.height()) / 2.0 - ext.y_bearing()).round();
                        cr.set_source_rgba(
                            txt_r as f64 / 255.0,
                            txt_g as f64 / 255.0,
                            txt_b as f64 / 255.0,
                            0.80 * alpha,
                        );
                        cr.move_to(tx, ty);
                        let _ = cr.show_text(t);
                    }
                }

                // Left-aligned title string (crisp and pixel-aligned)
                let text_pad_left = (stripe_w + (5.0 * chip_scale).round()).round();
                let text_x = (bar_x + text_pad_left).round();
                let max_text_w = (bar_w - text_pad_left - time_width - (3.0 * chip_scale).round()).max(0.0);

                let _ = cr.save();
                cr.rectangle(text_x, bar_y, max_text_w, chip_h);
                let _ = cr.clip();

                cr.set_source_rgba(
                    txt_r as f64 / 255.0,
                    txt_g as f64 / 255.0,
                    txt_b as f64 / 255.0,
                    alpha,
                );
                cr.set_font_size((12.0 * font_scale * chip_scale).round());
                cr.select_font_face(
                    "Sans",
                    gtk::cairo::FontSlant::Normal,
                    gtk::cairo::FontWeight::Normal,
                );
                let trunc = truncate_cairo_text(cr, &bar.event.summary, max_text_w);
                if let Ok(ext) = cr.text_extents(&trunc) {
                    let ty = (bar_y + (chip_h - ext.height()) / 2.0 - ext.y_bearing()).round();
                    cr.move_to(text_x, ty);
                    let _ = cr.show_text(&trunc);
                }
                let _ = cr.restore();
            }
        }

        // 7. Overflow Indicators (only when column events exceed max_tracks)
        for col in 0..7 {
            let total = col_event_counts[col];
            if total > max_tracks {
                let shown_before = max_tracks.saturating_sub(1);
                let of_count = total.saturating_sub(shown_before);
                if of_count > 0 {
                    let cell_x = kw_w + col as f64 * col_w;
                    let of_x = cell_x + 3.0;
                    let of_w = col_w - 6.0;
                    let of_y = cell_y + day_header_h + shown_before as f64 * chip_step;
                    let of_h = chip_h;

                    let date_idx = row * 7 + col;
                    let is_hovered = layout.visible_dates.get(date_idx).map_or(false, |&d| {
                        matches!(hovered_target, Some(MonthHoverTarget::Overflow { date }) if *date == d)
                    });

                    // Transparent background by default; subtle highlight only when hovered
                    if is_hovered {
                        draw_cairo_rounded_rect(cr, of_x, of_y, of_w, of_h, 6.0);
                        if is_dark {
                            cr.set_source_rgba(1.0, 1.0, 1.0, 0.12);
                        } else {
                            cr.set_source_rgba(0.0, 0.0, 0.0, 0.06);
                        }
                        let _ = cr.fill();
                    }

                    let of_text = format!("+{}", of_count);
                    cr.set_font_size((11.0 * font_scale * chip_scale).round());
                    cr.select_font_face(
                        "Sans",
                        gtk::cairo::FontSlant::Normal,
                        if is_hovered {
                            gtk::cairo::FontWeight::Bold
                        } else {
                            gtk::cairo::FontWeight::Normal
                        },
                    );
                    if is_dark {
                        cr.set_source_rgba(1.0, 1.0, 1.0, if is_hovered { 0.95 } else { 0.65 });
                    } else {
                        cr.set_source_rgba(0.0, 0.0, 0.0, if is_hovered { 0.90 } else { 0.60 });
                    }
                    if let Ok(ext) = cr.text_extents(&of_text) {
                        let tx = (of_x + (8.0 * chip_scale).round() - ext.x_bearing()).round();
                        let ty = (of_y + (chip_h - ext.height()) / 2.0 - ext.y_bearing()).round();
                        cr.move_to(tx, ty);
                        let _ = cr.show_text(&of_text);
                    }
                }
            }
        }
    }

    let _ = cr.restore();
}

fn draw_month_header_row(
    cr: &gtk::cairo::Context,
    width: f64,
    header_h: f64,
    kw_w: f64,
    col_w: f64,
    layout: &PreparedMonthLayout,
    is_dark: bool,
    font_scale: f64,
) {
    if is_dark {
        cr.set_source_rgb(30.0 / 255.0, 30.0 / 255.0, 30.0 / 255.0);
    } else {
        cr.set_source_rgb(1.0, 1.0, 1.0);
    }
    cr.rectangle(0.0, 0.0, width, header_h);
    let _ = cr.fill();

    if is_dark {
        cr.set_source_rgba(1.0, 1.0, 1.0, 0.02);
    } else {
        cr.set_source_rgba(0.0, 0.0, 0.0, 0.015);
    }
    cr.rectangle(0.0, 0.0, width, header_h);
    let _ = cr.fill();

    if layout.show_week_numbers {
        if is_dark {
            cr.set_source_rgba(1.0, 1.0, 1.0, 0.50);
        } else {
            cr.set_source_rgba(0.0, 0.0, 0.0, 0.50);
        }
        cr.set_font_size((11.0 * font_scale).round());
        cr.select_font_face(
            "sans-serif",
            gtk::cairo::FontSlant::Normal,
            gtk::cairo::FontWeight::Bold,
        );
        if let Ok(ext) = cr.text_extents("KW") {
            let tx = ((kw_w - ext.width()) / 2.0 - ext.x_bearing()).round();
            let ty = ((header_h - ext.height()) / 2.0 - ext.y_bearing()).round();
            cr.move_to(tx, ty);
            let _ = cr.show_text("KW");
        }
    }

    cr.set_font_size((11.0 * font_scale).round());
    cr.select_font_face(
        "sans-serif",
        gtk::cairo::FontSlant::Normal,
        gtk::cairo::FontWeight::Bold,
    );
    for col in 0..7 {
        let raw_name = layout
            .weekday_names_short
            .get(col)
            .map(|s| s.as_str())
            .unwrap_or("");
        let name = raw_name.to_uppercase();
        let cx = kw_w + col as f64 * col_w;
        if is_dark {
            cr.set_source_rgba(1.0, 1.0, 1.0, 0.55);
        } else {
            cr.set_source_rgba(0.0, 0.0, 0.0, 0.50);
        }
        if let Ok(ext) = cr.text_extents(&name) {
            let tx = (cx + (col_w - ext.width()) / 2.0 - ext.x_bearing()).round();
            let ty = ((header_h - ext.height()) / 2.0 - ext.y_bearing()).round();
            cr.move_to(tx, ty);
            let _ = cr.show_text(&name);
        }
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn draw_month_canvas(
    cr: &gtk::cairo::Context,
    width: f64,
    height: f64,
    layout: &PreparedMonthLayout,
    selected_time_slot: Option<SelectedTimeSlot>,
    drag_selection: Option<MonthDragSelection>,
    hovered_target: Option<&MonthHoverTarget>,
    is_dark: bool,
    anim: Option<&MonthScrollAnimState>,
) {
    let font_scale = crate::views::accessibility::get_system_font_scale();
    let high_contrast = crate::views::accessibility::is_high_contrast_active();
    let header_h = 28.0;
    let kw_w = if layout.show_week_numbers { 36.0 } else { 0.0 };
    let grid_w = (width - kw_w).max(1.0);
    let grid_h = (height - header_h).max(1.0);
    let num_rows = (layout.visible_dates.len() / 7).max(1);
    let col_w = grid_w / 7.0;
    let row_h = grid_h / (num_rows as f64);
    let chip_scale = configured_chip_scale();

    if let Ok(mut font_options) = gtk::cairo::FontOptions::new() {
        font_options.set_antialias(gtk::cairo::Antialias::Subpixel);
        font_options.set_hint_style(gtk::cairo::HintStyle::Full);
        font_options.set_hint_metrics(gtk::cairo::HintMetrics::On);
        cr.set_font_options(&font_options);
    }

    // 0. Canvas background (pure white in light mode for maximum contrast)
    if is_dark {
        cr.set_source_rgb(30.0 / 255.0, 30.0 / 255.0, 30.0 / 255.0);
    } else {
        cr.set_source_rgb(1.0, 1.0, 1.0);
    }
    cr.rectangle(0.0, 0.0, width, height);
    let _ = cr.fill();

    // 1. Grid content clipped to grid area (below static header)
    let _ = cr.save();
    cr.rectangle(0.0, header_h, width, grid_h);
    let _ = cr.clip();

    if let Some(anim) = anim {
        let incoming_offset = anim.current_offset;
        let outgoing_offset = anim.current_offset - anim.start_offset;
        let outgoing_rows = anim.outgoing_layout.weeks.len();
        let step_count = (anim.start_offset.abs() / row_h).round().max(1.0) as usize;

        if anim.is_forward {
            // Forward (scrolled down into future):
            // Outgoing layout exits upward; draw its top rows [0..step_count] in the gap
            let out_end = step_count.min(outgoing_rows);
            draw_month_canvas_rows(
                cr,
                width,
                height,
                header_h,
                chip_scale,
                &anim.outgoing_layout,
                None,
                None,
                None,
                is_dark,
                high_contrast,
                font_scale,
                0..out_end,
                outgoing_offset,
            );
        } else {
            // Backward (scrolled up into past):
            // Outgoing layout exits downward; draw its bottom rows in the gap
            let out_start = outgoing_rows.saturating_sub(step_count);
            draw_month_canvas_rows(
                cr,
                width,
                height,
                header_h,
                chip_scale,
                &anim.outgoing_layout,
                None,
                None,
                None,
                is_dark,
                high_contrast,
                font_scale,
                out_start..outgoing_rows,
                outgoing_offset,
            );
        }

        // Draw all rows of the incoming layout
        draw_month_canvas_rows(
            cr,
            width,
            height,
            header_h,
            chip_scale,
            layout,
            selected_time_slot,
            drag_selection,
            hovered_target,
            is_dark,
            high_contrast,
            font_scale,
            0..num_rows,
            incoming_offset,
        );
    } else {
        // Static rendering (no animation)
        draw_month_canvas_rows(
            cr,
            width,
            height,
            header_h,
            chip_scale,
            layout,
            selected_time_slot,
            drag_selection,
            hovered_target,
            is_dark,
            high_contrast,
            font_scale,
            0..num_rows,
            0.0,
        );
    }
    let _ = cr.restore();

    // 2. Static Header Row on top
    draw_month_header_row(
        cr,
        width,
        header_h,
        kw_w,
        col_w,
        layout,
        is_dark,
        font_scale,
    );

    // 3. Crisp horizontal header divider line
    cr.set_line_width(if high_contrast { 1.5 } else { 1.0 });
    if high_contrast {
        if is_dark {
            cr.set_source_rgba(1.0, 1.0, 1.0, 0.65);
        } else {
            cr.set_source_rgba(0.0, 0.0, 0.0, 0.65);
        }
    } else if is_dark {
        cr.set_source_rgba(1.0, 1.0, 1.0, 0.14);
    } else {
        cr.set_source_rgba(0.0, 0.0, 0.0, 0.14);
    }
    let y_hdr = header_h.round() + 0.5;
    cr.move_to(0.0, y_hdr);
    cr.line_to(width, y_hdr);
    let _ = cr.stroke();
}

fn draw_cairo_rounded_rect(
    cr: &gtk::cairo::Context,
    x: f64,
    y: f64,
    width: f64,
    height: f64,
    radius: f64,
) {
    let r = radius.min(width / 2.0).min(height / 2.0);
    let degrees = std::f64::consts::PI / 180.0;
    cr.new_sub_path();
    cr.arc(x + width - r, y + r, r, -90.0 * degrees, 0.0 * degrees);
    cr.arc(x + width - r, y + height - r, r, 0.0 * degrees, 90.0 * degrees);
    cr.arc(x + r, y + height - r, r, 90.0 * degrees, 180.0 * degrees);
    cr.arc(x + r, y + r, r, 180.0 * degrees, 270.0 * degrees);
    cr.close_path();
}

fn truncate_cairo_text(cr: &gtk::cairo::Context, text: &str, max_width: f64) -> String {
    if text.is_empty() || max_width <= 0.0 {
        return String::new();
    }
    let total_w = match cr.text_extents(text) {
        Ok(ext) => {
            if ext.width() <= max_width {
                return text.to_string();
            }
            ext.width()
        }
        Err(_) => return text.to_string(),
    };

    let char_indices: Vec<usize> = text.char_indices().map(|(i, _)| i).collect();
    let num_chars = char_indices.len();
    if num_chars == 0 {
        return String::new();
    }

    // Estimate character fit from average character width
    let avg_char_w = (total_w / num_chars as f64).max(1.0);
    let est = (max_width / avg_char_w).round() as usize;

    // Narrow search window around estimate with safety clamping
    let mut low = est.saturating_sub(6);
    let mut high = (est + 6).min(num_chars);

    let mut test_str = String::with_capacity(text.len() + 4);

    // Expand search window if estimate was outside bounds
    if low > 0 {
        let byte_end = if low < num_chars { char_indices[low] } else { text.len() };
        test_str.clear();
        test_str.push_str(&text[..byte_end]);
        test_str.push('…');
        if let Ok(ext) = cr.text_extents(&test_str) {
            if ext.width() > max_width {
                low = 0;
            }
        } else {
            low = 0;
        }
    }
    if high < num_chars {
        let byte_end = char_indices[high];
        test_str.clear();
        test_str.push_str(&text[..byte_end]);
        test_str.push('…');
        if let Ok(ext) = cr.text_extents(&test_str) {
            if ext.width() <= max_width {
                high = num_chars;
            }
        }
    }

    let mut best = 0usize;
    while low <= high {
        let mid = (low + high) / 2;
        let byte_end = if mid < num_chars { char_indices[mid] } else { text.len() };
        test_str.clear();
        test_str.push_str(&text[..byte_end]);
        test_str.push('…');
        if let Ok(ext) = cr.text_extents(&test_str) {
            if ext.width() <= max_width {
                best = mid;
                low = mid + 1;
            } else {
                if mid == 0 {
                    break;
                }
                high = mid - 1;
            }
        } else {
            break;
        }
    }

    let byte_end = if best < num_chars { char_indices[best] } else { text.len() };
    let mut res = String::with_capacity(byte_end + 4);
    res.push_str(&text[..byte_end]);
    res.push('…');
    res
}

#[derive(Clone, Debug)]
pub(crate) struct PlacedTimeGridChip {
    pub(crate) event: CalendarEventRecord,
    pub(crate) start_slot: usize,
    pub(crate) row_span: usize,
    pub(crate) col_idx: usize,
    pub(crate) total_cols: usize,
    pub(crate) time_text: String,
}

#[derive(Clone, Debug)]
struct ResizeDragState {
    chip_idx: usize,
    event: CalendarEventRecord,
    start_slot: usize,
    initial_end_slot: usize,
    current_end_slot: usize,
}

fn compute_placed_timed_chips(
    day_events: &[CalendarEventRecord],
    day: NaiveDate,
    interval_minutes: u32,
    slot_count: usize,
) -> Vec<PlacedTimeGridChip> {
    let mut timed_events: Vec<CalendarEventRecord> = day_events
        .iter()
        .filter(|e| !e.all_day && event_display_range(e).map(|r| r.len_days() <= 1).unwrap_or(true))
        .cloned()
        .collect();
    timed_events.sort_by_key(|e| event_start_datetime(e));

    struct RawTimedEvent {
        event: CalendarEventRecord,
        start_slot: usize,
        end_slot: usize,
        row_span: usize,
        start_min: u32,
        time_text: String,
    }

    let mut raw_events = Vec::new();
    for event in timed_events {
        let (start_min, end_min, time_text) =
            event_occurrence_times_for_date(&event, day, interval_minutes);

        let start_slot = ((start_min / interval_minutes) as usize)
            .min(slot_count.saturating_sub(1));
        let end_slot = (((end_min + interval_minutes - 1) / interval_minutes) as usize)
            .max(start_slot + 1)
            .min(slot_count);
        let row_span = (end_slot - start_slot).max(1);

        raw_events.push(RawTimedEvent {
            event,
            start_slot,
            end_slot,
            row_span,
            start_min,
            time_text,
        });
    }

    raw_events.sort_by(|a, b| {
        a.start_min
            .cmp(&b.start_min)
            .then_with(|| a.end_slot.cmp(&b.end_slot))
            .then_with(|| a.event.summary.cmp(&b.event.summary))
    });

    let mut clusters: Vec<Vec<RawTimedEvent>> = Vec::new();
    let mut current_cluster: Vec<RawTimedEvent> = Vec::new();
    let mut cluster_end = 0;

    for item in raw_events {
        if current_cluster.is_empty() || item.start_slot < cluster_end {
            cluster_end = cluster_end.max(item.end_slot);
            current_cluster.push(item);
        } else {
            clusters.push(std::mem::take(&mut current_cluster));
            cluster_end = item.end_slot;
            current_cluster.push(item);
        }
    }
    if !current_cluster.is_empty() {
        clusters.push(current_cluster);
    }

    let mut placed_chips: Vec<PlacedTimeGridChip> = Vec::new();

    for cluster in clusters {
        let mut col_ends: Vec<usize> = Vec::new();
        let mut cluster_placed = Vec::new();

        for item in cluster {
            let mut col_idx = None;
            for (idx, end) in col_ends.iter_mut().enumerate() {
                if *end <= item.start_slot {
                    *end = item.end_slot;
                    col_idx = Some(idx);
                    break;
                }
            }
            let c = col_idx.unwrap_or_else(|| {
                let idx = col_ends.len();
                col_ends.push(item.end_slot);
                idx
            });
            cluster_placed.push((item.event, item.start_slot, item.row_span, c, item.time_text));
        }

        let total_cols = col_ends.len().max(1);

        for (event, start_slot, row_span, col_idx, time_text) in cluster_placed {
            placed_chips.push(PlacedTimeGridChip {
                event,
                start_slot,
                row_span,
                col_idx,
                total_cols,
                time_text,
            });
        }
    }

    placed_chips
}

fn chip_rect_coordinates(
    chip: &PlacedTimeGridChip,
    width: f64,
    slot_height: f64,
) -> (f64, f64, f64, f64) {
    let total_cols = chip.total_cols.max(1) as f64;
    let col_gap = 2.0;
    let margin_start = 2.0;
    let margin_end = 8.0;
    let available_w = (width - margin_start - margin_end - (total_cols - 1.0) * col_gap).max(20.0);
    let col_w = available_w / total_cols;
    let x = margin_start + chip.col_idx as f64 * (col_w + col_gap);
    let y = chip.start_slot as f64 * slot_height + 1.0;
    let w = col_w;
    let h = (chip.row_span as f64 * slot_height - 2.0).max(18.0);
    (x, y, w, h)
}

fn find_chip_at(
    chips: &[PlacedTimeGridChip],
    x: f64,
    y: f64,
    width: f64,
    slot_height: f64,
) -> Option<usize> {
    for (idx, chip) in chips.iter().enumerate().rev() {
        let (cx, cy, cw, ch) = chip_rect_coordinates(chip, width, slot_height);
        if x >= cx && x <= cx + cw && y >= cy && y <= cy + ch {
            return Some(idx);
        }
    }
    None
}

fn find_chip_bottom_edge_at(
    chips: &[PlacedTimeGridChip],
    x: f64,
    y: f64,
    width: f64,
    slot_height: f64,
) -> Option<usize> {
    for (idx, chip) in chips.iter().enumerate().rev() {
        if event_mutation_error(&chip.event).is_some() {
            continue;
        }
        let (cx, cy, cw, ch) = chip_rect_coordinates(chip, width, slot_height);
        if x >= cx && x <= cx + cw && y >= (cy + ch - 8.0) && y <= (cy + ch + 5.0) {
            return Some(idx);
        }
    }
    None
}

fn format_minute_of_day(minute: u32, use_12h: bool) -> String {
    if !use_12h && minute >= 24 * 60 {
        return "24:00".to_string();
    }
    let h = (minute / 60) % 24;
    let m = minute % 60;
    if use_12h {
        let (display_h, am_pm) = match h {
            0 => (12, "AM"),
            1..=11 => (h, "AM"),
            12 => (12, "PM"),
            _ => (h - 12, "PM"),
        };
        if m == 0 {
            format!("{display_h} {am_pm}")
        } else {
            format!("{display_h}:{m:02} {am_pm}")
        }
    } else {
        format!("{h:02}:{m:02}")
    }
}

fn draw_ghost_move_chip(
    cr: &gtk::cairo::Context,
    move_state: &MoveDragState,
    width: f64,
    slot_height: f64,
    interval_minutes: u32,
    is_dark: bool,
    use_12h: bool,
) {
    let font_scale = crate::views::accessibility::get_system_font_scale();
    let margin_start = 2.0;
    let margin_end = 8.0;
    let x = margin_start;
    let w = (width - margin_start - margin_end).max(20.0);
    let y = move_state.current_start_slot as f64 * slot_height + 1.0;
    let h = (move_state.row_span as f64 * slot_height - 2.0).max(18.0);
    let card_radius = 6.0;

    let color_hex = event_color_for_record(&move_state.event);
    let (bg_hex, _, _, fg_hex) = pastel_colors_for_hex(&color_hex, is_dark);
    let (bg_r, bg_g, bg_b) = parse_hex_color(&bg_hex).unwrap_or(if is_dark { (40, 60, 84) } else { (205, 224, 248) });
    let (stripe_r, stripe_g, stripe_b) = parse_hex_color(&color_hex).unwrap_or((53, 132, 228));
    let (fg_r, fg_g, fg_b) = parse_hex_color(&fg_hex).unwrap_or(if is_dark { (255, 255, 255) } else { (46, 52, 54) });

    // Subtle drop shadow for floating effect
    draw_cairo_rounded_rect(cr, x + 2.0, y + 2.0, w, h, card_radius);
    cr.set_source_rgba(0.0, 0.0, 0.0, if is_dark { 0.35 } else { 0.18 });
    let _ = cr.fill();

    // Background fill (elevated, slightly translucent)
    draw_cairo_rounded_rect(cr, x, y, w, h, card_radius);
    cr.set_source_rgba(bg_r as f64 / 255.0, bg_g as f64 / 255.0, bg_b as f64 / 255.0, 0.92);
    let _ = cr.fill();

    // Solid accent border to indicate active placement
    draw_cairo_rounded_rect(cr, x, y, w, h, card_radius);
    cr.set_source_rgba(stripe_r as f64 / 255.0, stripe_g as f64 / 255.0, stripe_b as f64 / 255.0, 0.90);
    cr.set_line_width(2.0);
    let _ = cr.stroke();

    // Left accent stripe
    let stripe_w = (5.0 * font_scale).clamp(4.0, 7.0).round();
    let _ = cr.save();
    draw_cairo_rounded_rect(cr, x, y, w, h, card_radius);
    let _ = cr.clip();
    cr.rectangle(x, y, stripe_w, h);
    cr.set_source_rgba(stripe_r as f64 / 255.0, stripe_g as f64 / 255.0, stripe_b as f64 / 255.0, 1.0);
    let _ = cr.fill();
    let _ = cr.restore();

    // Text: Snapped Time + Title
    let start_min = (move_state.current_start_slot as u32 * interval_minutes).min(1439);
    let end_min = ((move_state.current_start_slot + move_state.row_span) as u32 * interval_minutes).min(1440);
    let time_str = format!("{}–{}", format_minute_of_day(start_min, use_12h), format_minute_of_day(end_min, use_12h));

    let untitled = gettext("(Untitled)");
    let title = if move_state.event.summary.trim().is_empty() {
        untitled.as_str()
    } else {
        move_state.event.summary.as_str()
    };

    let text_x = x + stripe_w + (6.0 * font_scale).round();
    let max_text_w = (w - stripe_w - (10.0 * font_scale).round()).max(10.0);

    let _ = cr.save();
    draw_cairo_rounded_rect(cr, x, y, w, h, card_radius);
    let _ = cr.clip();

    cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
    cr.set_font_size((11.0 * font_scale).round());
    cr.set_source_rgba(fg_r as f64 / 255.0, fg_g as f64 / 255.0, fg_b as f64 / 255.0, 1.0);

    let trunc_title = truncate_cairo_text(cr, title, max_text_w);
    cr.move_to(text_x.round(), (y + 14.0 * font_scale).round());
    let _ = cr.show_text(&trunc_title);

    if h >= 32.0 {
        cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
        cr.set_font_size((10.0 * font_scale).round());
        cr.set_source_rgba(fg_r as f64 / 255.0, fg_g as f64 / 255.0, fg_b as f64 / 255.0, 0.85);
        let trunc_time = truncate_cairo_text(cr, &time_str, max_text_w);
        cr.move_to(text_x.round(), (y + 27.0 * font_scale).round());
        let _ = cr.show_text(&trunc_time);
    }

    let _ = cr.restore();
}

pub(crate) fn compute_current_time_line_y(height: f64, now_min: f64) -> f64 {
    let now_y = (now_min / 1440.0) * height;
    now_y.floor() + 1.0
}

fn draw_current_time_indicator_line(cr: &gtk::cairo::Context, width: f64, height: f64, now_min: f64) {
    let line_y = compute_current_time_line_y(height, now_min);
    let is_dark = adw::StyleManager::default().is_dark();
    let (r, g, b) = if is_dark {
        (255.0 / 255.0, 92.0 / 255.0, 92.0 / 255.0)
    } else {
        (230.0 / 255.0, 45.0 / 255.0, 66.0 / 255.0)
    };
    cr.set_source_rgba(r, g, b, 0.95);
    cr.set_line_width(2.0);
    cr.move_to(0.0, line_y);
    cr.line_to(width, line_y);
    let _ = cr.stroke();

    // Crisp leading indicator dot on the left edge when drawing inside a day column (width > 72px)
    if width > 72.0 {
        cr.arc(4.5, line_y, 4.0, 0.0, 2.0 * std::f64::consts::PI);
        cr.set_source_rgba(r, g, b, 1.0);
        let _ = cr.fill();
    }
}

fn draw_time_grid_chip_card(
    cr: &gtk::cairo::Context,
    chip: &PlacedTimeGridChip,
    width: f64,
    slot_height: f64,
    is_dark: bool,
    is_past: bool,
) {
    if is_past {
        cr.push_group();
    }

    let (x, y, w, h) = chip_rect_coordinates(chip, width, slot_height);
    let color_hex = event_color_for_record(&chip.event);
    let (bg_hex, _, _, _) = pastel_colors_for_hex(&color_hex, is_dark);

    let (bg_r, bg_g, bg_b) =
        parse_hex_color(&bg_hex).unwrap_or(if is_dark { (40, 60, 84) } else { (205, 224, 248) });
    let (stripe_r, stripe_g, stripe_b) =
        parse_hex_color(&color_hex).unwrap_or((53, 132, 228));

    let font_scale = crate::views::accessibility::get_system_font_scale();
    let card_radius = 6.0;
    let stripe_w = (5.0 * font_scale).clamp(4.0, 7.0).round();

    // 1. Soft pastel background (GNOME Calendar style)
    draw_cairo_rounded_rect(cr, x, y, w, h, card_radius);
    cr.set_source_rgba(
        bg_r as f64 / 255.0,
        bg_g as f64 / 255.0,
        bg_b as f64 / 255.0,
        1.0,
    );
    let _ = cr.fill();

    // 2. Solid color accent bar on the left edge (the signature GNOME Calendar left stripe)
    let _ = cr.save();
    draw_cairo_rounded_rect(cr, x, y, w, h, card_radius);
    let _ = cr.clip();
    cr.rectangle(x, y, stripe_w, h);
    cr.set_source_rgba(
        stripe_r as f64 / 255.0,
        stripe_g as f64 / 255.0,
        stripe_b as f64 / 255.0,
        1.0,
    );
    let _ = cr.fill();
    let _ = cr.restore();

    if is_past {
        let _ = cr.pop_group_to_source();
        let _ = cr.paint_with_alpha(0.55);
    }
}

fn draw_time_grid_chip_content(
    cr: &gtk::cairo::Context,
    chip: &PlacedTimeGridChip,
    width: f64,
    slot_height: f64,
    is_dark: bool,
    is_past: bool,
) {
    if is_past {
        cr.push_group();
    }

    let (x, y, w, h) = chip_rect_coordinates(chip, width, slot_height);
    let color_hex = event_color_for_record(&chip.event);
    let (_, _, _, fg_hex) = pastel_colors_for_hex(&color_hex, is_dark);
    let (fg_r, fg_g, fg_b) =
        parse_hex_color(&fg_hex).unwrap_or(if is_dark { (255, 255, 255) } else { (46, 52, 54) });

    let font_scale = crate::views::accessibility::get_system_font_scale();
    let card_radius = 6.0;
    let stripe_w = (5.0 * font_scale).clamp(4.0, 7.0).round();

    let untitled = gettext("(Untitled)");
    let title = if chip.event.summary.trim().is_empty() {
        untitled.as_str()
    } else {
        chip.event.summary.as_str()
    };

    let text_x = x + stripe_w + (6.0 * font_scale).round();
    let max_text_w = (w - stripe_w - (10.0 * font_scale).round()).max(10.0);

    let _ = cr.save();
    // Clip to chip interior
    draw_cairo_rounded_rect(cr, x, y, w, h, card_radius);
    let _ = cr.clip();

    let start_time = chip.time_text.split('–').next().unwrap_or(&chip.time_text).trim();

    if h >= 52.0 && !chip.event.location.trim().is_empty() {
        // 3-line layout when time grid is stretched: Time + Title (Bold) + Location
        cr.select_font_face(
            "Sans",
            gtk::cairo::FontSlant::Normal,
            gtk::cairo::FontWeight::Normal,
        );
        cr.set_font_size((10.0 * font_scale).round());
        cr.set_source_rgba(
            fg_r as f64 / 255.0,
            fg_g as f64 / 255.0,
            fg_b as f64 / 255.0,
            1.0,
        );
        let trunc_time = truncate_cairo_text(cr, &chip.time_text, max_text_w);
        cr.move_to(text_x.round(), (y + 13.0 * font_scale).round());
        let _ = cr.show_text(&trunc_time);

        cr.select_font_face(
            "Sans",
            gtk::cairo::FontSlant::Normal,
            gtk::cairo::FontWeight::Bold,
        );
        cr.set_font_size((11.5 * font_scale).round());
        cr.set_source_rgba(
            fg_r as f64 / 255.0,
            fg_g as f64 / 255.0,
            fg_b as f64 / 255.0,
            1.0,
        );
        let trunc_title = truncate_cairo_text(cr, title, max_text_w);
        cr.move_to(text_x.round(), (y + 27.0 * font_scale).round());
        let _ = cr.show_text(&trunc_title);

        cr.select_font_face(
            "Sans",
            gtk::cairo::FontSlant::Normal,
            gtk::cairo::FontWeight::Normal,
        );
        cr.set_font_size((9.5 * font_scale).round());
        cr.set_source_rgba(
            fg_r as f64 / 255.0,
            fg_g as f64 / 255.0,
            fg_b as f64 / 255.0,
            0.85,
        );
        let loc = chip.event.location.trim();
        let trunc_loc = truncate_cairo_text(cr, loc, max_text_w);
        cr.move_to(text_x.round(), (y + 40.0 * font_scale).round());
        let _ = cr.show_text(&trunc_loc);
    } else if h >= 28.0 {
        // Multi-line: Time on top, Title bold below
        cr.select_font_face(
            "Sans",
            gtk::cairo::FontSlant::Normal,
            gtk::cairo::FontWeight::Normal,
        );
        cr.set_font_size((10.0 * font_scale).round());
        cr.set_source_rgba(
            fg_r as f64 / 255.0,
            fg_g as f64 / 255.0,
            fg_b as f64 / 255.0,
            1.0,
        );
        let trunc_time = truncate_cairo_text(cr, start_time, max_text_w);
        cr.move_to(text_x.round(), (y + 13.0 * font_scale).round());
        let _ = cr.show_text(&trunc_time);

        cr.select_font_face(
            "Sans",
            gtk::cairo::FontSlant::Normal,
            gtk::cairo::FontWeight::Bold,
        );
        cr.set_font_size((11.5 * font_scale).round());
        cr.set_source_rgba(
            fg_r as f64 / 255.0,
            fg_g as f64 / 255.0,
            fg_b as f64 / 255.0,
            1.0,
        );
        let trunc_title = truncate_cairo_text(cr, title, max_text_w);
        cr.move_to(text_x.round(), (y + 27.0 * font_scale).round());
        let _ = cr.show_text(&trunc_title);
    } else {
        // Single-line for compact appointments: "08:00 Meeting..."
        let font_sz = ((h * 0.52).clamp(9.0, 11.5) * font_scale).round();
        cr.select_font_face(
            "Sans",
            gtk::cairo::FontSlant::Normal,
            gtk::cairo::FontWeight::Normal,
        );
        cr.set_font_size(font_sz);
        cr.set_source_rgba(
            fg_r as f64 / 255.0,
            fg_g as f64 / 255.0,
            fg_b as f64 / 255.0,
            1.0,
        );
        let single_line = format!("{} {}", start_time, title);
        let trunc = truncate_cairo_text(cr, &single_line, max_text_w);
        cr.move_to(text_x.round(), (y + (h / 2.0 + font_sz * 0.35)).round());
        let _ = cr.show_text(&trunc);
    }

    let _ = cr.restore();

    if is_past {
        let _ = cr.pop_group_to_source();
        let _ = cr.paint_with_alpha(0.55);
    }
}

pub(crate) fn build_prepared_agenda_items(
    events_by_date: &BTreeMap<NaiveDate, Vec<CalendarEventRecord>>,
    visible_range: CalendarDateRange,
    today: NaiveDate,
) -> Vec<PreparedAgendaItem> {
    let mut items = Vec::new();
    let mut current_y = 0.0;
    let header_height = 36.0;
    let row_height = 46.0;
    let is_12h = is_12h_clock();

    for date in visible_range.dates() {
        let Some(events) = events_by_date.get(&date) else {
            continue;
        };
        if events.is_empty() {
            continue;
        }
        let text = format_date(date);
        let is_today = date == today;
        items.push(PreparedAgendaItem::DateHeader {
            date,
            text,
            is_today,
            y: current_y,
            height: header_height,
        });
        current_y += header_height;

        let mut sorted_events: Vec<&CalendarEventRecord> = events.iter().collect();
        if sorted_events.len() > 1 {
            sorted_events.sort_by(|a, b| compare_day_events_order(a, b, date));
        }

        for event in sorted_events {
                let identity = CalendarEventIdentity::from_event(event);
                let time_str = event_time_text_for_date(event, date, is_12h);
                let title = if event.summary.trim().is_empty() {
                    gettext("(Untitled)")
                } else {
                    event.summary.trim().to_string()
                };
                let loc = event.location.trim();
                let sub = if !loc.is_empty() && !loc.eq_ignore_ascii_case(event.summary.trim()) {
                    loc.to_string()
                } else {
                    String::new()
                };
                let category = if event.component.contains("CATEGORIES") {
                    category_names_from_ical_component(&event.component)
                        .into_iter()
                        .next()
                } else {
                    None
                };
                let color_hex = event_color_for_record(&event);
                let color = if let Some((r, g, b)) = parse_hex_color(&color_hex) {
                    (r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0)
                } else {
                    (0.21, 0.52, 0.89)
                };

            items.push(PreparedAgendaItem::EventRow {
                date,
                record: event.clone(),
                identity,
                color,
                time_str,
                title,
                sub,
                category,
                y: current_y,
                height: row_height,
            });
            current_y += row_height;
        }
    }

    items
}

pub(crate) fn hit_test_agenda_canvas(items: &[PreparedAgendaItem], y: f64) -> Option<usize> {
    if items.is_empty() || y.is_nan() || y < 0.0 {
        return None;
    }
    let total_h = items.last().map(|it| it.y() + it.height()).unwrap_or(0.0);
    if y >= total_h {
        return None;
    }
    let idx = items.partition_point(|it| (it.y() + it.height()) <= y);
    if idx < items.len() && y >= items[idx].y() && y < items[idx].y() + items[idx].height() {
        Some(idx)
    } else {
        None
    }
}

pub(crate) fn find_sticky_header_info(
    items: &[PreparedAgendaItem],
    scroll_y: f64,
) -> Option<(usize, f64)> {
    if items.is_empty() || scroll_y <= 0.0 {
        return None;
    }
    let mut candidate_idx = None;
    for (idx, item) in items.iter().enumerate() {
        if let PreparedAgendaItem::DateHeader { y, .. } = item {
            if *y <= scroll_y {
                candidate_idx = Some(idx);
            } else {
                break;
            }
        }
    }

    let header_idx = candidate_idx?;
    let header_h = items[header_idx].height();

    let mut next_header_y = None;
    for item in &items[(header_idx + 1)..] {
        if let PreparedAgendaItem::DateHeader { y, .. } = item {
            next_header_y = Some(*y);
            break;
        }
    }

    let sticky_y = if let Some(next_y) = next_header_y {
        if next_y - scroll_y < header_h {
            next_y - header_h
        } else {
            scroll_y
        }
    } else {
        scroll_y
    };

    Some((header_idx, sticky_y))
}

pub(crate) fn hit_test_agenda_canvas_with_scroll(
    items: &[PreparedAgendaItem],
    logical_y: f64,
    scroll_y: f64,
) -> Option<usize> {
    if items.is_empty() || logical_y.is_nan() || logical_y < 0.0 {
        return None;
    }
    if let Some((sticky_idx, sticky_y)) = find_sticky_header_info(items, scroll_y) {
        if scroll_y > items[sticky_idx].y() {
            let sticky_h = items[sticky_idx].height();
            if logical_y >= sticky_y && logical_y < sticky_y + sticky_h {
                return Some(sticky_idx);
            }
        }
    }
    hit_test_agenda_canvas(items, logical_y)
}

fn draw_agenda_date_header(
    cr: &gtk::cairo::Context,
    text: &str,
    is_today: bool,
    row_y: f64,
    row_h: f64,
    width: f64,
    is_dark: bool,
    is_sticky: bool,
) {
    let fg = if is_dark { 1.0 } else { 0.0 };
    let primary_alpha = if is_dark { 0.95 } else { 0.90 };

    // 0. If sticky, draw an opaque background first so passing items behind it don't bleed through
    if is_sticky {
        cr.rectangle(0.0, row_y, width, row_h);
        if is_dark {
            cr.set_source_rgb(0.12, 0.12, 0.12);
        } else {
            cr.set_source_rgb(0.98, 0.98, 0.98);
        }
        let _ = cr.fill();
    }

    // 1. Background fill: Keep neutral for all headers (clean Libadwaita styling)
    cr.rectangle(0.0, row_y, width, row_h);
    let bg_alpha = if is_today {
        if is_dark { 0.05 } else { 0.035 }
    } else {
        if is_dark { 0.035 } else { 0.025 }
    };
    cr.set_source_rgba(fg, fg, fg, bg_alpha);
    let _ = cr.fill();

    // 2. Today badge & Date text (borderless modern Libadwaita header)
    let _ = cr.save();
    if is_today {
        // Modern Libadwaita "HEUTE" / "TODAY" pill badge right in front of the date
        let today_str = crate::i18n::gettext("Today");
        cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
        cr.set_font_size(11.0);
        let today_ext = cr.text_extents(&today_str).ok();
        let (tw, _th, txb, _tyb) = today_ext.map(|e| (e.width(), e.height(), e.x_bearing(), e.y_bearing())).unwrap_or((32.0, 9.0, 0.0, -8.0));
        let cap_ext = cr.text_extents("H").ok();
        let (cap_h, cap_yb) = cap_ext.map(|e| (e.height(), e.y_bearing())).unwrap_or((8.0, -8.0));
        let badge_h = 22.0;
        let badge_w = (tw + 18.0).max(52.0);
        let badge_x = 16.0;
        let badge_y = row_y + (row_h - badge_h) / 2.0;

        // Subtle accent capsule pill (clean tint, not aggressive solid block)
        draw_cairo_rounded_rect(cr, badge_x, badge_y, badge_w, badge_h, 9999.0);
        cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.22 } else { 0.16 });
        let _ = cr.fill();

        // Accent colored text inside badge (crisp, readable, elegant)
        cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
        let tx = badge_x + (badge_w - tw) / 2.0 - txb;
        let ty = badge_y + (badge_h - cap_h) / 2.0 - cap_yb;
        cr.move_to(tx, ty);
        let _ = cr.show_text(&today_str);

        // Date text follows badge in primary text color (calm and clean, NOT bright blue)
        let date_x = badge_x + badge_w + 10.0;
        let max_text_w = (width - date_x - 16.0).max(40.0);
        cr.rectangle(date_x, row_y, max_text_w, row_h);
        let _ = cr.clip();
        cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
        cr.set_font_size(14.0);
        cr.set_source_rgba(fg, fg, fg, primary_alpha);
        let trunc_text = truncate_cairo_text(cr, text, max_text_w);
        cr.move_to(date_x, row_y + 23.5);
        let _ = cr.show_text(&trunc_text);
    } else {
        // Regular day header
        let max_text_w = (width - 32.0).max(40.0);
        cr.rectangle(16.0, row_y, max_text_w, row_h);
        let _ = cr.clip();
        cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
        cr.set_font_size(14.0);
        cr.set_source_rgba(fg, fg, fg, primary_alpha);
        let trunc_text = truncate_cairo_text(cr, text, max_text_w);
        cr.move_to(16.0, row_y + 23.5);
        let _ = cr.show_text(&trunc_text);
    }
    let _ = cr.restore();

    // 3. Fine bottom separator / shadow line when sticky to delineate pinned header from passing rows
    if is_sticky {
        cr.set_source_rgba(fg, fg, fg, if is_dark { 0.16 } else { 0.08 });
        cr.set_line_width(1.0);
        cr.move_to(0.0, (row_y + row_h).round() - 0.5);
        cr.line_to(width, (row_y + row_h).round() - 0.5);
        let _ = cr.stroke();
    }
}

pub(crate) fn draw_agenda_canvas(
    cr: &gtk::cairo::Context,
    items: &[PreparedAgendaItem],
    width: f64,
    clip_y1: f64,
    clip_y2: f64,
    selected_idx: Option<usize>,
    hovered_idx: Option<usize>,
    is_dark: bool,
) {
    if items.is_empty() {
        return;
    }

    if let Ok(mut font_options) = gtk::cairo::FontOptions::new() {
        font_options.set_antialias(gtk::cairo::Antialias::Subpixel);
        font_options.set_hint_style(gtk::cairo::HintStyle::Full);
        font_options.set_hint_metrics(gtk::cairo::HintMetrics::On);
        cr.set_font_options(&font_options);
    }

    let start_idx = items.partition_point(|it| (it.y() + it.height()) < clip_y1);
    let end_idx = (items.partition_point(|it| it.y() <= clip_y2) + 1).min(items.len());
    let dim_past = configured_dim_past_events();
    let today = Local::now().date_naive();
    let now_dt = Local::now().naive_local();

    let fg = if is_dark { 1.0 } else { 0.0 };
    let primary_alpha = if is_dark { 0.95 } else { 0.90 };
    let secondary_alpha = if is_dark { 0.60 } else { 0.55 };

    let sticky_info = find_sticky_header_info(items, clip_y1);
    let active_sticky_idx = if let Some((idx, _)) = sticky_info {
        if clip_y1 > items[idx].y() {
            Some(idx)
        } else {
            None
        }
    } else {
        None
    };

    for idx in start_idx..end_idx {
        if Some(idx) == active_sticky_idx {
            continue;
        }
        match &items[idx] {
            PreparedAgendaItem::DateHeader { text, is_today, y, height, .. } => {
                draw_agenda_date_header(cr, text, *is_today, *y, *height, width, is_dark, false);
            }
            PreparedAgendaItem::EventRow {
                date,
                record,
                color,
                time_str,
                title,
                sub,
                category: _,
                y,
                height,
                ..
            } => {
                let row_y = *y;
                let row_h = *height;
                let is_selected = selected_idx == Some(idx);
                let is_hovered = hovered_idx == Some(idx);
                let is_running = is_event_running_now(record, *date);
                let is_past = dim_past && !is_selected && is_agenda_event_past(record, *date, today, now_dt);

                if is_past {
                    cr.push_group();
                }

                // 1. Background (Selection / Hover)
                if is_selected {
                    cr.rectangle(0.0, row_y, width, row_h);
                    cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, if is_dark { 0.22 } else { 0.13 });
                    let _ = cr.fill();
                } else if is_hovered {
                    cr.rectangle(0.0, row_y, width, row_h);
                    let hover_alpha = if is_dark { 0.05 } else { 0.04 };
                    cr.set_source_rgba(fg, fg, fg, hover_alpha);
                    let _ = cr.fill();
                }

                // 2. Left accent indicator bar in calendar color (widened to 5.5px)
                let (dr, dg, db) = *color;
                let bar_w = if is_running { 6.5 } else { 5.5 };
                cr.rectangle(0.0, row_y, bar_w, row_h);
                cr.set_source_rgb(dr, dg, db);
                let _ = cr.fill();

                // 3. Row separator (edge-to-edge from 0.0 to width, only between rows of the same day)
                let is_last_in_day = idx + 1 >= items.len() || matches!(&items[idx + 1], PreparedAgendaItem::DateHeader { .. });
                if !is_last_in_day {
                    let line_alpha = if is_dark { 0.07 } else { 0.05 };
                    cr.set_source_rgba(fg, fg, fg, line_alpha);
                    cr.set_line_width(1.0);
                    cr.move_to(0.0, (row_y + row_h).round() - 0.5);
                    cr.line_to(width, (row_y + row_h).round() - 0.5);
                    let _ = cr.stroke();
                }

                // 4. Time column (Uniform, calm regular font — no competing bold weights, zero offset)
                let time_x = 16.0;
                let time_w = 105.0;
                let all_day_label = crate::i18n::gettext("All Day");
                let is_all_day = time_str == &all_day_label || time_str.eq_ignore_ascii_case("all-day") || time_str.eq_ignore_ascii_case("ganztägig");

                let _ = cr.save();
                cr.rectangle(time_x, row_y, time_w, row_h);
                cr.clip();

                if is_all_day {
                    // Soft, elegant capsule pill for all-day events (centered, dynamic width, Libadwaita standard height)
                    cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
                    cr.set_font_size(11.5);
                    let ext = cr.text_extents(time_str).ok();
                    let (ew, _eh, exb, _eyb) = ext.map(|e| (e.width(), e.height(), e.x_bearing(), e.y_bearing())).unwrap_or((36.0, 9.0, 0.0, -8.0));
                    let cap_ext = cr.text_extents("H").ok();
                    let (cap_h, cap_yb) = cap_ext.map(|e| (e.height(), e.y_bearing())).unwrap_or((8.0, -8.0));
                    let pill_h = 24.0;
                    let pill_w = (ew + 20.0).clamp(56.0, time_w);
                    let pill_y = if sub.is_empty() { row_y + (row_h - pill_h) / 2.0 } else { row_y + 11.0 };
                    draw_cairo_rounded_rect(cr, time_x, pill_y, pill_w, pill_h, 9999.0);
                    cr.set_source_rgba(fg, fg, fg, if is_dark { 0.09 } else { 0.06 });
                    let _ = cr.fill();

                    cr.set_source_rgba(fg, fg, fg, if is_dark { 0.85 } else { 0.70 });
                    let trunc_all_day = truncate_cairo_text(cr, time_str, pill_w - 12.0);
                    let trunc_ext = cr.text_extents(&trunc_all_day).ok();
                    let (tew, _teh, texb, _teyb) = trunc_ext.map(|e| (e.width(), e.height(), e.x_bearing(), e.y_bearing())).unwrap_or((ew, 9.0, exb, -8.0));
                    let tx = time_x + (pill_w - tew) / 2.0 - texb;
                    let ty = pill_y + (pill_h - cap_h) / 2.0 - cap_yb;
                    cr.move_to(tx, ty);
                    let _ = cr.show_text(&trunc_all_day);
                } else {
                    // Timed event: Uniform, calm regular font
                    let time_y = if sub.is_empty() { row_y + 28.0 } else { row_y + 20.0 };
                    cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
                    cr.set_font_size(12.5);
                    cr.set_source_rgba(fg, fg, fg, if is_dark { 0.80 } else { 0.68 });
                    let max_text_w = if is_running { time_w - 18.0 } else { time_w };
                    let trunc_time = truncate_cairo_text(cr, time_str, max_text_w);
                    cr.move_to(time_x, time_y);
                    let _ = cr.show_text(&trunc_time);

                    // Live running indicator (clock icon placed neatly behind the time text)
                    if is_running {
                        let ext = cr.text_extents(&trunc_time).ok();
                        let text_advance = ext.map(|e| e.x_advance()).unwrap_or(60.0);
                        let icon_cx = (time_x + text_advance + 8.5).min(time_x + time_w - 6.0);
                        let icon_cy = if sub.is_empty() { row_y + 23.5 } else { row_y + 15.5 };
                        let radius = 5.0;

                        cr.new_sub_path();
                        cr.set_line_cap(gtk::cairo::LineCap::Round);
                        cr.set_line_width(1.2);
                        cr.set_source_rgba(53.0 / 255.0, 132.0 / 255.0, 228.0 / 255.0, 1.0);
                        cr.arc(icon_cx, icon_cy, radius, 0.0, 2.0 * std::f64::consts::PI);
                        let _ = cr.stroke();

                        // Hour hand (12:00)
                        cr.move_to(icon_cx, icon_cy);
                        cr.line_to(icon_cx, icon_cy - 2.8);
                        let _ = cr.stroke();

                        // Minute hand (2:15)
                        cr.move_to(icon_cx, icon_cy);
                        cr.line_to(icon_cx + 2.0, icon_cy + 0.6);
                        let _ = cr.stroke();
                    }
                }
                let _ = cr.restore();

                // 5. Summary & Subtitle (Clean 16px spacing after time column)
                let title_x = 16.0 + 105.0 + 16.0;
                let right_margin = 16.0;
                let max_title_w = (width - title_x - right_margin).max(40.0);

                let _ = cr.save();
                cr.rectangle(title_x, row_y, max_title_w, row_h);
                cr.clip();

                // Summary (GNOME HIG Body Text: 13.5px normal)
                cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
                cr.set_font_size(13.5);
                cr.set_source_rgba(fg, fg, fg, primary_alpha);
                let title_y = if sub.is_empty() { row_y + 28.0 } else { row_y + 20.0 };
                let trunc_title = truncate_cairo_text(cr, title, max_title_w);
                cr.move_to(title_x, title_y);
                let _ = cr.show_text(&trunc_title);

                // Subtitle (GNOME HIG Secondary Text: 12.0px normal)
                if !sub.is_empty() {
                    cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
                    cr.set_font_size(12.0);
                    cr.set_source_rgba(fg, fg, fg, secondary_alpha);
                    let trunc_sub = truncate_cairo_text(cr, sub, max_title_w);
                    cr.move_to(title_x, row_y + 36.5);
                    let _ = cr.show_text(&trunc_sub);
                }
                let _ = cr.restore();

                if is_past {
                    let _ = cr.pop_group_to_source();
                    let _ = cr.paint_with_alpha(0.55);
                }
            }
        }
    }

    // Paint sticky header on top so events cleanly slide behind it
    if let Some(s_idx) = active_sticky_idx {
        if let Some((_, sticky_y)) = sticky_info {
            if let PreparedAgendaItem::DateHeader { text, is_today, height, .. } = &items[s_idx] {
                draw_agenda_date_header(cr, text, *is_today, sticky_y, *height, width, is_dark, true);
            }
        }
    }
}

fn prepare_calendar_list_row(event: &CalendarEventRecord) -> PreparedCalendarListRow {
    let identity = CalendarEventIdentity::from_event(event);
    let date_str = if let Some(d) = event_start_date(event) {
        d.format("%a., %d.%m.%Y").to_string()
    } else if !event.start.is_empty() {
        event.start.split(' ').next().unwrap_or(&event.start).to_string()
    } else {
        String::new()
    };
    let time_str = if event.all_day {
        crate::i18n::gettext("All Day")
    } else if !event.end.is_empty() {
        let t1 = event.start.split(' ').nth(1).unwrap_or(&event.start);
        let t2 = event.end.split(' ').nth(1).unwrap_or(&event.end);
        format!("{t1} – {t2}")
    } else if !event.start.is_empty() {
        event.start.split(' ').nth(1).unwrap_or(&event.start).to_string()
    } else {
        "-".to_string()
    };
    let title = if event.summary.trim().is_empty() {
        crate::i18n::gettext("(Untitled)")
    } else {
        event.summary.trim().to_string()
    };
    let sub = if !event.location.trim().is_empty() && !event.source_display_name.is_empty() {
        format!("{} · {}", event.location.trim(), event.source_display_name)
    } else if !event.location.trim().is_empty() {
        event.location.trim().to_string()
    } else if !event.source_display_name.is_empty() {
        event.source_display_name.clone()
    } else {
        String::new()
    };
    let category = category_names_from_ical_component(&event.component)
        .into_iter()
        .next();
    let color_hex = event_color_for_record(event);
    let color = if let Some((r, g, b)) = parse_hex_color(&color_hex) {
        (r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0)
    } else {
        (0.21, 0.52, 0.89)
    };
    PreparedCalendarListRow {
        record: event.clone(),
        identity,
        date_str,
        time_str,
        title,
        sub,
        category,
        color,
    }
}

fn draw_prepared_calendar_list_row(
    cr: &gtk::cairo::Context,
    item: &PreparedCalendarListRow,
    row_y: f64,
    width: f64,
    row_height: f64,
    is_selected: bool,
    is_hovered: bool,
    is_dark: bool,
) {
    // 1. Background
    if is_selected {
        cr.rectangle(0.0, row_y, width, row_height);
        cr.set_source_rgba(0.21, 0.52, 0.89, if is_dark { 0.28 } else { 0.16 });
        let _ = cr.fill();

        // Left accent indicator bar
        cr.rectangle(0.0, row_y, 4.0, row_height);
        cr.set_source_rgba(0.21, 0.52, 0.89, 1.0);
        let _ = cr.fill();
    } else if is_hovered {
        cr.rectangle(0.0, row_y, width, row_height);
        let hover_alpha = if is_dark { 0.05 } else { 0.04 };
        let hover_col = if is_dark { 1.0 } else { 0.0 };
        cr.set_source_rgba(hover_col, hover_col, hover_col, hover_alpha);
        let _ = cr.fill();
    }

    // Bottom row separator line
    let line_alpha = if is_dark { 0.08 } else { 0.06 };
    let line_col = if is_dark { 1.0 } else { 0.0 };
    cr.set_source_rgba(line_col, line_col, line_col, line_alpha);
    cr.set_line_width(1.0);
    cr.move_to(0.0, (row_y + row_height).round() - 0.5);
    cr.line_to(width, (row_y + row_height).round() - 0.5);
    let _ = cr.stroke();

    // 2. Calendar source dot
    let dot_x = 18.0;
    let dot_y = row_y + row_height / 2.0;
    let (dr, dg, db) = item.color;
    cr.arc(dot_x, dot_y, 4.5, 0.0, 2.0 * std::f64::consts::PI);
    cr.set_source_rgb(dr, dg, db);
    let _ = cr.fill();

    // Text colors
    let fg = if is_dark { 1.0 } else { 0.0 };
    let primary_alpha = if is_dark { 0.95 } else { 0.90 };
    let secondary_alpha = if is_dark { 0.60 } else { 0.55 };

    // 3. Date & Time column
    let _ = cr.save();
    cr.rectangle(36.0, row_y, 135.0, row_height);
    cr.clip();
    cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
    cr.set_font_size(12.0);
    cr.set_source_rgba(fg, fg, fg, primary_alpha);
    cr.move_to(36.0, row_y + 19.0);
    let _ = cr.show_text(&item.date_str);

    // Time
    cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
    cr.set_font_size(11.0);
    cr.set_source_rgba(fg, fg, fg, secondary_alpha);
    cr.move_to(36.0, row_y + 35.0);
    let _ = cr.show_text(&item.time_str);
    let _ = cr.restore();

    // Subtle vertical column separator
    cr.set_source_rgba(line_col, line_col, line_col, line_alpha * 1.5);
    cr.move_to(175.5, row_y + 8.0);
    cr.line_to(175.5, row_y + row_height - 8.0);
    let _ = cr.stroke();

    // 4. Summary & Subtitle
    let title_x = 190.0;
    let right_margin = if width > 500.0 { 150.0 } else { 30.0 };
    let max_title_w = (width - title_x - right_margin).max(60.0);

    let _ = cr.save();
    cr.rectangle(title_x, row_y, max_title_w, row_height);
    cr.clip();
    // Summary
    cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
    cr.set_font_size(13.0);
    cr.set_source_rgba(fg, fg, fg, primary_alpha);
    cr.move_to(title_x, row_y + 19.0);
    let _ = cr.show_text(&item.title);

    // Subtitle (location & calendar)
    if !item.sub.is_empty() {
        cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Normal);
        cr.set_font_size(11.0);
        cr.set_source_rgba(fg, fg, fg, secondary_alpha);
        cr.move_to(title_x, row_y + 35.0);
        let _ = cr.show_text(&item.sub);
    }
    let _ = cr.restore();

    // 5. Category pill badge (on right side)
    if width > 460.0 {
        if let Some(cat) = &item.category {
            let cat_w = 90.0;
            let cat_x = width - cat_w - 20.0;
            let cat_y = row_y + 13.0;
            draw_cairo_rounded_rect(cr, cat_x, cat_y, cat_w, 20.0, 9999.0);
            cr.set_source_rgba(fg, fg, fg, if is_dark { 0.10 } else { 0.06 });
            let _ = cr.fill();

            let _ = cr.save();
            cr.rectangle(cat_x + 8.0, cat_y, cat_w - 16.0, 20.0);
            cr.clip();
            cr.select_font_face("Sans", gtk::cairo::FontSlant::Normal, gtk::cairo::FontWeight::Bold);
            cr.set_font_size(10.0);
            cr.set_source_rgba(fg, fg, fg, secondary_alpha);
            cr.move_to(cat_x + 8.0, cat_y + 14.0);
            let _ = cr.show_text(cat);
            let _ = cr.restore();
        }
    }
}

fn draw_calendar_list_row(
    cr: &gtk::cairo::Context,
    event: &CalendarEventRecord,
    row_y: f64,
    width: f64,
    row_height: f64,
    is_selected: bool,
    is_hovered: bool,
    is_dark: bool,
) {
    let item = prepare_calendar_list_row(event);
    draw_prepared_calendar_list_row(
        cr,
        &item,
        row_y,
        width,
        row_height,
        is_selected,
        is_hovered,
        is_dark,
    );
}

fn make_context_menu_button(
    _icon_name: &str,
    label_text: &str,
    destructive: bool,
) -> gtk::Button {
    crate::views::create_context_menu_button(None, label_text, destructive)
}

fn show_calendar_event_context_menu(
    page: &CalendarPage,
    anchor_widget: &impl glib::object::IsA<gtk::Widget>,
    event: &CalendarEventRecord,
    rect: gdk::Rectangle,
) {
    let anchor_widget = anchor_widget.as_ref();
    let action_state = calendar_event_action_state(event, CalendarStoreService::new().is_writable());
    let writable = action_state.can_edit;
    let recurring = action_state.recurring;

    let (popover, menu_box) = crate::views::create_context_popover(Some(&rect));

    // 1. Edit
    let edit = make_context_menu_button("document-edit-symbolic", &gettext("Edit Appointment"), false);
    edit.set_sensitive(writable);
    let popover_for_edit = popover.clone();
    let page_weak_edit = page.downgrade();
    let event_identity_for_edit = CalendarEventIdentity::from_event(event);
    let anchor_for_edit = anchor_widget.clone();
    edit.connect_clicked(move |_| {
        popover_for_edit.popdown();
        if let (Some(page), Some(identity)) = (page_weak_edit.upgrade(), event_identity_for_edit.as_ref()) {
            page.open_event_editor_for_identity(&anchor_for_edit, identity);
        }
    });
    menu_box.append(&edit);

    // 2. Copy
    let copy = make_context_menu_button("edit-copy-symbolic", &gettext("Copy to Local Calendar"), false);
    copy.set_sensitive(action_state.can_copy_to_local);
    let popover_for_copy = popover.clone();
    let page_weak_copy = page.downgrade();
    let event_for_copy = event.clone();
    let anchor_for_copy = anchor_widget.clone();
    copy.connect_clicked(move |_| {
        popover_for_copy.popdown();
        if let Some(page) = page_weak_copy.upgrade() {
            page.transfer_event_to_local(event_for_copy.clone(), CalendarTransferKind::Copy, &anchor_for_copy);
        }
    });
    menu_box.append(&copy);

    // 3. Move
    let move_btn = make_context_menu_button("folder-symbolic", &gettext("Move to Local Calendar"), false);
    move_btn.set_sensitive(action_state.can_move_to_local);
    let popover_for_move = popover.clone();
    let page_weak_move = page.downgrade();
    let event_for_move = event.clone();
    let anchor_for_move = anchor_widget.clone();
    move_btn.connect_clicked(move |_| {
        popover_for_move.popdown();
        if let Some(page) = page_weak_move.upgrade() {
            page.transfer_event_to_local(event_for_move.clone(), CalendarTransferKind::Move, &anchor_for_move);
        }
    });
    menu_box.append(&move_btn);

    menu_box.append(&gtk::Separator::new(gtk::Orientation::Horizontal));

    // 4. Export
    let export = make_context_menu_button("document-save-symbolic", &gettext("Export Appointment"), false);
    export.set_sensitive(action_state.can_export);
    let popover_for_export = popover.clone();
    let event_for_export = event.clone();
    let anchor_for_export = anchor_widget.clone();
    export.connect_clicked(move |_| {
        popover_for_export.popdown();
        if let Some(root) = anchor_for_export.root() {
            if let Ok(window) = root.downcast::<gtk::Window>() {
                let filter_ics = gtk::FileFilter::new();
                filter_ics.set_name(Some("iCalendar (*.ics)"));
                filter_ics.add_pattern("*.ics");

                let filter_csv = gtk::FileFilter::new();
                filter_csv.set_name(Some(&gettext("Comma-separated values (*.csv)")));
                filter_csv.add_pattern("*.csv");

                let filter_rdf = gtk::FileFilter::new();
                filter_rdf.set_name(Some("RDF / RSS 1.0 (*.rdf)"));
                filter_rdf.add_pattern("*.rdf");

                let filters = gio::ListStore::new::<gtk::FileFilter>();
                filters.append(&filter_ics);
                filters.append(&filter_csv);
                filters.append(&filter_rdf);

                let safe_name = if event_for_export.summary.trim().is_empty() {
                    "appointment".to_string()
                } else {
                    event_for_export
                        .summary
                        .chars()
                        .filter(|c| c.is_alphanumeric() || *c == '_' || *c == '-')
                        .collect::<String>()
                };
                let initial_name = format!("{}.ics", if safe_name.is_empty() { "appointment" } else { &safe_name });

                let file_dialog = gtk::FileDialog::builder()
                    .title(&gettext("Export Appointment"))
                    .filters(&filters)
                    .default_filter(&filter_ics)
                    .initial_name(&initial_name)
                    .modal(true)
                    .build();
                let event_for_dialog = event_for_export.clone();
                let anchor_for_result = anchor_for_export.clone();
                file_dialog.save(Some(&window), None::<&gio::Cancellable>, move |result| {
                    let Ok(file) = result else { return };
                    let format = if let Some(path) = file.path() {
                        let ext = path.extension().and_then(|s| s.to_str()).unwrap_or("");
                        if ext.eq_ignore_ascii_case("csv") {
                            CalendarExportFormat::Csv
                        } else if ext.eq_ignore_ascii_case("rdf") {
                            CalendarExportFormat::Rdf
                        } else {
                            CalendarExportFormat::ICalendar
                        }
                    } else {
                        CalendarExportFormat::ICalendar
                    };
                    let payload = match export_calendar_events(&[event_for_dialog.clone()], format, None) {
                        Ok(data) => data,
                        Err(err) => {
                            show_toast_for_widget(&anchor_for_result, &err);
                            return;
                        }
                    };
                    let save_result = file.replace_contents(
                        payload.as_bytes(),
                        None,
                        true,
                        gio::FileCreateFlags::NONE,
                        None::<&gio::Cancellable>,
                    );
                    match save_result {
                        Ok(_) => show_toast_for_widget(
                            &anchor_for_result,
                            &gettext("Appointment exported as {format}")
                                .replace("{format}", &format.display_label()),
                        ),
                        Err(error) => show_toast_for_widget(
                            &anchor_for_result,
                            &gettext("Appointment could not be saved: {error}")
                                .replace("{error}", &error.to_string()),
                        ),
                    }
                });
            }
        }
    });
    menu_box.append(&export);

    // 5. Print
    let print = make_context_menu_button("printer-symbolic", &gettext("Print Appointment"), false);
    print.set_sensitive(action_state.can_print);
    let popover_for_print = popover.clone();
    let event_for_print = event.clone();
    let anchor_for_print = anchor_widget.clone();
    print.connect_clicked(move |_| {
        popover_for_print.popdown();
        let default_summary = gettext("Appointment");
        let summary_display = if event_for_print.summary.trim().is_empty() {
            default_summary.as_str()
        } else {
            event_for_print.summary.trim()
        };
        match build_event_print_document(&event_for_print) {
            Ok(doc) => {
                show_toast_for_widget(
                    &anchor_for_print,
                    &gettext("Print view for “{summary}” prepared ({count} characters); Print portal is Linux handoff")
                        .replace("{summary}", summary_display)
                        .replace("{count}", &doc.html.len().to_string()),
                );
            }
            Err(err) => {
                show_toast_for_widget(
                    &anchor_for_print,
                    &gettext("Printing failed: {error}").replace("{error}", &err.to_string()),
                );
            }
        }
    });
    menu_box.append(&print);

    menu_box.append(&gtk::Separator::new(gtk::Orientation::Horizontal));

    // 6. Delete
    let delete = make_context_menu_button("user-trash-symbolic", &gettext("Delete Appointment"), true);
    delete.set_sensitive(action_state.can_delete);
    let popover_for_delete = popover.clone();
    let page_weak_delete = page.downgrade();
    let event_for_delete = event.clone();
    let anchor_for_delete = anchor_widget.clone();
    delete.connect_clicked(move |_| {
        popover_for_delete.popdown();
        if let Some(page) = page_weak_delete.upgrade() {
            page.prompt_delete_event(&anchor_for_delete, &event_for_delete, recurring);
        }
    });
    menu_box.append(&delete);

    popover.set_parent(anchor_widget);
    popover.set_child(Some(&menu_box));
    popover.connect_closed(|p| {
        let p = p.clone();
        glib::idle_add_local_once(move || {
            p.unparent();
        });
    });
    popover.popup();
}

fn show_calendar_day_context_menu(
    page: &CalendarPage,
    anchor_widget: &impl glib::object::IsA<gtk::Widget>,
    date: NaiveDate,
    time_slot: Option<(u32, u32)>,
    rect: gdk::Rectangle,
) {
    let anchor_widget = anchor_widget.as_ref();
    let (popover, menu_box) = crate::views::create_context_popover(Some(&rect));
    let multi_range = page.selected_time_slot().and_then(|slot| {
        let (s, e) = if slot.date <= slot.end_date {
            (slot.date, slot.end_date)
        } else {
            (slot.end_date, slot.date)
        };
        (s < e && date >= s && date <= e).then_some((s, e))
    });

    // 1. New Appointment…
    let new_btn = make_context_menu_button("list-add-symbolic", &gettext("New Appointment…"), false);
    let popover_for_new = popover.clone();
    let page_weak_new = page.downgrade();
    new_btn.connect_clicked(move |_| {
        popover_for_new.popdown();
        if let Some(page) = page_weak_new.upgrade() {
            let dialog = if let Some((s_date, e_date)) = multi_range {
                crate::dialogs::EventDialog::new_all_day_for_date_range(s_date, e_date)
            } else if let Some((s_min, e_min)) = time_slot {
                let start_time = date.and_hms_opt(0, 0, 0).unwrap() + Duration::minutes(s_min as i64);
                let end_time = date.and_hms_opt(0, 0, 0).unwrap() + Duration::minutes(e_min as i64);
                crate::dialogs::EventDialog::new_for_time_range(start_time, end_time)
            } else {
                crate::dialogs::EventDialog::new_for_date(date)
            };
            let page_for_refresh = page.downgrade();
            dialog.connect_closed(move |_| {
                if let Some(page) = page_for_refresh.upgrade() {
                    page.reload_calendar_data();
                }
            });
            dialog.present_adaptive(&page);
        }
    });
    menu_box.append(&new_btn);

    // 2. New All-Day Event…
    let allday_btn = make_context_menu_button("appointment-soon-symbolic", &gettext("New All-Day Event…"), false);
    let popover_for_allday = popover.clone();
    let page_weak_allday = page.downgrade();
    allday_btn.connect_clicked(move |_| {
        popover_for_allday.popdown();
        if let Some(page) = page_weak_allday.upgrade() {
            let dialog = if let Some((s_date, e_date)) = multi_range {
                crate::dialogs::EventDialog::new_all_day_for_date_range(s_date, e_date)
            } else {
                crate::dialogs::EventDialog::new_all_day_for_date(date)
            };
            let page_for_refresh = page.downgrade();
            dialog.connect_closed(move |_| {
                if let Some(page) = page_for_refresh.upgrade() {
                    page.reload_calendar_data();
                }
            });
            dialog.present_adaptive(&page);
        }
    });
    menu_box.append(&allday_btn);

    menu_box.append(&gtk::Separator::new(gtk::Orientation::Horizontal));

    // 3. Open in Day View
    let day_btn = make_context_menu_button("x-office-calendar-symbolic", &gettext("Open in Day View"), false);
    let popover_for_day = popover.clone();
    let page_weak_day = page.downgrade();
    day_btn.connect_clicked(move |_| {
        popover_for_day.popdown();
        if let Some(page) = page_weak_day.upgrade() {
            *page.imp().current_date.borrow_mut() = date;
            page.imp()
                .view_state
                .borrow_mut()
                .set_anchor(date, configured_first_weekday());
            page.imp().view_state.borrow_mut().select_civil_day(date);
            page.select_calendar_view(CalendarView::Day);
        }
    });
    menu_box.append(&day_btn);

    // 4. Open in Week View
    let week_btn = make_context_menu_button("view-calendar-week-symbolic", &gettext("Open in Week View"), false);
    let popover_for_week = popover.clone();
    let page_weak_week = page.downgrade();
    week_btn.connect_clicked(move |_| {
        popover_for_week.popdown();
        if let Some(page) = page_weak_week.upgrade() {
            *page.imp().current_date.borrow_mut() = date;
            page.imp()
                .view_state
                .borrow_mut()
                .set_anchor(date, configured_first_weekday());
            page.imp().view_state.borrow_mut().select_civil_day(date);
            page.select_calendar_view(CalendarView::Week);
        }
    });
    menu_box.append(&week_btn);

    menu_box.append(&gtk::Separator::new(gtk::Orientation::Horizontal));

    // 5. Go to Today
    let today_btn = make_context_menu_button("go-jump-symbolic", &gettext("Go to Today"), false);
    let popover_for_today = popover.clone();
    let page_weak_today = page.downgrade();
    today_btn.connect_clicked(move |_| {
        popover_for_today.popdown();
        if let Some(page) = page_weak_today.upgrade() {
            let today = Local::now().date_naive();
            page.imp()
                .view_state
                .borrow_mut()
                .today(today, configured_first_weekday());
            *page.imp().current_date.borrow_mut() = today;
            page.sync_mini_calendar();
            page.refresh_calendar_views();
        }
    });
    menu_box.append(&today_btn);

    popover.set_parent(anchor_widget);
    popover.set_child(Some(&menu_box));
    popover.connect_closed(|p| {
        let p = p.clone();
        glib::idle_add_local_once(move || {
            p.unparent();
        });
    });
    popover.popup();
}

fn ensure_month_popover_chip_css_class(
    base_hex: &str,
    bg: &str,
    hover: &str,
    active: &str,
    fg: &str,
    all_day: bool,
) -> String {
    thread_local! {
        static CLASS_CACHE: std::cell::RefCell<std::collections::HashMap<(String, String, String, String, String, bool), String>> =
            std::cell::RefCell::new(std::collections::HashMap::new());
    }
    let key = (
        base_hex.to_string(),
        bg.to_string(),
        hover.to_string(),
        active.to_string(),
        fg.to_string(),
        all_day,
    );
    CLASS_CACHE.with(|cache| {
        let mut map = cache.borrow_mut();
        if let Some(class_name) = map.get(&key) {
            class_name.clone()
        } else {
            let class_name = format!("cal-mp-chip-{}", map.len());
            if gtk::is_initialized_main_thread() {
                if let Some(display) = gtk::gdk::Display::default() {
                    let provider = gtk::CssProvider::new();
                    let css = if all_day {
                        format!(
                            "button.{class_name} {{ border: none; outline: none; border-radius: 5px; box-shadow: none; background-color: {bg}; min-height: 28px; padding: 2px 10px; margin: 1px 0; }} \
                             button.{class_name} label {{ color: {fg}; }} \
                             button.{class_name}:hover {{ border: none; outline: none; border-radius: 5px; box-shadow: none; background-color: {hover}; }} \
                             button.{class_name}:active {{ border: none; outline: none; border-radius: 5px; box-shadow: none; background-color: {active}; }}"
                        )
                    } else {
                        format!(
                            "button.{class_name} {{ border: none; outline: none; border-left: 5px solid {base_hex}; border-radius: 5px; box-shadow: none; background-color: {bg}; min-height: 28px; padding: 2px 8px; margin: 1px 0; }} \
                             button.{class_name} label {{ color: {fg}; }} \
                             button.{class_name}:hover {{ border: none; outline: none; border-left: 5px solid {base_hex}; border-radius: 5px; box-shadow: none; background-color: {hover}; }} \
                             button.{class_name}:active {{ border: none; outline: none; border-left: 5px solid {base_hex}; border-radius: 5px; box-shadow: none; background-color: {active}; }}"
                        )
                    };
                    provider.load_from_string(&css);
                    gtk::style_context_add_provider_for_display(
                        &display,
                        &provider,
                        gtk::STYLE_PROVIDER_PRIORITY_APPLICATION,
                    );
                }
            }
            map.insert(key, class_name.clone());
            class_name
        }
    })
}

fn show_month_overflow_popover(
    page: &CalendarPage,
    parent: &gtk::DrawingArea,
    date: NaiveDate,
    pointing_to: Option<gdk::Rectangle>,
) {
    let popover = gtk::Popover::builder()
        .autohide(true)
        .has_arrow(true)
        .css_classes(vec!["calendar-month-day-popover"])
        .build();
    if let Some(ref rect) = pointing_to {
        popover.set_pointing_to(Some(rect));
    }
    popover.set_parent(parent);

    let popover_weak = popover.downgrade();
    popover.connect_closed(move |_| {
        if let Some(popover) = popover_weak.upgrade() {
            popover.unparent();
        }
    });

    let content_box = gtk::Box::builder()
        .orientation(gtk::Orientation::Vertical)
        .spacing(6)
        .margin_start(12)
        .margin_end(12)
        .margin_top(10)
        .margin_bottom(10)
        .build();

    // ── Header Bar: Big Day Number & Close Button (GNOME Calendar Parity) ──
    let header_box = gtk::Box::builder()
        .orientation(gtk::Orientation::Horizontal)
        .spacing(8)
        .margin_bottom(6)
        .valign(gtk::Align::Center)
        .build();

    let day_num_label = gtk::Label::builder()
        .label(&format!("{}", date.day()))
        .css_classes(vec!["month-popover-day-number"])
        .hexpand(true)
        .xalign(0.0)
        .build();

    let day_btn = gtk::Button::builder()
        .child(&day_num_label)
        .css_classes(vec!["flat", "month-popover-day-btn"])
        .tooltip_text(&crate::i18n::gettext("Open in Day View"))
        .hexpand(true)
        .halign(gtk::Align::Start)
        .build();
    let page_weak_day = page.downgrade();
    let popover_day = popover.clone();
    day_btn.connect_clicked(move |_| {
        popover_day.popdown();
        if let Some(page) = page_weak_day.upgrade() {
            *page.imp().current_date.borrow_mut() = date;
            page.imp()
                .view_state
                .borrow_mut()
                .set_anchor(date, configured_first_weekday());
            page.imp().view_state.borrow_mut().select_civil_day(date);
            if page.imp().is_mobile.get() {
                page.imp().drill_down_previous_view.set(Some(CalendarView::Month));
            }
            page.select_calendar_view(CalendarView::Day);
            if let Some(win) = crate::window::find_meridian_window(&page) {
                win.sync_back_button();
            }
        }
    });
    header_box.append(&day_btn);

    let close_btn = gtk::Button::builder()
        .icon_name("window-close-symbolic")
        .css_classes(vec!["flat", "circular", "month-popover-close-btn"])
        .tooltip_text(&crate::i18n::gettext("Close"))
        .valign(gtk::Align::Center)
        .build();
    let popover_close = popover.clone();
    close_btn.connect_clicked(move |_| {
        popover_close.popdown();
    });
    header_box.append(&close_btn);
    content_box.append(&header_box);

    // ── Events List ──
    let mut events_map = page.events_by_date(CalendarDateRange::single(date));
    let mut events = events_map.remove(&date).unwrap_or_default();

    // Sort: all-day first, then timed events chronologically
    events.sort_by(|a, b| {
        match (a.all_day, b.all_day) {
            (true, false) => std::cmp::Ordering::Less,
            (false, true) => std::cmp::Ordering::Greater,
            _ => a.start.cmp(&b.start).then_with(|| a.summary.cmp(&b.summary)),
        }
    });

    let scroll = gtk::ScrolledWindow::builder()
        .hscrollbar_policy(gtk::PolicyType::Never)
        .vscrollbar_policy(gtk::PolicyType::Automatic)
        .propagate_natural_height(true)
        .propagate_natural_width(true)
        .max_content_height(340)
        .min_content_width(260)
        .build();

    let events_box = gtk::Box::builder()
        .orientation(gtk::Orientation::Vertical)
        .spacing(5)
        .build();

    let is_dark = adw::StyleManager::default().is_dark();

    if events.is_empty() {
        let empty_label = gtk::Label::builder()
            .label(&crate::i18n::gettext("No appointments"))
            .css_classes(vec!["dim-label"])
            .margin_top(16)
            .margin_bottom(16)
            .build();
        events_box.append(&empty_label);
    } else {
        for event in events {
            let color_hex = event_color_for_record(&event);
            let (_accent_hex, bg_hex, hover_hex, active_hex, fg_hex) = {
                let (bg, hover, active, fg) = pastel_colors_for_hex(&color_hex, is_dark);
                (color_hex.clone(), bg, hover, active, fg)
            };
            let class_name = ensure_month_popover_chip_css_class(
                &color_hex,
                &bg_hex,
                &hover_hex,
                &active_hex,
                &fg_hex,
                event.all_day,
            );

            let summary_text = if event.summary.trim().is_empty() {
                crate::i18n::gettext("(Untitled)")
            } else {
                event.summary.clone()
            };

            let title_label = gtk::Label::builder()
                .label(&summary_text)
                .xalign(0.0)
                .hexpand(true)
                .ellipsize(gtk::pango::EllipsizeMode::End)
                .css_classes(vec!["month-popover-event-title"])
                .build();

            let row_button = gtk::Button::builder()
                .child(&title_label)
                .css_classes(vec!["month-popover-event-chip", &class_name])
                .tooltip_text(&summary_text)
                .build();

            let page_weak = page.downgrade();
            let parent_clone = parent.clone();
            let event_clone = event.clone();
            let popover_clone = popover.clone();
            row_button.connect_clicked(move |_| {
                popover_clone.popdown();
                if let Some(page) = page_weak.upgrade() {
                    page.select_and_inspect_event(&event_clone, Some(date));
                    if !page.is_tag_vpane_visible() {
                        show_calendar_event_details_popover_full(
                            &page,
                            &parent_clone,
                            &event_clone,
                            Some(date),
                            pointing_to,
                        );
                    }
                }
            });

            events_box.append(&row_button);
        }
    }

    scroll.set_child(Some(&events_box));
    content_box.append(&scroll);

    // ── Bottom Action: "New Event..." ──
    let new_event_btn = gtk::Button::builder()
        .label(&crate::i18n::gettext("New Event…"))
        .css_classes(vec!["flat", "month-popover-new-event-btn"])
        .halign(gtk::Align::Center)
        .margin_top(10)
        .margin_bottom(2)
        .build();

    let page_weak = page.downgrade();
    let parent_clone = parent.clone();
    let popover_clone = popover.clone();
    new_event_btn.connect_clicked(move |_| {
        popover_clone.popdown();
        if let Some(page) = page_weak.upgrade() {
            let start_dt = date.and_hms_opt(9, 0, 0).unwrap_or_default();
            let end_dt = date.and_hms_opt(10, 0, 0).unwrap_or_default();
            page.present_quick_add(&parent_clone, pointing_to, start_dt, end_dt, false);
        }
    });
    content_box.append(&new_event_btn);

    popover.set_child(Some(&content_box));
    popover.popup();
}

fn resize_event_component_end(raw: &str, delta_minutes: i64) -> Result<String, String> {
    if raw.trim().is_empty() {
        return Err(gettext("The appointment contains no iCalendar data"));
    }
    if ical_property(raw, "RECURRENCE-ID").is_some() {
        return Err(gettext(
            "Recurring exceptions with RECURRENCE-ID cannot be resized directly",
        ));
    }
    if let Some(value) = ical_property(raw, "DTEND") {
        let Some(shifted) = shift_ical_datetime_value_full(&value, 0, delta_minutes) else {
            return Err(gettext("DTEND could not be evaluated while resizing"));
        };
        let property_prefix =
            ical_property_prefix(raw, "DTEND").unwrap_or_else(|| "DTEND".to_string());
        Ok(update_ical_property(raw, &property_prefix, Some(&shifted)))
    } else if let Some(start_val) = ical_property(raw, "DTSTART") {
        let Some(shifted) = shift_ical_datetime_value_full(&start_val, 0, 30 + delta_minutes) else {
            return Err(gettext("DTEND could not be evaluated while resizing"));
        };
        let prefix = ical_property_prefix(raw, "DTSTART")
            .map(|p| p.replace("DTSTART", "DTEND"))
            .unwrap_or_else(|| "DTEND".to_string());
        Ok(update_ical_property(raw, &prefix, Some(&shifted)))
    } else {
        Err(gettext("The appointment has no start or end time to adjust"))
    }
}

fn install_event_drag_source<W: IsA<gtk::Widget>>(
    widget: &W,
    event: &CalendarEventRecord,
    occurrence_date: NaiveDate,
) {
    if event.source_uid.trim().is_empty()
        || event.uid.trim().is_empty()
        || event_mutation_error(event).is_some()
    {
        return;
    }
    let recurrence_id = calendar_recurrence_id(event).unwrap_or_default();
    let payload = format!(
        "{}\n{}\n{}\n{}",
        event.source_uid,
        event.uid,
        recurrence_id,
        occurrence_date.format("%Y-%m-%d")
    );
    let drag_source = gtk::DragSource::new();
    drag_source.set_actions(gdk::DragAction::MOVE | gdk::DragAction::COPY);
    drag_source
        .connect_prepare(move |_, _, _| Some(gdk::ContentProvider::for_value(&payload.to_value())));
    widget.add_controller(drag_source);
}

fn install_day_drop_target<W: IsA<gtk::Widget>>(
    widget: &W,
    page: &CalendarPage,
    target_date: NaiveDate,
) {
    install_time_slot_drop_target(widget, page, target_date, None);
}

fn handle_dropped_event_payload(
    page: &CalendarPage,
    payload: &str,
    target_date: NaiveDate,
    target_minute: Option<u32>,
    is_copy: bool,
) -> bool {
    let mut payload_parts = payload.splitn(4, '\n');
    let Some(source_uid) = payload_parts.next() else {
        return false;
    };
    let Some(uid) = payload_parts.next() else {
        return false;
    };
    let recurrence_id = payload_parts
        .next()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let occurrence_date = payload_parts
        .next()
        .and_then(|value| NaiveDate::parse_from_str(value, "%Y-%m-%d").ok());
    let records = page.imp().event_records.borrow().as_ref().cloned();
    let Some(event) = records.and_then(|records| {
        let target_identity =
            calendar_event_identity_from_parts(source_uid, uid, recurrence_id);
        unique_event_for_identity(&records.borrow(), &target_identity)
    }) else {
        show_toast_for_widget(page, &gettext("The dragged appointment is no longer loaded"));
        return false;
    };
    let Some(start_date) = occurrence_date.or_else(|| event_start_date(&event)) else {
        show_toast_for_widget(page, &gettext("The appointment has no valid start date"));
        return false;
    };
    let delta_days = (target_date - start_date).num_days();
    let delta_minutes = if let Some(target_min) = target_minute {
        if event.all_day {
            0
        } else {
            let start_dt = event_start_datetime(&event);
            let current_minute = start_dt
                .map(|dt| dt.time().hour() * 60 + dt.time().minute())
                .unwrap_or(0);
            target_min as i64 - current_minute as i64
        }
    } else {
        0
    };
    if is_copy {
        page.duplicate_event_by_delta(event, delta_days, delta_minutes);
    } else {
        page.move_event_by_delta(event, delta_days, delta_minutes);
    }
    true
}

fn install_time_slot_drop_target<W: IsA<gtk::Widget>>(
    widget: &W,
    page: &CalendarPage,
    target_date: NaiveDate,
    target_minute: Option<u32>,
) {
    let drop_target = gtk::DropTarget::new(glib::Type::STRING, gdk::DragAction::MOVE | gdk::DragAction::COPY);
    let page_weak = page.downgrade();
    drop_target.connect_drop(move |target, value, _, _| {
        let Ok(payload) = value.get::<String>() else {
            return false;
        };
        let Some(page) = page_weak.upgrade() else {
            return false;
        };
        let is_copy = target.current_drop().map(|d| d.actions().contains(gdk::DragAction::COPY)).unwrap_or(false);
        handle_dropped_event_payload(&page, &payload, target_date, target_minute, is_copy)
    });
    widget.add_controller(drop_target);
}

fn shift_event_component(raw: &str, delta_days: i64) -> Result<String, String> {
    shift_event_component_full(raw, delta_days, 0)
}

fn shift_event_component_full(
    raw: &str,
    delta_days: i64,
    delta_minutes: i64,
) -> Result<String, String> {
    if raw.trim().is_empty() {
        return Err(gettext("The appointment contains no iCalendar data"));
    }
    if ical_property(raw, "RECURRENCE-ID").is_some() {
        return Err(
            gettext("Recurring exceptions with RECURRENCE-ID cannot be moved by dragging; the calendar service cannot address the exception unambiguously"),
        );
    }

    let mut updated = raw.to_string();
    for property_name in ["DTSTART", "DTEND"] {
        let Some(value) = ical_property(&updated, property_name) else {
            continue;
        };
        let Some(shifted) =
            shift_ical_datetime_value_full(&value, delta_days, delta_minutes)
        else {
            return Err(
                gettext("{property} could not be evaluated while moving")
                    .replace("{property}", property_name),
            );
        };
        let property_prefix = ical_property_prefix(&updated, property_name)
            .unwrap_or_else(|| property_name.to_string());
        updated = update_ical_property(&updated, &property_prefix, Some(&shifted));
    }
    for property_name in ["RDATE", "EXDATE"] {
        updated = shift_ical_date_list_property_full(&updated, property_name, delta_days, delta_minutes)?;
    }
    updated = shift_rrule_full(&updated, delta_days, delta_minutes)?;
    Ok(updated)
}

fn shift_ical_date_list_property(
    raw: &str,
    property_name: &str,
    delta_days: i64,
) -> Result<String, String> {
    shift_ical_date_list_property_full(raw, property_name, delta_days, 0)
}

fn shift_ical_date_list_property_full(
    raw: &str,
    property_name: &str,
    delta_days: i64,
    delta_minutes: i64,
) -> Result<String, String> {
    let target = property_name.to_ascii_uppercase();
    let mut lines = Vec::new();
    let mut component_depth = 0usize;
    let mut replaced = false;

    for line in unfold_ical_lines(raw) {
        let Some((property, value)) = line.split_once(':') else {
            lines.push(line);
            continue;
        };
        let name = property
            .split(';')
            .next()
            .unwrap_or(property)
            .to_ascii_uppercase();
        if name == target && component_depth <= 1 {
            let shifted_values = value
                .split(',')
                .map(|value| {
                    shift_ical_datetime_value_full(value, delta_days, delta_minutes).ok_or_else(|| {
                        gettext("{property} could not be evaluated while moving")
                            .replace("{property}", property_name)
                    })
                })
                .collect::<Result<Vec<_>, _>>()?;
            // Keep every line's own TZID/VALUE parameters. Combining lines
            // under the first prefix would silently change a mixed-zone
            // EXDATE/RDATE set.
            lines.push(format!("{property}:{}", shifted_values.join(",")));
            replaced = true;
        } else {
            lines.push(line);
        }

        if name == "BEGIN" {
            component_depth = component_depth.saturating_add(1);
        } else if name == "END" {
            component_depth = component_depth.saturating_sub(1);
        }
    }

    if !replaced {
        return Ok(raw.to_string());
    }
    Ok(format!("{}\r\n", lines.join("\r\n")))
}

fn shift_rrule(raw: &str, delta_days: i64) -> Result<String, String> {
    shift_rrule_full(raw, delta_days, 0)
}

fn shift_rrule_full(
    raw: &str,
    delta_days: i64,
    delta_minutes: i64,
) -> Result<String, String> {
    let Some(rule) = ical_property(raw, "RRULE") else {
        return Ok(raw.to_string());
    };
    let parsed_rule = parse_recurrence_rule(&rule).ok_or_else(|| {
        gettext("The recurrence rule is invalid and was not moved")
    })?;

    // A date shift is exact for daily rules and weekly rules. Weekly BYDAY
    // values must move with DTSTART; leaving them untouched would create a
    // different series. More complex monthly/yearly filters cannot be
    // translated losslessly by a simple drag, so report that fact instead of
    // writing a plausible-looking but wrong recurrence.
    if !matches!(parsed_rule.frequency.as_str(), "DAILY" | "WEEKLY") {
        return Err(
            gettext("This recurrence cannot be moved safely by dragging; please edit the appointment"),
        );
    }

    let mut changed = false;
    let shifted_rule = rule
        .split(';')
        .map(|part| {
            let Some((key, value)) = part.split_once('=') else {
                return Ok(part.to_string());
            };
            if key.eq_ignore_ascii_case("UNTIL") {
                let shifted = shift_ical_datetime_value_full(value, delta_days, delta_minutes).ok_or_else(|| {
                    gettext("RRULE-UNTIL could not be evaluated while moving")
                })?;
                changed = true;
                return Ok(format!("{key}={shifted}"));
            }
            if key.eq_ignore_ascii_case("BYDAY") {
                let shifted_days = value
                    .split(',')
                    .map(|token| {
                        let by_day = parse_extended_weekday_token(token).ok_or_else(|| {
                            gettext("RRULE-BYDAY could not be evaluated while moving")
                        })?;
                        Ok(format_shifted_recurrence_day(by_day, delta_days))
                    })
                    .collect::<Result<Vec<_>, String>>()?;
                changed = true;
                return Ok(format!("{key}={}", shifted_days.join(",")));
            }
            if matches!(
                key.to_ascii_uppercase().as_str(),
                "BYMONTHDAY" | "BYMONTH" | "BYSETPOS"
            ) {
                return Err(
                    gettext("This recurrence contains filters that cannot be moved safely by dragging"),
                );
            }
            Ok(part.to_string())
        })
        .collect::<Result<Vec<_>, String>>()?
        .join(";");
    if !changed {
        return Ok(raw.to_string());
    }
    let property_prefix = ical_property_prefix(raw, "RRULE").unwrap_or_else(|| "RRULE".to_string());
    Ok(update_ical_property(
        raw,
        &property_prefix,
        Some(&shifted_rule),
    ))
}

fn format_shifted_recurrence_day(by_day: RecurrenceByDay, delta_days: i64) -> String {
    let weekday_index =
        (i64::from(by_day.weekday.num_days_from_monday()) + delta_days).rem_euclid(7);
    let weekday = match weekday_index {
        0 => Weekday::Mon,
        1 => Weekday::Tue,
        2 => Weekday::Wed,
        3 => Weekday::Thu,
        4 => Weekday::Fri,
        5 => Weekday::Sat,
        _ => Weekday::Sun,
    };
    let token = match weekday {
        Weekday::Mon => "MO",
        Weekday::Tue => "TU",
        Weekday::Wed => "WE",
        Weekday::Thu => "TH",
        Weekday::Fri => "FR",
        Weekday::Sat => "SA",
        Weekday::Sun => "SU",
    };
    by_day
        .ordinal
        .map(|ordinal| format!("{ordinal}{token}"))
        .unwrap_or_else(|| token.to_string())
}

fn ical_property_prefix(raw: &str, target: &str) -> Option<String> {
    let target = target.to_ascii_uppercase();
    unfold_ical_lines(raw).into_iter().find_map(|line| {
        let (property, _) = line.split_once(':')?;
        let name = property
            .split(';')
            .next()
            .unwrap_or(property)
            .to_ascii_uppercase();
        (name == target).then(|| property.to_string())
    })
}

fn shift_ical_datetime_value(value: &str, delta_days: i64) -> Option<String> {
    shift_ical_datetime_value_full(value, delta_days, 0)
}

fn shift_ical_datetime_value_full(
    value: &str,
    delta_days: i64,
    delta_minutes: i64,
) -> Option<String> {
    let value = value.trim();
    if value.len() == 8 {
        let date = NaiveDate::parse_from_str(value, "%Y%m%d").ok()?;
        return Some(
            (date + Duration::days(delta_days))
                .format("%Y%m%d")
                .to_string(),
        );
    }
    if value.len() < 15 || value.as_bytes().get(8) != Some(&b'T') {
        return None;
    }
    if !value.is_char_boundary(15) {
        return None;
    }
    let datetime = NaiveDateTime::parse_from_str(&value[..15], "%Y%m%dT%H%M%S").ok()?;
    let suffix = &value[15..];
    let shift = Duration::days(delta_days) + Duration::minutes(delta_minutes);
    Some(format!(
        "{}{}",
        (datetime + shift).format("%Y%m%dT%H%M%S"),
        suffix
    ))
}

fn week_start_for(date: NaiveDate, first_weekday: Weekday) -> NaiveDate {
    let current = i64::from(date.weekday().num_days_from_monday());
    let first = i64::from(first_weekday.num_days_from_monday());
    date - Duration::days((current - first).rem_euclid(7))
}

fn calendar_year_range_option(year: i32) -> Option<CalendarDateRange> {
    let start = NaiveDate::from_ymd_opt(year, 1, 1)?;
    // `NaiveDate` has no representable exclusive end after its maximum date.
    // Clip the final civil year to that boundary instead of panicking while
    // constructing a viewport at `NaiveDate::MAX`.
    let end = year
        .checked_add(1)
        .and_then(|next_year| NaiveDate::from_ymd_opt(next_year, 1, 1))
        .unwrap_or(NaiveDate::MAX);
    if start >= end {
        return None;
    }
    Some(CalendarDateRange::new(start, end))
}

fn calendar_year_range(year: i32) -> CalendarDateRange {
    calendar_year_range_option(year).unwrap_or_else(|| {
        NaiveDate::from_ymd_opt(year, 1, 1)
            .map(CalendarDateRange::single)
            .unwrap_or_else(|| CalendarDateRange::single(NaiveDate::MIN))
    })
}

fn shift_year(date: NaiveDate, direction: i32) -> NaiveDate {
    let Some(year) = date.year().checked_add(direction) else {
        return date;
    };
    NaiveDate::from_ymd_opt(year, date.month(), date.day())
        .or_else(|| {
            (28..=31)
                .rev()
                .find_map(|day| NaiveDate::from_ymd_opt(year, date.month(), day))
        })
        .unwrap_or(date)
}

fn configured_first_weekday() -> Weekday {
    AppSettings::try_new()
        .map(|settings| settings.calendar_week_start())
        .filter(|value| value == "sunday")
        .map(|_| Weekday::Sun)
        .unwrap_or(Weekday::Mon)
}

fn add_months(year: i32, month: u32, offset: usize) -> (i32, u32) {
    let total_month = (month - 1) as usize + offset;
    let new_year = year + (total_month / 12) as i32;
    let new_month = (total_month % 12 + 1) as u32;
    (new_year, new_month)
}

fn ensure_event_chip_css_class(
    base_hex: &str,
    bg: &str,
    hover: &str,
    active: &str,
    fg: &str,
) -> String {
    thread_local! {
        static CLASS_CACHE: std::cell::RefCell<HashMap<(String, String, String, String, String), String>> =
            std::cell::RefCell::new(HashMap::new());
    }
    let key = (
        base_hex.to_string(),
        bg.to_string(),
        hover.to_string(),
        active.to_string(),
        fg.to_string(),
    );
    CLASS_CACHE.with(|cache| {
        let mut map = cache.borrow_mut();
        if let Some(class_name) = map.get(&key) {
            class_name.clone()
        } else {
            let class_name = format!("cal-chip-{}", map.len());
            if gtk::is_initialized_main_thread() {
                if let Some(display) = gtk::gdk::Display::default() {
                    let provider = gtk::CssProvider::new();
                    provider.load_from_string(&format!(
                        "button.{class_name} {{ border: none; outline: none; border-left: 6px solid {base_hex}; border-radius: 6px; box-shadow: none; background-color: {bg}; color: {fg}; }} \
                         button.{class_name}:hover {{ border: none; outline: none; border-left: 6px solid {base_hex}; border-radius: 6px; box-shadow: none; background-color: {hover}; color: {fg}; }} \
                         button.{class_name}:active {{ border: none; outline: none; border-left: 6px solid {base_hex}; border-radius: 6px; box-shadow: none; background-color: {active}; color: {fg}; }}"
                    ));
                    gtk::style_context_add_provider_for_display(
                        &display,
                        &provider,
                        gtk::STYLE_PROVIDER_PRIORITY_APPLICATION,
                    );
                }
            }
            map.insert(key, class_name.clone());
            class_name
        }
    })
}

fn ensure_year_event_bar_css_class(color: &str) -> String {
    let clean = color.trim_start_matches('#').to_lowercase();
    let class_name = format!("cal-year-bar-{clean}");
    thread_local! {
        static REGISTERED: std::cell::RefCell<HashSet<String>> =
            std::cell::RefCell::new(HashSet::new());
    }
    let already = REGISTERED.with(|r| r.borrow().contains(&class_name));
    if !already {
        if let Some(display) = gtk::gdk::Display::default() {
            let p = gtk::CssProvider::new();
            p.load_from_string(&format!(
                "box.{class_name} {{ background-color: {color}; border-radius: 9999px; min-width: 4px; width: 4px; }}"
            ));
            gtk::style_context_add_provider_for_display(
                &display,
                &p,
                gtk::STYLE_PROVIDER_PRIORITY_APPLICATION,
            );
            REGISTERED.with(|r| r.borrow_mut().insert(class_name.clone()));
        }
    }
    class_name
}

fn ensure_category_pill_css_class(cat_col: &str) -> String {
    let clean = cat_col.trim_start_matches('#').to_lowercase();
    let class_name = format!("cal-cat-pill-{clean}");
    thread_local! {
        static REGISTERED: std::cell::RefCell<HashSet<String>> =
            std::cell::RefCell::new(HashSet::new());
    }
    let already = REGISTERED.with(|r| r.borrow().contains(&class_name));
    if !already {
        if let Some(display) = gtk::gdk::Display::default() {
            let p = gtk::CssProvider::new();
            p.load_from_string(&format!(
                "label.{class_name} {{ background-color: alpha({cat_col}, 0.20); color: {cat_col}; }}"
            ));
            gtk::style_context_add_provider_for_display(
                &display,
                &p,
                gtk::STYLE_PROVIDER_PRIORITY_APPLICATION,
            );
            REGISTERED.with(|r| r.borrow_mut().insert(class_name.clone()));
        }
    }
    class_name
}

/// Determines the dominant month (year, month) for a month grid range (5 or 6 weeks).
/// A month is dominant if it occupies a strict majority of the visible rows (evaluated by the row's midpoint date).
/// In case of ties or near-ties, hysteresis is applied: the currently active month (`current_ym`) is preserved
/// if it is one of the candidate months, preventing visual flickering during continuous row-by-row scrolling.
pub(crate) fn dominant_month_for_range(
    range: CalendarDateRange,
    current_ym: Option<(i32, u32)>,
) -> (i32, u32) {
    let num_rows = (range.len_days() / 7).max(1);
    let mut row_counts: BTreeMap<(i32, u32), usize> = BTreeMap::new();
    for r in 0..num_rows {
        if let Some(midpoint) = range.start.checked_add_signed(Duration::days(r * 7 + 3)) {
            *row_counts.entry((midpoint.year(), midpoint.month())).or_insert(0) += 1;
        }
    }

    // 1. A month with strict majority of rows is unconditionally dominant (>= 3 of 5, >= 4 of 6)
    let majority = (num_rows as usize / 2) + 1;
    for (&ym, &count) in &row_counts {
        if count >= majority {
            return ym;
        }
    }

    // 2. In case of tie, preserve current_ym if it is one of the candidate months with >= half the rows
    let half = (num_rows as usize) / 2;
    if let Some(curr) = current_ym {
        if let Some(&count) = row_counts.get(&curr) {
            if count >= half {
                return curr;
            }
        }
    }

    // 3. Fallback to month with highest row count, or start of range
    row_counts
        .into_iter()
        .max_by_key(|&(_, count)| count)
        .map(|(ym, _)| ym)
        .unwrap_or_else(|| (range.start.year(), range.start.month()))
}

fn days_in_month(year: i32, month: u32) -> u32 {
    let (next_y, next_m) = if month == 12 {
        (year + 1, 1)
    } else {
        (year, month + 1)
    };
    NaiveDate::from_ymd_opt(next_y, next_m, 1)
        .and_then(|d| d.pred_opt())
        .map(|d| d.day())
        .unwrap_or(30)
}

fn step_date_by_month(date: NaiveDate, delta_months: i32) -> NaiveDate {
    let mut year = date.year();
    let mut month = date.month() as i32 + delta_months;
    while month < 1 {
        month += 12;
        year -= 1;
    }
    while month > 12 {
        month -= 12;
        year += 1;
    }
    let day = date.day().min(days_in_month(year, month as u32));
    NaiveDate::from_ymd_opt(year, month as u32, day).unwrap_or(date)
}

fn step_date_by_year(date: NaiveDate, delta_years: i32) -> NaiveDate {
    let year = date.year() + delta_years;
    let month = date.month();
    let day = date.day().min(days_in_month(year, month));
    NaiveDate::from_ymd_opt(year, month, day).unwrap_or(date)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct DateChooserCellInfo {
    pub date: NaiveDate,
    pub is_outside_month: bool,
    pub is_selected_day: bool,
    pub is_today: bool,
    pub is_selected_week: bool,
    pub is_last_col: bool,
    pub in_visible_range: bool,
    pub is_range_start: bool,
    pub is_range_end: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct DateChooserWeekInfo {
    pub week_number: u32,
    pub week_start: NaiveDate,
    pub is_selected_week: bool,
    pub has_visible_days: bool,
    pub days: Vec<DateChooserCellInfo>,
}

fn date_chooser_grid_start(view_date: NaiveDate, first_weekday: Weekday) -> NaiveDate {
    let first_of_month =
        NaiveDate::from_ymd_opt(view_date.year(), view_date.month(), 1).unwrap_or(view_date);
    let days_before = (first_of_month.weekday().num_days_from_monday() + 7
        - first_weekday.num_days_from_monday())
        % 7;
    first_of_month - Duration::days(days_before as i64)
}

pub(crate) fn compute_date_chooser_weeks(
    view_date: NaiveDate,
    anchor_date: NaiveDate,
    today: NaiveDate,
    active_view: CalendarView,
    first_weekday: Weekday,
) -> Vec<DateChooserWeekInfo> {
    let view_year = view_date.year();
    let view_month = view_date.month();
    let grid_start = date_chooser_grid_start(view_date, first_weekday);

    let is_week_like_view = matches!(
        active_view,
        CalendarView::Week | CalendarView::WorkWeek | CalendarView::Month
    );
    let anchor_iso_week = anchor_date.iso_week();
    let anchor_in_view_month =
        anchor_date.year() == view_year && anchor_date.month() == view_month;

    let mut weeks = Vec::with_capacity(6);

    for row_idx in 0..6 {
        let week_start = grid_start + Duration::days((row_idx * 7) as i64);
        let iso_week = week_start.iso_week();
        let is_week_selected =
            is_week_like_view && anchor_in_view_month && (iso_week == anchor_iso_week);

        let mut days = Vec::with_capacity(7);
        for col_idx in 0..7 {
            let cell_date = week_start + Duration::days(col_idx as i64);
            let is_outside_month = cell_date.month() != view_month;
            days.push(DateChooserCellInfo {
                date: cell_date,
                is_outside_month,
                is_selected_day: !is_outside_month && cell_date == anchor_date,
                is_today: !is_outside_month && cell_date == today,
                is_selected_week: is_week_selected,
                is_last_col: col_idx == 6,
                in_visible_range: false,
                is_range_start: false,
                is_range_end: false,
            });
        }

        weeks.push(DateChooserWeekInfo {
            week_number: iso_week.week(),
            week_start,
            is_selected_week: is_week_selected,
            has_visible_days: false,
            days,
        });
    }

    weeks
}

/// Mini-calendar model that highlights exactly the range shown in the active
/// calendar view (single day, work week, week, month window) as a continuous
/// pill per row.
pub(crate) fn compute_date_chooser_weeks_for_viewport(
    view_date: NaiveDate,
    viewport: &CalendarViewport,
    today: NaiveDate,
    first_weekday: Weekday,
) -> Vec<DateChooserWeekInfo> {
    compute_date_chooser_weeks_with_visibility(view_date, viewport.anchor_date, today, first_weekday, |d| {
        if viewport.view == CalendarView::Day || viewport.view == CalendarView::Year || viewport.view == CalendarView::List || viewport.view == CalendarView::Agenda {
            false
        } else {
            is_day_visible_in_viewport(viewport, d)
        }
    })
}

pub(crate) fn compute_date_chooser_weeks_for_range(
    view_date: NaiveDate,
    range: CalendarDateRange,
    anchor_date: NaiveDate,
    today: NaiveDate,
    first_weekday: Weekday,
) -> Vec<DateChooserWeekInfo> {
    compute_date_chooser_weeks_with_visibility(view_date, anchor_date, today, first_weekday, |d| {
        range.contains(d)
    })
}

fn compute_date_chooser_weeks_with_visibility(
    view_date: NaiveDate,
    anchor_date: NaiveDate,
    today: NaiveDate,
    first_weekday: Weekday,
    is_visible: impl Fn(NaiveDate) -> bool,
) -> Vec<DateChooserWeekInfo> {
    let view_month = view_date.month();
    let grid_start = date_chooser_grid_start(view_date, first_weekday);
    let mut weeks = Vec::with_capacity(6);

    for row_idx in 0..6 {
        let week_start = grid_start + Duration::days((row_idx * 7) as i64);
        let visible: Vec<bool> = (0..7)
            .map(|c| is_visible(week_start + Duration::days(c as i64)))
            .collect();
        let has_visible_days = visible.iter().any(|v| *v);
        // A week is "selected" when the whole visible range of that row spans multiple days
        let visible_count = visible.iter().filter(|v| **v).count();

        let mut days = Vec::with_capacity(7);
        for col_idx in 0..7 {
            let cell_date = week_start + Duration::days(col_idx as i64);
            let is_outside_month = cell_date.month() != view_month;
            let in_range = visible[col_idx];
            let prev_in = col_idx > 0 && visible[col_idx - 1];
            let next_in = col_idx < 6 && visible[col_idx + 1];
            days.push(DateChooserCellInfo {
                date: cell_date,
                is_outside_month,
                is_selected_day: cell_date == anchor_date,
                is_today: cell_date == today,
                is_selected_week: visible_count > 1,
                is_last_col: col_idx == 6,
                in_visible_range: in_range,
                is_range_start: in_range && !prev_in,
                is_range_end: in_range && !next_in,
            });
        }

        weeks.push(DateChooserWeekInfo {
            week_number: week_start.iso_week().week(),
            week_start,
            is_selected_week: visible_count > 1,
            has_visible_days,
            days,
        });
    }

    weeks
}

fn is_day_visible_in_viewport(viewport: &CalendarViewport, date: NaiveDate) -> bool {
    match viewport.view {
        CalendarView::Day => date == viewport.anchor_date,
        CalendarView::Week => viewport.visible_range.contains(date),
        CalendarView::WorkWeek => {
            viewport.visible_range.contains(date) && configured_workdays().contains(&date.weekday())
        }
        CalendarView::Month => viewport.visible_range.contains(date),
        CalendarView::Agenda => false,
        CalendarView::Year => false,
        CalendarView::List => false,
    }
}

fn update_mini_calendar_classes(
    cal: &gtk::Calendar,
    y: i32,
    m: u32,
    viewport: &CalendarViewport,
    has_selected_date: bool,
) {
    let today = chrono::Local::now().date_naive();
    let (prev_y, prev_m) = if m == 1 { (y - 1, 12) } else { (y, m - 1) };
    let (next_y, next_m) = if m == 12 { (y + 1, 1) } else { (y, m + 1) };

    let mut child = cal.first_child();
    while let Some(w) = child {
        if w.css_name() == "grid" {
            let mut cell = w.first_child();
            let mut in_current_month = false;
            let mut past_current_month = false;

            while let Some(lbl) = cell {
                if lbl.has_css_class("day-number") {
                    let is_other_month = lbl.has_css_class("other-month");
                    if !is_other_month {
                        in_current_month = true;
                    } else if in_current_month {
                        past_current_month = true;
                    }

                    if !has_selected_date || viewport.view == CalendarView::Month {
                        lbl.unset_state_flags(gtk::StateFlags::SELECTED);
                    }

                    lbl.remove_css_class("range-start");
                    lbl.remove_css_class("range-end");

                    if let Ok(label) = lbl.clone().downcast::<gtk::Label>() {
                        let text = label.text();
                        if let Ok(day_num) = text.parse::<u32>() {
                            let (cell_y, cell_m) = if !in_current_month {
                                (prev_y, prev_m)
                            } else if past_current_month {
                                (next_y, next_m)
                            } else {
                                (y, m)
                            };

                            if let Some(d) = NaiveDate::from_ymd_opt(cell_y, cell_m, day_num) {
                                let is_visible = is_day_visible_in_viewport(viewport, d);
                                let is_range = is_visible && viewport.view != CalendarView::Day && viewport.view != CalendarView::Year && viewport.view != CalendarView::List;
                                if is_range {
                                    lbl.set_state_flags(gtk::StateFlags::CHECKED, false);

                                    let prev_visible = d
                                        .pred_opt()
                                        .map(|p| is_day_visible_in_viewport(viewport, p))
                                        .unwrap_or(false);
                                    let next_visible = d
                                        .succ_opt()
                                        .map(|n| is_day_visible_in_viewport(viewport, n))
                                        .unwrap_or(false);

                                    if viewport.view != CalendarView::Month {
                                        if !prev_visible {
                                            lbl.add_css_class("range-start");
                                        }
                                        if !next_visible {
                                            lbl.add_css_class("range-end");
                                        }
                                    }
                                } else {
                                    lbl.unset_state_flags(gtk::StateFlags::CHECKED);
                                }

                                if !is_other_month
                                    && d == today
                                    && y == today.year()
                                    && m == today.month()
                                {
                                    lbl.add_css_class("today");
                                } else {
                                    lbl.remove_css_class("today");
                                }
                            }
                        }
                    }
                }
                cell = lbl.next_sibling();
            }
            break;
        }
        child = w.next_sibling();
    }
}

