    #[test]
    fn test_calendar_continuous_grid_zoom_slot_height_and_markup_scaling() {
        let base_slot_height_30 = 24.0f64;
        let base_slot_height_60 = 36.0f64;

        // Verify slot_height scaling across scale boundaries [0.75, 1.50]
        let scales = [0.75, 1.0, 1.25, 1.50];
        let expected_30 = [18, 24, 30, 36];
        let expected_60 = [27, 36, 45, 54];

        for (i, &scale) in scales.iter().enumerate() {
            let h30 = ((base_slot_height_30 * scale).round() as i32).max(12);
            assert_eq!(h30, expected_30[i]);
            let h60 = ((base_slot_height_60 * scale).round() as i32).max(12);
            assert_eq!(h60, expected_60[i]);

            // Scaled hour markup: shrinks when scale < 1.0, stays standard handsome readable size at/above 1.0
            let markup = format_hour_markup_scaled(9 * 60, false, scale);
            let expected_main_sz = if scale < 1.0 {
                ((18000.0 * scale).round() as i32).max(12000)
            } else {
                18000
            };
            assert!(markup.contains(&format!(r#"size="{expected_main_sz}""#)));
        }

        // Verify scroll ratio conservation math
        let old_upper = 1152.0; // 24 * 48 (at 1.0 scale)
        let old_val = 480.0;    // 10:00 AM (10 hours down)
        let ratio = old_val / old_upper;
        let new_upper = 1728.0; // 24 * 72 (at 1.5 scale)
        let new_val = ratio * new_upper;
        assert_eq!(new_val, 720.0); // 10 * 72 = 720.0 (still exactly 10:00 AM!)
    }

    #[test]
    fn test_calendar_time_grid_zoom_controllers_attached() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };

        let page = CalendarPage::new();
        let box_widget = gtk::Box::new(gtk::Orientation::Vertical, 0);
        page.attach_time_grid_zoom_controllers(&box_widget);

        let controllers = box_widget.observe_controllers();
        let mut has_scroll = false;
        let mut has_key = false;
        for i in 0..controllers.n_items() {
            if let Some(item) = controllers.item(i) {
                if item.downcast_ref::<gtk::EventControllerScroll>().is_some() {
                    has_scroll = true;
                }
                if item.downcast_ref::<gtk::EventControllerKey>().is_some() {
                    has_key = true;
                }
            }
        }
        assert!(has_scroll, "EventControllerScroll must be attached to time grid container");
        assert!(has_key, "EventControllerKey must be attached to time grid container");
    }

    #[test]
    fn test_calendar_workday_scroll_and_allday_chip_unscaled() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };

        let page = CalendarPage::new();

        // 1. Initial center ratio must be None
        assert_eq!(page.imp().time_grid_center_ratio.get(), None);

        // 2. Switching views must reset scroll to workday start and clear center ratio
        page.imp().time_grid_reset_scroll.set(false);
        page.imp().time_grid_center_ratio.set(Some(0.6));
        page.select_calendar_view(CalendarView::Month);
        assert!(page.imp().time_grid_reset_scroll.get());
        assert_eq!(page.imp().time_grid_center_ratio.get(), None);

        // 3. Workday start baseline: default is 09:00 (540 min = 9 * 60)
        let (workday_start, _) = configured_workday_range();
        assert_eq!(workday_start, 540);

        // Target start min directly uses workday start (e.g. 540 min), independent of arbitrary nighttime noise
        let target_start_min = workday_start;
        assert_eq!(target_start_min, 540);

        // 4. Center-anchored zoom math verification:
        // Center ratio 0.55 (around 13:12 / 1:12 PM) must stay centered in the viewport across zoom levels
        let center_ratio = 0.55f64;
        let page_size = 600.0f64;

        // Zoom level 1: upper = 1152 (1.0 scale)
        let upper1 = 1152.0f64;
        let top1 = (center_ratio * upper1 - (page_size / 2.0)).clamp(0.0, upper1 - page_size);
        let center1 = (top1 + (page_size / 2.0)) / upper1;
        assert!((center1 - center_ratio).abs() < 0.0001);

        // Zoom level 2: upper = 1728 (1.5 scale)
        let upper2 = 1728.0f64;
        let top2 = (center_ratio * upper2 - (page_size / 2.0)).clamp(0.0, upper2 - page_size);
        let center2 = (top2 + (page_size / 2.0)) / upper2;
        assert!((center2 - center_ratio).abs() < 0.0001);

        // Verify that top scroll was adjusted proportionally so the center did NOT jump to 0.0
        assert!(top2 > top1);
        assert!(top1 > 0.0);

        // 4. All-day event chip remains fixed at 22px regardless of zoom scale
        let dummy_event = CalendarEventRecord {
            uid: "allday-test-1".to_string(),
            source_uid: "src-1".to_string(),
            source_display_name: "Calendar".to_string(),
            component: "BEGIN:VEVENT\r\nUID:allday-test-1\r\nSUMMARY:Vacation\r\nEND:VEVENT\r\n".to_string(),
            summary: "Vacation".to_string(),
            start: "2026-10-08".to_string(),
            end: "2026-10-09".to_string(),
            location: String::new(),
            description: String::new(),
            all_day: true,
        };

        set_cached_chip_scale(1.50);
        let chip_zoom_in = calendar_grid_event_chip(
            &page,
            &dummy_event,
            true,
            NaiveDate::from_ymd_opt(2026, 10, 8).unwrap(),
            None,
            1,
            false,
            false,
        );
        assert_eq!(chip_zoom_in.height_request(), 22, "All-day chip height must remain 22px at 150% zoom");

        set_cached_chip_scale(0.75);
        let chip_zoom_out = calendar_grid_event_chip(
            &page,
            &dummy_event,
            true,
            NaiveDate::from_ymd_opt(2026, 10, 8).unwrap(),
            None,
            1,
            false,
            false,
        );
        assert_eq!(chip_zoom_out.height_request(), 22, "All-day chip height must remain 22px at 75% zoom");

        // 5. Workday start scroll target calculation:
        // Night hours (00:00-07:00) are scrolled out of view by default
        let interval_minutes = 30u32;
        let base_slot_height = 24.0f64;
        let workday_start_slot = (workday_start / interval_minutes) as f64;
        let initial_target_y = workday_start_slot * base_slot_height;
        assert!(initial_target_y >= 336.0, "Workday start scroll must be at or after 07:00 (336px) so night hours are scrolled above viewport");
        assert_eq!(initial_target_y, 432.0);

        // 6. Zoom anchor center ratio debounced cleanup
        page.imp().time_grid_center_ratio.set(Some(0.55));
        assert_eq!(page.imp().time_grid_center_ratio.get(), Some(0.55));
        page.set_chip_scale(1.10);
        assert!(page.imp().time_grid_center_ratio_cleanup_source.borrow().is_some(), "Debounce timer must be scheduled on zoom");

        // Reset cached scale back to default
        set_cached_chip_scale(1.0);
    }

    #[test]
    fn month_scroll_by_week_navigation_step() {
        let anchor = NaiveDate::from_ymd_opt(2026, 9, 15).unwrap();
        let mut state_month = CalendarViewState::new(CalendarView::Month, anchor, Weekday::Mon);

        // Standard month navigation (shift by month)
        state_month.navigate_step(1, Weekday::Mon, false);
        assert_eq!(
            state_month.anchor_date,
            NaiveDate::from_ymd_opt(2026, 10, 1).unwrap()
        );

        // Week-by-week month navigation (shift by 7 days)
        let mut state_week_scroll =
            CalendarViewState::new(CalendarView::Month, anchor, Weekday::Mon);
        state_week_scroll.navigate_step(1, Weekday::Mon, true);
        assert_eq!(
            state_week_scroll.anchor_date,
            NaiveDate::from_ymd_opt(2026, 9, 22).unwrap()
        );
        state_week_scroll.navigate_step(-1, Weekday::Mon, true);
        assert_eq!(state_week_scroll.anchor_date, anchor);
    }

    #[test]
    fn calendar_sidebar_mini_calendars_sync_consecutive_months() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };
        let page = CalendarPage::new();
        let target = NaiveDate::from_ymd_opt(2026, 9, 7).unwrap();
        page.navigate_to_date(target);

        let cal1 = page.imp().mini_calendar.borrow().clone().unwrap();
        let cal2 = page.imp().mini_calendar_2.borrow().clone().unwrap();
        let cal3 = page.imp().mini_calendar_3.borrow().clone().unwrap();
        let cal4 = page.imp().mini_calendar_4.borrow().clone().unwrap();

        assert_eq!(cal1.date().month(), 9);
        assert_eq!(cal2.date().month(), 10);
        assert_eq!(cal3.date().month(), 11);
        assert_eq!(cal4.date().month(), 12);

        let previous_week_start = AppSettings::try_new().map(|s| {
            let prev = s.calendar_week_start();
            s.set_calendar_week_start("monday");
            prev
        });

        // Verify marked days in Week view (default week is 2026-09-07 to 2026-09-13)
        page.select_calendar_view(CalendarView::Week);
        assert!(cal1.day_is_marked(7));
        assert!(cal1.day_is_marked(13));
        assert!(!cal1.day_is_marked(6));
        assert!(!cal1.day_is_marked(14));
        assert!(!cal2.day_is_marked(7));

        // Verify marked days in WorkWeek view (Mon-Fri 7..=11, Sat-Sun not marked)
        page.select_calendar_view(CalendarView::WorkWeek);
        assert!(cal1.day_is_marked(7));
        assert!(cal1.day_is_marked(11));
        assert!(!cal1.day_is_marked(12));
        assert!(!cal1.day_is_marked(13));

        // Verify marked days in Day view (only anchor day 7 marked)
        page.select_calendar_view(CalendarView::Day);
        assert!(cal1.day_is_marked(7));
        assert!(!cal1.day_is_marked(8));

        // Verify marked days in Month view (September days marked, October unmarked)
        page.select_calendar_view(CalendarView::Month);
        assert!(cal1.day_is_marked(1));
        assert!(cal1.day_is_marked(15));
        assert!(cal1.day_is_marked(30));
        assert!(!cal2.day_is_marked(1));

        // Test October (crossing into January of next year, matching user's screenshot)
        let october_target = NaiveDate::from_ymd_opt(2026, 10, 15).unwrap();
        page.navigate_to_date(october_target);
        assert_eq!(cal1.date().year(), 2026);
        assert_eq!(cal1.date().month(), 10);
        assert_eq!(cal2.date().year(), 2026);
        assert_eq!(cal2.date().month(), 11);
        assert_eq!(cal3.date().year(), 2026);
        assert_eq!(cal3.date().month(), 12);
        assert_eq!(cal4.date().year(), 2027);
        assert_eq!(cal4.date().month(), 1);

        // Verify limitless scaling beyond 4 months (e.g. 6 consecutive months)
        page.ensure_mini_calendar_count(6);
        assert_eq!(page.imp().mini_calendars.borrow().len(), 6);
        let cal5 = page.imp().mini_calendars.borrow()[4].clone();
        let cal6 = page.imp().mini_calendars.borrow()[5].clone();
        assert_eq!(cal5.date().year(), 2027);
        assert_eq!(cal5.date().month(), 2);
        assert_eq!(cal6.date().year(), 2027);
        assert_eq!(cal6.date().month(), 3);

        if let Some(prev) = previous_week_start {
            if let Some(settings) = AppSettings::try_new() {
                settings.set_calendar_week_start(&prev);
            }
        }
    }

    #[test]
    fn workday_cell_qualification_requires_both_working_hours_and_configured_weekday() {
        let workdays = [
            Weekday::Mon,
            Weekday::Tue,
            Weekday::Wed,
            Weekday::Thu,
            Weekday::Fri,
        ];
        let (workday_start, workday_end) = (540, 1020); // 09:00 to 17:00

        let monday = NaiveDate::from_ymd_opt(2026, 8, 10).unwrap();
        let sunday = NaiveDate::from_ymd_opt(2026, 8, 9).unwrap();

        // Monday 10:00 (600m) -> Workday cell
        assert!(is_workday_cell(600, workday_start, workday_end, monday.weekday(), &workdays));

        // Monday 08:00 (480m) -> Offhours
        assert!(!is_workday_cell(480, workday_start, workday_end, monday.weekday(), &workdays));

        // Sunday 10:00 (600m) -> Offhours (not a configured workday)
        assert!(!is_workday_cell(600, workday_start, workday_end, sunday.weekday(), &workdays));
    }

