    #[test]
    fn test_year_and_agenda_virtualization_and_fast_indexing() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };
        let page = CalendarPage::new();
        assert!(page.imp().agenda_vadjustment.borrow().is_some());
        assert!(page.imp().agenda_canvas.borrow().is_some());
        assert!(page.imp().year_vadjustment.borrow().is_some());
        assert!(page.imp().year_canvas.borrow().is_some());
        assert!(page.imp().year_paned.borrow().is_some());

        // Verify switching to Month, Agenda, Year views operates smoothly
        page.select_calendar_view(CalendarView::Month);
        assert_eq!(*page.imp().current_view.borrow(), CalendarView::Month);

        page.select_calendar_view(CalendarView::Agenda);
        assert_eq!(*page.imp().current_view.borrow(), CalendarView::Agenda);

        page.select_calendar_view(CalendarView::Year);
        assert_eq!(*page.imp().current_view.borrow(), CalendarView::Year);

        page.select_calendar_view(CalendarView::List);
        assert_eq!(*page.imp().current_view.borrow(), CalendarView::List);

        // Canvas widgets should remain stable and not get destroyed on view switches
        assert!(page.imp().year_canvas.borrow().is_some());
        assert!(page.imp().agenda_canvas.borrow().is_some());
        assert!(page.imp().month_canvas.borrow().is_some());
        assert!(page.imp().calendar_list_canvas.borrow().is_some());
    }

    #[test]
    fn test_calendar_view_switching_caching_and_zero_alloc_ordering() {
        let ev1 = CalendarEventRecord {
            uid: "ev-1".to_string(),
            source_uid: "src-1".to_string(),
            source_display_name: "Calendar".to_string(),
            component: "BEGIN:VEVENT\r\nUID:ev-1\r\nDTSTART:20260915T140000\r\nDTEND:20260915T150000\r\nSUMMARY:Meeting Zebra\r\nEND:VEVENT\r\n".to_string(),
            summary: "Meeting Zebra".to_string(),
            start: "2026-09-15 14:00".to_string(),
            end: "2026-09-15 15:00".to_string(),
            location: String::new(),
            description: String::new(),
            all_day: false,
        };
        let ev2 = CalendarEventRecord {
            uid: "ev-2".to_string(),
            source_uid: "src-1".to_string(),
            source_display_name: "Calendar".to_string(),
            component: "BEGIN:VEVENT\r\nUID:ev-2\r\nDTSTART:20260915T090000\r\nDTEND:20260915T100000\r\nSUMMARY:breakfast apple\r\nEND:VEVENT\r\n".to_string(),
            summary: "breakfast apple".to_string(),
            start: "2026-09-15 09:00".to_string(),
            end: "2026-09-15 10:00".to_string(),
            location: String::new(),
            description: String::new(),
            all_day: false,
        };

        // compare_event_list_order should compare case-insensitively and chronologically
        assert_eq!(compare_event_list_order(&ev2, &ev1), std::cmp::Ordering::Less);

        // Index precomputes sorting
        let snapshot = CalendarSnapshot {
            events: vec![ev1.clone(), ev2.clone()],
            tasks: Vec::new(),
            memos: Vec::new(),
        };
        let index = CalendarSnapshotIndex::new(Arc::new(snapshot));
        assert_eq!(index.all_event_indices, vec![1, 0]); // ev2 (09:00) before ev1 (14:00)

        let hidden = HashSet::new();
        let plan = build_list_projection_plan(&index, "", None, &hidden);
        assert_eq!(plan.events.len(), 2);
        assert_eq!(plan.events[0].uid, "ev-2");
        assert_eq!(plan.events[1].uid, "ev-1");
        assert_eq!(plan.prepared.len(), 2);
        assert_eq!(plan.prepared[0].title, "breakfast apple");
        assert_eq!(plan.prepared[1].title, "Meeting Zebra");
    }



    #[test]
    fn test_month_hover_target_isolates_recurring_event_occurrences() {
        let anchor = NaiveDate::from_ymd_opt(2026, 10, 1).unwrap();
        let viewport = CalendarViewport::for_view(CalendarView::Month, anchor, Weekday::Mon);
        let days: Vec<NaiveDate> = viewport.visible_range.dates().collect();
        assert_eq!(days.len(), configured_month_grid_cells() as usize);

        // Daily recurring event: same UID, 10:00 to 11:00 on day 0 and day 1
        let event_occ_0 = CalendarEventRecord {
            uid: "recurring-daily-uid".to_string(),
            source_uid: "s1".to_string(),
            source_display_name: "Calendar".to_string(),
            component: "BEGIN:VEVENT\nRRULE:FREQ=DAILY\nEND:VEVENT".to_string(),
            summary: "Daily Standup".to_string(),
            start: format!("{}T10:00:00", days[0].format("%Y-%m-%d")),
            end: format!("{}T11:00:00", days[0].format("%Y-%m-%d")),
            location: String::new(),
            description: String::new(),
            all_day: false,
        };
        let event_occ_1 = CalendarEventRecord {
            uid: "recurring-daily-uid".to_string(),
            source_uid: "s1".to_string(),
            source_display_name: "Calendar".to_string(),
            component: "BEGIN:VEVENT\nRRULE:FREQ=DAILY\nEND:VEVENT".to_string(),
            summary: "Daily Standup".to_string(),
            start: format!("{}T10:00:00", days[1].format("%Y-%m-%d")),
            end: format!("{}T11:00:00", days[1].format("%Y-%m-%d")),
            location: String::new(),
            description: String::new(),
            all_day: false,
        };

        let mut events_by_date = BTreeMap::new();
        events_by_date.entry(days[0]).or_insert_with(Vec::new).push(event_occ_0);
        events_by_date.entry(days[1]).or_insert_with(Vec::new).push(event_occ_1);

        let workdays: HashSet<Weekday> = [Weekday::Mon, Weekday::Tue, Weekday::Wed, Weekday::Thu, Weekday::Fri].into_iter().collect();
        let weekday_names_full = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
        let weekday_names_short = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

        let layout = prepare_month_layout(
            &viewport,
            &events_by_date,
            days[0],
            false,
            &workdays,
            false,
            &weekday_names_full,
            &weekday_names_short,
            false,
            6,
        );

        // Verify that separate occurrences were NOT merged into a continuous bar
        let event_bars: Vec<_> = layout.weeks[0].event_bars.iter().filter(|b| b.event.uid == "recurring-daily-uid").collect();
        assert_eq!(event_bars.len(), 2, "Daily recurring occurrences must be distinct bars");
        assert_eq!(event_bars[0].occurrence_date, days[0]);
        assert_eq!(event_bars[1].occurrence_date, days[1]);
        assert_eq!(event_bars[0].start_col, 0);
        assert_eq!(event_bars[1].start_col, 1);

        let width = 700.0;
        let height = 628.0;

        // Hit testing occurrence 0 must return occurrence_date = days[0]
        let hit_0 = hit_test_month_canvas(50.0, 60.0, width, height, &layout);
        match hit_0 {
            Some(MonthCanvasHit::Event { ref event, occurrence_date, .. }) => {
                assert_eq!(event.uid, "recurring-daily-uid");
                assert_eq!(occurrence_date, days[0]);
            }
            other => panic!("Expected MonthCanvasHit::Event for occ 0, got {other:?}"),
        }

        // Hit testing occurrence 1 must return occurrence_date = days[1]
        let hit_1 = hit_test_month_canvas(150.0, 60.0, width, height, &layout);
        match hit_1 {
            Some(MonthCanvasHit::Event { ref event, occurrence_date, .. }) => {
                assert_eq!(event.uid, "recurring-daily-uid");
                assert_eq!(occurrence_date, days[1]);
            }
            other => panic!("Expected MonthCanvasHit::Event for occ 1, got {other:?}"),
        }

        // When hovering occurrence 0, only occurrence 0 evaluates is_hovered == true
        let hover_target = MonthHoverTarget::Event {
            uid: "recurring-daily-uid".to_string(),
            occurrence_date: days[0],
        };
        let occ_0_is_hovered = match &hover_target {
            MonthHoverTarget::Event { uid, occurrence_date } => {
                uid == &event_bars[0].event.uid && occurrence_date == &event_bars[0].occurrence_date
            }
            _ => false,
        };
        let occ_1_is_hovered = match &hover_target {
            MonthHoverTarget::Event { uid, occurrence_date } => {
                uid == &event_bars[1].event.uid && occurrence_date == &event_bars[1].occurrence_date
            }
            _ => false,
        };

        assert!(occ_0_is_hovered, "Occurrence 0 must be hovered");
        assert!(!occ_1_is_hovered, "Occurrence 1 must NOT be hovered when hovering occurrence 0");
    }

    #[test]
    fn test_month_overflow_chip_flush_geometry_and_hover() {
        let monday = NaiveDate::from_ymd_opt(2026, 10, 5).unwrap();
        let viewport = CalendarViewport::for_view(CalendarView::Month, monday, Weekday::Mon);
        let days: Vec<NaiveDate> = viewport.visible_range.dates().collect();

        // Populate day 0 with 8 events so it always overflows across any zoom level
        let mut events_by_date = BTreeMap::new();
        for i in 0..8 {
            let ev = CalendarEventRecord {
                uid: format!("ev-{i}"),
                source_uid: "s1".to_string(),
                source_display_name: "Work".to_string(),
                component: "BEGIN:VEVENT\nEND:VEVENT".to_string(),
                summary: format!("Event {i}"),
                start: format!("{}T09:00:00", days[0].format("%Y-%m-%d")),
                end: format!("{}T10:00:00", days[0].format("%Y-%m-%d")),
                location: String::new(),
                description: String::new(),
                all_day: false,
            };
            events_by_date.entry(days[0]).or_insert_with(Vec::new).push(ev);
        }

        let workdays: HashSet<Weekday> = [Weekday::Mon, Weekday::Tue, Weekday::Wed, Weekday::Thu, Weekday::Fri].into_iter().collect();
        let weekday_names_full = ["Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag"];
        let weekday_names_short = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"];

        let layout = prepare_month_layout(
            &viewport,
            &events_by_date,
            days[0],
            false,
            &workdays,
            false,
            &weekday_names_full,
            &weekday_names_short,
            false,
            16,
        );

        let width = 736.0;
        let height = 628.0;
        let kw_w = 0.0;
        let col_w = (width - kw_w) / 7.0;
        let num_rows = (layout.visible_dates.len() / 7).max(1) as f64;
        let row_h = (height - 28.0) / num_rows;

        for chip_scale in [0.75, 1.0, 1.25, 1.50] {
            let (_day_header_h, chip_h, _chip_step, _max_tracks) = month_layout_metrics(row_h, chip_scale);

            let cell_x = kw_w + 0.0 * col_w;
            let expected_of_x = cell_x + 3.0;
            let expected_of_w = col_w - 6.0;

            // An event bar on track 0 in that same column has the exact same horizontal geometry
            let expected_bar_x = cell_x + 3.0;
            let expected_bar_w = col_w - 6.0;

            assert_eq!(expected_of_x, expected_bar_x, "Overflow chip must be horizontally flush with event chip");
            assert_eq!(expected_of_w, expected_bar_w, "Overflow chip width must exactly match event chip width");
            assert!(chip_h >= 14.0, "Overflow chip height must be at least 14px");
            assert_eq!(_chip_step, chip_h + (2.0 * chip_scale).round().max(1.0));
        }

        // Test hit testing with standard scale 1.0
        set_cached_chip_scale(1.0);
        let default_scale = 1.0;
        let (day_header_h, chip_h, chip_step, max_tracks) = month_layout_metrics(row_h, default_scale);
        let shown_before = max_tracks.saturating_sub(1);
        let cell_x = kw_w + 0.0 * col_w;
        let of_x = cell_x + 3.0;
        let of_y = 28.0 + day_header_h + shown_before as f64 * chip_step;

        // Hit test on the overflow chip center
        let hit = hit_test_month_canvas(of_x + 10.0, of_y + chip_h / 2.0, width, height, &layout);
        match hit {
            Some(MonthCanvasHit::Overflow { date }) => {
                assert_eq!(date, days[0], "Hit test must correctly detect overflow chip on day 0");
            }
            other => panic!("Expected MonthCanvasHit::Overflow, got {other:?}"),
        }

        // Hit test in the 3px margin outside the chip must NOT hit the overflow chip
        let hit_margin = hit_test_month_canvas(cell_x + 1.0, of_y + chip_h / 2.0, width, height, &layout);
        match hit_margin {
            Some(MonthCanvasHit::DayCell { date }) => {
                assert_eq!(date, days[0]);
            }
            Some(MonthCanvasHit::Overflow { .. }) => {
                panic!("Overflow hit test should NOT trigger in cell margin");
            }
            _ => {}
        }

        // Test MonthHoverTarget equality
        let overflow_target = MonthHoverTarget::Overflow { date: days[0] };
        assert_eq!(overflow_target, MonthHoverTarget::Overflow { date: days[0] });
        assert_ne!(overflow_target, MonthHoverTarget::Overflow { date: days[1] });
    }

    #[test]
    fn test_event_occurrence_dates_in_range_historical_event_performance() {
        let historical_event = CalendarEventRecord {
            uid: "historical-1999".to_string(),
            source_uid: "s1".to_string(),
            source_display_name: "Calendar".to_string(),
            component: "BEGIN:VEVENT\r\nUID:historical-1999\r\nDTSTART;VALUE=DATE:19990101\r\nRRULE:FREQ=DAILY\r\nEND:VEVENT\r\n".to_string(),
            summary: "Daily since 1999".to_string(),
            start: "1999-01-01".to_string(),
            end: "1999-01-01".to_string(),
            location: String::new(),
            description: String::new(),
            all_day: true,
        };

        let t0 = std::time::Instant::now();
        let dates = event_occurrence_dates_in_range(&historical_event, calendar_year_range(2026));
        let elapsed = t0.elapsed();

        assert_eq!(dates.len(), 365);
        assert_eq!(dates[0], date("2026-01-01"));
        assert_eq!(dates[364], date("2026-12-31"));
        assert!(
            elapsed.as_millis() < 50,
            "1-year query for 1999 series took too long: {elapsed:?}"
        );
    }

    #[test]
    fn test_resize_event_component_end() {
        let ical = "BEGIN:VCALENDAR\r\nBEGIN:VEVENT\r\nUID:123\r\nDTSTART:20260925T100000Z\r\nDTEND:20260925T110000Z\r\nSUMMARY:Meeting\r\nEND:VEVENT\r\nEND:VCALENDAR";
        // Increase duration by 30 minutes
        let resized = resize_event_component_end(ical, 30).expect("resize should succeed");
        assert!(resized.contains("DTEND:20260925T113000Z"));

        // Decrease duration by 15 minutes
        let shorter = resize_event_component_end(ical, -15).expect("resize should succeed");
        assert!(shorter.contains("DTEND:20260925T104500Z"));

        // Empty should fail
        assert!(resize_event_component_end("", 30).is_err());

        // Event with only DTSTART creates DTEND (default 30 min + delta)
        let ical_no_end = "BEGIN:VCALENDAR\r\nBEGIN:VEVENT\r\nUID:123\r\nDTSTART:20260925T100000Z\r\nSUMMARY:Meeting\r\nEND:VEVENT\r\nEND:VCALENDAR";
        let with_end = resize_event_component_end(ical_no_end, 30).expect("should create DTEND");
        assert!(with_end.contains("DTEND:20260925T110000Z"));
    }

    #[test]
    fn test_find_chip_bottom_edge_at() {
        let chip = PlacedTimeGridChip {
            event: CalendarEventRecord {
                uid: "ev-1".to_string(),
                source_uid: "local".to_string(),
                source_display_name: "Calendar".to_string(),
                component: "BEGIN:VEVENT\r\nUID:ev-1\r\nSUMMARY:Test\r\nEND:VEVENT".to_string(),
                summary: "Test".to_string(),
                start: "2026-09-25 10:00".to_string(),
                end: "2026-09-25 11:00".to_string(),
                location: String::new(),
                description: String::new(),
                all_day: false,
            },
            start_slot: 20, // 20 * 20 = 400.0 y
            row_span: 2,    // 2 * 20 = 40.0 y -> height = 40.0
            col_idx: 0,
            total_cols: 1,
            time_text: "10:00 - 11:00".to_string(),
        };

        let chips = vec![chip];
        let width = 200.0;
        let slot_height = 20.0;

        // cy = 400.0, ch = 40.0. Bottom edge is at y = 440.0.
        // Hit zone: cy + ch - 8.0 ..= cy + ch + 5.0 => 432.0 ..= 445.0.
        // x is within [cx, cx + cw] => [2.0, 196.0].
        assert_eq!(find_chip_bottom_edge_at(&chips, 50.0, 439.0, width, slot_height), Some(0));
        assert_eq!(find_chip_bottom_edge_at(&chips, 50.0, 444.0, width, slot_height), Some(0));
        assert_eq!(find_chip_bottom_edge_at(&chips, 50.0, 432.5, width, slot_height), Some(0));

        // Inside the chip middle (not on edge)
        assert_eq!(find_chip_bottom_edge_at(&chips, 50.0, 415.0, width, slot_height), None);

        // Below the hit zone
        assert_eq!(find_chip_bottom_edge_at(&chips, 50.0, 448.0, width, slot_height), None);

        // Outside horizontally
        assert_eq!(find_chip_bottom_edge_at(&chips, 205.0, 440.0, width, slot_height), None);
    }

    #[test]
    fn test_selected_time_slot_clearing_and_redraw() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };
        let page = CalendarPage::new();

        let date1 = NaiveDate::from_ymd_opt(2026, 9, 25).unwrap();
        let date2 = NaiveDate::from_ymd_opt(2026, 9, 26).unwrap();

        // 1. Initial state
        assert_eq!(page.selected_time_slot(), None);

        // 2. Set slot selection
        let slot = SelectedTimeSlot {
            date: date1,
            end_date: date2,
            start_minute: 600,
            end_minute: 660,
        };
        page.set_selected_time_slot(Some(slot));
        assert_eq!(page.selected_time_slot(), Some(slot));

        // 3. Clear slot selection
        page.clear_selected_time_slot();
        assert_eq!(page.selected_time_slot(), None);

        // 4. Verify continuous_day_canvases registration
        let area1 = gtk::DrawingArea::new();
        let area2 = gtk::DrawingArea::new();
        page.imp().continuous_day_canvases.borrow_mut().push(area1);
        page.imp().continuous_day_canvases.borrow_mut().push(area2);
        assert_eq!(page.imp().continuous_day_canvases.borrow().len(), 2);

        // 5. Calling queue_redraw_all_time_slots works without panic
        page.queue_redraw_all_time_slots();

        // 6. View switch clears slot selection
        page.set_selected_time_slot(Some(slot));
        assert!(page.selected_time_slot().is_some());
        page.select_calendar_view(CalendarView::Month);
        assert_eq!(page.selected_time_slot(), None);
    }

    #[test]
    fn test_multitrack_allday_overlay_measurement_in_week_view() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };
        let page = CalendarPage::new();

        let days = [
            NaiveDate::from_ymd_opt(2026, 9, 28).unwrap(), // Mon (0)
            NaiveDate::from_ymd_opt(2026, 9, 29).unwrap(), // Tue (1)
            NaiveDate::from_ymd_opt(2026, 9, 30).unwrap(), // Wed (2)
            NaiveDate::from_ymd_opt(2026, 10, 1).unwrap(), // Thu (3)
            NaiveDate::from_ymd_opt(2026, 10, 2).unwrap(), // Fri (4)
            NaiveDate::from_ymd_opt(2026, 10, 3).unwrap(), // Sat (5)
            NaiveDate::from_ymd_opt(2026, 10, 4).unwrap(), // Sun (6)
        ];

        let event1 = CalendarEventRecord {
            uid: "ev1".to_string(),
            source_uid: "s1".to_string(),
            source_display_name: "Personal".to_string(),
            component: "BEGIN:VEVENT\r\nUID:ev1\r\nDTSTART;VALUE=DATE:20260928\r\nDTEND;VALUE=DATE:20261001\r\nSUMMARY:Vacation Part 1\r\nEND:VEVENT\r\n".to_string(),
            summary: "Vacation Part 1".to_string(),
            start: "2026-09-28".to_string(),
            end: "2026-10-01".to_string(),
            location: String::new(),
            description: String::new(),
            all_day: true,
        };

        let event2 = CalendarEventRecord {
            uid: "ev2".to_string(),
            source_uid: "s1".to_string(),
            source_display_name: "Personal".to_string(),
            component: "BEGIN:VEVENT\r\nUID:ev2\r\nDTSTART;VALUE=DATE:20260929\r\nDTEND;VALUE=DATE:20261002\r\nSUMMARY:Conference\r\nEND:VEVENT\r\n".to_string(),
            summary: "Conference".to_string(),
            start: "2026-09-29".to_string(),
            end: "2026-10-02".to_string(),
            location: String::new(),
            description: String::new(),
            all_day: true,
        };

        *page.imp().event_records.borrow_mut() = Some(Rc::new(RefCell::new(vec![event1, event2])));

        let view = gtk::Box::new(gtk::Orientation::Vertical, 0);
        page.render_continuous_time_grid(&view, &days);

        // Header grid is the first child of view
        let header_grid = view
            .first_child()
            .and_then(|w| w.downcast::<gtk::Grid>().ok())
            .expect("First child must be header_grid");

        // all_day_container is at col 0, row 1
        let all_day_container = header_grid
            .child_at(0, 1)
            .and_then(|w| w.downcast::<gtk::Box>().ok())
            .expect("all_day_container must exist at (0, 1)");
        assert_eq!(all_day_container.vexpands(), false);

        // days_overlay is at col 1, row 1 (when no secondary timezone)
        let days_overlay = header_grid
            .child_at(1, 1)
            .and_then(|w| w.downcast::<gtk::Overlay>().ok())
            .expect("days_overlay must exist at (1, 1)");

        // Find the allday_grid inside days_overlay
        let mut found_allday_grid = None;
        let mut curr = days_overlay.first_child();
        while let Some(w) = curr {
            if let Ok(grid) = w.clone().downcast::<gtk::Grid>() {
                found_allday_grid = Some(grid);
                break;
            }
            curr = w.next_sibling();
        }
        let allday_grid = found_allday_grid.expect("allday_grid overlay must exist");

        // Verify that measure_overlay is explicitly enabled!
        assert!(
            days_overlay.is_measure_overlay(&allday_grid),
            "days_overlay must measure allday_grid so multiple tracks expand the row"
        );

        // Verify that both overlapping events were attached to separate rows (tracks)
        let chip_track0 = allday_grid.child_at(0, 0);
        let chip_track1 = allday_grid.child_at(1, 1);
        assert!(chip_track0.is_some(), "Track 0 must contain event 1");
        assert!(chip_track1.is_some(), "Track 1 must contain event 2");
    }

    #[test]
    fn test_period_label_text_non_redundant_complements() {
        let _gtk_lock = crate::window::GTK_TEST_MUTEX
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(_context) = crate::window::gtk_test_main_context() else {
            return;
        };
        let page = CalendarPage::new();
        let target = NaiveDate::from_ymd_opt(2026, 10, 15).unwrap();
        page.navigate_to_date(target);

        // Day view: title complements column "THU 15" with month and year
        page.select_calendar_view(CalendarView::Day);
        assert_eq!(page.period_label_text(), "October 2026");

        // Week view: within same month should be "October 2026"
        page.select_calendar_view(CalendarView::Week);
        assert_eq!(page.period_label_text(), "October 2026");

        // Week view: cross-month should be "September – October 2026"
        let cross_date = NaiveDate::from_ymd_opt(2026, 9, 30).unwrap();
        page.navigate_to_date(cross_date);
        page.select_calendar_view(CalendarView::Week);
        assert_eq!(page.period_label_text(), "September \u{2013} October 2026");

        // WorkWeek view: should also be month/year
        page.select_calendar_view(CalendarView::WorkWeek);
        assert_eq!(page.period_label_text(), "September \u{2013} October 2026");
    }

    #[test]
    fn test_date_chooser_weeks_and_date_stepping() {
        // 1. Test step_date_by_month
        let d_oct31 = NaiveDate::from_ymd_opt(2026, 10, 31).unwrap();
        let d_nov = step_date_by_month(d_oct31, 1);
        assert_eq!(d_nov, NaiveDate::from_ymd_opt(2026, 11, 30).unwrap());

        let d_jan = NaiveDate::from_ymd_opt(2026, 1, 15).unwrap();
        let d_dec_prev = step_date_by_month(d_jan, -1);
        assert_eq!(d_dec_prev, NaiveDate::from_ymd_opt(2025, 12, 15).unwrap());

        let d_dec = NaiveDate::from_ymd_opt(2026, 12, 5).unwrap();
        let d_jan_next = step_date_by_month(d_dec, 1);
        assert_eq!(d_jan_next, NaiveDate::from_ymd_opt(2027, 1, 5).unwrap());

        // 2. Test step_date_by_year
        let d_2026 = NaiveDate::from_ymd_opt(2026, 10, 6).unwrap();
        assert_eq!(step_date_by_year(d_2026, 1), NaiveDate::from_ymd_opt(2027, 10, 6).unwrap());
        assert_eq!(step_date_by_year(d_2026, -2), NaiveDate::from_ymd_opt(2024, 10, 6).unwrap());

        let leap_feb29 = NaiveDate::from_ymd_opt(2024, 2, 29).unwrap();
        assert_eq!(step_date_by_year(leap_feb29, 1), NaiveDate::from_ymd_opt(2025, 2, 28).unwrap());

        // 3. Test compute_date_chooser_weeks for October 2026 (matching reference image)
        let view_date = NaiveDate::from_ymd_opt(2026, 10, 1).unwrap();
        let anchor_date = NaiveDate::from_ymd_opt(2026, 10, 6).unwrap(); // Tuesday Oct 6
        let today = NaiveDate::from_ymd_opt(2026, 10, 6).unwrap();

        let weeks = compute_date_chooser_weeks(
            view_date,
            anchor_date,
            today,
            CalendarView::Week,
            Weekday::Mon,
        );

        // Exactly 6 weeks, each with 7 days
        assert_eq!(weeks.len(), 6);
        for w in &weeks {
            assert_eq!(w.days.len(), 7);
        }

        // First week starts on Monday Sep 28 (week 40)
        assert_eq!(weeks[0].week_number, 40);
        assert_eq!(weeks[0].week_start, NaiveDate::from_ymd_opt(2026, 9, 28).unwrap());
        assert!(!weeks[0].is_selected_week);
        // Sep 28, 29, 30 are outside Oct; Oct 1, 2, 3, 4 are inside Oct
        assert!(weeks[0].days[0].is_outside_month); // Sep 28
        assert!(weeks[0].days[1].is_outside_month); // Sep 29
        assert!(weeks[0].days[2].is_outside_month); // Sep 30
        assert!(!weeks[0].days[3].is_outside_month); // Oct 1
        assert_eq!(weeks[0].days[3].date.day(), 1);

        // Second week (week 41, containing anchor Oct 6) MUST be selected in Week view
        assert_eq!(weeks[1].week_number, 41);
        assert!(weeks[1].is_selected_week);
        for day in &weeks[1].days {
            assert!(day.is_selected_week);
        }
        // Oct 6 is at index 1 (Monday is 5, Tuesday is 6)
        assert_eq!(weeks[1].days[1].date, anchor_date);
        assert!(weeks[1].days[1].is_selected_day);
        assert!(weeks[1].days[1].is_today);
        // Last col has is_last_col: true
        assert!(weeks[1].days[6].is_last_col);
        assert!(!weeks[1].days[5].is_last_col);

        // Other weeks are not selected
        assert!(!weeks[2].is_selected_week);
        assert!(!weeks[3].is_selected_week);

        // 4. In Day view, week is not selected as a whole
        let day_view_weeks = compute_date_chooser_weeks(
            view_date,
            anchor_date,
            today,
            CalendarView::Day,
            Weekday::Mon,
        );
        assert!(!day_view_weeks[1].is_selected_week);
        assert!(day_view_weeks[1].days[1].is_selected_day);
    }

    #[test]
    fn test_multi_week_vacation_persists_track_zero() {
        let monday_1 = NaiveDate::from_ymd_opt(2026, 9, 28).unwrap();
        let week1_dates: Vec<NaiveDate> = (0..7).map(|i| monday_1 + Duration::days(i)).collect();
        let monday_2 = monday_1 + Duration::days(7);
        let week2_dates: Vec<NaiveDate> = (0..7).map(|i| monday_2 + Duration::days(i)).collect();

        // 14-day vacation: Sep 28 to Oct 11 inclusive (covers week 1 and week 2)
        let vacation = CalendarEventRecord {
            uid: "vacation-sru".to_string(),
            source_uid: "s1".to_string(),
            source_display_name: "Calendar".to_string(),
            component: String::new(),
            summary: "Urlaub SRU".to_string(),
            start: "2026-09-28".to_string(),
            end: "2026-10-12".to_string(),
            location: String::new(),
            description: String::new(),
            all_day: true,
        };

        // Shorter 2-day event in week 2 starting on Monday Oct 05
        let audi = CalendarEventRecord {
            uid: "audi-paketierung".to_string(),
            source_uid: "s1".to_string(),
            source_display_name: "Calendar".to_string(),
            component: String::new(),
            summary: "Audi Paketierung".to_string(),
            start: "2026-10-05".to_string(),
            end: "2026-10-07".to_string(),
            location: String::new(),
            description: String::new(),
            all_day: true,
        };

        let mut events_by_date = BTreeMap::new();
        for &d in &week1_dates {
            events_by_date.entry(d).or_insert_with(Vec::new).push(vacation.clone());
        }
        for &d in &week2_dates {
            events_by_date.entry(d).or_insert_with(Vec::new).push(vacation.clone());
        }
        events_by_date.entry(week2_dates[0]).or_insert_with(Vec::new).push(audi.clone());
        events_by_date.entry(week2_dates[1]).or_insert_with(Vec::new).push(audi.clone());

        // In week 1: Vacation is track 0
        let layouts_w1 = compute_week_cell_layouts(&week1_dates, &events_by_date, 6);
        for col in 0..7 {
            match &layouts_w1[col].visible_items[0] {
                MonthCellTrackItem::Event { event, .. } => assert_eq!(event.uid, "vacation-sru"),
                _ => panic!("Expected vacation on track 0 in week 1 col {}", col),
            }
        }

        // In week 2: Vacation MUST still be Track 0 (and NOT pushed down by Audi)!
        let layouts_w2 = compute_week_cell_layouts(&week2_dates, &events_by_date, 6);
        for col in 0..7 {
            match &layouts_w2[col].visible_items[0] {
                MonthCellTrackItem::Event { event, .. } => assert_eq!(event.uid, "vacation-sru"),
                _ => panic!("Expected vacation on track 0 in week 2 col {}", col),
            }
        }
        // Audi is in Track 1 on col 0 and 1
        match &layouts_w2[0].visible_items[1] {
            MonthCellTrackItem::Event { event, .. } => assert_eq!(event.uid, "audi-paketierung"),
            _ => panic!("Expected audi on track 1 in week 2 col 0"),
        }
    }

    #[test]
    fn test_recurring_multiday_event_occurrence_range_and_month_bar() {
        let monday = NaiveDate::from_ymd_opt(2026, 10, 5).unwrap();
        let week_dates: Vec<NaiveDate> = (0..7).map(|i| monday + Duration::days(i)).collect();

        // Recurring event starting in 2024, every week Monday to Wednesday (3 days)
        let recurring = CalendarEventRecord {
            uid: "rec-trip".to_string(),
            source_uid: "s1".to_string(),
            source_display_name: "Calendar".to_string(),
            component: "BEGIN:VEVENT\nRRULE:FREQ=WEEKLY;BYDAY=MO\nEND:VEVENT".to_string(),
            summary: "Weekly 3-Day Trip".to_string(),
            start: "2024-01-01".to_string(),
            end: "2024-01-04".to_string(),
            location: String::new(),
            description: String::new(),
            all_day: true,
        };

        // Test event_occurrence_range_for_date for Monday Oct 5
        let range = event_occurrence_range_for_date(&recurring, monday).expect("occurrence range");
        assert_eq!(range.start, monday);
        assert_eq!(range.len_days(), 3);
        assert_eq!(range.last_inclusive(), monday + Duration::days(2));

        // Test event_occurrence_range_for_date for Tuesday Oct 6 (covered by Monday occurrence)
        let range_tue = event_occurrence_range_for_date(&recurring, monday + Duration::days(1)).expect("occurrence range on Tue");
        assert_eq!(range_tue.start, monday);
        assert_eq!(range_tue.len_days(), 3);

        let mut events_by_date = BTreeMap::new();
        events_by_date.entry(week_dates[0]).or_insert_with(Vec::new).push(recurring.clone());
        events_by_date.entry(week_dates[1]).or_insert_with(Vec::new).push(recurring.clone());
        events_by_date.entry(week_dates[2]).or_insert_with(Vec::new).push(recurring.clone());

        let layouts = compute_week_cell_layouts(&week_dates, &events_by_date, 6);
        // Track 0 on Mon, Tue, Wed
        for c in 0..3 {
            match &layouts[c].visible_items[0] {
                MonthCellTrackItem::Event { event, occurrence_date, .. } => {
                    assert_eq!(event.uid, "rec-trip");
                    assert_eq!(*occurrence_date, monday);
                }
                _ => panic!("Expected recurring event on track 0 for col {}", c),
            }
        }
        // Thu, Fri, Sat, Sun have no events
        assert_eq!(layouts[3].visible_items.len(), 0);
    }

    #[test]
    fn test_is_event_running_now_logic() {
        let now = chrono::Local::now();
        let today = now.date_naive();
        let yesterday = today - Duration::days(1);
        let tomorrow = today + Duration::days(1);

        let mut event = CalendarEventRecord {
            uid: "running-test".to_string(),
            source_uid: "s1".to_string(),
            source_display_name: "Work".to_string(),
            component: "BEGIN:VEVENT\nSUMMARY:Test Event\nEND:VEVENT".to_string(),
            summary: "Test Event".to_string(),
            start: format!("{}T09:00:00", today.format("%Y-%m-%d")),
            end: format!("{}T10:00:00", today.format("%Y-%m-%d")),
            location: "Room 1".to_string(),
            description: "Details".to_string(),
            all_day: false,
        };

        // Yesterday and tomorrow should always be false
        assert!(!is_event_running_now(&event, yesterday));
        assert!(!is_event_running_now(&event, tomorrow));

        // All day event on today should be excluded from clock / running now
        event.all_day = true;
        assert!(!is_event_running_now(&event, today));

        // Timed event enclosing now should be true
        event.all_day = false;
        let now_h = now.time().hour();
        let start_h = now_h.saturating_sub(1);
        let end_h = (now_h + 2).min(23);
        if start_h < end_h {
            event.start = format!("{}T{:02}:00:00", today.format("%Y-%m-%d"), start_h);
            event.end = format!("{}T{:02}:00:00", today.format("%Y-%m-%d"), end_h);
            assert!(is_event_running_now(&event, today));
        }

        // Timed event in the past today
        if now_h > 2 {
            event.start = format!("{}T00:00:00", today.format("%Y-%m-%d"));
            event.end = format!("{}T01:00:00", today.format("%Y-%m-%d"));
            assert!(!is_event_running_now(&event, today));
        }
    }

    #[test]
    fn test_month_overflow_count_never_plus_one_math() {
        for max_tracks in 1usize..=16 {
            for total in 0usize..=30 {
                if total > max_tracks {
                    let shown_before = max_tracks.saturating_sub(1);
                    let of_count = total.saturating_sub(shown_before);
                    // Crucial invariant: of_count must NEVER be 1. It must always be >= 2.
                    assert!(
                        of_count >= 2,
                        "Overflow count must be at least 2 when total ({}) > max_tracks ({}), got {}",
                        total, max_tracks, of_count
                    );
                }
            }
        }
    }

